"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73013"],{38390(e){e.exports=JSON.parse('[{"id":"FIN-1194","slug":"401-k","term":"401(k)","also_known_as":[],"difficulty":"Advanced","definition":"A 401(k) is a workplace retirement savings plan in the United States, named after a section of the tax code, that lets employees save part of their pay with tax advantages, often with contributions added by the employer.","letter":"#","hasNote":false},{"id":"FIN-1099","slug":"abandonment-option","term":"Abandonment Option","also_known_as":[],"difficulty":"Advanced","definition":"An abandonment option is a company\'s ability to stop a project before its planned end, and recover some value by selling assets or cutting losses, if the project performs worse than expected.","letter":"A","hasNote":false},{"id":"FIN-1242","slug":"absolute-advantage","term":"Absolute Advantage","also_known_as":[],"difficulty":"Advanced","definition":"Absolute advantage is the ability of a country, business or person to produce more of a good or service than others using the same amount of resources.","letter":"A","hasNote":false},{"id":"FIN-1064","slug":"absorption-costing","term":"Absorption Costing","also_known_as":[],"difficulty":"Advanced","definition":"Absorption costing is a method of calculating product costs that includes all manufacturing costs, both variable and fixed, in the cost of each unit produced.","letter":"A","hasNote":false},{"id":"FIN-561","slug":"accelerated-depreciation","term":"Accelerated Depreciation","also_known_as":[],"difficulty":"Intermediate","definition":"Accelerated depreciation is a method of depreciation that charges more of an asset\'s cost in the early years of its life and less in later years, compared with spreading the cost evenly.","letter":"A","hasNote":false},{"id":"FIN-091","slug":"accounting","term":"Accounting","also_known_as":[],"difficulty":"Beginner","definition":"Accounting is the process of recording, organising and reporting a business\'s financial transactions so that owners, managers, investors, lenders and governments can understand its financial position and performance.","letter":"A","hasNote":false},{"id":"FIN-107","slug":"accounting-equation","term":"Accounting Equation","also_known_as":[],"difficulty":"Beginner","definition":"The accounting equation states that a business\'s assets equal its liabilities plus its equity. Everything a business owns is financed either by borrowing or by its owners.","letter":"A","hasNote":false},{"id":"FIN-605","slug":"accounting-estimate","term":"Accounting Estimate","also_known_as":[],"difficulty":"Intermediate","definition":"An accounting estimate is an approximation of an amount in the financial statements that cannot be measured precisely and depends on judgment about future events, such as bad debts, warranty costs or an asset\'s useful life.","letter":"A","hasNote":false},{"id":"FIN-1057","slug":"accounting-fraud","term":"Accounting Fraud","also_known_as":[],"difficulty":"Advanced","definition":"Accounting fraud is the deliberate manipulation of a company\'s financial statements to mislead investors, lenders, regulators or others about its financial performance or position.","letter":"A","hasNote":false},{"id":"FIN-604","slug":"accounting-policy","term":"Accounting Policy","also_known_as":[],"difficulty":"Intermediate","definition":"An accounting policy is a specific principle, rule or practice a company chooses and applies in preparing its financial statements, such as how it values inventory or recognises revenue.","letter":"A","hasNote":false},{"id":"FIN-132","slug":"accounts-payable","term":"Accounts Payable","also_known_as":["Trade Payables"],"difficulty":"Beginner","definition":"Accounts payable is the money a business owes to its suppliers for goods or services it has received but not yet paid for.","letter":"A","hasNote":true},{"id":"FIN-131","slug":"accounts-receivable","term":"Accounts Receivable","also_known_as":["Trade Receivables"],"difficulty":"Beginner","definition":"Accounts receivable is the money customers owe a business for goods or services they have received but not yet paid for.","letter":"A","hasNote":true},{"id":"FIN-1180","slug":"accredited-investor","term":"Accredited Investor","also_known_as":[],"difficulty":"Advanced","definition":"An accredited investor is a person or organisation that meets financial or professional criteria set by regulators, allowing them to invest in certain private offerings not available to the general public. The term is used mainly in the United States.","letter":"A","hasNote":false},{"id":"FIN-1370","slug":"accretion-dilution","term":"Accretion/Dilution","also_known_as":[],"difficulty":"Advanced","definition":"Accretion/dilution analysis shows whether an acquisition is expected to increase or decrease the acquiring company\'s earnings per share.","letter":"A","hasNote":false},{"id":"FIN-095","slug":"accrual-accounting","term":"Accrual Accounting","also_known_as":[],"difficulty":"Beginner","definition":"Accrual accounting records income when it is earned and expenses when they are incurred, regardless of when cash actually changes hands.","letter":"A","hasNote":false},{"id":"FIN-1058","slug":"accrual-quality","term":"Accrual Quality","also_known_as":[],"difficulty":"Advanced","definition":"Accrual quality is the extent to which a company\'s accrual-based accounting profits are reliably backed by cash flows, rather than by estimates and adjustments that may later prove wrong.","letter":"A","hasNote":false},{"id":"FIN-126","slug":"accrued-expense","term":"Accrued Expense","also_known_as":[],"difficulty":"Beginner","definition":"An accrued expense is a cost a business has already incurred but has not yet paid or been billed for by the end of the reporting period.","letter":"A","hasNote":false},{"id":"FIN-127","slug":"accrued-revenue","term":"Accrued Revenue","also_known_as":[],"difficulty":"Beginner","definition":"Accrued revenue is income a business has earned by delivering goods or services but has not yet billed or received by the end of the reporting period.","letter":"A","hasNote":false},{"id":"FIN-151","slug":"accumulated-depreciation","term":"Accumulated Depreciation","also_known_as":[],"difficulty":"Intermediate","definition":"Accumulated depreciation is the total depreciation charged on an asset since it was bought. It is subtracted from the asset\'s original cost to show its current book value.","letter":"A","hasNote":false},{"id":"FIN-1288","slug":"acquirer","term":"Acquirer","also_known_as":[],"difficulty":"Advanced","definition":"In card payments, an acquirer is the bank or financial institution that enables a merchant to accept card payments, processing transactions on the merchant\'s behalf and depositing the funds into its account.","letter":"A","hasNote":false},{"id":"FIN-964","slug":"acquisition","term":"Acquisition","also_known_as":[],"difficulty":"Beginner","definition":"An acquisition is a transaction in which one company buys a controlling stake in, or all of, another company or its assets.","letter":"A","hasNote":false},{"id":"FIN-716","slug":"active-investing","term":"Active Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Active investing is an investment strategy in which a manager or investor selects investments and adjusts holdings in an attempt to outperform a benchmark index.","letter":"A","hasNote":false},{"id":"FIN-1177","slug":"active-share","term":"Active Share","also_known_as":[],"difficulty":"Advanced","definition":"Active share is a measure of how much a fund\'s holdings differ from its benchmark index, expressed as a percentage from 0%, identical to the index, to 100%, no overlap at all.","letter":"A","hasNote":false},{"id":"FIN-1067","slug":"activity-based-costing","term":"Activity-Based Costing","also_known_as":[],"difficulty":"Advanced","definition":"Activity-based costing (ABC) is a method of assigning overhead costs to products or services based on the activities they actually use, such as machine setups, inspections or orders processed, rather than a single broad measure such as labour hours.","letter":"A","hasNote":false},{"id":"FIN-1411","slug":"actuary","term":"Actuary","also_known_as":[],"difficulty":"Advanced","definition":"An actuary is a professional who uses mathematics, statistics and financial theory to measure and manage risk and uncertainty, especially in insurance, pensions and investments.","letter":"A","hasNote":false},{"id":"FIN-817","slug":"adjustable-rate-mortgage","term":"Adjustable-Rate Mortgage (ARM)","also_known_as":["ARM"],"difficulty":"Intermediate","definition":"An adjustable-rate mortgage (ARM) is a home loan, common in the United States, whose interest rate is fixed for an initial period and then changes at regular intervals in line with a benchmark interest rate.","letter":"A","hasNote":false},{"id":"FIN-1092","slug":"adjusted-ebitda","term":"Adjusted EBITDA","also_known_as":[],"difficulty":"Advanced","definition":"Adjusted EBITDA is earnings before interest, taxes, depreciation and amortization, further adjusted to exclude items that management considers unusual, non-recurring or non-cash, such as restructuring costs and share-based compensation.","letter":"A","hasNote":false},{"id":"FIN-1004","slug":"adjusted-gross-income","term":"Adjusted Gross Income","also_known_as":[],"difficulty":"Intermediate","definition":"Adjusted gross income (AGI) is a measure of income used in the United States federal tax system: a person\'s total gross income minus certain specific deductions, called adjustments.","letter":"A","hasNote":false},{"id":"FIN-102","slug":"adjusting-entry","term":"Adjusting Entry","also_known_as":[],"difficulty":"Beginner","definition":"An adjusting entry is a journal entry made at the end of an accounting period to update account balances so that revenue and expenses are recorded in the correct period.","letter":"A","hasNote":false},{"id":"FIN-1034","slug":"adverse-opinion","term":"Adverse Opinion","also_known_as":[],"difficulty":"Advanced","definition":"An adverse opinion is an audit opinion stating that a company\'s financial statements are not fairly presented, because misstatements are both material and pervasive.","letter":"A","hasNote":false},{"id":"FIN-809","slug":"adverse-selection","term":"Adverse Selection","also_known_as":[],"difficulty":"Intermediate","definition":"Adverse selection is a situation in which one party in a transaction has more information than the other, leading to a higher likelihood of attracting the wrong type of participant, such as high-risk customers in insurance or poor-quality goods in a market.","letter":"A","hasNote":false},{"id":"FIN-174","slug":"after-tax-cost-of-debt","term":"After-Tax Cost of Debt","also_known_as":[],"difficulty":"Intermediate","definition":"The after-tax cost of debt is the interest rate a company pays on its borrowing after taking into account the tax savings from deducting interest from taxable profit.","letter":"A","hasNote":false},{"id":"FIN-688","slug":"after-tax-return","term":"After-Tax Return","also_known_as":[],"difficulty":"Intermediate","definition":"After-tax return is the return an investor actually keeps from an investment after paying any taxes on the income and gains it produced.","letter":"A","hasNote":false},{"id":"FIN-1112","slug":"agency-cost","term":"Agency Cost","also_known_as":[],"difficulty":"Advanced","definition":"Agency cost is the cost that arises from conflicts of interest between people who own a business, or have a stake in it, and the people who manage it on their behalf.","letter":"A","hasNote":false},{"id":"FIN-797","slug":"aggregate-demand","term":"Aggregate Demand","also_known_as":[],"difficulty":"Intermediate","definition":"Aggregate demand is the total demand for all goods and services in an economy at a given overall price level, over a period of time.","letter":"A","hasNote":false},{"id":"FIN-798","slug":"aggregate-supply","term":"Aggregate Supply","also_known_as":[],"difficulty":"Intermediate","definition":"Aggregate supply is the total amount of goods and services that all businesses in an economy are willing and able to produce at a given overall price level, over a period of time.","letter":"A","hasNote":false},{"id":"FIN-1205","slug":"algorithmic-trading","term":"Algorithmic Trading","also_known_as":[],"difficulty":"Advanced","definition":"Algorithmic trading is the use of computer programs to place trades automatically according to pre-set rules, based on factors such as price, timing, volume or mathematical models.","letter":"A","hasNote":false},{"id":"FIN-136","slug":"allowance-for-doubtful-accounts","term":"Allowance for Doubtful Accounts","also_known_as":[],"difficulty":"Beginner","definition":"An allowance for doubtful accounts is an estimate of how much of a business\'s accounts receivable will not be collected. It reduces the receivables shown on the balance sheet to the amount the business realistically expects to receive.","letter":"A","hasNote":false},{"id":"FIN-690","slug":"alpha","term":"Alpha","also_known_as":[],"difficulty":"Intermediate","definition":"Alpha is the return an investment earns above or below what would be expected given the risk it took, often measured against a benchmark index.","letter":"A","hasNote":false},{"id":"FIN-1495","slug":"alternative-data","term":"Alternative Data","also_known_as":[],"difficulty":"Advanced","definition":"Alternative data is information used by investors and analysts that comes from sources other than traditional financial data, such as company reports, market prices and economic statistics.","letter":"A","hasNote":false},{"id":"FIN-433","slug":"american-option","term":"American Option","also_known_as":[],"difficulty":"Intermediate","definition":"An American option is an option that can be exercised at any time up to and including its expiration date.","letter":"A","hasNote":false},{"id":"FIN-089","slug":"amortization","term":"Amortization","also_known_as":[],"difficulty":"Beginner","definition":"Amortization is the gradual repayment of a loan through regular payments that cover both interest and part of the principal, so that the loan is fully repaid by the end of its term.","letter":"A","hasNote":false},{"id":"FIN-152","slug":"amortization-expense","term":"Amortization Expense","also_known_as":[],"difficulty":"Intermediate","definition":"Amortization expense is the portion of an intangible asset\'s cost, such as a patent, software licence or customer contract, that is charged to the income statement in a period as the asset is used up.","letter":"A","hasNote":false},{"id":"FIN-512","slug":"amortization-schedule","term":"Amortization Schedule","also_known_as":[],"difficulty":"Intermediate","definition":"An amortization schedule is a table showing every payment on a loan, how much of each payment goes to interest and how much to principal, and the balance remaining after each payment.","letter":"A","hasNote":false},{"id":"FIN-1156","slug":"anchoring-bias","term":"Anchoring Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Anchoring bias is the tendency to rely too heavily on the first piece of information encountered, called the anchor, when making judgments and decisions, even when it is not relevant.","letter":"A","hasNote":false},{"id":"FIN-951","slug":"angel-investor","term":"Angel Investor","also_known_as":[],"difficulty":"Beginner","definition":"An angel investor is a wealthy individual who invests their own money in early-stage start-ups, usually in exchange for an ownership stake or convertible securities.","letter":"A","hasNote":false},{"id":"FIN-054","slug":"annual-percentage-rate","term":"Annual Percentage Rate (APR)","also_known_as":["APR"],"difficulty":"Beginner","definition":"The annual percentage rate (APR) is the yearly cost of borrowing expressed as a percentage. It includes the interest rate and, in many cases, certain fees, so different loans can be compared more fairly.","letter":"A","hasNote":false},{"id":"FIN-055","slug":"annual-percentage-yield","term":"Annual Percentage Yield (APY)","also_known_as":["APY"],"difficulty":"Beginner","definition":"The annual percentage yield (APY) is the actual return earned on a savings account or deposit in one year, including the effect of compounding.","letter":"A","hasNote":false},{"id":"FIN-1129","slug":"annual-recurring-revenue","term":"Annual Recurring Revenue (ARR)","also_known_as":["ARR"],"difficulty":"Intermediate","definition":"Annual recurring revenue (ARR) is the yearly value of the subscription or contracted recurring revenue a company expects to receive from its existing customers, based on their current contracts.","letter":"A","hasNote":false},{"id":"FIN-608","slug":"annual-report","term":"Annual Report","also_known_as":[],"difficulty":"Intermediate","definition":"An annual report is a comprehensive document a company publishes each year describing its activities, strategy, performance and financial position, including its audited financial statements.","letter":"A","hasNote":false},{"id":"FIN-686","slug":"annualized-return","term":"Annualized Return","also_known_as":[],"difficulty":"Intermediate","definition":"Annualized return is the average yearly rate of return an investment would need to earn, with compounding, to produce its total return over a period longer or shorter than a year.","letter":"A","hasNote":false},{"id":"FUT-0018","slug":"annuity","term":"Annuity","also_known_as":[],"difficulty":"Intermediate","definition":"An annuity is a series of equal payments made at regular intervals for a set period, such as monthly loan repayments or yearly pension payments. The word is also used for an insurance product that provides a guaranteed income, often in retirement.","letter":"A","hasNote":false},{"id":"FIN-511","slug":"annuity-due","term":"Annuity Due","also_known_as":[],"difficulty":"Intermediate","definition":"An annuity due is a series of equal payments made at the beginning of each period, such as rent paid at the start of each month.","letter":"A","hasNote":false},{"id":"FIN-1454","slug":"anti-dilution-protection","term":"Anti-Dilution Protection","also_known_as":[],"difficulty":"Advanced","definition":"Anti-dilution protection is a provision that protects investors, typically holders of preferred shares in venture capital deals, if a company later issues shares at a lower price than they paid, by adjusting the price at which their shares convert into ordinary shares.","letter":"A","hasNote":false},{"id":"FIN-854","slug":"anti-money-laundering","term":"Anti-Money Laundering (AML)","also_known_as":["AML"],"difficulty":"Intermediate","definition":"Anti-money laundering (AML) refers to the laws, regulations and procedures designed to prevent criminals from disguising illegally obtained money as legitimate income.","letter":"A","hasNote":false},{"id":"FIN-802","slug":"appreciation","term":"Appreciation","also_known_as":[],"difficulty":"Beginner","definition":"Appreciation is an increase in the value of a currency compared with other currencies, or more generally an increase in the value of any asset over time.","letter":"A","hasNote":false},{"id":"FIN-894","slug":"arbitrage","term":"Arbitrage","also_known_as":[],"difficulty":"Intermediate","definition":"Arbitrage is the practice of profiting from price differences for the same or equivalent assets in different markets, by buying where the price is lower and simultaneously selling where it is higher.","letter":"A","hasNote":false},{"id":"FIN-476","slug":"arithmetic-mean","term":"Arithmetic Mean","also_known_as":[],"difficulty":"Beginner","definition":"The arithmetic mean is the sum of a set of values divided by the number of values. It is what most people mean by \\"the average\\".","letter":"A","hasNote":false},{"id":"FIN-266","slug":"ask-price","term":"Ask Price","also_known_as":[],"difficulty":"Intermediate","definition":"The ask price is the lowest price a seller is currently willing to accept for a security. It is also called the offer price.","letter":"A","hasNote":false},{"id":"FIN-013","slug":"asset","term":"Asset","also_known_as":[],"difficulty":"Beginner","definition":"An asset is anything you own or control that has value and is expected to provide a future benefit, such as cash, investments, property, equipment or money others owe you.","letter":"A","hasNote":false},{"id":"FIN-228","slug":"asset-allocation","term":"Asset Allocation","also_known_as":[],"difficulty":"Beginner","definition":"Asset allocation is the way an investor divides their money among different types of assets, such as shares, bonds, property and cash.","letter":"A","hasNote":false},{"id":"FIN-912","slug":"asset-backed-security","term":"Asset-Backed Security (ABS)","also_known_as":["ABS"],"difficulty":"Intermediate","definition":"An asset-backed security (ABS) is an investment backed by a pool of loans or receivables other than mortgages, such as car loans, credit card balances, student loans or equipment leases.","letter":"A","hasNote":false},{"id":"FIN-1278","slug":"asset-based-lending","term":"Asset-Based Lending","also_known_as":[],"difficulty":"Advanced","definition":"Asset-based lending is a type of business borrowing secured against specific assets, such as receivables, inventory, equipment or property, where the amount available depends mainly on the value of those assets.","letter":"A","hasNote":false},{"id":"FIN-881","slug":"asset-based-valuation","term":"Asset-Based Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Asset-based valuation is a method of valuing a company based on the value of its assets minus its liabilities, rather than on its earnings or cash flows.","letter":"A","hasNote":false},{"id":"FIN-1432","slug":"asset-heavy-business","term":"Asset-Heavy Business","also_known_as":[],"difficulty":"Advanced","definition":"An asset-heavy business is a company that needs large amounts of physical assets, such as factories, equipment, property, vehicles or infrastructure, to operate and grow.","letter":"A","hasNote":false},{"id":"FIN-943","slug":"asset-light-business","term":"Asset-Light Business","also_known_as":[],"difficulty":"Intermediate","definition":"An asset-light business is a company that operates with relatively few physical assets, such as property, factories or equipment, often relying on outsourcing, partnerships, licensing or technology instead.","letter":"A","hasNote":false},{"id":"FIN-1191","slug":"asset-location","term":"Asset Location","also_known_as":[],"difficulty":"Advanced","definition":"Asset location is choosing which types of investment to hold in which types of account, such as taxable, tax-deferred and tax-free accounts, to reduce the total tax paid.","letter":"A","hasNote":false},{"id":"FIN-1445","slug":"asset-sale","term":"Asset Sale","also_known_as":[],"difficulty":"Advanced","definition":"An asset sale is a transaction in which a buyer purchases specific assets of a business, and often takes on selected liabilities, rather than buying the company that owns them.","letter":"A","hasNote":false},{"id":"FIN-624","slug":"asset-turnover","term":"Asset Turnover","also_known_as":[],"difficulty":"Intermediate","definition":"Asset turnover is revenue divided by total assets, showing how much sales a company generates for each unit of assets it owns.","letter":"A","hasNote":false},{"id":"FIN-736","slug":"assets-under-management","term":"Assets Under Management (AUM)","also_known_as":["AUM"],"difficulty":"Intermediate","definition":"Assets under management (AUM) is the total market value of the investments that a fund manager, financial institution or adviser manages on behalf of clients.","letter":"A","hasNote":false},{"id":"FIN-436","slug":"assignment-option","term":"Assignment (Option)","also_known_as":[],"difficulty":"Intermediate","definition":"Assignment, for options, is the notice received by an option seller that the buyer has exercised the option, obliging the seller to fulfil the contract.","letter":"A","hasNote":false},{"id":"FIN-591","slug":"associate-company","term":"Associate Company","also_known_as":[],"difficulty":"Intermediate","definition":"An associate company is a business in which an investor has significant influence, but not control, typically through holding about 20% to 50% of the voting rights.","letter":"A","hasNote":false},{"id":"FIN-890","slug":"assumption","term":"Assumption","also_known_as":[],"difficulty":"Intermediate","definition":"In financial modelling, an assumption is an input value, such as a growth rate, profit margin, interest rate or discount rate, that an analyst chooses to drive the projections and results of a model.","letter":"A","hasNote":false},{"id":"FIN-442","slug":"at-the-money","term":"At-the-Money","also_known_as":[],"difficulty":"Intermediate","definition":"An option is at the money when its strike price is equal to, or very close to, the current price of the underlying asset.","letter":"A","hasNote":false},{"id":"FIN-596","slug":"audit","term":"Audit","also_known_as":[],"difficulty":"Intermediate","definition":"An audit is an independent examination of an organisation\'s financial statements, records or processes to check whether they are accurate and follow the relevant rules.","letter":"A","hasNote":false},{"id":"FIN-1040","slug":"audit-trail","term":"Audit Trail","also_known_as":[],"difficulty":"Advanced","definition":"An audit trail is a step-by-step record showing how a transaction or figure was created, changed and approved, linking final reported numbers back to their source documents.","letter":"A","hasNote":false},{"id":"FIN-599","slug":"auditor-s-opinion","term":"Auditor\'s Opinion","also_known_as":[],"difficulty":"Intermediate","definition":"An auditor\'s opinion is the formal conclusion an external auditor gives on whether a company\'s financial statements are presented fairly, in all material respects, in line with the applicable accounting framework.","letter":"A","hasNote":false},{"id":"FIN-791","slug":"austerity","term":"Austerity","also_known_as":[],"difficulty":"Intermediate","definition":"Austerity is a government policy of reducing budget deficits and debt by cutting public spending, raising taxes or both.","letter":"A","hasNote":false},{"id":"FIN-1138","slug":"authorized-shares","term":"Authorized Shares","also_known_as":[],"difficulty":"Advanced","definition":"Authorized shares are the maximum number of shares a company is legally allowed to issue, as set out in its founding documents.","letter":"A","hasNote":false},{"id":"FIN-821","slug":"auto-loan","term":"Auto Loan","also_known_as":[],"difficulty":"Beginner","definition":"An auto loan is a loan used to buy a car or other vehicle, typically repaid in fixed monthly instalments over a set number of years and secured against the vehicle itself.","letter":"A","hasNote":false},{"id":"FIN-1486","slug":"autocorrelation","term":"Autocorrelation","also_known_as":[],"difficulty":"Advanced","definition":"Autocorrelation is the degree to which a time series is correlated with its own past values, showing whether past observations help predict future ones.","letter":"A","hasNote":false},{"id":"FIN-1291","slug":"automated-clearing-house","term":"Automated Clearing House (ACH)","also_known_as":["ACH"],"difficulty":"Advanced","definition":"The Automated Clearing House (ACH) is an electronic network in the United States used to move money between bank accounts, for payments such as direct deposits of salaries, bill payments and transfers between accounts.","letter":"A","hasNote":false},{"id":"FIN-1230","slug":"automatic-stabilizer","term":"Automatic Stabilizer","also_known_as":[],"difficulty":"Advanced","definition":"An automatic stabilizer is a feature of the tax and benefit system that automatically supports the economy during downturns and restrains it during booms, without any new decision by the government.","letter":"A","hasNote":false},{"id":"FIN-1476","slug":"average-contract-value","term":"Average Contract Value (ACV)","also_known_as":["ACV"],"difficulty":"Advanced","definition":"Average contract value (ACV) is the average annual revenue a company earns from each customer contract, used mainly by subscription and software businesses selling multi-year agreements.","letter":"A","hasNote":false},{"id":"FIN-1124","slug":"average-revenue-per-user","term":"Average Revenue per User (ARPU)","also_known_as":["ARPU"],"difficulty":"Advanced","definition":"Average revenue per user (ARPU) is the average amount of revenue a business earns from each user or customer over a period, calculated as total revenue divided by the number of users.","letter":"A","hasNote":false},{"id":"FIN-1125","slug":"average-selling-price","term":"Average Selling Price (ASP)","also_known_as":["ASP"],"difficulty":"Advanced","definition":"Average selling price (ASP) is the average price at which a product or group of products is sold over a period, calculated as total revenue from those products divided by the number of units sold.","letter":"A","hasNote":false},{"id":"FIN-1127","slug":"backlog","term":"Backlog","also_known_as":[],"difficulty":"Advanced","definition":"Backlog is the value of orders or contracts a company has received but not yet fulfilled, representing revenue it expects to recognise in future.","letter":"B","hasNote":false},{"id":"FIN-1401","slug":"backtesting","term":"Backtesting","also_known_as":[],"difficulty":"Advanced","definition":"Backtesting is the process of testing a model, strategy or risk measure by applying it to historical data and comparing its predictions or results with what actually happened.","letter":"B","hasNote":false},{"id":"FIN-1383","slug":"backwardation","term":"Backwardation","also_known_as":[],"difficulty":"Advanced","definition":"Backwardation is a situation in a futures market where futures prices for later delivery dates are lower than the current spot price or prices for nearer delivery dates.","letter":"B","hasNote":false},{"id":"FIN-135","slug":"bad-debt","term":"Bad Debt","also_known_as":[],"difficulty":"Beginner","definition":"Bad debt is money owed to a business that it does not expect to collect, usually because a customer cannot or will not pay.","letter":"B","hasNote":false},{"id":"FIN-1309","slug":"bail-in","term":"Bail-In","also_known_as":[],"difficulty":"Advanced","definition":"A bail-in is the rescue of a failing bank by imposing losses on its shareholders and creditors, including by writing down or converting their debt into shares, rather than using taxpayers\' money.","letter":"B","hasNote":false},{"id":"FIN-855","slug":"bailout","term":"Bailout","also_known_as":[],"difficulty":"Intermediate","definition":"A bailout is financial support given to a company, bank, industry or country facing serious difficulties, usually by a government or international organisation, to prevent its collapse.","letter":"B","hasNote":false},{"id":"FIN-109","slug":"balance-sheet","term":"Balance Sheet","also_known_as":["Statement of Financial Position"],"difficulty":"Beginner","definition":"A balance sheet is a financial statement that shows what a business owns, what it owes and what belongs to its owners at a specific date.","letter":"B","hasNote":true},{"id":"FIN-834","slug":"balance-transfer","term":"Balance Transfer","also_known_as":[],"difficulty":"Beginner","definition":"A balance transfer is moving an outstanding debt from one credit card to another, usually to take advantage of a lower interest rate, often an introductory rate of 0% for a set period.","letter":"B","hasNote":false},{"id":"FIN-824","slug":"balloon-payment","term":"Balloon Payment","also_known_as":[],"difficulty":"Intermediate","definition":"A balloon payment is a large, lump-sum payment due at the end of a loan, after a series of smaller regular payments that did not fully repay the amount borrowed.","letter":"B","hasNote":false},{"id":"FIN-336","slug":"bank","term":"Bank","also_known_as":[],"difficulty":"Beginner","definition":"A bank is a financial institution that accepts deposits from customers, lends money to individuals and businesses, and provides services such as payments and currency exchange.","letter":"B","hasNote":false},{"id":"FIN-360","slug":"bank-capital","term":"Bank Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Bank capital is the money a bank\'s owners have invested in it, together with profits it has kept, which acts as a cushion to absorb losses before depositors and other creditors are affected.","letter":"B","hasNote":false},{"id":"FIN-1282","slug":"bank-guarantee","term":"Bank Guarantee","also_known_as":[],"difficulty":"Advanced","definition":"A bank guarantee is a promise by a bank to pay a specified amount to a beneficiary if its customer fails to meet an obligation, such as paying for goods or completing a contract.","letter":"B","hasNote":false},{"id":"FIN-603","slug":"bank-reconciliation","term":"Bank Reconciliation","also_known_as":[],"difficulty":"Intermediate","definition":"A bank reconciliation is the process of comparing a company\'s cash records with its bank statement and explaining any differences, so that both show the true cash balance.","letter":"B","hasNote":false},{"id":"FIN-1308","slug":"bank-resolution","term":"Bank Resolution","also_known_as":[],"difficulty":"Advanced","definition":"Bank resolution is the process by which authorities manage the failure of a bank in an orderly way, protecting critical services, depositors and financial stability while avoiding the use of taxpayers\' money.","letter":"B","hasNote":false},{"id":"FIN-357","slug":"bank-run","term":"Bank Run","also_known_as":[],"difficulty":"Beginner","definition":"A bank run happens when large numbers of customers withdraw their deposits at the same time because they fear the bank may fail.","letter":"B","hasNote":false},{"id":"FIN-367","slug":"bank-transfer","term":"Bank Transfer","also_known_as":[],"difficulty":"Beginner","definition":"A bank transfer is the electronic movement of money from one bank account to another, either within the same bank or between different banks.","letter":"B","hasNote":false},{"id":"FIN-086","slug":"bankruptcy","term":"Bankruptcy","also_known_as":[],"difficulty":"Beginner","definition":"Bankruptcy is a legal process for people or businesses that cannot repay their debts. It allows debts to be reorganised or wiped out, usually in exchange for giving up some assets and accepting restrictions.","letter":"B","hasNote":false},{"id":"FIN-1115","slug":"bankruptcy-cost","term":"Bankruptcy Cost","also_known_as":[],"difficulty":"Advanced","definition":"Bankruptcy cost is the cost a company and its stakeholders bear when it goes through, or comes close to, bankruptcy, including legal and administrative fees and the loss of value caused by financial distress.","letter":"B","hasNote":false},{"id":"FIN-1369","slug":"bargain-purchase-gain","term":"Bargain Purchase Gain","also_known_as":[],"difficulty":"Advanced","definition":"A bargain purchase gain is a gain recorded by a buyer when it acquires a business for less than the fair value of the target\'s identifiable net assets.","letter":"B","hasNote":false},{"id":"FIN-206","slug":"base-case","term":"Base Case","also_known_as":[],"difficulty":"Beginner","definition":"The base case is the most likely or expected scenario in a financial forecast, built on realistic assumptions about how the business and the economy will perform.","letter":"B","hasNote":false},{"id":"FIN-998","slug":"base-year","term":"Base Year","also_known_as":[],"difficulty":"Intermediate","definition":"A base year is the year chosen as the reference point for an index or for adjusting data, typically assigned a value of 100 so that values in other years can be compared with it.","letter":"B","hasNote":false},{"id":"FIN-1318","slug":"basel-accords","term":"Basel Accords","also_known_as":[],"difficulty":"Advanced","definition":"The Basel Accords are a series of international banking regulations developed by the Basel Committee on Banking Supervision, setting minimum standards for bank capital, liquidity and risk management.","letter":"B","hasNote":false},{"id":"FIN-573","slug":"basic-eps","term":"Basic EPS","also_known_as":[],"difficulty":"Intermediate","definition":"Basic EPS is a company\'s net income attributable to ordinary shareholders divided by the weighted average number of ordinary shares outstanding during the period.","letter":"B","hasNote":false},{"id":"FIN-1380","slug":"basis","term":"Basis","also_known_as":[],"difficulty":"Advanced","definition":"In futures markets, basis is the difference between the spot price of an asset and the price of a futures contract on that asset.","letter":"B","hasNote":false},{"id":"FIN-506","slug":"basis-point","term":"Basis Point","also_known_as":[],"difficulty":"Beginner","definition":"A basis point is one hundredth of one percentage point, or 0.01%. It is used to describe small changes in interest rates, yields and fees precisely.","letter":"B","hasNote":false},{"id":"FIN-1381","slug":"basis-risk","term":"Basis Risk","also_known_as":[],"difficulty":"Advanced","definition":"Basis risk is the risk that the price of a hedging instrument and the price of the asset being hedged do not move exactly together, so the hedge does not fully offset losses.","letter":"B","hasNote":false},{"id":"FIN-1480","slug":"bayes-theorem","term":"Bayes\' Theorem","also_known_as":[],"difficulty":"Advanced","definition":"Bayes\' theorem is a mathematical rule for updating the probability of an event or belief when new evidence becomes available, by combining the original probability with how likely the evidence would be if the belief were true.","letter":"B","hasNote":false},{"id":"FIN-723","slug":"bear-market","term":"Bear Market","also_known_as":[],"difficulty":"Beginner","definition":"A bear market is a period during which prices in a financial market fall substantially, commonly defined as a decline of 20% or more from a recent high, accompanied by widespread pessimism.","letter":"B","hasNote":false},{"id":"FIN-920","slug":"bear-put-spread","term":"Bear Put Spread","also_known_as":[],"difficulty":"Intermediate","definition":"A bear put spread is an options strategy that profits from a moderate fall in an asset\'s price, created by buying a put option and selling another put option with a lower exercise price on the same asset and expiry date.","letter":"B","hasNote":false},{"id":"FIN-1241","slug":"behavioral-economics","term":"Behavioral Economics","also_known_as":[],"difficulty":"Advanced","definition":"Behavioral economics is a field of economics that studies how psychological, social and emotional factors affect people\'s economic decisions, often in ways that differ from the predictions of traditional models assuming fully rational behaviour.","letter":"B","hasNote":false},{"id":"FIN-720","slug":"behavioral-finance","term":"Behavioral Finance","also_known_as":[],"difficulty":"Intermediate","definition":"Behavioral finance is the study of how psychological factors, emotions and mental shortcuts influence the financial decisions of investors and the behaviour of markets.","letter":"B","hasNote":false},{"id":"FIN-234","slug":"benchmark","term":"Benchmark","also_known_as":[],"difficulty":"Beginner","definition":"A benchmark is a standard, usually a market index, against which the performance of an investment, fund or portfolio is measured.","letter":"B","hasNote":false},{"id":"FIN-1079","slug":"benchmarking","term":"Benchmarking","also_known_as":[],"difficulty":"Advanced","definition":"Benchmarking is comparing a business\'s performance, processes or costs with those of competitors, industry averages or recognised best performers, to identify gaps and opportunities for improvement.","letter":"B","hasNote":false},{"id":"FIN-1297","slug":"beneficial-owner","term":"Beneficial Owner","also_known_as":[],"difficulty":"Advanced","definition":"A beneficial owner is the person who ultimately owns or controls a company, trust or other legal entity, or on whose behalf a transaction is carried out, even if the assets are held in someone else\'s name.","letter":"B","hasNote":false},{"id":"FIN-526","slug":"beneficiary","term":"Beneficiary","also_known_as":[],"difficulty":"Beginner","definition":"A beneficiary is a person or organisation named to receive money, property or other benefits from an insurance policy, pension, investment account, will or trust.","letter":"B","hasNote":false},{"id":"FIN-434","slug":"bermudan-option","term":"Bermudan Option","also_known_as":[],"difficulty":"Intermediate","definition":"A Bermudan option is an option that can be exercised only on certain specified dates before expiry, as well as on the expiration date itself.","letter":"B","hasNote":false},{"id":"FIN-209","slug":"best-case-scenario","term":"Best-Case Scenario","also_known_as":["Upside Case"],"difficulty":"Beginner","definition":"The best-case scenario is a forecast based on optimistic but still plausible assumptions, showing how good results could be if things go well.","letter":"B","hasNote":true},{"id":"FUT-0352","slug":"beta","term":"Beta","also_known_as":[],"difficulty":"Intermediate","definition":"Beta is a measure of how much an investment\'s price tends to move compared with the overall market. A beta of 1 means it moves in line with the market; above 1 means it moves more, and below 1 means it moves less.","letter":"B","hasNote":false},{"id":"FIN-267","slug":"bid-ask-spread","term":"Bid-Ask Spread","also_known_as":[],"difficulty":"Intermediate","definition":"The bid-ask spread is the difference between the highest price a buyer will pay for a security and the lowest price a seller will accept.","letter":"B","hasNote":false},{"id":"FIN-265","slug":"bid-price","term":"Bid Price","also_known_as":[],"difficulty":"Intermediate","definition":"The bid price is the highest price a buyer is currently willing to pay for a security, such as a share or bond.","letter":"B","hasNote":false},{"id":"FIN-1496","slug":"big-data","term":"Big Data","also_known_as":[],"difficulty":"Intermediate","definition":"Big data refers to extremely large and complex sets of data that cannot easily be stored, processed or analysed with traditional tools, often described by their volume, velocity and variety.","letter":"B","hasNote":false},{"id":"FIN-1481","slug":"binomial-distribution","term":"Binomial Distribution","also_known_as":[],"difficulty":"Advanced","definition":"The binomial distribution is a probability distribution that describes the number of successes in a fixed number of independent trials, where each trial has only two possible outcomes, such as success or failure, with the same probability each time.","letter":"B","hasNote":false},{"id":"FIN-899","slug":"black-swan-event","term":"Black Swan Event","also_known_as":[],"difficulty":"Intermediate","definition":"A black swan event is an extremely rare, unpredictable event with severe consequences, which people often claim, after the fact, should have been foreseeable.","letter":"B","hasNote":false},{"id":"FIN-870","slug":"blockchain","term":"Blockchain","also_known_as":[],"difficulty":"Beginner","definition":"Blockchain is a type of digital ledger that records transactions in a chain of linked blocks, shared across many computers, so that records are transparent and extremely difficult to change once added.","letter":"B","hasNote":false},{"id":"FIN-704","slug":"blue-chip-stock","term":"Blue-Chip Stock","also_known_as":[],"difficulty":"Beginner","definition":"A blue-chip stock is a share in a large, well-established and financially sound company with a long record of reliable performance, often paying regular dividends.","letter":"B","hasNote":false},{"id":"FIN-243","slug":"bond","term":"Bond","also_known_as":[],"difficulty":"Beginner","definition":"A bond is a loan that an investor makes to a government or company. The issuer promises to pay regular interest and to repay the original amount on a set date.","letter":"B","hasNote":false},{"id":"FIN-260","slug":"bond-duration","term":"Bond Duration","also_known_as":[],"difficulty":"Intermediate","definition":"Bond duration measures how sensitive a bond\'s price is to changes in interest rates. It is expressed in years and can be used to estimate the percentage change in price for a one-percentage-point change in yield.","letter":"B","hasNote":false},{"id":"FIN-259","slug":"bond-price","term":"Bond Price","also_known_as":[],"difficulty":"Intermediate","definition":"A bond price is the amount investors are willing to pay for a bond in the market. It is often quoted as a percentage of the bond\'s face value.","letter":"B","hasNote":false},{"id":"FIN-558","slug":"book-value","term":"Book Value","also_known_as":[],"difficulty":"Intermediate","definition":"Book value is the value of a company\'s equity as shown on its balance sheet: total assets minus total liabilities. It is often expressed per share.","letter":"B","hasNote":false},{"id":"FIN-1126","slug":"bookings","term":"Bookings","also_known_as":[],"difficulty":"Advanced","definition":"Bookings are the total value of contracts or orders signed with customers during a period, regardless of when the revenue from them will be recognised or the cash received.","letter":"B","hasNote":false},{"id":"FIN-092","slug":"bookkeeping","term":"Bookkeeping","also_known_as":[],"difficulty":"Beginner","definition":"Bookkeeping is the day-to-day recording of a business\'s financial transactions, such as sales, purchases, payments and receipts, in an organised way.","letter":"B","hasNote":false},{"id":"FIN-044","slug":"borrower","term":"Borrower","also_known_as":["Debtor"],"difficulty":"Beginner","definition":"A borrower is a person, business or government that receives money from a lender and agrees to pay it back later, usually with interest.","letter":"B","hasNote":true},{"id":"FIN-464","slug":"brand-equity","term":"Brand Equity","also_known_as":[],"difficulty":"Intermediate","definition":"Brand equity is the extra value a company gains from having a well-known and well-regarded brand, beyond the value of the product itself.","letter":"B","hasNote":false},{"id":"FIN-178","slug":"break-even-analysis","term":"Break-Even Analysis","also_known_as":[],"difficulty":"Beginner","definition":"Break-even analysis works out the level of sales at which a business\'s total revenue exactly covers its total costs, so it makes neither a profit nor a loss.","letter":"B","hasNote":false},{"id":"FIN-1365","slug":"break-fee","term":"Break Fee","also_known_as":[],"difficulty":"Advanced","definition":"A break fee is a payment one party to an agreed merger or acquisition must make to the other if the deal fails to complete for specified reasons, such as the target\'s board accepting a rival offer.","letter":"B","hasNote":false},{"id":"FIN-1274","slug":"bridge-loan","term":"Bridge Loan","also_known_as":[],"difficulty":"Advanced","definition":"A bridge loan is a short-term loan used to cover a gap in funding until longer-term financing is arranged or an expected payment, such as the proceeds of a sale, is received.","letter":"B","hasNote":false},{"id":"FIN-277","slug":"broker","term":"Broker","also_known_as":[],"difficulty":"Intermediate","definition":"A broker is a person or firm that arranges transactions between buyers and sellers in return for a fee or commission, without usually owning the asset being traded.","letter":"B","hasNote":false},{"id":"FIN-276","slug":"brokerage","term":"Brokerage","also_known_as":[],"difficulty":"Intermediate","definition":"A brokerage is a firm that buys and sells securities on behalf of its clients and usually provides accounts, research and other investment services.","letter":"B","hasNote":false},{"id":"FIN-021","slug":"budget","term":"Budget","also_known_as":["Budgeting"],"difficulty":"Beginner","definition":"A budget is a plan for how money will be earned and spent over a set period, such as a month or a year. It sets limits for spending in different categories and shows how much can be saved.","letter":"B","hasNote":true},{"id":"FIN-787","slug":"budget-deficit","term":"Budget Deficit","also_known_as":[],"difficulty":"Intermediate","definition":"A budget deficit occurs when a government\'s spending exceeds its revenue, mainly from taxes, over a given period, usually a year.","letter":"B","hasNote":false},{"id":"FIN-212","slug":"budget-variance","term":"Budget Variance","also_known_as":[],"difficulty":"Intermediate","definition":"A budget variance is the difference between a budgeted amount and the actual result, such as actual sales or costs compared with what was planned.","letter":"B","hasNote":false},{"id":"FIN-450","slug":"bull-call-spread","term":"Bull Call Spread","also_known_as":[],"difficulty":"Intermediate","definition":"A bull call spread is an options strategy that involves buying a call option and selling another call option with a higher strike price on the same asset and expiry, to profit from a moderate price rise at a lower cost.","letter":"B","hasNote":false},{"id":"FIN-722","slug":"bull-market","term":"Bull Market","also_known_as":[],"difficulty":"Beginner","definition":"A bull market is a period during which prices in a financial market, usually the stock market, rise substantially and investor confidence is high.","letter":"B","hasNote":false},{"id":"FIN-673","slug":"burn-rate","term":"Burn Rate","also_known_as":["Cash Burn"],"difficulty":"Intermediate","definition":"Burn rate is the rate at which a company, usually a start-up or loss-making business, spends its cash, typically measured per month.","letter":"B","hasNote":true},{"id":"FIN-1403","slug":"business-continuity","term":"Business Continuity","also_known_as":[],"difficulty":"Advanced","definition":"Business continuity is an organisation\'s ability to keep its critical operations running, or restore them quickly, during and after a disruption such as a natural disaster, cyberattack, power failure or pandemic.","letter":"B","hasNote":false},{"id":"FIN-756","slug":"business-cycle","term":"Business Cycle","also_known_as":[],"difficulty":"Beginner","definition":"The business cycle is the recurring pattern of expansion and contraction in economic activity over time, as an economy moves through periods of growth, peak, decline and recovery.","letter":"B","hasNote":false},{"id":"FIN-1421","slug":"business-interruption-insurance","term":"Business Interruption Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Business interruption insurance is insurance that covers the loss of income and extra costs a business suffers when it cannot operate normally because of physical damage to its property from an insured event, such as a fire or flood.","letter":"B","hasNote":false},{"id":"FIN-1275","slug":"business-loan","term":"Business Loan","also_known_as":[],"difficulty":"Intermediate","definition":"A business loan is money borrowed by a company or business owner from a bank or other lender to fund business needs, such as starting up, buying equipment, managing cash flow or expanding.","letter":"B","hasNote":false},{"id":"FIN-451","slug":"business-model","term":"Business Model","also_known_as":[],"difficulty":"Beginner","definition":"A business model describes how a company creates value for its customers and makes money from doing so.","letter":"B","hasNote":false},{"id":"FIN-452","slug":"business-plan","term":"Business Plan","also_known_as":[],"difficulty":"Beginner","definition":"A business plan is a written document that sets out a business\'s goals, strategy, target market, operations and financial forecasts, and explains how it intends to succeed.","letter":"B","hasNote":false},{"id":"FIN-382","slug":"business-valuation","term":"Business Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Business valuation is the process of estimating the total economic value of a company or business, often for a sale, investment, merger, tax, legal or financial reporting purpose.","letter":"B","hasNote":false},{"id":"FIN-449","slug":"butterfly-spread","term":"Butterfly Spread","also_known_as":[],"difficulty":"Intermediate","definition":"A butterfly spread is an options strategy that combines options at three different strike prices to profit if the underlying asset\'s price stays close to a particular level at expiry, with limited risk and limited reward.","letter":"B","hasNote":false},{"id":"FIN-717","slug":"buy-and-hold","term":"Buy and Hold","also_known_as":[],"difficulty":"Intermediate","definition":"Buy and hold is an investment strategy in which an investor buys assets, such as shares or funds, and keeps them for a long period, regardless of short-term market movements.","letter":"B","hasNote":false},{"id":"FIN-863","slug":"buy-now-pay-later","term":"Buy Now, Pay Later (BNPL)","also_known_as":["BNPL"],"difficulty":"Intermediate","definition":"Buy now, pay later (BNPL) is a short-term financing option that allows shoppers to buy goods immediately and pay for them in instalments, often interest-free if payments are made on time.","letter":"B","hasNote":false},{"id":"FIN-1374","slug":"calendar-spread","term":"Calendar Spread","also_known_as":[],"difficulty":"Advanced","definition":"A calendar spread is an options strategy that involves buying and selling options on the same asset with the same exercise price but different expiry dates, usually selling a shorter-dated option and buying a longer-dated one.","letter":"C","hasNote":false},{"id":"FIN-119","slug":"calendar-year","term":"Calendar Year","also_known_as":[],"difficulty":"Beginner","definition":"A calendar year is the standard twelve-month period from 1 January to 31 December.","letter":"C","hasNote":false},{"id":"FIN-426","slug":"call-option","term":"Call Option","also_known_as":[],"difficulty":"Intermediate","definition":"A call option is a contract that gives its buyer the right, but not the obligation, to buy an asset at a set price, the strike price, on or before a specific date.","letter":"C","hasNote":false},{"id":"FIN-668","slug":"cannibalization","term":"Cannibalization","also_known_as":[],"difficulty":"Intermediate","definition":"Cannibalization is the reduction in sales of a company\'s existing products caused by the introduction of a new product that customers buy instead.","letter":"C","hasNote":false},{"id":"FIN-1086","slug":"capacity-utilization","term":"Capacity Utilization","also_known_as":[],"difficulty":"Advanced","definition":"Capacity utilization is the percentage of a business\'s or economy\'s potential output that is actually being produced.","letter":"C","hasNote":false},{"id":"FIN-335","slug":"capital-account-balance-of-payments","term":"Capital Account (Balance of Payments)","also_known_as":[],"difficulty":"Intermediate","definition":"The capital account, in the balance of payments, records certain transfers of capital and the purchase or sale of non-produced, non-financial assets between a country and the rest of the world.","letter":"C","hasNote":false},{"id":"FIN-361","slug":"capital-adequacy-ratio","term":"Capital Adequacy Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The capital adequacy ratio is a measure of a bank\'s capital compared with its risk-weighted assets. It shows whether the bank has enough capital to absorb potential losses.","letter":"C","hasNote":false},{"id":"FIN-169","slug":"capital-allocation","term":"Capital Allocation","also_known_as":[],"difficulty":"Beginner","definition":"Capital allocation is how a company decides to use its available money among competing options, such as investing in growth, buying other businesses, paying down debt or returning cash to shareholders.","letter":"C","hasNote":false},{"id":"FUT-0890","slug":"capital-asset-pricing-model","term":"Capital Asset Pricing Model (CAPM)","also_known_as":["CAPM"],"difficulty":"Intermediate","definition":"The Capital Asset Pricing Model (CAPM) is a widely used method for estimating the return investors should expect from an asset, based on the risk-free rate, the extra return expected from the market and the asset\'s sensitivity to market movements.","letter":"C","hasNote":false},{"id":"FIN-175","slug":"capital-budgeting","term":"Capital Budgeting","also_known_as":[],"difficulty":"Beginner","definition":"Capital budgeting is the process a company uses to evaluate and choose major long-term investments, such as new equipment, factories, products or acquisitions.","letter":"C","hasNote":false},{"id":"FIN-1437","slug":"capital-call","term":"Capital Call","also_known_as":[],"difficulty":"Advanced","definition":"A capital call is a request by a private fund manager to its investors to transfer part of the money they have committed to the fund, usually to make a new investment or pay fees.","letter":"C","hasNote":false},{"id":"FIN-1267","slug":"capital-controls","term":"Capital Controls","also_known_as":[],"difficulty":"Advanced","definition":"Capital controls are measures taken by a government or central bank to limit the flow of money into or out of a country, such as taxes on foreign investment, limits on currency conversion or restrictions on moving funds abroad.","letter":"C","hasNote":false},{"id":"FIN-157","slug":"capital-expenditure","term":"Capital Expenditure","also_known_as":["CapEx"],"difficulty":"Beginner","definition":"Capital expenditure is money a business spends to buy, upgrade or extend the life of long-term physical assets, such as buildings, machinery, vehicles or technology.","letter":"C","hasNote":false},{"id":"FIN-1245","slug":"capital-flight","term":"Capital Flight","also_known_as":[],"difficulty":"Advanced","definition":"Capital flight is the rapid movement of large amounts of money out of a country by investors and residents, usually because of fears about economic or political instability, currency devaluation or government policies.","letter":"C","hasNote":false},{"id":"FIN-262","slug":"capital-gain","term":"Capital Gain","also_known_as":[],"difficulty":"Beginner","definition":"A capital gain is the profit made when an asset, such as a share, property or bond, is sold for more than its purchase price.","letter":"C","hasNote":false},{"id":"FIN-547","slug":"capital-gains-tax","term":"Capital Gains Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Capital gains tax is a tax charged on the profit made when an asset, such as shares, property or a business, is sold for more than it cost.","letter":"C","hasNote":false},{"id":"FIN-1101","slug":"capital-intensity","term":"Capital Intensity","also_known_as":[],"difficulty":"Advanced","definition":"Capital intensity is the amount of capital, such as property, equipment and other assets, a business needs to generate each unit of revenue.","letter":"C","hasNote":false},{"id":"FIN-680","slug":"capital-loss","term":"Capital Loss","also_known_as":[],"difficulty":"Beginner","definition":"A capital loss is the loss made when an asset, such as a share, bond or property, is sold for less than its purchase price.","letter":"C","hasNote":false},{"id":"FIN-669","slug":"capital-rationing","term":"Capital Rationing","also_known_as":[],"difficulty":"Intermediate","definition":"Capital rationing is a situation in which a company limits the total amount it will invest in new projects, so it must choose among profitable opportunities rather than pursuing all of them.","letter":"C","hasNote":false},{"id":"FIN-168","slug":"capital-structure","term":"Capital Structure","also_known_as":[],"difficulty":"Intermediate","definition":"Capital structure is the mix of debt and equity a company uses to finance its operations and assets.","letter":"C","hasNote":false},{"id":"FIN-562","slug":"capitalization","term":"Capitalization","also_known_as":[],"difficulty":"Intermediate","definition":"Capitalization, in accounting, is the practice of recording a cost as an asset on the balance sheet rather than as an immediate expense, because it will benefit the business over more than one period.","letter":"C","hasNote":false},{"id":"FIN-1425","slug":"captive-insurer","term":"Captive Insurer","also_known_as":[],"difficulty":"Advanced","definition":"A captive insurer is an insurance company owned by a business or group of businesses, set up mainly to insure the risks of its owners.","letter":"C","hasNote":false},{"id":"FIN-1398","slug":"carbon-credit","term":"Carbon Credit","also_known_as":[],"difficulty":"Advanced","definition":"A carbon credit is a tradable permit or certificate representing the right to emit, or the reduction or removal of, one tonne of carbon dioxide or an equivalent amount of another greenhouse gas.","letter":"C","hasNote":false},{"id":"FIN-837","slug":"card-network","term":"Card Network","also_known_as":[],"difficulty":"Intermediate","definition":"A card network is a company that operates the system connecting card issuers, merchants and their banks, setting the rules and processing the information that allows card payments to be authorised, cleared and settled.","letter":"C","hasNote":false},{"id":"FIN-960","slug":"carried-interest","term":"Carried Interest","also_known_as":[],"difficulty":"Intermediate","definition":"Carried interest is the share of an investment fund\'s profits paid to its managers, typically around 20% of profits above a minimum return, as a reward for performance.","letter":"C","hasNote":false},{"id":"FIN-557","slug":"carrying-amount","term":"Carrying Amount","also_known_as":[],"difficulty":"Intermediate","definition":"The carrying amount is the value at which an asset or liability is recorded on the balance sheet. For a long-term asset, it is usually the original cost minus accumulated depreciation and any impairment.","letter":"C","hasNote":false},{"id":"FIN-1444","slug":"carve-out","term":"Carve-Out","also_known_as":[],"difficulty":"Advanced","definition":"A carve-out is the separation of a business unit from its parent company, either by selling it or by listing part of it on a stock market, while the parent often keeps a stake.","letter":"C","hasNote":false},{"id":"FIN-016","slug":"cash","term":"Cash","also_known_as":[],"difficulty":"Beginner","definition":"Cash is money that is immediately available to spend, including coins, banknotes and money in bank accounts that can be withdrawn at any time.","letter":"C","hasNote":false},{"id":"FIN-835","slug":"cash-advance","term":"Cash Advance","also_known_as":[],"difficulty":"Beginner","definition":"A cash advance is withdrawing cash using a credit card, either from a cash machine or a bank, which is treated as borrowing against the card\'s credit limit.","letter":"C","hasNote":false},{"id":"FIN-017","slug":"cash-balance","term":"Cash Balance","also_known_as":[],"difficulty":"Beginner","definition":"A cash balance is the amount of cash held at a specific moment, such as the money in a bank account at the end of a day or a month.","letter":"C","hasNote":false},{"id":"FIN-096","slug":"cash-basis-accounting","term":"Cash-Basis Accounting","also_known_as":[],"difficulty":"Beginner","definition":"Cash-basis accounting records income only when cash is received and expenses only when cash is paid out.","letter":"C","hasNote":false},{"id":"FIN-023","slug":"cash-budget","term":"Cash Budget","also_known_as":[],"difficulty":"Beginner","definition":"A cash budget is a plan that estimates how much cash will come in and go out over coming weeks or months, showing whether there will be enough cash to pay the bills on time.","letter":"C","hasNote":false},{"id":"FIN-1372","slug":"cash-consideration","term":"Cash Consideration","also_known_as":[],"difficulty":"Advanced","definition":"Cash consideration is payment for an acquisition made in cash, rather than with shares or other securities.","letter":"C","hasNote":false},{"id":"FIN-652","slug":"cash-conversion-cycle","term":"Cash Conversion Cycle","also_known_as":[],"difficulty":"Intermediate","definition":"The cash conversion cycle is the number of days it takes a business to turn money spent on inventory back into cash from customers, after allowing for the time it takes to pay its suppliers.","letter":"C","hasNote":false},{"id":"FIN-563","slug":"cash-equivalents","term":"Cash Equivalents","also_known_as":[],"difficulty":"Intermediate","definition":"Cash equivalents are short-term, highly liquid investments that can be quickly converted into a known amount of cash and carry very little risk of changes in value.","letter":"C","hasNote":false},{"id":"FIN-193","slug":"cash-flow-forecast","term":"Cash Flow Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A cash flow forecast is an estimate of the cash a business expects to receive and pay out over a future period, usually week by week or month by month.","letter":"C","hasNote":false},{"id":"FIN-192","slug":"cash-flow-from-financing","term":"Cash Flow from Financing","also_known_as":[],"difficulty":"Intermediate","definition":"Cash flow from financing is the section of the cash flow statement that shows cash moving between a company and its lenders and owners, such as borrowing, repaying debt, issuing shares and paying dividends.","letter":"C","hasNote":false},{"id":"FIN-191","slug":"cash-flow-from-investing","term":"Cash Flow from Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Cash flow from investing is the section of the cash flow statement that shows cash spent on, or received from, long-term assets and investments.","letter":"C","hasNote":false},{"id":"FIN-114","slug":"cash-flow-statement","term":"Cash Flow Statement","also_known_as":[],"difficulty":"Beginner","definition":"The cash flow statement shows how much cash came into and went out of a business during a period, grouped into operating, investing and financing activities.","letter":"C","hasNote":false},{"id":"FIN-1104","slug":"cash-management","term":"Cash Management","also_known_as":[],"difficulty":"Advanced","definition":"Cash management is the process of collecting, holding, spending and investing a business\'s cash efficiently, so that it always has enough to meet its needs while making good use of any surplus.","letter":"C","hasNote":false},{"id":"FIN-628","slug":"cash-ratio","term":"Cash Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The cash ratio is cash and cash equivalents, sometimes including short-term investments, divided by current liabilities. It is the most conservative measure of a company\'s ability to meet short-term obligations.","letter":"C","hasNote":false},{"id":"FIN-018","slug":"cash-reserve","term":"Cash Reserve","also_known_as":[],"difficulty":"Beginner","definition":"A cash reserve is money deliberately set aside and kept easily accessible to cover unexpected costs, shortfalls in income or short-term needs.","letter":"C","hasNote":false},{"id":"FIN-1396","slug":"catastrophe-bond","term":"Catastrophe Bond","also_known_as":[],"difficulty":"Advanced","definition":"A catastrophe bond is a type of bond, usually issued for an insurer or reinsurer, that pays investors a high interest rate but can lose some or all of its principal if a specified disaster, such as a major hurricane or earthquake, occurs.","letter":"C","hasNote":false},{"id":"FUT-0599","slug":"central-bank","term":"Central Bank","also_known_as":[],"difficulty":"Beginner","definition":"A central bank is the public institution that manages a country\'s or region\'s currency, money supply and interest rates, and oversees the stability of the banking system.","letter":"C","hasNote":false},{"id":"FIN-872","slug":"central-bank-digital-currency","term":"Central Bank Digital Currency (CBDC)","also_known_as":["CBDC"],"difficulty":"Intermediate","definition":"A central bank digital currency (CBDC) is a digital form of a country\'s official currency, issued and backed by its central bank.","letter":"C","hasNote":false},{"id":"FIN-1224","slug":"central-bank-independence","term":"Central Bank Independence","also_known_as":[],"difficulty":"Advanced","definition":"Central bank independence is the degree to which a central bank can set monetary policy, such as interest rates, free from political interference by the government.","letter":"C","hasNote":false},{"id":"FIN-1315","slug":"central-counterparty","term":"Central Counterparty (CCP)","also_known_as":["CCP"],"difficulty":"Advanced","definition":"A central counterparty (CCP) is a clearing house that steps in between the two sides of a trade, becoming the buyer to every seller and the seller to every buyer, and guaranteeing that trades will be completed even if one party defaults.","letter":"C","hasNote":false},{"id":"FIN-991","slug":"central-limit-theorem","term":"Central Limit Theorem","also_known_as":[],"difficulty":"Intermediate","definition":"The central limit theorem is a principle of statistics stating that the average of a large number of independent random values tends to follow a normal distribution, regardless of the shape of the original distribution.","letter":"C","hasNote":false},{"id":"FIN-352","slug":"certificate-of-deposit","term":"Certificate of Deposit (CD)","also_known_as":["CD"],"difficulty":"Beginner","definition":"A certificate of deposit (CD) is a type of time deposit offered by banks and credit unions that pays a fixed interest rate for a fixed term, such as six months, one year or five years.","letter":"C","hasNote":false},{"id":"FIN-1036","slug":"change-in-accounting-estimate","term":"Change in Accounting Estimate","also_known_as":[],"difficulty":"Advanced","definition":"A change in accounting estimate is an adjustment to an amount in the financial statements that was based on judgment, made because new information or developments show the earlier estimate needs revising.","letter":"C","hasNote":false},{"id":"FIN-1450","slug":"change-of-control","term":"Change of Control","also_known_as":[],"difficulty":"Advanced","definition":"A change of control is a transaction or event in which ownership or control of a company passes to a different person or group, such as when it is acquired or a new shareholder gains a majority stake.","letter":"C","hasNote":false},{"id":"FIN-1472","slug":"chapter-11","term":"Chapter 11","also_known_as":[],"difficulty":"Advanced","definition":"Chapter 11 is a section of the United States Bankruptcy Code that allows a struggling company to continue operating while it reorganises its debts and business under court supervision.","letter":"C","hasNote":false},{"id":"FIN-831","slug":"charge-off","term":"Charge-Off","also_known_as":[],"difficulty":"Intermediate","definition":"A charge-off is a debt that a lender has written off as unlikely to be collected, usually after the borrower has missed payments for several months. The term is used mainly in the United States.","letter":"C","hasNote":false},{"id":"FIN-862","slug":"chargeback","term":"Chargeback","also_known_as":[],"difficulty":"Intermediate","definition":"A chargeback is a reversal of a card payment, initiated by the cardholder\'s bank, usually after the cardholder disputes a transaction because of fraud, non-delivery or faulty goods.","letter":"C","hasNote":false},{"id":"FIN-1021","slug":"charitable-deduction","term":"Charitable Deduction","also_known_as":[],"difficulty":"Intermediate","definition":"A charitable deduction is a reduction in taxable income allowed for donations made to qualifying charities.","letter":"C","hasNote":false},{"id":"FIN-098","slug":"chart-of-accounts","term":"Chart of Accounts","also_known_as":[],"difficulty":"Beginner","definition":"A chart of accounts is a complete, organised list of all the accounts a business uses to record its transactions, usually grouped by type and given reference numbers.","letter":"C","hasNote":false},{"id":"FIN-1294","slug":"check","term":"Check","also_known_as":[],"difficulty":"Intermediate","definition":"A check is a written order from an account holder instructing their bank to pay a specified amount from their account to a named person or organisation. It is spelled cheque in British English.","letter":"C","hasNote":false},{"id":"FIN-354","slug":"checking-account","term":"Checking Account","also_known_as":[],"difficulty":"Beginner","definition":"A checking account is a bank account used for everyday transactions, such as receiving pay, paying bills, making card payments and withdrawing cash.","letter":"C","hasNote":false},{"id":"FIN-472","slug":"churn-rate","term":"Churn Rate","also_known_as":["Attrition Rate"],"difficulty":"Beginner","definition":"The churn rate is the percentage of customers who stop using a company\'s product or service during a given period.","letter":"C","hasNote":false},{"id":"FIN-726","slug":"circuit-breaker","term":"Circuit Breaker","also_known_as":[],"difficulty":"Intermediate","definition":"A circuit breaker is a rule that temporarily halts trading on a stock exchange, or in a particular security, when prices fall or rise sharply within a short time.","letter":"C","hasNote":false},{"id":"FIN-1346","slug":"circular-reference","term":"Circular Reference","also_known_as":[],"difficulty":"Advanced","definition":"A circular reference is a situation in a spreadsheet or financial model where a formula depends, directly or indirectly, on its own result.","letter":"C","hasNote":false},{"id":"FIN-1407","slug":"claim-reserve","term":"Claim Reserve","also_known_as":[],"difficulty":"Advanced","definition":"A claim reserve is the amount of money an insurer sets aside to pay claims that have occurred but have not yet been fully settled, including claims that have been reported and those not yet reported.","letter":"C","hasNote":false},{"id":"FIN-926","slug":"claims","term":"Claims","also_known_as":[],"difficulty":"Beginner","definition":"A claim is a formal request made by a policyholder to an insurer for payment or other benefits under the terms of an insurance policy, following a covered loss or event.","letter":"C","hasNote":false},{"id":"FIN-1238","slug":"classical-economics","term":"Classical Economics","also_known_as":[],"difficulty":"Advanced","definition":"Classical economics is a school of economic thought, developed in the late eighteenth and nineteenth centuries, which holds that free markets tend to reach full employment on their own, with flexible prices and wages balancing supply and demand.","letter":"C","hasNote":false},{"id":"FIN-1477","slug":"clawback","term":"Clawback","also_known_as":[],"difficulty":"Advanced","definition":"A clawback is a provision that allows money already paid to be taken back, such as requiring a fund manager to return excess carried interest or requiring executives to repay bonuses after misconduct or misstated results.","letter":"C","hasNote":false},{"id":"FIN-1164","slug":"clearing","term":"Clearing","also_known_as":[],"difficulty":"Advanced","definition":"Clearing is the process, after a trade is agreed, of confirming its details, calculating what each party owes and managing the risk that one side fails to complete the trade before settlement takes place.","letter":"C","hasNote":false},{"id":"FIN-1314","slug":"clearing-house","term":"Clearing House","also_known_as":[],"difficulty":"Advanced","definition":"A clearing house is an organisation that sits between buyers and sellers in financial markets, confirming and processing trades, and in many cases guaranteeing their completion if one party defaults.","letter":"C","hasNote":false},{"id":"FIN-1174","slug":"closed-end-fund","term":"Closed-End Fund","also_known_as":[],"difficulty":"Advanced","definition":"A closed-end fund is an investment fund that issues a fixed number of shares, which then trade on a stock exchange at market prices that can differ from the value of the fund\'s investments.","letter":"C","hasNote":false},{"id":"FIN-103","slug":"closing-entry","term":"Closing Entry","also_known_as":[],"difficulty":"Beginner","definition":"A closing entry is a journal entry made at the end of an accounting period to move the balances of revenue, expense and dividend accounts into retained earnings, resetting those accounts to zero for the next period.","letter":"C","hasNote":false},{"id":"FIN-489","slug":"coefficient-of-determination","term":"Coefficient of Determination (R-Squared)","also_known_as":["R-Squared"],"difficulty":"Intermediate","definition":"The coefficient of determination, written R-squared, is a measure of how much of the variation in a dependent variable is explained by a regression model. It ranges from 0 to 1.","letter":"C","hasNote":false},{"id":"FIN-1123","slug":"cohort-analysis","term":"Cohort Analysis","also_known_as":[],"difficulty":"Advanced","definition":"Cohort analysis is a method of studying groups of customers who share a common starting point, such as the month they signed up, to see how their behaviour, such as retention or spending, changes over time.","letter":"C","hasNote":false},{"id":"FIN-522","slug":"coinsurance","term":"Coinsurance","also_known_as":[],"difficulty":"Beginner","definition":"Coinsurance is the percentage of medical costs that a person with health insurance pays after meeting their deductible, with the insurer paying the remaining percentage.","letter":"C","hasNote":false},{"id":"FIN-919","slug":"collar","term":"Collar","also_known_as":[],"difficulty":"Intermediate","definition":"A collar is an options strategy that protects an existing holding against large losses by buying a put option and paying for it, partly or fully, by selling a call option, which limits potential gains.","letter":"C","hasNote":false},{"id":"FIN-081","slug":"collateral","term":"Collateral","also_known_as":[],"difficulty":"Beginner","definition":"Collateral is an asset that a borrower pledges to a lender as security for a loan. If the loan is not repaid, the lender can take the asset and sell it.","letter":"C","hasNote":false},{"id":"FIN-1390","slug":"collateralized-debt-obligation","term":"Collateralized Debt Obligation (CDO)","also_known_as":["CDO"],"difficulty":"Advanced","definition":"A collateralized debt obligation (CDO) is a structured investment that pools debt instruments, such as bonds, loans or mortgage-backed securities, and divides the resulting cash flows into tranches with different levels of risk and return.","letter":"C","hasNote":false},{"id":"FIN-1391","slug":"collateralized-loan-obligation","term":"Collateralized Loan Obligation (CLO)","also_known_as":["CLO"],"difficulty":"Advanced","definition":"A collateralized loan obligation (CLO) is a structured investment that pools leveraged loans to companies and divides the cash flows from them into tranches with different levels of risk and return.","letter":"C","hasNote":false},{"id":"FIN-832","slug":"collection-account","term":"Collection Account","also_known_as":[],"difficulty":"Intermediate","definition":"A collection account is an entry on a credit report, used mainly in the United States, showing that an unpaid debt has been passed to a collection agency or sold to a debt buyer.","letter":"C","hasNote":false},{"id":"FIN-1083","slug":"combined-leverage","term":"Combined Leverage","also_known_as":[],"difficulty":"Advanced","definition":"Combined leverage measures how sensitive a company\'s earnings per share are to changes in sales, taking account of both operating leverage and financial leverage.","letter":"C","hasNote":false},{"id":"FIN-1408","slug":"combined-ratio","term":"Combined Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The combined ratio is a measure of an insurer\'s underwriting profitability, calculated as the sum of its claims and expenses divided by the premiums it earns, expressed as a percentage.","letter":"C","hasNote":false},{"id":"FIN-337","slug":"commercial-bank","term":"Commercial Bank","also_known_as":["Commercial Banking"],"difficulty":"Beginner","definition":"A commercial bank is a bank that takes deposits and makes loans to individuals and businesses, providing everyday banking services such as current accounts, savings accounts, loans and payments.","letter":"C","hasNote":true},{"id":"FIN-849","slug":"commercial-paper","term":"Commercial Paper","also_known_as":[],"difficulty":"Intermediate","definition":"Commercial paper is a short-term, unsecured debt instrument issued by large companies and financial institutions to raise money for immediate needs, such as payroll or stock purchases.","letter":"C","hasNote":false},{"id":"FIN-1397","slug":"commodity-derivative","term":"Commodity Derivative","also_known_as":[],"difficulty":"Advanced","definition":"A commodity derivative is a financial contract whose value depends on the price of a commodity, such as oil, natural gas, metals or agricultural products.","letter":"C","hasNote":false},{"id":"FIN-1317","slug":"common-equity-tier-1","term":"Common Equity Tier 1 (CET1)","also_known_as":["CET1"],"difficulty":"Advanced","definition":"Common Equity Tier 1 (CET1) is the highest-quality form of bank capital, made up mainly of ordinary shares and retained earnings, after deductions for items such as goodwill, and is used to absorb losses while a bank continues operating.","letter":"C","hasNote":false},{"id":"FIN-311","slug":"common-resource","term":"Common Resource","also_known_as":[],"difficulty":"Intermediate","definition":"A common resource is a good that is rivalrous, meaning one person\'s use reduces what is available to others, but non-excludable, meaning it is hard to stop people from using it. Examples include ocean fish, groundwater and clean air.","letter":"C","hasNote":false},{"id":"FIN-614","slug":"common-size-analysis","term":"Common-Size Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Common-size analysis expresses every line of a financial statement as a percentage of a single base figure, such as revenue for the income statement or total assets for the balance sheet.","letter":"C","hasNote":false},{"id":"FIN-239","slug":"common-stock","term":"Common Stock","also_known_as":["Ordinary Share"],"difficulty":"Beginner","definition":"Common stock is the standard type of company ownership. It gives holders voting rights and a share of profits, but they are paid last if the company is wound up.","letter":"C","hasNote":true},{"id":"FIN-392","slug":"comparable-company-analysis","term":"Comparable Company Analysis","also_known_as":["Trading Comparables","Trading Comps"],"difficulty":"Intermediate","definition":"Comparable company analysis is a valuation method that estimates a company\'s value by comparing it with similar publicly traded companies, using valuation multiples such as price-to-earnings or EV/EBITDA.","letter":"C","hasNote":true},{"id":"FIN-799","slug":"comparative-advantage","term":"Comparative Advantage","also_known_as":[],"difficulty":"Intermediate","definition":"Comparative advantage is the ability of a country, business or person to produce a good or service at a lower opportunity cost than others, meaning they give up less of other things to produce it.","letter":"C","hasNote":false},{"id":"FIN-1256","slug":"competition-policy","term":"Competition Policy","also_known_as":["Antitrust"],"difficulty":"Advanced","definition":"Competition policy is the set of laws and enforcement actions designed to keep markets competitive, by preventing practices such as cartels, abuse of market dominance and mergers that would significantly reduce competition.","letter":"C","hasNote":true},{"id":"FIN-462","slug":"competitive-advantage","term":"Competitive Advantage","also_known_as":[],"difficulty":"Beginner","definition":"A competitive advantage is a feature or capability that allows a business to outperform its rivals, for example by offering better value, charging higher prices or operating at lower cost.","letter":"C","hasNote":false},{"id":"FIN-306","slug":"complementary-good","term":"Complementary Good","also_known_as":[],"difficulty":"Beginner","definition":"A complementary good is a product that is typically used together with another, so that demand for one depends on demand for the other, such as printers and ink or cars and petrol.","letter":"C","hasNote":false},{"id":"FIN-1367","slug":"completion-accounts","term":"Completion Accounts","also_known_as":[],"difficulty":"Advanced","definition":"Completion accounts are financial statements prepared shortly after an acquisition completes, showing the business\'s actual cash, debt and working capital at the completion date, used to calculate the final purchase price.","letter":"C","hasNote":false},{"id":"FIN-225","slug":"compound-annual-growth-rate","term":"Compound Annual Growth Rate (CAGR)","also_known_as":["CAGR"],"difficulty":"Beginner","definition":"The compound annual growth rate (CAGR) is the steady yearly growth rate that would take a value from its starting point to its ending point over a number of years, assuming growth compounds each year.","letter":"C","hasNote":false},{"id":"FIN-052","slug":"compound-interest","term":"Compound Interest","also_known_as":[],"difficulty":"Beginner","definition":"Compound interest is interest calculated on your original money and on the interest it has already earned, so your balance grows a little faster each period.","letter":"C","hasNote":false},{"id":"FIN-053","slug":"compounding-frequency","term":"Compounding Frequency","also_known_as":[],"difficulty":"Beginner","definition":"Compounding frequency is how often interest is calculated and added to a balance, such as yearly, quarterly, monthly or daily.","letter":"C","hasNote":false},{"id":"FIN-1145","slug":"concentration-risk","term":"Concentration Risk","also_known_as":[],"difficulty":"Advanced","definition":"Concentration risk is the risk of large losses from having too much exposure to a single investment, borrower, sector, region or other common factor.","letter":"C","hasNote":false},{"id":"FIN-1479","slug":"conditional-probability","term":"Conditional Probability","also_known_as":[],"difficulty":"Advanced","definition":"Conditional probability is the probability that an event will occur given that another event has already occurred or is known to be true.","letter":"C","hasNote":false},{"id":"FIN-491","slug":"confidence-interval","term":"Confidence Interval","also_known_as":[],"difficulty":"Intermediate","definition":"A confidence interval is a range of values, calculated from sample data, that is likely to contain the true value of an unknown population measure, such as an average, with a stated level of confidence.","letter":"C","hasNote":false},{"id":"FIN-1357","slug":"confidential-information-memorandum","term":"Confidential Information Memorandum (CIM)","also_known_as":["CIM"],"difficulty":"Advanced","definition":"A confidential information memorandum (CIM) is a detailed document prepared by a seller\'s adviser describing a business for sale, given to potential buyers after they sign a non-disclosure agreement.","letter":"C","hasNote":false},{"id":"FIN-1155","slug":"confirmation-bias","term":"Confirmation Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Confirmation bias is the tendency to seek out, interpret and remember information in ways that support what one already believes, while ignoring or dismissing information that contradicts it.","letter":"C","hasNote":false},{"id":"FIN-122","slug":"consistency-principle","term":"Consistency Principle","also_known_as":[],"difficulty":"Beginner","definition":"The consistency principle is the accounting rule that a business should use the same accounting methods from one period to the next, so that its results can be compared fairly over time.","letter":"C","hasNote":false},{"id":"FIN-589","slug":"consolidation","term":"Consolidation","also_known_as":[],"difficulty":"Intermediate","definition":"Consolidation is the process of combining the financial statements of a parent company and the companies it controls into a single set of accounts, as if they were one business.","letter":"C","hasNote":false},{"id":"FIN-776","slug":"consumer-confidence","term":"Consumer Confidence","also_known_as":[],"difficulty":"Intermediate","definition":"Consumer confidence is a measure of how optimistic or pessimistic households feel about the economy and their own financial situation, usually based on regular surveys.","letter":"C","hasNote":false},{"id":"FUT-0567","slug":"consumer-price-index","term":"Consumer Price Index (CPI)","also_known_as":["CPI"],"difficulty":"Beginner","definition":"The Consumer Price Index (CPI) is a measure of the average change over time in the prices paid by households for a typical basket of goods and services. It is the most common way of measuring inflation.","letter":"C","hasNote":false},{"id":"FIN-320","slug":"consumer-surplus","term":"Consumer Surplus","also_known_as":[],"difficulty":"Intermediate","definition":"Consumer surplus is the difference between the maximum amount a buyer is willing to pay for a good and the price they actually pay. It measures the extra benefit buyers receive from a purchase.","letter":"C","hasNote":false},{"id":"FIN-838","slug":"contactless-payment","term":"Contactless Payment","also_known_as":[],"difficulty":"Beginner","definition":"Contactless payment is a way of paying by tapping a card, phone, smartwatch or other device on a payment terminal, without inserting a card or, for smaller amounts, entering a PIN.","letter":"C","hasNote":false},{"id":"FIN-1382","slug":"contango","term":"Contango","also_known_as":[],"difficulty":"Advanced","definition":"Contango is a situation in a futures market where futures prices for later delivery dates are higher than the current spot price or prices for nearer delivery dates.","letter":"C","hasNote":false},{"id":"FIN-580","slug":"contingent-liability","term":"Contingent Liability","also_known_as":[],"difficulty":"Intermediate","definition":"A contingent liability is a possible obligation that depends on the outcome of an uncertain future event, such as a lawsuit or a guarantee, and is not recorded on the balance sheet unless it becomes probable and measurable.","letter":"C","hasNote":false},{"id":"FIN-1001","slug":"continuous-compounding","term":"Continuous Compounding","also_known_as":[],"difficulty":"Intermediate","definition":"Continuous compounding is the theoretical limit of compounding interest more and more frequently, so that interest is added at every instant, producing the maximum possible growth for a given annual rate.","letter":"C","hasNote":false},{"id":"FIN-1046","slug":"contract-asset","term":"Contract Asset","also_known_as":[],"difficulty":"Advanced","definition":"A contract asset is a company\'s right to payment for goods or services it has already delivered to a customer, when that right still depends on something other than the passage of time, such as completing further work.","letter":"C","hasNote":false},{"id":"FIN-1047","slug":"contract-liability","term":"Contract Liability","also_known_as":[],"difficulty":"Advanced","definition":"A contract liability is a company\'s obligation to provide goods or services to a customer for which it has already received payment, or for which payment is due.","letter":"C","hasNote":false},{"id":"FIN-758","slug":"contraction","term":"Contraction","also_known_as":[],"difficulty":"Intermediate","definition":"A contraction is the phase of the business cycle in which economic activity is declining, with falling output, and usually rising unemployment and weaker spending and investment.","letter":"C","hasNote":false},{"id":"FIN-1151","slug":"contrarian-investing","term":"Contrarian Investing","also_known_as":[],"difficulty":"Advanced","definition":"Contrarian investing is an investment strategy of going against prevailing market sentiment, buying assets that are out of favour and selling those that are popular.","letter":"C","hasNote":false},{"id":"FIN-645","slug":"contribution-margin","term":"Contribution Margin","also_known_as":[],"difficulty":"Intermediate","definition":"Contribution margin is a product\'s selling price minus its variable cost per unit. It is the amount each sale contributes towards covering fixed costs and then producing profit.","letter":"C","hasNote":false},{"id":"FIN-646","slug":"contribution-margin-ratio","term":"Contribution Margin Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The contribution margin ratio is the contribution margin divided by the selling price, showing the percentage of each sale available to cover fixed costs and generate profit.","letter":"C","hasNote":false},{"id":"FIN-884","slug":"control-premium","term":"Control Premium","also_known_as":[],"difficulty":"Intermediate","definition":"A control premium is the amount by which the price paid to acquire a controlling stake in a company exceeds the market value of its shares before the deal.","letter":"C","hasNote":false},{"id":"FIN-743","slug":"convertible-bond","term":"Convertible Bond","also_known_as":[],"difficulty":"Intermediate","definition":"A convertible bond is a bond that can be exchanged for a set number of the issuing company\'s shares, usually at the investor\'s choice, combining features of debt and equity.","letter":"C","hasNote":false},{"id":"FIN-978","slug":"convertible-note","term":"Convertible Note","also_known_as":[],"difficulty":"Intermediate","definition":"A convertible note is a short-term loan, commonly used by early-stage start-ups, that converts into shares in the company at a later funding round instead of being repaid in cash.","letter":"C","hasNote":false},{"id":"FIN-263","slug":"convexity","term":"Convexity","also_known_as":[],"difficulty":"Intermediate","definition":"Convexity measures how a bond\'s sensitivity to interest rates itself changes as rates move. It explains why bond prices do not change in a straight line when yields rise or fall.","letter":"C","hasNote":false},{"id":"FIN-521","slug":"copayment","term":"Copayment","also_known_as":[],"difficulty":"Beginner","definition":"A copayment is a fixed amount that a person with health insurance pays for a particular medical service or prescription, with the insurer covering the rest of the cost.","letter":"C","hasNote":false},{"id":"FIN-468","slug":"copyright","term":"Copyright","also_known_as":[],"difficulty":"Beginner","definition":"Copyright is a legal right that protects original creative works, such as books, music, films, artwork, photographs and software, giving the creator exclusive rights to copy, distribute and adapt them.","letter":"C","hasNote":false},{"id":"FIN-765","slug":"core-inflation","term":"Core Inflation","also_known_as":[],"difficulty":"Intermediate","definition":"Core inflation is a measure of inflation that excludes items with volatile prices, most commonly food and energy, to show the underlying trend in price changes.","letter":"C","hasNote":false},{"id":"FIN-246","slug":"corporate-bond","term":"Corporate Bond","also_known_as":[],"difficulty":"Beginner","definition":"A corporate bond is a bond issued by a company to borrow money from investors, paying regular interest and repaying the face value at maturity.","letter":"C","hasNote":false},{"id":"FIN-166","slug":"corporate-finance","term":"Corporate Finance","also_known_as":[],"difficulty":"Beginner","definition":"Corporate finance is the area of finance that deals with how companies raise money, decide where to invest it and manage it to increase their value for owners.","letter":"C","hasNote":false},{"id":"FIN-570","slug":"corporate-income-tax","term":"Corporate Income Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Corporate income tax is a tax charged by governments on the profits of companies.","letter":"C","hasNote":false},{"id":"FIN-484","slug":"correlation","term":"Correlation","also_known_as":[],"difficulty":"Beginner","definition":"Correlation is a statistical relationship between two variables, describing whether and how strongly they tend to move together.","letter":"C","hasNote":false},{"id":"FIN-485","slug":"correlation-coefficient","term":"Correlation Coefficient","also_known_as":[],"difficulty":"Intermediate","definition":"The correlation coefficient is a number between \u22121 and +1 that measures the strength and direction of the straight-line relationship between two variables.","letter":"C","hasNote":false},{"id":"FIN-343","slug":"correspondent-bank","term":"Correspondent Bank","also_known_as":[],"difficulty":"Intermediate","definition":"A correspondent bank is a bank that provides services, such as making payments or handling currency transactions, on behalf of another bank, often in a different country.","letter":"C","hasNote":false},{"id":"FIN-082","slug":"cosigner","term":"Cosigner","also_known_as":[],"difficulty":"Beginner","definition":"A cosigner is a person who signs a loan together with the main borrower and becomes equally responsible for repaying it.","letter":"C","hasNote":false},{"id":"FIN-1063","slug":"cost-allocation","term":"Cost Allocation","also_known_as":[],"difficulty":"Advanced","definition":"Cost allocation is the process of assigning shared or indirect costs, such as rent, IT or management salaries, to products, departments, projects or customers.","letter":"C","hasNote":false},{"id":"FIN-1188","slug":"cost-basis","term":"Cost Basis","also_known_as":["Tax Basis"],"difficulty":"Advanced","definition":"Cost basis is the original value of an asset for tax purposes, usually the purchase price plus costs such as commissions, used to calculate the gain or loss when the asset is sold.","letter":"C","hasNote":true},{"id":"FIN-1071","slug":"cost-center","term":"Cost Center","also_known_as":[],"difficulty":"Advanced","definition":"A cost center is a department or unit of a business whose manager is responsible for controlling costs, but not for generating revenue or profit.","letter":"C","hasNote":false},{"id":"FIN-1070","slug":"cost-driver","term":"Cost Driver","also_known_as":[],"difficulty":"Advanced","definition":"A cost driver is a factor that causes a cost to change, such as the number of units produced, machine hours, orders processed or customer calls handled.","letter":"C","hasNote":false},{"id":"FIN-170","slug":"cost-of-capital","term":"Cost of Capital","also_known_as":[],"difficulty":"Beginner","definition":"The cost of capital is the minimum return a company must earn on its investments to satisfy the people who provide its funding, its lenders and shareholders.","letter":"C","hasNote":false},{"id":"FIN-173","slug":"cost-of-debt","term":"Cost of Debt","also_known_as":[],"difficulty":"Beginner","definition":"The cost of debt is the effective interest rate a company pays on the money it borrows, through loans and bonds.","letter":"C","hasNote":false},{"id":"FIN-172","slug":"cost-of-equity","term":"Cost of Equity","also_known_as":[],"difficulty":"Intermediate","definition":"The cost of equity is the return shareholders expect to earn for investing in a company\'s shares, given the risk they are taking.","letter":"C","hasNote":false},{"id":"FIN-142","slug":"cost-of-goods-sold","term":"Cost of Goods Sold","also_known_as":["Cost of Sales"],"difficulty":"Beginner","definition":"Cost of goods sold is the direct cost of the products a business sold during a period, including materials, direct labour and production overheads.","letter":"C","hasNote":true},{"id":"FIN-031","slug":"cost-of-living","term":"Cost of Living","also_known_as":[],"difficulty":"Beginner","definition":"The cost of living is the amount of money needed to pay for a basic standard of living in a particular place and time, including housing, food, transport, healthcare and other everyday necessities.","letter":"C","hasNote":false},{"id":"FIN-768","slug":"cost-push-inflation","term":"Cost-Push Inflation","also_known_as":[],"difficulty":"Intermediate","definition":"Cost-push inflation is inflation caused by rising production costs, such as wages, raw materials or energy, which businesses pass on to consumers through higher prices.","letter":"C","hasNote":false},{"id":"FIN-666","slug":"cost-synergy","term":"Cost Synergy","also_known_as":[],"difficulty":"Intermediate","definition":"A cost synergy is a saving that two businesses expect to achieve by combining, through eliminating duplicate costs, gaining scale or operating more efficiently together.","letter":"C","hasNote":false},{"id":"FIN-902","slug":"counterparty-risk","term":"Counterparty Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Counterparty risk is the risk that the other party in a financial contract or transaction will fail to meet its obligations, such as by not making a payment or delivering an asset as agreed.","letter":"C","hasNote":false},{"id":"FIN-1335","slug":"country-risk-premium","term":"Country Risk Premium","also_known_as":[],"difficulty":"Advanced","definition":"A country risk premium is the extra return investors require for investing in a particular country, to compensate for risks such as political instability, economic volatility, currency problems and weaker legal protections.","letter":"C","hasNote":false},{"id":"FIN-253","slug":"coupon","term":"Coupon","also_known_as":[],"difficulty":"Intermediate","definition":"A coupon is the regular interest payment a bond pays to its holder, usually once or twice a year.","letter":"C","hasNote":false},{"id":"FIN-254","slug":"coupon-rate","term":"Coupon Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The coupon rate is the annual interest rate a bond pays, expressed as a percentage of its face value.","letter":"C","hasNote":false},{"id":"FIN-483","slug":"covariance","term":"Covariance","also_known_as":[],"difficulty":"Intermediate","definition":"Covariance is a measure of how two variables move together. A positive covariance means they tend to rise and fall together; a negative covariance means one tends to rise when the other falls.","letter":"C","hasNote":false},{"id":"FIN-1468","slug":"covenant-lite-loan","term":"Covenant-Lite Loan","also_known_as":[],"difficulty":"Advanced","definition":"A covenant-lite loan is a loan, usually to a leveraged company, with few or no maintenance covenants, meaning the borrower does not have to meet regular financial tests, such as leverage or interest coverage limits, to avoid default.","letter":"C","hasNote":false},{"id":"FIN-444","slug":"covered-call","term":"Covered Call","also_known_as":[],"difficulty":"Intermediate","definition":"A covered call is an options strategy in which an investor who owns shares sells call options on those same shares to earn extra income from the premium.","letter":"C","hasNote":false},{"id":"FIN-073","slug":"credit","term":"Credit","also_known_as":[],"difficulty":"Beginner","definition":"Credit is the ability to borrow money or buy goods and services now, with an agreement to pay later. It also describes the trust a lender places in a borrower to repay.","letter":"C","hasNote":false},{"id":"FIN-1273","slug":"credit-analysis","term":"Credit Analysis","also_known_as":[],"difficulty":"Advanced","definition":"Credit analysis is the process of assessing how likely a borrower is to repay a loan or debt in full and on time, by examining its finances, business, management and the terms of the borrowing.","letter":"C","hasNote":false},{"id":"FIN-828","slug":"credit-bureau","term":"Credit Bureau","also_known_as":[],"difficulty":"Beginner","definition":"A credit bureau is a company that collects and maintains information about how individuals and businesses borrow and repay money, and provides credit reports and credit scores to lenders and other authorised users.","letter":"C","hasNote":false},{"id":"FIN-363","slug":"credit-card","term":"Credit Card","also_known_as":[],"difficulty":"Beginner","definition":"A credit card is a payment card that lets you borrow money from the card issuer, up to a set limit, to pay for purchases, with the option to repay in full or over time with interest.","letter":"C","hasNote":false},{"id":"FIN-909","slug":"credit-default-swap","term":"Credit Default Swap (CDS)","also_known_as":["CDS"],"difficulty":"Intermediate","definition":"A credit default swap (CDS) is a contract in which one party pays regular fees to another in exchange for protection against a specific borrower defaulting on its debt.","letter":"C","hasNote":false},{"id":"FIN-1394","slug":"credit-enhancement","term":"Credit Enhancement","also_known_as":[],"difficulty":"Advanced","definition":"Credit enhancement is any feature that reduces the credit risk of a security, especially in a securitization, making it more likely that investors will be repaid and often allowing it to receive a higher credit rating.","letter":"C","hasNote":false},{"id":"FIN-830","slug":"credit-freeze","term":"Credit Freeze","also_known_as":[],"difficulty":"Beginner","definition":"A credit freeze is a restriction, available in the United States, that stops credit bureaus from sharing a person\'s credit report with new lenders, making it much harder for anyone to open new accounts in that person\'s name.","letter":"C","hasNote":false},{"id":"FIN-078","slug":"credit-history","term":"Credit History","also_known_as":[],"difficulty":"Beginner","definition":"Credit history is the record of how you have borrowed and repaid money over time. It shows lenders how reliably you have managed credit in the past.","letter":"C","hasNote":false},{"id":"FIN-829","slug":"credit-inquiry","term":"Credit Inquiry","also_known_as":[],"difficulty":"Intermediate","definition":"A credit inquiry is a request by a lender or other organisation to view a person\'s credit report, usually made when that person applies for credit.","letter":"C","hasNote":false},{"id":"FIN-074","slug":"credit-limit","term":"Credit Limit","also_known_as":[],"difficulty":"Beginner","definition":"A credit limit is the maximum amount a lender allows you to borrow on a credit card or line of credit.","letter":"C","hasNote":false},{"id":"FIN-675","slug":"credit-rating","term":"Credit Rating","also_known_as":[],"difficulty":"Intermediate","definition":"A credit rating is an assessment of how likely a borrower, such as a company or government, is to repay its debts in full and on time, usually expressed as a letter grade.","letter":"C","hasNote":false},{"id":"FIN-077","slug":"credit-report","term":"Credit Report","also_known_as":[],"difficulty":"Beginner","definition":"A credit report is a detailed record of your borrowing and repayment history, kept by a credit bureau and used by lenders to judge your creditworthiness.","letter":"C","hasNote":false},{"id":"FIN-695","slug":"credit-risk","term":"Credit Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Credit risk is the risk that a borrower or counterparty will fail to make payments it owes, such as interest or principal on a loan or bond.","letter":"C","hasNote":false},{"id":"FIN-076","slug":"credit-score","term":"Credit Score","also_known_as":[],"difficulty":"Beginner","definition":"A credit score is a number that summarises how likely you are to repay borrowed money, based on information in your credit report. Lenders use it to decide whether to lend to you and at what interest rate.","letter":"C","hasNote":false},{"id":"FIN-264","slug":"credit-spread","term":"Credit Spread","also_known_as":[],"difficulty":"Intermediate","definition":"A credit spread is the difference between the yield on a bond with credit risk, such as a corporate bond, and the yield on a government bond of similar maturity that is considered safe.","letter":"C","hasNote":false},{"id":"FIN-380","slug":"credit-underwriting","term":"Credit Underwriting","also_known_as":[],"difficulty":"Intermediate","definition":"Credit underwriting is the process a lender uses to evaluate a borrower\'s creditworthiness and decide whether to approve a loan, how much to lend and on what terms.","letter":"C","hasNote":false},{"id":"FIN-340","slug":"credit-union","term":"Credit Union","also_known_as":[],"difficulty":"Beginner","definition":"A credit union is a not-for-profit financial cooperative owned by its members, which provides savings accounts, loans and other banking services to those members.","letter":"C","hasNote":false},{"id":"FIN-075","slug":"credit-utilization","term":"Credit Utilization","also_known_as":[],"difficulty":"Beginner","definition":"Credit utilization is the share of your available revolving credit that you are currently using, expressed as a percentage.","letter":"C","hasNote":false},{"id":"FIN-845","slug":"cross-border-payment","term":"Cross-Border Payment","also_known_as":[],"difficulty":"Intermediate","definition":"A cross-border payment is a transfer of money between people, businesses or institutions located in different countries, often involving a currency conversion.","letter":"C","hasNote":false},{"id":"FIN-304","slug":"cross-price-elasticity","term":"Cross-Price Elasticity","also_known_as":[],"difficulty":"Intermediate","definition":"Cross-price elasticity measures how the quantity demanded of one good responds to a change in the price of another good.","letter":"C","hasNote":false},{"id":"FIN-945","slug":"cross-selling","term":"Cross-Selling","also_known_as":[],"difficulty":"Intermediate","definition":"Cross-selling is the practice of encouraging existing customers to buy additional products or services that are related to, or complement, what they already purchase.","letter":"C","hasNote":false},{"id":"FIN-1330","slug":"crypto-exchange","term":"Crypto Exchange","also_known_as":[],"difficulty":"Advanced","definition":"A crypto exchange is a platform where people can buy, sell and trade cryptocurrencies and other digital assets, either for traditional currencies or for other cryptocurrencies.","letter":"C","hasNote":false},{"id":"FIN-873","slug":"crypto-wallet","term":"Crypto Wallet","also_known_as":[],"difficulty":"Intermediate","definition":"A crypto wallet is a tool, either software or a physical device, used to store the private keys that give access to cryptocurrencies, allowing users to send, receive and manage their digital assets.","letter":"C","hasNote":false},{"id":"FIN-869","slug":"cryptocurrency","term":"Cryptocurrency","also_known_as":[],"difficulty":"Beginner","definition":"Cryptocurrency is a type of digital currency that uses cryptography to secure transactions and typically operates on a decentralised network, usually a blockchain, without being issued or controlled by a central bank.","letter":"C","hasNote":false},{"id":"FIN-002","slug":"currency","term":"Currency","also_known_as":[],"difficulty":"Beginner","definition":"A currency is the specific form of money used in a country or region, such as the euro, the US dollar or the Indian rupee. It is issued by a government or central bank and used to price goods and settle debts.","letter":"C","hasNote":false},{"id":"FIN-1265","slug":"currency-board","term":"Currency Board","also_known_as":[],"difficulty":"Advanced","definition":"A currency board is a strict form of fixed exchange rate system in which a monetary authority is legally required to exchange domestic currency for a specified foreign currency at a fixed rate, and to back all domestic currency in issue with foreign reserves.","letter":"C","hasNote":false},{"id":"FIN-1246","slug":"currency-crisis","term":"Currency Crisis","also_known_as":[],"difficulty":"Advanced","definition":"A currency crisis is a sudden, sharp fall in the value of a country\'s currency, often accompanied by speculative attacks, loss of foreign reserves and economic disruption.","letter":"C","hasNote":false},{"id":"FIN-807","slug":"currency-peg","term":"Currency Peg","also_known_as":[],"difficulty":"Intermediate","definition":"A currency peg is a policy in which a country fixes its currency\'s exchange rate to another currency, usually a major one such as the US dollar or the euro, or to a basket of currencies.","letter":"C","hasNote":false},{"id":"FIN-698","slug":"currency-risk","term":"Currency Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Currency risk is the risk that changes in exchange rates will reduce the value of investments, income or costs that are denominated in a foreign currency.","letter":"C","hasNote":false},{"id":"FIN-908","slug":"currency-swap","term":"Currency Swap","also_known_as":[],"difficulty":"Intermediate","definition":"A currency swap is a contract in which two parties exchange principal and interest payments in different currencies over a set period, and then swap the principal back at the end.","letter":"C","hasNote":false},{"id":"FIN-334","slug":"current-account-balance-of-payments","term":"Current Account (Balance of Payments)","also_known_as":[],"difficulty":"Intermediate","definition":"The current account, in the balance of payments, records a country\'s transactions with the rest of the world in goods, services, income and transfers over a period.","letter":"C","hasNote":false},{"id":"FIN-159","slug":"current-asset","term":"Current Asset","also_known_as":[],"difficulty":"Beginner","definition":"A current asset is an asset that a business expects to convert into cash, sell or use up within one year or within its normal operating cycle, if that is longer.","letter":"C","hasNote":false},{"id":"FIN-161","slug":"current-liability","term":"Current Liability","also_known_as":[],"difficulty":"Beginner","definition":"A current liability is an obligation a business expects to pay within one year or within its normal operating cycle, if that is longer.","letter":"C","hasNote":false},{"id":"FIN-626","slug":"current-ratio","term":"Current Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The current ratio is current assets divided by current liabilities, showing whether a company has enough short-term resources to cover its short-term obligations.","letter":"C","hasNote":false},{"id":"FIN-256","slug":"current-yield","term":"Current Yield","also_known_as":[],"difficulty":"Intermediate","definition":"Current yield is a bond\'s annual coupon payment divided by its current market price, showing the income return an investor receives at today\'s price.","letter":"C","hasNote":false},{"id":"FIN-728","slug":"custodian","term":"Custodian","also_known_as":[],"difficulty":"Intermediate","definition":"A custodian is a financial institution that holds and safeguards investments, such as shares, bonds and cash, on behalf of clients, and handles related tasks like settling trades and collecting income.","letter":"C","hasNote":false},{"id":"FIN-471","slug":"customer-acquisition-cost","term":"Customer Acquisition Cost","also_known_as":[],"difficulty":"Intermediate","definition":"Customer acquisition cost is the average amount a business spends to win one new customer, including marketing, advertising and sales costs.","letter":"C","hasNote":false},{"id":"FIN-1135","slug":"customer-concentration","term":"Customer Concentration","also_known_as":[],"difficulty":"Advanced","definition":"Customer concentration is the extent to which a company\'s revenue comes from a small number of customers.","letter":"C","hasNote":false},{"id":"FIN-1296","slug":"customer-due-diligence","term":"Customer Due Diligence (CDD)","also_known_as":["CDD"],"difficulty":"Advanced","definition":"Customer due diligence (CDD) is the process financial institutions and other regulated businesses use to identify and verify their customers and understand the nature of their relationship, in order to detect and prevent money laundering, terrorist financing and fraud.","letter":"C","hasNote":false},{"id":"FIN-470","slug":"customer-lifetime-value","term":"Customer Lifetime Value","also_known_as":[],"difficulty":"Intermediate","definition":"Customer lifetime value is the total profit a business expects to earn from a customer over the entire period of their relationship.","letter":"C","hasNote":false},{"id":"FIN-473","slug":"customer-retention","term":"Customer Retention","also_known_as":[],"difficulty":"Beginner","definition":"Customer retention is a business\'s ability to keep its existing customers over time, and the strategies it uses to do so.","letter":"C","hasNote":false},{"id":"FIN-1420","slug":"cyber-insurance","term":"Cyber Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Cyber insurance is insurance that covers financial losses resulting from cyber incidents, such as data breaches, ransomware attacks, hacking and system failures.","letter":"C","hasNote":false},{"id":"FIN-1402","slug":"cyber-risk","term":"Cyber Risk","also_known_as":[],"difficulty":"Advanced","definition":"Cyber risk is the risk of financial loss, disruption or reputational damage resulting from failures or attacks on an organisation\'s information technology systems, such as hacking, ransomware, data breaches or system outages.","letter":"C","hasNote":false},{"id":"FIN-705","slug":"cyclical-stock","term":"Cyclical Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A cyclical stock is a share in a company whose sales and profits rise and fall strongly with the economic cycle, doing well when the economy is growing and poorly during downturns.","letter":"C","hasNote":false},{"id":"FIN-772","slug":"cyclical-unemployment","term":"Cyclical Unemployment","also_known_as":[],"difficulty":"Intermediate","definition":"Cyclical unemployment is unemployment caused by a downturn in the business cycle, when demand for goods and services falls and businesses reduce their workforce.","letter":"C","hasNote":false},{"id":"FIN-1000","slug":"dashboard","term":"Dashboard","also_known_as":[],"difficulty":"Intermediate","definition":"A dashboard is a visual display that brings together key information, such as performance measures, charts and alerts, on a single screen or page, allowing users to monitor important data at a glance.","letter":"D","hasNote":false},{"id":"FIN-1494","slug":"data-governance","term":"Data Governance","also_known_as":[],"difficulty":"Advanced","definition":"Data governance is the framework of policies, roles, standards and processes an organisation uses to manage its data, ensuring it is accurate, secure, used appropriately and compliant with laws and regulations.","letter":"D","hasNote":false},{"id":"FIN-1493","slug":"data-quality","term":"Data Quality","also_known_as":[],"difficulty":"Intermediate","definition":"Data quality is the degree to which data are accurate, complete, consistent, timely and fit for their intended use.","letter":"D","hasNote":false},{"id":"FIN-1358","slug":"data-room","term":"Data Room","also_known_as":[],"difficulty":"Advanced","definition":"A data room is a secure location, now almost always online, where a company makes confidential documents available to potential buyers, investors or their advisers during due diligence for a transaction.","letter":"D","hasNote":false},{"id":"FIN-1500","slug":"data-snooping","term":"Data Snooping","also_known_as":[],"difficulty":"Advanced","definition":"Data snooping is the practice of testing many hypotheses, models or strategies on the same data set until one appears significant, making it likely that the apparent result is due to chance rather than a genuine effect.","letter":"D","hasNote":false},{"id":"FIN-1353","slug":"data-table","term":"Data Table","also_known_as":[],"difficulty":"Advanced","definition":"A data table is a spreadsheet tool that automatically recalculates a model\'s result for a range of different input values, displaying the outcomes in a grid.","letter":"D","hasNote":false},{"id":"FIN-999","slug":"data-visualization","term":"Data Visualization","also_known_as":[],"difficulty":"Intermediate","definition":"Data visualization is the presentation of data in graphical form, such as charts, graphs and maps, to make information easier to understand, analyse and communicate.","letter":"D","hasNote":false},{"id":"FIN-1200","slug":"day-count-convention","term":"Day-Count Convention","also_known_as":[],"difficulty":"Advanced","definition":"A day-count convention is the rule used to calculate how much interest accrues between two dates, by defining how the days in the period and in the year are counted.","letter":"D","hasNote":false},{"id":"FIN-654","slug":"days-inventory-outstanding","term":"Days Inventory Outstanding","also_known_as":[],"difficulty":"Intermediate","definition":"Days inventory outstanding (DIO) is the average number of days a business holds inventory before selling it.","letter":"D","hasNote":false},{"id":"FIN-655","slug":"days-payable-outstanding","term":"Days Payable Outstanding","also_known_as":[],"difficulty":"Intermediate","definition":"Days payable outstanding (DPO) is the average number of days a business takes to pay its suppliers.","letter":"D","hasNote":false},{"id":"FIN-653","slug":"days-sales-outstanding","term":"Days Sales Outstanding","also_known_as":[],"difficulty":"Intermediate","definition":"Days sales outstanding (DSO) is the average number of days it takes a business to collect payment from its customers after a sale.","letter":"D","hasNote":false},{"id":"FIN-1167","slug":"days-to-cover","term":"Days to Cover","also_known_as":[],"difficulty":"Advanced","definition":"Days to cover is the number of days it would take short sellers to buy back all the shares they have sold short, based on the share\'s average daily trading volume.","letter":"D","hasNote":false},{"id":"FIN-322","slug":"deadweight-loss","term":"Deadweight Loss","also_known_as":[],"difficulty":"Intermediate","definition":"Deadweight loss is the loss of total economic benefit to society that occurs when a market does not operate at its efficient level, often because of taxes, price controls or monopoly power.","letter":"D","hasNote":false},{"id":"FIN-278","slug":"dealer","term":"Dealer","also_known_as":[],"difficulty":"Intermediate","definition":"A dealer is a person or firm that buys and sells securities for their own account, acting as the other party in a trade and profiting from the difference between buying and selling prices.","letter":"D","hasNote":false},{"id":"FIN-105","slug":"debit","term":"Debit","also_known_as":[],"difficulty":"Beginner","definition":"A debit is an entry on the left side of an account in double-entry bookkeeping. Debits increase asset and expense accounts and decrease liability, equity and revenue accounts.","letter":"D","hasNote":false},{"id":"FIN-063","slug":"debt","term":"Debt","also_known_as":[],"difficulty":"Beginner","definition":"Debt is money that one party owes to another. It arises when a person, business or government borrows money or buys something now and agrees to pay later.","letter":"D","hasNote":false},{"id":"FIN-067","slug":"debt-avalanche","term":"Debt Avalanche","also_known_as":[],"difficulty":"Beginner","definition":"The debt avalanche is a debt repayment method in which you pay off the debt with the highest interest rate first while making minimum payments on the rest, then move to the next highest rate.","letter":"D","hasNote":false},{"id":"FIN-064","slug":"debt-balance","term":"Debt Balance","also_known_as":[],"difficulty":"Beginner","definition":"A debt balance is the total amount still owed on a debt at a particular moment, including any unpaid interest and fees that have been added.","letter":"D","hasNote":false},{"id":"FIN-1284","slug":"debt-collector","term":"Debt Collector","also_known_as":[],"difficulty":"Intermediate","definition":"A debt collector is a person or company that tries to recover unpaid debts, either on behalf of the original creditor or after buying the debt.","letter":"D","hasNote":false},{"id":"FIN-833","slug":"debt-consolidation","term":"Debt Consolidation","also_known_as":[],"difficulty":"Beginner","definition":"Debt consolidation is combining several debts into a single new loan or payment, often with the aim of lowering the interest rate, reducing monthly payments or simplifying repayment.","letter":"D","hasNote":false},{"id":"FIN-1360","slug":"debt-free-cash-free","term":"Debt-Free Cash-Free","also_known_as":[],"difficulty":"Advanced","definition":"Debt-free cash-free is a common basis for pricing an acquisition, in which the buyer agrees a price for the business assuming it has no debt and no cash, with the final payment to the seller adjusted for the actual debt and cash at completion.","letter":"D","hasNote":false},{"id":"FIN-629","slug":"debt-ratio","term":"Debt Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The debt ratio is a company\'s total liabilities, or sometimes total debt, divided by its total assets, showing what share of its assets is financed by obligations to others rather than by owners.","letter":"D","hasNote":false},{"id":"FIN-1248","slug":"debt-restructuring","term":"Debt Restructuring","also_known_as":[],"difficulty":"Advanced","definition":"Debt restructuring is the renegotiation of a borrower\'s existing debts, such as reducing the amount owed, lowering interest rates or extending repayment periods, typically to avoid default or to recover from financial distress.","letter":"D","hasNote":false},{"id":"FIN-1342","slug":"debt-schedule","term":"Debt Schedule","also_known_as":[],"difficulty":"Advanced","definition":"A debt schedule is a part of a financial model that tracks a company\'s borrowings over time, including opening balances, new borrowing, repayments, interest and closing balances for each type of debt.","letter":"D","hasNote":false},{"id":"FIN-813","slug":"debt-service","term":"Debt Service","also_known_as":[],"difficulty":"Intermediate","definition":"Debt service is the money a borrower must pay over a period to cover the interest and principal repayments due on its debts.","letter":"D","hasNote":false},{"id":"FIN-634","slug":"debt-service-coverage-ratio","term":"Debt Service Coverage Ratio (DSCR)","also_known_as":["DSCR"],"difficulty":"Intermediate","definition":"The debt service coverage ratio (DSCR) is the cash available to service debt divided by the total debt payments due, including both interest and principal, over a period.","letter":"D","hasNote":false},{"id":"FIN-1285","slug":"debt-settlement","term":"Debt Settlement","also_known_as":[],"difficulty":"Intermediate","definition":"Debt settlement is an agreement between a borrower and a creditor in which the creditor accepts less than the full amount owed as final payment.","letter":"D","hasNote":false},{"id":"FIN-066","slug":"debt-snowball","term":"Debt Snowball","also_known_as":[],"difficulty":"Beginner","definition":"The debt snowball is a debt repayment method in which you pay off your smallest debt first while making minimum payments on the rest, then roll that payment into the next smallest debt.","letter":"D","hasNote":false},{"id":"FIN-630","slug":"debt-to-equity-ratio","term":"Debt-to-Equity Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The debt-to-equity ratio is a company\'s total debt divided by its shareholders\' equity, showing how much it relies on borrowed money compared with owners\' money.","letter":"D","hasNote":false},{"id":"FIN-789","slug":"debt-to-gdp-ratio","term":"Debt-to-GDP Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The debt-to-GDP ratio compares a country\'s government debt with the size of its economy, measured by gross domestic product, and is expressed as a percentage.","letter":"D","hasNote":false},{"id":"FIN-065","slug":"debt-to-income-ratio","term":"Debt-to-Income Ratio","also_known_as":[],"difficulty":"Beginner","definition":"The debt-to-income ratio compares how much a person pays towards debts each month with how much they earn before tax. It is expressed as a percentage.","letter":"D","hasNote":false},{"id":"FIN-1323","slug":"decentralized-finance","term":"Decentralized Finance (DeFi)","also_known_as":["DeFi"],"difficulty":"Advanced","definition":"Decentralized finance (DeFi) refers to financial services, such as lending, borrowing, trading and earning interest, that are provided through software programs running on public blockchains, without traditional intermediaries such as banks or brokers.","letter":"D","hasNote":false},{"id":"FUT-0009","slug":"deductible","term":"Deductible","also_known_as":["Excess (UK)","Excess"],"difficulty":"Beginner","definition":"A deductible is the amount the policyholder must pay out of their own pocket on an insurance claim before the insurer starts paying.","letter":"D","hasNote":true},{"id":"FIN-084","slug":"default","term":"Default","also_known_as":[],"difficulty":"Beginner","definition":"Default is a failure to meet the terms of a loan or debt, most commonly by not making required payments. It can also mean breaking other conditions in a loan agreement.","letter":"D","hasNote":false},{"id":"FIN-B3-NEW4","slug":"defensive-stock","term":"Defensive Stock","also_known_as":[],"difficulty":"Advanced","definition":"A defensive stock is a share in a company whose sales and profits tend to remain stable regardless of the state of the economy, because it sells products or services people need in good times and bad.","letter":"D","hasNote":false},{"id":"FIN-1414","slug":"deferred-annuity","term":"Deferred Annuity","also_known_as":[],"difficulty":"Advanced","definition":"A deferred annuity is an insurance contract in which a person invests money, either as a lump sum or through regular payments, which grows over time before being converted into income payments starting at a later date.","letter":"D","hasNote":false},{"id":"FIN-572","slug":"deferred-tax","term":"Deferred Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Deferred tax is income tax that will be payable or recoverable in future periods because of timing differences between when items are recognised in the accounts and when they are recognised for tax.","letter":"D","hasNote":false},{"id":"FIN-1023","slug":"deferred-tax-asset","term":"Deferred Tax Asset","also_known_as":[],"difficulty":"Advanced","definition":"A deferred tax asset is an amount of income tax a company expects to recover in future, because it has paid tax earlier than its accounts recognise the related expense, or has unused tax losses or credits to carry forward.","letter":"D","hasNote":false},{"id":"FIN-1024","slug":"deferred-tax-liability","term":"Deferred Tax Liability","also_known_as":[],"difficulty":"Advanced","definition":"A deferred tax liability is an amount of income tax a company expects to pay in future, because its accounts recognise profit earlier than the tax rules tax it, usually because tax deductions have been taken earlier than the related accounting expense.","letter":"D","hasNote":false},{"id":"FIN-761","slug":"deflation","term":"Deflation","also_known_as":[],"difficulty":"Beginner","definition":"Deflation is a sustained fall in the general level of prices for goods and services across an economy, meaning the inflation rate is below zero.","letter":"D","hasNote":false},{"id":"FIN-1085","slug":"degree-of-financial-leverage","term":"Degree of Financial Leverage","also_known_as":[],"difficulty":"Advanced","definition":"The degree of financial leverage (DFL) measures how much a company\'s earnings per share change in percentage terms for a given percentage change in operating profit, reflecting the effect of fixed interest costs.","letter":"D","hasNote":false},{"id":"FIN-1084","slug":"degree-of-operating-leverage","term":"Degree of Operating Leverage","also_known_as":[],"difficulty":"Advanced","definition":"The degree of operating leverage (DOL) measures how much a company\'s operating profit changes in percentage terms for a given percentage change in sales.","letter":"D","hasNote":false},{"id":"FIN-085","slug":"delinquency","term":"Delinquency","also_known_as":[],"difficulty":"Beginner","definition":"Delinquency is the state of being behind on a required payment for a loan or bill. An account becomes delinquent as soon as a payment is missed.","letter":"D","hasNote":false},{"id":"FIN-917","slug":"delta","term":"Delta","also_known_as":[],"difficulty":"Intermediate","definition":"Delta is a measure of how much an option\'s price is expected to change when the price of the underlying asset changes by one unit.","letter":"D","hasNote":false},{"id":"FIN-1379","slug":"delta-hedging","term":"Delta Hedging","also_known_as":[],"difficulty":"Advanced","definition":"Delta hedging is a strategy of offsetting the price risk of an options position by taking an opposite position in the underlying asset, sized according to the option\'s delta, so that small price movements have little effect on the overall position.","letter":"D","hasNote":false},{"id":"FIN-296","slug":"demand","term":"Demand","also_known_as":[],"difficulty":"Beginner","definition":"Demand is the quantity of a good or service that buyers are willing and able to purchase at different prices over a period of time.","letter":"D","hasNote":false},{"id":"FIN-298","slug":"demand-curve","term":"Demand Curve","also_known_as":[],"difficulty":"Intermediate","definition":"A demand curve is a graph showing the relationship between the price of a good and the quantity buyers are willing to purchase at each price, with all other factors held constant.","letter":"D","hasNote":false},{"id":"FIN-350","slug":"demand-deposit","term":"Demand Deposit","also_known_as":[],"difficulty":"Intermediate","definition":"A demand deposit is money held in a bank account that can be withdrawn at any time, without advance notice or penalty, such as the balance in a current or checking account.","letter":"D","hasNote":false},{"id":"FIN-767","slug":"demand-pull-inflation","term":"Demand-Pull Inflation","also_known_as":[],"difficulty":"Intermediate","definition":"Demand-pull inflation is inflation caused by total demand for goods and services in an economy growing faster than the economy\'s ability to produce them.","letter":"D","hasNote":false},{"id":"FIN-1251","slug":"demographic-dividend","term":"Demographic Dividend","also_known_as":[],"difficulty":"Advanced","definition":"A demographic dividend is the economic growth that can occur when the share of a country\'s population that is of working age rises relative to the share of dependants, such as children and older people.","letter":"D","hasNote":false},{"id":"FIN-1252","slug":"dependency-ratio","term":"Dependency Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The dependency ratio compares the number of people typically not of working age, children and older people, with the number of people of working age, showing how many dependants each working-age person supports.","letter":"D","hasNote":false},{"id":"FIN-349","slug":"deposit","term":"Deposit","also_known_as":[],"difficulty":"Beginner","definition":"A deposit is money placed into a bank or other financial institution for safekeeping, which the depositor can later withdraw, often earning interest.","letter":"D","hasNote":false},{"id":"FIN-376","slug":"deposit-beta","term":"Deposit Beta","also_known_as":[],"difficulty":"Intermediate","definition":"Deposit beta measures how much of a change in central bank or market interest rates a bank passes on to the interest rates it pays depositors.","letter":"D","hasNote":false},{"id":"FIN-358","slug":"deposit-flight","term":"Deposit Flight","also_known_as":[],"difficulty":"Intermediate","definition":"Deposit flight is the movement of deposits out of a bank, a group of banks or a country, usually because depositors are worried about safety or can earn better returns elsewhere.","letter":"D","hasNote":false},{"id":"FIN-356","slug":"deposit-insurance","term":"Deposit Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Deposit insurance is a government-backed scheme that protects bank customers\' deposits, up to a set limit, if their bank fails.","letter":"D","hasNote":false},{"id":"FIN-848","slug":"deposit-rate","term":"Deposit Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A deposit rate is the interest rate a bank pays to customers on money held in deposit accounts, such as savings accounts and fixed-term deposits.","letter":"D","hasNote":false},{"id":"FIN-150","slug":"depreciation","term":"Depreciation","also_known_as":[],"difficulty":"Beginner","definition":"Depreciation is the process of spreading the cost of a physical long-term asset, such as a machine, vehicle or building, over the years it is expected to be used.","letter":"D","hasNote":false},{"id":"FIN-1343","slug":"depreciation-schedule","term":"Depreciation Schedule","also_known_as":[],"difficulty":"Advanced","definition":"A depreciation schedule is a table in a financial model or accounting record that shows how the cost of each fixed asset, or group of assets, is spread over its useful life, period by period.","letter":"D","hasNote":false},{"id":"FIN-759","slug":"depression","term":"Depression","also_known_as":[],"difficulty":"Intermediate","definition":"A depression is a severe and prolonged downturn in economic activity, much deeper and longer-lasting than an ordinary recession, with large falls in output and very high unemployment.","letter":"D","hasNote":false},{"id":"FIN-421","slug":"derivative","term":"Derivative","also_known_as":[],"difficulty":"Intermediate","definition":"A derivative is a financial contract whose value depends on, or is derived from, the price of something else, such as a share, bond, currency, commodity or interest rate.","letter":"D","hasNote":false},{"id":"FIN-803","slug":"devaluation","term":"Devaluation","also_known_as":[],"difficulty":"Intermediate","definition":"Devaluation is a deliberate reduction by a government or central bank in the official value of its currency relative to other currencies, under a fixed or pegged exchange rate system.","letter":"D","hasNote":false},{"id":"FIN-709","slug":"developed-market","term":"Developed Market","also_known_as":[],"difficulty":"Intermediate","definition":"A developed market is a country with a mature, high-income economy, well-established financial markets, strong legal protections for investors and reliable market infrastructure.","letter":"D","hasNote":false},{"id":"FIN-1321","slug":"digital-asset","term":"Digital Asset","also_known_as":[],"difficulty":"Advanced","definition":"A digital asset is any asset that exists in digital form and can be owned and transferred, most commonly used to describe cryptocurrencies, stablecoins, tokens and other assets recorded on a blockchain.","letter":"D","hasNote":false},{"id":"FIN-865","slug":"digital-banking","term":"Digital Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Digital banking is the provision of banking services through online and mobile channels, allowing customers to manage accounts, make payments and access financial products without visiting a branch.","letter":"D","hasNote":false},{"id":"FIN-368","slug":"digital-wallet","term":"Digital Wallet","also_known_as":[],"difficulty":"Beginner","definition":"A digital wallet is a software application, usually on a smartphone, that securely stores payment information so users can pay for goods and services electronically without a physical card or cash.","letter":"D","hasNote":false},{"id":"FIN-574","slug":"diluted-eps","term":"Diluted EPS","also_known_as":[],"difficulty":"Intermediate","definition":"Diluted EPS is earnings per share calculated as if all securities that could become ordinary shares, such as stock options, warrants and convertible bonds, had been converted, giving a more cautious measure of profit per share.","letter":"D","hasNote":false},{"id":"FIN-664","slug":"dilution","term":"Dilution","also_known_as":[],"difficulty":"Intermediate","definition":"Dilution is the reduction in existing shareholders\' percentage ownership of a company when it issues new shares.","letter":"D","hasNote":false},{"id":"FIN-319","slug":"diminishing-marginal-utility","term":"Diminishing Marginal Utility","also_known_as":[],"difficulty":"Intermediate","definition":"Diminishing marginal utility is the principle that each additional unit of a good or service usually gives less extra satisfaction than the one before it.","letter":"D","hasNote":false},{"id":"FIN-642","slug":"direct-cost","term":"Direct Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A direct cost is a cost that can be traced directly to a specific product, service, project or department, such as the materials used to make a product.","letter":"D","hasNote":false},{"id":"FIN-842","slug":"direct-debit","term":"Direct Debit","also_known_as":[],"difficulty":"Beginner","definition":"A direct debit is an arrangement, common in the United Kingdom and Europe, that authorises an organisation to collect payments directly from a customer\'s bank account, with amounts and dates that can vary.","letter":"D","hasNote":false},{"id":"FIN-1419","slug":"directors-and-officers-insurance","term":"Directors and Officers Insurance (D&O)","also_known_as":["D&O"],"difficulty":"Advanced","definition":"Directors and officers insurance (D&O) is liability insurance that protects company directors and senior officers against the personal costs of claims alleging wrongful acts in their management of the company, such as breaches of duty, misleading statements or mismanagement.","letter":"D","hasNote":false},{"id":"FIN-934","slug":"disability-insurance","term":"Disability Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Disability insurance is insurance that replaces part of a person\'s income if they cannot work because of illness or injury.","letter":"D","hasNote":false},{"id":"FIN-1035","slug":"disclaimer-of-opinion","term":"Disclaimer of Opinion","also_known_as":[],"difficulty":"Advanced","definition":"A disclaimer of opinion is a statement by an auditor that they cannot express an opinion on a company\'s financial statements, because they were unable to obtain enough evidence and the possible effects are both material and pervasive.","letter":"D","hasNote":false},{"id":"FIN-420","slug":"discount-factor","term":"Discount Factor","also_known_as":["Present Value Factor"],"difficulty":"Intermediate","definition":"A discount factor is the number that a future cash flow is multiplied by to convert it into its present value. It is always less than 1 for positive discount rates and future dates.","letter":"D","hasNote":true},{"id":"FIN-886","slug":"discount-for-lack-of-control","term":"Discount for Lack of Control","also_known_as":[],"difficulty":"Intermediate","definition":"A discount for lack of control is a reduction applied to the value of a minority ownership stake because the holder cannot direct or influence the company\'s major decisions.","letter":"D","hasNote":false},{"id":"FIN-885","slug":"discount-for-lack-of-marketability","term":"Discount for Lack of Marketability","also_known_as":[],"difficulty":"Intermediate","definition":"A discount for lack of marketability is a reduction applied to the value of an ownership stake because it cannot easily be sold, such as shares in a private company.","letter":"D","hasNote":false},{"id":"FIN-418","slug":"discount-period","term":"Discount Period","also_known_as":[],"difficulty":"Intermediate","definition":"The discount period is the length of time, usually measured in years, over which a future cash flow is discounted back to its present value.","letter":"D","hasNote":false},{"id":"FIN-183","slug":"discount-rate","term":"Discount Rate","also_known_as":[],"difficulty":"Beginner","definition":"A discount rate is the interest rate used to convert future cash flows into their value today. A higher discount rate makes future money worth less in today\'s terms.","letter":"D","hasNote":false},{"id":"FIN-1176","slug":"discount-to-nav","term":"Discount to NAV","also_known_as":[],"difficulty":"Advanced","definition":"A discount to NAV is the amount by which the market price of a fund\'s shares is below its net asset value per share, usually expressed as a percentage.","letter":"D","hasNote":false},{"id":"FIN-395","slug":"discounted-cash-flow","term":"Discounted Cash Flow (DCF)","also_known_as":["DCF"],"difficulty":"Intermediate","definition":"Discounted cash flow (DCF) is a valuation method that estimates the value of an investment or company by forecasting the cash it will generate in the future and discounting that cash back to its value today.","letter":"D","hasNote":false},{"id":"FIN-180","slug":"discounted-payback-period","term":"Discounted Payback Period","also_known_as":[],"difficulty":"Intermediate","definition":"The discounted payback period is the time it takes for an investment to recover its initial cost from its future cash flows, after converting those cash flows into today\'s values.","letter":"D","hasNote":false},{"id":"FIN-509","slug":"discounting","term":"Discounting","also_known_as":[],"difficulty":"Intermediate","definition":"Discounting is the process of working out what a future amount of money is worth today, by reducing it to reflect the return that could be earned in the meantime.","letter":"D","hasNote":false},{"id":"FIN-008","slug":"discretionary-income","term":"Discretionary Income","also_known_as":[],"difficulty":"Beginner","definition":"Discretionary income is the money left after paying taxes and essential living costs such as housing, food, utilities and transport. It can be spent on wants, saved or invested.","letter":"D","hasNote":false},{"id":"FIN-650","slug":"diseconomies-of-scale","term":"Diseconomies of Scale","also_known_as":[],"difficulty":"Intermediate","definition":"Diseconomies of scale occur when a business becomes so large that its average cost per unit starts to rise, rather than fall, as output increases further.","letter":"D","hasNote":false},{"id":"FIN-762","slug":"disinflation","term":"Disinflation","also_known_as":[],"difficulty":"Intermediate","definition":"Disinflation is a slowdown in the rate of inflation, meaning prices are still rising, but more slowly than before.","letter":"D","hasNote":false},{"id":"FIN-007","slug":"disposable-income","term":"Disposable Income","also_known_as":[],"difficulty":"Beginner","definition":"Disposable income is the money left from your income after taxes and compulsory deductions have been taken out. It is what you actually have available to spend or save.","letter":"D","hasNote":false},{"id":"FIN-1158","slug":"disposition-effect","term":"Disposition Effect","also_known_as":[],"difficulty":"Advanced","definition":"The disposition effect is the tendency of investors to sell investments that have risen in value too quickly, while holding on to investments that have fallen in value for too long.","letter":"D","hasNote":false},{"id":"FIN-1463","slug":"distressed-investing","term":"Distressed Investing","also_known_as":[],"difficulty":"Advanced","definition":"Distressed investing is buying the debt, shares or assets of companies in financial difficulty, such as those near or in bankruptcy, at low prices, with the aim of profiting from their recovery or restructuring.","letter":"D","hasNote":false},{"id":"FIN-1438","slug":"distribution-waterfall","term":"Distribution Waterfall","also_known_as":[],"difficulty":"Advanced","definition":"A distribution waterfall is the order and method by which profits and capital from a private fund or investment are distributed between investors and the fund manager.","letter":"D","hasNote":false},{"id":"FUT-0030","slug":"diversification","term":"Diversification","also_known_as":[],"difficulty":"Beginner","definition":"Diversification is spreading investments across many different assets so that a loss in any one of them has a smaller effect on the whole portfolio.","letter":"D","hasNote":false},{"id":"FIN-965","slug":"divestiture","term":"Divestiture","also_known_as":[],"difficulty":"Intermediate","definition":"A divestiture is the sale or disposal of a business unit, subsidiary, division or assets by a company.","letter":"D","hasNote":false},{"id":"FIN-261","slug":"dividend","term":"Dividend","also_known_as":[],"difficulty":"Beginner","definition":"A dividend is a payment a company makes to its shareholders, usually in cash, as a share of its profits.","letter":"D","hasNote":false},{"id":"FIN-1089","slug":"dividend-coverage-ratio","term":"Dividend Coverage Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The dividend coverage ratio measures how many times a company\'s earnings could pay its dividends, usually calculated as earnings per share divided by dividends per share.","letter":"D","hasNote":false},{"id":"FIN-396","slug":"dividend-discount-model","term":"Dividend Discount Model (DDM)","also_known_as":["DDM"],"difficulty":"Intermediate","definition":"The dividend discount model (DDM) is a valuation method that estimates the value of a share as the present value of all the dividends it is expected to pay in the future.","letter":"D","hasNote":false},{"id":"FIN-656","slug":"dividend-payout-ratio","term":"Dividend Payout Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The dividend payout ratio is the proportion of a company\'s net income that it pays out to shareholders as dividends, usually expressed as a percentage.","letter":"D","hasNote":false},{"id":"FIN-659","slug":"dividend-policy","term":"Dividend Policy","also_known_as":[],"difficulty":"Intermediate","definition":"Dividend policy is a company\'s approach to deciding how much of its profits to pay out to shareholders as dividends and how much to retain for reinvestment.","letter":"D","hasNote":false},{"id":"FIN-1140","slug":"dividend-reinvestment-plan","term":"Dividend Reinvestment Plan (DRIP)","also_known_as":["DRIP"],"difficulty":"Advanced","definition":"A dividend reinvestment plan (DRIP) is an arrangement that automatically uses a shareholder\'s cash dividends to buy more shares in the same company or fund, instead of paying the dividends out in cash.","letter":"D","hasNote":false},{"id":"FIN-548","slug":"dividend-tax","term":"Dividend Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Dividend tax is tax charged on dividends, the payments companies make to their shareholders out of profits.","letter":"D","hasNote":false},{"id":"FIN-677","slug":"dividend-yield","term":"Dividend Yield","also_known_as":[],"difficulty":"Beginner","definition":"Dividend yield is a company\'s annual dividend per share divided by its current share price, showing the income return an investor receives from dividends at today\'s price.","letter":"D","hasNote":false},{"id":"FIN-578","slug":"dividends-payable","term":"Dividends Payable","also_known_as":[],"difficulty":"Intermediate","definition":"Dividends payable is a liability representing dividends that a company\'s board has declared but not yet paid to shareholders.","letter":"D","hasNote":false},{"id":"FIN-718","slug":"dollar-cost-averaging","term":"Dollar-Cost Averaging","also_known_as":[],"difficulty":"Intermediate","definition":"Dollar-cost averaging is an investment strategy of investing a fixed amount of money at regular intervals, regardless of market prices, so that more units are bought when prices are low and fewer when they are high.","letter":"D","hasNote":false},{"id":"FIN-1266","slug":"dollarization","term":"Dollarization","also_known_as":[],"difficulty":"Advanced","definition":"Dollarization is when a country uses a foreign currency, most often the US dollar, alongside or instead of its own currency, either officially or because people choose to.","letter":"D","hasNote":false},{"id":"FIN-1022","slug":"donor-advised-fund","term":"Donor-Advised Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A donor-advised fund is an account, mainly used in the United States, held by a sponsoring charity, into which a donor makes an irrevocable gift, receives an immediate tax deduction and later recommends grants to other charities over time.","letter":"D","hasNote":false},{"id":"FIN-097","slug":"double-entry-bookkeeping","term":"Double-Entry Bookkeeping","also_known_as":[],"difficulty":"Beginner","definition":"Double-entry bookkeeping is a system in which every transaction is recorded in at least two accounts, with equal debits and credits, so that the books always balance.","letter":"D","hasNote":false},{"id":"FIN-1013","slug":"double-taxation","term":"Double Taxation","also_known_as":[],"difficulty":"Intermediate","definition":"Double taxation is when the same income is taxed twice, either at two levels in one country, such as company profits and then dividends, or by two different countries.","letter":"D","hasNote":false},{"id":"FIN-517","slug":"down-payment","term":"Down Payment","also_known_as":[],"difficulty":"Beginner","definition":"A down payment is the portion of a purchase price paid upfront in cash, with the rest usually financed by a loan, as when buying a home or car.","letter":"D","hasNote":false},{"id":"FIN-1461","slug":"down-round","term":"Down Round","also_known_as":[],"difficulty":"Intermediate","definition":"A down round is a funding round in which a company sells new shares at a lower price, and usually a lower valuation, than in its previous round.","letter":"D","hasNote":false},{"id":"FIN-1143","slug":"downside-risk","term":"Downside Risk","also_known_as":[],"difficulty":"Advanced","definition":"Downside risk is the risk that an investment will lose value, or perform worse than expected or than a set target.","letter":"D","hasNote":false},{"id":"FIN-1451","slug":"drag-along-right","term":"Drag-Along Right","also_known_as":[],"difficulty":"Advanced","definition":"A drag-along right is a provision in a shareholder agreement that allows majority shareholders who agree to sell the company to require minority shareholders to join the sale on the same terms.","letter":"D","hasNote":false},{"id":"FIN-968","slug":"due-diligence","term":"Due Diligence","also_known_as":[],"difficulty":"Intermediate","definition":"Due diligence is the detailed investigation and analysis a buyer, investor or lender carries out before completing a transaction, to verify information and identify risks.","letter":"D","hasNote":false},{"id":"FIN-625","slug":"dupont-analysis","term":"DuPont Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"DuPont analysis breaks return on equity into three parts, profit margin, asset turnover and financial leverage, to show what is driving a company\'s return to shareholders.","letter":"D","hasNote":false},{"id":"FIN-1362","slug":"earn-out","term":"Earn-Out","also_known_as":[],"difficulty":"Advanced","definition":"An earn-out is an arrangement in an acquisition where part of the purchase price is paid later, only if the acquired business meets agreed performance targets, such as revenue or profit, after the deal completes.","letter":"E","hasNote":false},{"id":"FIN-005","slug":"earned-income","term":"Earned Income","also_known_as":[],"difficulty":"Beginner","definition":"Earned income is money received in return for work, such as wages, salaries, bonuses, tips, commissions and profits from running your own business.","letter":"E","hasNote":false},{"id":"FIN-219","slug":"earnings-growth","term":"Earnings Growth","also_known_as":[],"difficulty":"Beginner","definition":"Earnings growth is the percentage change in a company\'s profit, usually net income or earnings per share, from one period to another.","letter":"E","hasNote":false},{"id":"FIN-612","slug":"earnings-management","term":"Earnings Management","also_known_as":[],"difficulty":"Intermediate","definition":"Earnings management is the use of accounting choices, estimates or the timing of real business decisions to present reported profits in a particular way, often to meet targets or smooth results.","letter":"E","hasNote":false},{"id":"FUT-0046","slug":"earnings-per-share","term":"Earnings Per Share (EPS)","also_known_as":["EPS"],"difficulty":"Beginner","definition":"Earnings per share (EPS) is a company\'s net income divided by the number of its shares outstanding. It shows how much profit is attributable to each share.","letter":"E","hasNote":false},{"id":"FUT-0050","slug":"ebit","term":"EBIT","also_known_as":["Earnings Before Interest and Taxes"],"difficulty":"Intermediate","definition":"EBIT stands for earnings before interest and taxes. It measures a company\'s profit before deducting interest on its debt and income tax.","letter":"E","hasNote":false},{"id":"FUT-0049","slug":"ebitda","term":"EBITDA","also_known_as":["Earnings Before Interest","Taxes","Depreciation and Amortization"],"difficulty":"Intermediate","definition":"EBITDA stands for earnings before interest, taxes, depreciation and amortization. It measures a company\'s profit from operations before financing costs, taxes and non-cash charges for the wearing out of assets.","letter":"E","hasNote":false},{"id":"FIN-619","slug":"ebitda-margin","term":"EBITDA Margin","also_known_as":[],"difficulty":"Intermediate","definition":"EBITDA margin is EBITDA divided by revenue, showing the percentage of each sale that remains as earnings before interest, taxes, depreciation and amortization.","letter":"E","hasNote":false},{"id":"FIN-1404","slug":"economic-capital","term":"Economic Capital","also_known_as":[],"difficulty":"Advanced","definition":"Economic capital is the amount of capital an organisation, such as a bank or insurer, estimates it needs to cover unexpected losses from all its risks, at a chosen level of confidence, based on its own internal risk models.","letter":"E","hasNote":false},{"id":"FIN-755","slug":"economic-growth","term":"Economic Growth","also_known_as":[],"difficulty":"Intermediate","definition":"Economic growth is the increase in the amount of goods and services an economy produces over time, usually measured as the percentage change in real GDP.","letter":"E","hasNote":false},{"id":"FIN-463","slug":"economic-moat","term":"Economic Moat","also_known_as":[],"difficulty":"Intermediate","definition":"An economic moat is a durable competitive advantage that protects a company\'s profits from competitors over a long period, much as a moat protects a castle.","letter":"E","hasNote":false},{"id":"FIN-1120","slug":"economic-profit","term":"Economic Profit","also_known_as":["Economic Value Added (EVA)","Economic Value Added","EVA"],"difficulty":"Advanced","definition":"Economic profit is the profit a business earns after deducting a charge for all the capital it uses, both debt and equity, showing whether it earns more than the full cost of its capital.","letter":"E","hasNote":true},{"id":"FIN-1254","slug":"economic-rent","term":"Economic Rent","also_known_as":[],"difficulty":"Advanced","definition":"Economic rent is income earned by a factor of production, such as land, labour or capital, above the minimum amount needed to keep it in its current use.","letter":"E","hasNote":false},{"id":"FIN-1250","slug":"economic-sanctions","term":"Economic Sanctions","also_known_as":[],"difficulty":"Advanced","definition":"Economic sanctions are restrictions imposed by one or more countries on another country, organisation or individual, limiting trade, investment or financial transactions, usually to pressure them to change their behaviour.","letter":"E","hasNote":false},{"id":"FIN-291","slug":"economics","term":"Economics","also_known_as":[],"difficulty":"Beginner","definition":"Economics is the study of how people, businesses and governments make choices about using limited resources to satisfy their wants and needs.","letter":"E","hasNote":false},{"id":"FIN-649","slug":"economies-of-scale","term":"Economies of Scale","also_known_as":[],"difficulty":"Intermediate","definition":"Economies of scale are the cost advantages a business gains as it grows larger, because the average cost of producing each unit falls as output increases.","letter":"E","hasNote":false},{"id":"FIN-1087","slug":"economies-of-scope","term":"Economies of Scope","also_known_as":[],"difficulty":"Advanced","definition":"Economies of scope are cost savings a company achieves by producing or selling several different products together, because they share resources such as facilities, technology, distribution or brand.","letter":"E","hasNote":false},{"id":"FIN-056","slug":"effective-annual-rate","term":"Effective Annual Rate (EAR)","also_known_as":["EAR"],"difficulty":"Beginner","definition":"The effective annual rate (EAR) is the true yearly interest rate on a loan or investment once compounding within the year is taken into account.","letter":"E","hasNote":false},{"id":"FIN-540","slug":"effective-tax-rate","term":"Effective Tax Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The effective tax rate is the total tax paid divided by total income, showing the average percentage of income that goes in tax.","letter":"E","hasNote":false},{"id":"FIN-719","slug":"efficient-market-hypothesis","term":"Efficient Market Hypothesis","also_known_as":[],"difficulty":"Intermediate","definition":"The efficient market hypothesis is the theory that market prices fully reflect all available information, so it is impossible to consistently earn above-average returns, after adjusting for risk, by using that information.","letter":"E","hasNote":false},{"id":"FIN-1031","slug":"elimination-entry","term":"Elimination Entry","also_known_as":[],"difficulty":"Advanced","definition":"An elimination entry is an adjustment made when preparing consolidated accounts to remove the effects of transactions and balances between companies in the same group.","letter":"E","hasNote":false},{"id":"FIN-1300","slug":"embedded-finance","term":"Embedded Finance","also_known_as":[],"difficulty":"Advanced","definition":"Embedded finance is the integration of financial services, such as payments, lending, insurance or banking, directly into the products and apps of non-financial companies.","letter":"E","hasNote":false},{"id":"FIN-024","slug":"emergency-fund","term":"Emergency Fund","also_known_as":[],"difficulty":"Beginner","definition":"An emergency fund is money set aside specifically to pay for unexpected events, such as losing a job, a medical bill or an urgent home or car repair.","letter":"E","hasNote":false},{"id":"FIN-708","slug":"emerging-market","term":"Emerging Market","also_known_as":[],"difficulty":"Intermediate","definition":"An emerging market is a country whose economy is developing quickly and becoming more integrated with global markets, but which is not yet considered fully developed.","letter":"E","hasNote":false},{"id":"FIN-980","slug":"employee-stock-option-plan","term":"Employee Stock Option Plan (ESOP)","also_known_as":["ESOP"],"difficulty":"Intermediate","definition":"An Employee Stock Option Plan (ESOP) is a scheme through which a company grants employees options to buy its shares at a fixed price in the future, as a way to reward and retain staff.","letter":"E","hasNote":false},{"id":"FIN-747","slug":"employer-match","term":"Employer Match","also_known_as":[],"difficulty":"Intermediate","definition":"An employer match is a contribution an employer makes to an employee\'s workplace retirement account, matching some or all of the employee\'s own contributions up to a set limit.","letter":"E","hasNote":false},{"id":"FIN-1116","slug":"enterprise-risk-management","term":"Enterprise Risk Management","also_known_as":[],"difficulty":"Advanced","definition":"Enterprise risk management (ERM) is a structured, organisation-wide approach to identifying, assessing, managing and monitoring all the significant risks that could affect an organisation\'s objectives.","letter":"E","hasNote":false},{"id":"FIN-384","slug":"enterprise-value","term":"Enterprise Value","also_known_as":[],"difficulty":"Intermediate","definition":"Enterprise value is a measure of a company\'s total value, including both its equity and its debt, minus its cash. It represents roughly what it would cost to buy the whole business.","letter":"E","hasNote":false},{"id":"FIN-877","slug":"enterprise-value-bridge","term":"Enterprise Value Bridge","also_known_as":[],"difficulty":"Intermediate","definition":"An enterprise value bridge is the set of adjustments that connects a company\'s enterprise value, the value of its whole business, with its equity value, the value belonging to shareholders.","letter":"E","hasNote":false},{"id":"FIN-741","slug":"environmental-social-and-governance","term":"Environmental, Social and Governance (ESG)","also_known_as":["ESG"],"difficulty":"Intermediate","definition":"Environmental, Social and Governance (ESG) refers to a set of criteria used to evaluate how a company manages environmental impacts, social responsibilities and corporate governance, often used by investors alongside financial analysis.","letter":"E","hasNote":false},{"id":"FIN-299","slug":"equilibrium-price","term":"Equilibrium Price","also_known_as":[],"difficulty":"Intermediate","definition":"The equilibrium price is the price at which the quantity of a good that buyers want to purchase equals the quantity sellers want to supply.","letter":"E","hasNote":false},{"id":"FIN-015","slug":"equity","term":"Equity","also_known_as":[],"difficulty":"Beginner","definition":"Equity is the value of ownership that remains after all debts are subtracted. For a person, it is the part of an asset, such as a home, that you own outright; for a business, it is the owners\' share of the company.","letter":"E","hasNote":false},{"id":"FIN-1081","slug":"equity-multiplier","term":"Equity Multiplier","also_known_as":[],"difficulty":"Advanced","definition":"The equity multiplier is a company\'s total assets divided by its shareholders\' equity, showing how much of its assets are funded by equity rather than debt and other liabilities.","letter":"E","hasNote":false},{"id":"FIN-701","slug":"equity-risk-premium","term":"Equity Risk Premium","also_known_as":[],"difficulty":"Intermediate","definition":"The equity risk premium is the extra return investors expect to earn from investing in shares rather than in risk-free assets, such as government bonds, over the long term.","letter":"E","hasNote":false},{"id":"FIN-242","slug":"equity-security","term":"Equity Security","also_known_as":[],"difficulty":"Beginner","definition":"An equity security is a financial instrument that represents ownership in a company, such as common or preferred shares.","letter":"E","hasNote":false},{"id":"FIN-383","slug":"equity-valuation","term":"Equity Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Equity valuation is the process of estimating the value of a company\'s shares, meaning the part of the business that belongs to its shareholders.","letter":"E","hasNote":false},{"id":"FIN-385","slug":"equity-value","term":"Equity Value","also_known_as":[],"difficulty":"Intermediate","definition":"Equity value is the value of a company that belongs to its shareholders, after all debts and other claims have been accounted for.","letter":"E","hasNote":false},{"id":"FIN-400","slug":"equity-value-multiple","term":"Equity Value Multiple","also_known_as":[],"difficulty":"Intermediate","definition":"An equity value multiple is a valuation ratio that compares the value of a company\'s shares with a financial measure that belongs to shareholders, such as earnings, book value or cash flow per share.","letter":"E","hasNote":false},{"id":"FIN-1097","slug":"equivalent-annual-annuity","term":"Equivalent Annual Annuity","also_known_as":[],"difficulty":"Advanced","definition":"Equivalent annual annuity (EAA) is a method of comparing projects with different lifespans by converting each project\'s net present value into an equal annual amount over its life.","letter":"E","hasNote":false},{"id":"FIN-857","slug":"escrow-account","term":"Escrow Account","also_known_as":[],"difficulty":"Intermediate","definition":"An escrow account is an account held by a neutral third party, which holds money or assets on behalf of two other parties until specific conditions are met.","letter":"E","hasNote":false},{"id":"FIN-529","slug":"estate","term":"Estate","also_known_as":[],"difficulty":"Beginner","definition":"An estate is everything a person owns at the time of their death, including property, money, investments and personal belongings, minus their debts.","letter":"E","hasNote":false},{"id":"FIN-530","slug":"estate-planning","term":"Estate Planning","also_known_as":[],"difficulty":"Intermediate","definition":"Estate planning is the process of arranging how your assets will be managed and passed on after your death, or if you become unable to manage them yourself.","letter":"E","hasNote":false},{"id":"FIN-531","slug":"estate-tax","term":"Estate Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Estate tax is a tax charged on the total value of a person\'s estate when they die, before it is passed on to heirs. It is paid by the estate itself.","letter":"E","hasNote":false},{"id":"FIN-1009","slug":"estimated-tax-payment","term":"Estimated Tax Payment","also_known_as":[],"difficulty":"Intermediate","definition":"An estimated tax payment is a payment of tax made during the year, usually in instalments, on income that does not have tax taken off at source, such as self-employment profits or investment income. The term is used mainly in the United States.","letter":"E","hasNote":false},{"id":"FIN-432","slug":"european-option","term":"European Option","also_known_as":[],"difficulty":"Intermediate","definition":"A European option is an option that can be exercised only on its expiration date, not before.","letter":"E","hasNote":false},{"id":"FIN-408","slug":"ev-ebit","term":"EV/EBIT","also_known_as":[],"difficulty":"Intermediate","definition":"EV/EBIT is a valuation multiple that divides a company\'s enterprise value by its EBIT, earnings before interest and taxes.","letter":"E","hasNote":false},{"id":"FIN-407","slug":"ev-ebitda","term":"EV/EBITDA","also_known_as":["Enterprise Value Multiple","Enterprise Multiple"],"difficulty":"Intermediate","definition":"EV/EBITDA is a valuation multiple that divides a company\'s enterprise value by its EBITDA, earnings before interest, taxes, depreciation and amortization.","letter":"E","hasNote":true},{"id":"FIN-409","slug":"ev-revenue","term":"EV/Revenue","also_known_as":[],"difficulty":"Intermediate","definition":"EV/Revenue is a valuation multiple that divides a company\'s enterprise value by its total revenue.","letter":"E","hasNote":false},{"id":"FIN-678","slug":"ex-dividend-date","term":"Ex-Dividend Date","also_known_as":[],"difficulty":"Beginner","definition":"The ex-dividend date is the date from which a share trades without the right to its next dividend. Investors who buy on or after this date do not receive that dividend; the seller does.","letter":"E","hasNote":false},{"id":"FIN-1307","slug":"excess-reserves","term":"Excess Reserves","also_known_as":[],"difficulty":"Advanced","definition":"Excess reserves are the reserves a bank holds at the central bank above the minimum amount it is required to hold.","letter":"E","hasNote":false},{"id":"FIN-280","slug":"exchange","term":"Exchange","also_known_as":[],"difficulty":"Intermediate","definition":"An exchange is an organised marketplace where securities, commodities or other financial instruments are bought and sold under set rules.","letter":"E","hasNote":false},{"id":"FUT-0531","slug":"exchange-rate","term":"Exchange Rate","also_known_as":[],"difficulty":"Beginner","definition":"An exchange rate is the price of one currency in terms of another, showing how much of one currency is needed to buy a unit of another.","letter":"E","hasNote":false},{"id":"FIN-1371","slug":"exchange-ratio","term":"Exchange Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The exchange ratio is the number of the acquirer\'s shares that target shareholders receive for each of their shares in a merger or acquisition paid for with stock.","letter":"E","hasNote":false},{"id":"FUT-0466","slug":"exchange-traded-fund","term":"Exchange-Traded Fund (ETF)","also_known_as":["ETF"],"difficulty":"Beginner","definition":"An exchange-traded fund (ETF) is an investment fund that holds a basket of assets, such as shares or bonds, and whose units trade on a stock exchange like ordinary shares.","letter":"E","hasNote":false},{"id":"FIN-329","slug":"excise-tax","term":"Excise Tax","also_known_as":[],"difficulty":"Intermediate","definition":"An excise tax is a tax charged on specific goods or activities, such as fuel, alcohol, tobacco or gambling, usually as a fixed amount per unit or a percentage of the price.","letter":"E","hasNote":false},{"id":"FIN-929","slug":"exclusion-insurance","term":"Exclusion (Insurance)","also_known_as":[],"difficulty":"Intermediate","definition":"An exclusion is a provision in an insurance policy that removes specific events, causes, types of property or circumstances from coverage, so the insurer will not pay claims arising from them.","letter":"E","hasNote":false},{"id":"FIN-435","slug":"exercise","term":"Exercise","also_known_as":[],"difficulty":"Intermediate","definition":"To exercise an option is to use the right it gives: to buy the underlying asset at the strike price for a call option, or to sell it at the strike price for a put option.","letter":"E","hasNote":false},{"id":"FIN-415","slug":"exit-multiple-method","term":"Exit Multiple Method","also_known_as":[],"difficulty":"Intermediate","definition":"The exit multiple method calculates a company\'s terminal value in a discounted cash flow model by applying a valuation multiple, such as EV/EBITDA, to a financial measure in the final forecast year.","letter":"E","hasNote":false},{"id":"FIN-961","slug":"exit-strategy","term":"Exit Strategy","also_known_as":[],"difficulty":"Intermediate","definition":"An exit strategy is a plan for how an investor or business owner will sell their stake in a company or end an investment, turning it into cash.","letter":"E","hasNote":false},{"id":"FIN-757","slug":"expansion","term":"Expansion","also_known_as":[],"difficulty":"Intermediate","definition":"An expansion is the phase of the business cycle in which economic activity is growing, with rising output, employment, incomes and spending.","letter":"E","hasNote":false},{"id":"FIN-1100","slug":"expansion-option","term":"Expansion Option","also_known_as":[],"difficulty":"Advanced","definition":"An expansion option is a company\'s ability to scale up a project or investment in future if conditions turn out to be favourable, such as demand proving stronger than expected.","letter":"E","hasNote":false},{"id":"FIN-983","slug":"expected-return","term":"Expected Return","also_known_as":[],"difficulty":"Intermediate","definition":"Expected return is the average return an investor anticipates from an investment, based on the probabilities of different possible outcomes or on estimates from financial models.","letter":"E","hasNote":false},{"id":"FIN-1400","slug":"expected-shortfall","term":"Expected Shortfall","also_known_as":[],"difficulty":"Advanced","definition":"Expected shortfall is a measure of risk that estimates the average loss a portfolio would suffer in the worst cases beyond a given confidence level, such as the worst 2.5% or 5% of outcomes.","letter":"E","hasNote":false},{"id":"FIN-982","slug":"expected-value","term":"Expected Value","also_known_as":[],"difficulty":"Intermediate","definition":"Expected value is the average outcome you would expect from an uncertain situation if it could be repeated many times, calculated by multiplying each possible outcome by its probability and adding the results.","letter":"E","hasNote":false},{"id":"FIN-199","slug":"expense-forecast","term":"Expense Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"An expense forecast is an estimate of the costs a business expects to incur over a future period.","letter":"E","hasNote":false},{"id":"FIN-125","slug":"expense-recognition","term":"Expense Recognition","also_known_as":[],"difficulty":"Beginner","definition":"Expense recognition is the accounting principle that decides when a cost is recorded as an expense, generally in the period when it helps generate revenue or when its benefit is used up.","letter":"E","hasNote":false},{"id":"FIN-430","slug":"expiration-date","term":"Expiration Date","also_known_as":[],"difficulty":"Intermediate","definition":"The expiration date is the last date on which an option or other derivative contract can be exercised or settled. After this date, the contract ceases to exist.","letter":"E","hasNote":false},{"id":"FIN-1485","slug":"exponential-smoothing","term":"Exponential Smoothing","also_known_as":[],"difficulty":"Advanced","definition":"Exponential smoothing is a forecasting method that predicts future values by taking a weighted average of past observations, giving the most weight to recent data and progressively less weight to older data.","letter":"E","hasNote":false},{"id":"FIN-597","slug":"external-audit","term":"External Audit","also_known_as":[],"difficulty":"Intermediate","definition":"An external audit is an independent examination of a company\'s financial statements by an outside auditing firm, resulting in a formal opinion on whether the statements give a true and fair view.","letter":"E","hasNote":false},{"id":"FIN-312","slug":"externality","term":"Externality","also_known_as":[],"difficulty":"Intermediate","definition":"An externality is a cost or benefit of an activity that affects people who are not directly involved in it, and that is not reflected in the price paid.","letter":"E","hasNote":false},{"id":"FIN-1492","slug":"extrapolation","term":"Extrapolation","also_known_as":[],"difficulty":"Advanced","definition":"Extrapolation is a method of estimating values beyond the range of known data, by extending an observed trend or pattern.","letter":"E","hasNote":false},{"id":"FIN-1152","slug":"factor-investing","term":"Factor Investing","also_known_as":[],"difficulty":"Advanced","definition":"Factor investing is an investment approach that targets specific characteristics, called factors, which research has linked to differences in returns, such as value, size, momentum, quality and low volatility.","letter":"F","hasNote":false},{"id":"FIN-1279","slug":"factoring","term":"Factoring","also_known_as":[],"difficulty":"Advanced","definition":"Factoring is a form of financing in which a business sells its unpaid customer invoices to a third party, called a factor, at a discount, in exchange for immediate cash.","letter":"F","hasNote":false},{"id":"FIN-1410","slug":"facultative-reinsurance","term":"Facultative Reinsurance","also_known_as":[],"difficulty":"Advanced","definition":"Facultative reinsurance is reinsurance arranged for an individual risk or policy, where the reinsurer reviews the specific risk and decides whether to accept it and on what terms.","letter":"F","hasNote":false},{"id":"FIN-1311","slug":"fair-lending","term":"Fair Lending","also_known_as":[],"difficulty":"Advanced","definition":"Fair lending refers to laws and practices, especially in the United States, that require lenders to treat credit applicants equally and prohibit discrimination based on characteristics such as race, sex, religion, national origin, age or marital status.","letter":"F","hasNote":false},{"id":"FIN-387","slug":"fair-market-value","term":"Fair Market Value","also_known_as":[],"difficulty":"Intermediate","definition":"Fair market value is the price at which an asset would change hands between a willing buyer and a willing seller, when both have reasonable knowledge of the relevant facts and neither is under pressure to buy or sell.","letter":"F","hasNote":false},{"id":"FIN-556","slug":"fair-value","term":"Fair Value","also_known_as":[],"difficulty":"Intermediate","definition":"Fair value is the price that would be received to sell an asset, or paid to transfer a liability, in an orderly transaction between market participants at the measurement date.","letter":"F","hasNote":false},{"id":"FIN-1340","slug":"fairness-opinion","term":"Fairness Opinion","also_known_as":[],"difficulty":"Advanced","definition":"A fairness opinion is a letter, usually from an investment bank or independent valuation firm, stating whether the price or terms in a proposed transaction, such as a merger or acquisition, are fair from a financial point of view to a company\'s shareholders.","letter":"F","hasNote":false},{"id":"FIN-989","slug":"fat-tailed-distribution","term":"Fat-Tailed Distribution","also_known_as":[],"difficulty":"Intermediate","definition":"A fat-tailed distribution is a probability distribution in which extreme outcomes, far from the average, occur more often than they would under a normal distribution.","letter":"F","hasNote":false},{"id":"FIN-1074","slug":"favorable-variance","term":"Favorable Variance","also_known_as":[],"difficulty":"Advanced","definition":"A favorable variance is a difference between actual and budgeted or standard results that improves profit, such as costs coming in lower than budget or revenue higher than budget.","letter":"F","hasNote":false},{"id":"FIN-B3-NEW1","slug":"federal-funds-rate","term":"Federal Funds Rate","also_known_as":[],"difficulty":"Advanced","definition":"The federal funds rate is the interest rate at which US banks lend reserve balances to each other overnight, and the main policy rate the US Federal Reserve targets to carry out monetary policy.","letter":"F","hasNote":false},{"id":"FIN-738","slug":"fiduciary","term":"Fiduciary","also_known_as":[],"difficulty":"Intermediate","definition":"A fiduciary is a person or organisation legally required to act in someone else\'s best interests when managing their money or affairs, putting that person\'s interests ahead of their own.","letter":"F","hasNote":false},{"id":"FIN-581","slug":"fifo","term":"FIFO","also_known_as":[],"difficulty":"Intermediate","definition":"FIFO, which stands for first in, first out, is an inventory costing method that assumes the oldest items in stock are sold first, so the cost of goods sold reflects older prices and remaining inventory reflects newer ones.","letter":"F","hasNote":false},{"id":"FIN-1052","slug":"finance-cost","term":"Finance Cost","also_known_as":[],"difficulty":"Advanced","definition":"Finance cost is the total cost of a company\'s borrowing for a period, mainly interest on loans and bonds, but also items such as interest on lease liabilities and the unwinding of discounts on long-term provisions.","letter":"F","hasNote":false},{"id":"FIN-585","slug":"finance-lease","term":"Finance Lease","also_known_as":[],"difficulty":"Intermediate","definition":"A finance lease is a lease that transfers substantially all the risks and rewards of owning an asset to the lessee, making it economically similar to buying the asset with borrowed money.","letter":"F","hasNote":false},{"id":"NEW-03","slug":"financial-account-balance-of-payments","term":"Financial Account (Balance of Payments)","also_known_as":[],"difficulty":"Intermediate","definition":"The financial account, in the balance of payments, records a country\'s cross-border investment flows, including foreign direct investment, purchases of shares and bonds, loans and changes in official reserves.","letter":"F","hasNote":false},{"id":"FIN-971","slug":"financial-buyer","term":"Financial Buyer","also_known_as":[],"difficulty":"Intermediate","definition":"A financial buyer is an investor, typically a private equity firm, that acquires a company mainly to earn a financial return, usually planning to improve and sell it within several years.","letter":"F","hasNote":false},{"id":"FIN-607","slug":"financial-close","term":"Financial Close","also_known_as":[],"difficulty":"Intermediate","definition":"Financial close is the process a company\'s finance team follows at the end of each accounting period to finalise its records, make adjustments and prepare financial statements.","letter":"F","hasNote":false},{"id":"FIN-1249","slug":"financial-contagion","term":"Financial Contagion","also_known_as":[],"difficulty":"Advanced","definition":"Financial contagion is the spread of financial problems, such as market crashes, bank failures or currency crises, from one country, market or institution to others.","letter":"F","hasNote":false},{"id":"FIN-1107","slug":"financial-covenant","term":"Financial Covenant","also_known_as":[],"difficulty":"Advanced","definition":"A financial covenant is a condition in a loan agreement requiring the borrower to keep certain financial measures, such as leverage, interest coverage or net worth, within agreed limits.","letter":"F","hasNote":false},{"id":"FIN-676","slug":"financial-distress","term":"Financial Distress","also_known_as":[],"difficulty":"Intermediate","definition":"Financial distress is a situation in which a company or individual struggles to meet financial obligations, such as paying debts, interest or suppliers on time.","letter":"F","hasNote":false},{"id":"FIN-025","slug":"financial-goal","term":"Financial Goal","also_known_as":[],"difficulty":"Beginner","definition":"A financial goal is a specific thing you want to achieve with money, such as building an emergency fund, buying a home, paying off debt or retiring at a certain age.","letter":"F","hasNote":false},{"id":"FIN-866","slug":"financial-inclusion","term":"Financial Inclusion","also_known_as":[],"difficulty":"Intermediate","definition":"Financial inclusion means ensuring that individuals and businesses have access to useful and affordable financial products and services, such as bank accounts, payments, savings, credit and insurance, delivered responsibly.","letter":"F","hasNote":false},{"id":"FIN-029","slug":"financial-independence","term":"Financial Independence","also_known_as":[],"difficulty":"Beginner","definition":"Financial independence is having enough income from savings, investments or other sources to cover your living costs without needing to work for money.","letter":"F","hasNote":false},{"id":"FIN-216","slug":"financial-kpi","term":"Financial KPI","also_known_as":[],"difficulty":"Beginner","definition":"A financial KPI is a key performance indicator based on financial results, such as revenue growth, profit margin, cash flow or return on investment.","letter":"F","hasNote":false},{"id":"FIN-648","slug":"financial-leverage","term":"Financial Leverage","also_known_as":[],"difficulty":"Intermediate","definition":"Financial leverage is the use of borrowed money to finance a company\'s assets, which magnifies the returns to shareholders, both gains and losses.","letter":"F","hasNote":false},{"id":"FIN-027","slug":"financial-literacy","term":"Financial Literacy","also_known_as":[],"difficulty":"Beginner","definition":"Financial literacy is the knowledge and skill needed to make sound decisions about money, such as budgeting, saving, borrowing, investing and understanding risk.","letter":"F","hasNote":false},{"id":"FIN-167","slug":"financial-management","term":"Financial Management","also_known_as":[],"difficulty":"Beginner","definition":"Financial management is the planning, organising and controlling of an organisation\'s money so that it can operate smoothly, meet its obligations and achieve its goals.","letter":"F","hasNote":false},{"id":"FIN-1316","slug":"financial-market-infrastructure","term":"Financial Market Infrastructure","also_known_as":[],"difficulty":"Advanced","definition":"Financial market infrastructure is the set of systems that allow payments, securities, derivatives and other financial transactions to be cleared, settled and recorded, such as payment systems, central securities depositories, central counterparties and trade repositories.","letter":"F","hasNote":false},{"id":"FIN-195","slug":"financial-model","term":"Financial Model","also_known_as":[],"difficulty":"Intermediate","definition":"A financial model is a structured representation of a business or project, usually built in a spreadsheet, that uses assumptions and calculations to estimate future financial results.","letter":"F","hasNote":false},{"id":"FIN-026","slug":"financial-plan","term":"Financial Plan","also_known_as":[],"difficulty":"Beginner","definition":"A financial plan is an overall strategy for managing your money to reach your financial goals. It brings together budgeting, saving, debt, investing, insurance, tax and retirement into one picture.","letter":"F","hasNote":false},{"id":"FIN-213","slug":"financial-planning-and-analysis","term":"Financial Planning and Analysis (FP&A)","also_known_as":["FP&A"],"difficulty":"Intermediate","definition":"Financial planning and analysis (FP&A) is the business function responsible for budgeting, forecasting and analysing financial performance to help managers make decisions.","letter":"F","hasNote":false},{"id":"FIN-039","slug":"financial-risk","term":"Financial Risk","also_known_as":[],"difficulty":"Beginner","definition":"Financial risk is the chance that a financial decision or investment will turn out worse than expected, including the possibility of losing money.","letter":"F","hasNote":false},{"id":"FIN-552","slug":"financial-scam","term":"Financial Scam","also_known_as":[],"difficulty":"Beginner","definition":"A financial scam is a dishonest scheme designed to trick people into handing over money, personal information or access to their accounts.","letter":"F","hasNote":false},{"id":"FIN-030","slug":"financial-security","term":"Financial Security","also_known_as":[],"difficulty":"Beginner","definition":"Financial security is having enough money, savings and protection to cover your needs, handle unexpected events and avoid serious financial hardship, both now and in the future.","letter":"F","hasNote":false},{"id":"FIN-108","slug":"financial-statement","term":"Financial Statement","also_known_as":[],"difficulty":"Beginner","definition":"A financial statement is a formal report that summarises a business\'s financial activity and position. The main ones are the balance sheet, the income statement and the cash flow statement.","letter":"F","hasNote":false},{"id":"FIN-028","slug":"financial-well-being","term":"Financial Well-Being","also_known_as":[],"difficulty":"Beginner","definition":"Financial well-being is a state in which you can meet your current financial commitments, feel secure about your financial future and have the freedom to make choices that let you enjoy life.","letter":"F","hasNote":false},{"id":"FIN-141","slug":"finished-goods","term":"Finished Goods","also_known_as":[],"difficulty":"Beginner","definition":"Finished goods are completed products that are ready to be sold to customers but have not yet been sold.","letter":"F","hasNote":false},{"id":"FIN-868","slug":"fintech","term":"Fintech","also_known_as":[],"difficulty":"Beginner","definition":"Fintech, short for financial technology, refers to the use of technology to deliver, improve or automate financial services, and to the companies that provide such services.","letter":"F","hasNote":false},{"id":"FIN-1231","slug":"fiscal-multiplier","term":"Fiscal Multiplier","also_known_as":[],"difficulty":"Advanced","definition":"The fiscal multiplier is the ratio of the change in a country\'s GDP to the change in government spending or taxes that caused it.","letter":"F","hasNote":false},{"id":"FIN-777","slug":"fiscal-policy","term":"Fiscal Policy","also_known_as":[],"difficulty":"Beginner","definition":"Fiscal policy is the use of government spending and taxation to influence the economy, such as supporting growth, reducing unemployment or controlling inflation.","letter":"F","hasNote":false},{"id":"FIN-1227","slug":"fiscal-surplus","term":"Fiscal Surplus","also_known_as":[],"difficulty":"Advanced","definition":"A fiscal surplus occurs when a government\'s revenue, mainly from taxes, exceeds its spending over a period, usually a year.","letter":"F","hasNote":false},{"id":"FIN-118","slug":"fiscal-year","term":"Fiscal Year","also_known_as":[],"difficulty":"Beginner","definition":"A fiscal year is the twelve-month period a business or government uses for its accounting and financial reporting. It may or may not match the calendar year.","letter":"F","hasNote":false},{"id":"FIN-1415","slug":"fixed-annuity","term":"Fixed Annuity","also_known_as":[],"difficulty":"Advanced","definition":"A fixed annuity is an annuity that pays a guaranteed rate of interest during its growth phase, or guaranteed fixed income payments during its payout phase, set by the insurance company.","letter":"F","hasNote":false},{"id":"FIN-1082","slug":"fixed-charge-coverage-ratio","term":"Fixed-Charge Coverage Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The fixed-charge coverage ratio measures a company\'s ability to pay its fixed financing charges, such as interest and lease payments, out of its earnings.","letter":"F","hasNote":false},{"id":"FIN-635","slug":"fixed-cost","term":"Fixed Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A fixed cost is a cost that stays the same in total regardless of how much a business produces or sells, at least within a certain range of activity and time period.","letter":"F","hasNote":false},{"id":"FIN-806","slug":"fixed-exchange-rate","term":"Fixed Exchange Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A fixed exchange rate is an exchange rate system in which a government or central bank sets its currency\'s value at a specific rate against another currency, a group of currencies or a commodity such as gold, and acts to keep it there.","letter":"F","hasNote":false},{"id":"FIN-244","slug":"fixed-income-security","term":"Fixed-Income Security","also_known_as":[],"difficulty":"Beginner","definition":"A fixed-income security is an investment that pays a set amount of interest or income at regular intervals and returns the principal at maturity, such as a bond.","letter":"F","hasNote":false},{"id":"FIN-059","slug":"fixed-rate","term":"Fixed Rate","also_known_as":[],"difficulty":"Beginner","definition":"A fixed rate is an interest rate that stays the same for an agreed period, regardless of changes in market interest rates.","letter":"F","hasNote":false},{"id":"FIN-816","slug":"fixed-rate-mortgage","term":"Fixed-Rate Mortgage","also_known_as":[],"difficulty":"Beginner","definition":"A fixed-rate mortgage is a home loan with an interest rate that stays the same for an agreed period, or for the entire life of the loan, so the regular payments do not change during that time.","letter":"F","hasNote":false},{"id":"FIN-1076","slug":"flexible-budget","term":"Flexible Budget","also_known_as":[],"difficulty":"Advanced","definition":"A flexible budget is a budget that adjusts to the actual level of activity, such as units produced or sold, so that actual results can be compared fairly with what costs should have been at that level.","letter":"F","hasNote":false},{"id":"FIN-805","slug":"floating-exchange-rate","term":"Floating Exchange Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A floating exchange rate is an exchange rate system in which a currency\'s value is determined by supply and demand in the foreign exchange market, rather than being fixed by the government or central bank.","letter":"F","hasNote":false},{"id":"FIN-892","slug":"football-field-chart","term":"Football Field Chart","also_known_as":[],"difficulty":"Intermediate","definition":"A football field chart is a horizontal bar chart that shows the range of values for a company produced by different valuation methods, allowing them to be compared at a glance.","letter":"F","hasNote":false},{"id":"FIN-859","slug":"forbearance","term":"Forbearance","also_known_as":[],"difficulty":"Intermediate","definition":"Forbearance is an agreement by a lender to temporarily reduce or pause a borrower\'s loan payments because the borrower is facing financial hardship.","letter":"F","hasNote":false},{"id":"FIN-1488","slug":"forecast-error","term":"Forecast Error","also_known_as":[],"difficulty":"Advanced","definition":"Forecast error is the difference between a forecast value and the actual value that occurred.","letter":"F","hasNote":false},{"id":"FIN-889","slug":"forecast-period","term":"Forecast Period","also_known_as":[],"difficulty":"Intermediate","definition":"The forecast period is the number of years for which an analyst explicitly projects a company\'s financial results, such as revenue, profit and cash flow, in a valuation model.","letter":"F","hasNote":false},{"id":"FIN-194","slug":"forecasting","term":"Forecasting","also_known_as":["Forecast"],"difficulty":"Intermediate","definition":"Forecasting is the process of estimating future financial results, such as sales, costs, profits or cash flows, based on past data, current trends and assumptions about what will happen.","letter":"F","hasNote":true},{"id":"FIN-860","slug":"foreclosure","term":"Foreclosure","also_known_as":[],"difficulty":"Intermediate","definition":"Foreclosure is the legal process, a term used mainly in the United States, by which a lender takes possession of and sells a property after the borrower fails to keep up with mortgage payments.","letter":"F","hasNote":false},{"id":"FIN-1053","slug":"foreign-currency-translation","term":"Foreign Currency Translation","also_known_as":[],"difficulty":"Advanced","definition":"Foreign currency translation is the process of converting the financial statements of a foreign subsidiary from its own currency into the parent company\'s reporting currency, so they can be included in the group\'s consolidated accounts.","letter":"F","hasNote":false},{"id":"FIN-1270","slug":"foreign-exchange","term":"Foreign Exchange (Forex)","also_known_as":["Forex"],"difficulty":"Advanced","definition":"Foreign exchange (forex) is the exchange of one currency for another, and the global market in which currencies are traded.","letter":"F","hasNote":false},{"id":"FIN-423","slug":"forward-contract","term":"Forward Contract","also_known_as":[],"difficulty":"Intermediate","definition":"A forward contract is a private agreement between two parties to buy or sell an asset at a set price on a specific future date.","letter":"F","hasNote":false},{"id":"FIN-785","slug":"forward-guidance","term":"Forward Guidance","also_known_as":[],"difficulty":"Intermediate","definition":"Forward guidance is communication by a central bank about the likely future path of its monetary policy, such as how long interest rates are expected to stay at a certain level, to influence expectations and financial conditions today.","letter":"F","hasNote":false},{"id":"FIN-402","slug":"forward-p-e","term":"Forward P/E","also_known_as":[],"difficulty":"Intermediate","definition":"Forward P/E is a company\'s current share price divided by its expected earnings per share for the next twelve months or the next financial year.","letter":"F","hasNote":false},{"id":"FIN-1199","slug":"forward-rate","term":"Forward Rate","also_known_as":[],"difficulty":"Advanced","definition":"In fixed income, a forward rate is an interest rate for a period that starts at a future date, implied by today\'s spot rates for different maturities.","letter":"F","hasNote":false},{"id":"FIN-1385","slug":"forward-rate-agreement","term":"Forward Rate Agreement (FRA)","also_known_as":["FRA"],"difficulty":"Advanced","definition":"A forward rate agreement (FRA) is a contract between two parties to fix an interest rate for a set period starting at a future date, with a cash payment at the start of that period based on the difference between the agreed rate and the actual market rate.","letter":"F","hasNote":false},{"id":"FIN-783","slug":"fractional-reserve-banking","term":"Fractional-Reserve Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Fractional-reserve banking is a banking system in which banks keep only a portion of their customers\' deposits as reserves and lend out or invest the rest.","letter":"F","hasNote":false},{"id":"FIN-457","slug":"franchise-model","term":"Franchise Model","also_known_as":[],"difficulty":"Beginner","definition":"A franchise model is a business model in which a company, the franchisor, allows independent business owners, the franchisees, to operate outlets under its brand and system in return for fees and royalties.","letter":"F","hasNote":false},{"id":"FIN-554","slug":"fraud","term":"Fraud","also_known_as":[],"difficulty":"Beginner","definition":"Fraud is deliberate deception carried out to gain money, property or an unfair advantage, or to cause someone else a loss.","letter":"F","hasNote":false},{"id":"FIN-185","slug":"free-cash-flow","term":"Free Cash Flow","also_known_as":[],"difficulty":"Intermediate","definition":"Free cash flow is the cash a business generates from its operations after paying for the capital investments needed to maintain and grow it. It is the cash available to repay debt, pay dividends or reinvest.","letter":"F","hasNote":false},{"id":"FIN-187","slug":"free-cash-flow-to-equity","term":"Free Cash Flow to Equity (FCFE)","also_known_as":["FCFE","Levered Free Cash Flow"],"difficulty":"Intermediate","definition":"Free cash flow to equity (FCFE) is the cash available to a company\'s shareholders after operating costs, taxes, reinvestment and all payments to and from lenders.","letter":"F","hasNote":true},{"id":"FIN-186","slug":"free-cash-flow-to-firm","term":"Free Cash Flow to Firm (FCFF)","also_known_as":["FCFF","Unlevered Free Cash Flow"],"difficulty":"Intermediate","definition":"Free cash flow to the firm (FCFF) is the cash a business generates from its operations, after taxes and the investment needed to sustain and grow it, that is available to all its funders, both lenders and shareholders.","letter":"F","hasNote":true},{"id":"FIN-1088","slug":"free-cash-flow-yield","term":"Free Cash Flow Yield","also_known_as":[],"difficulty":"Advanced","definition":"Free cash flow yield is a company\'s free cash flow per share divided by its share price, or total free cash flow divided by market value, showing how much free cash the company generates relative to its value.","letter":"F","hasNote":false},{"id":"FIN-289","slug":"free-float","term":"Free Float","also_known_as":[],"difficulty":"Intermediate","definition":"Free float is the number of a company\'s shares that are available for the public to trade, excluding shares held by insiders, governments, controlling shareholders or others unlikely to sell.","letter":"F","hasNote":false},{"id":"FIN-800","slug":"free-trade","term":"Free Trade","also_known_as":[],"difficulty":"Intermediate","definition":"Free trade is international trade with few or no government-imposed barriers, such as tariffs, quotas or import restrictions, allowing goods and services to move freely between countries.","letter":"F","hasNote":false},{"id":"FIN-455","slug":"freemium-model","term":"Freemium Model","also_known_as":[],"difficulty":"Beginner","definition":"A freemium model is a business model in which a basic version of a product or service is offered free of charge, while customers pay for premium features, extra capacity or an advertising-free experience.","letter":"F","hasNote":false},{"id":"FIN-773","slug":"frictional-unemployment","term":"Frictional Unemployment","also_known_as":[],"difficulty":"Intermediate","definition":"Frictional unemployment is the short-term unemployment that occurs when people are between jobs, entering the workforce for the first time or returning to work after a break, while they search for a suitable position.","letter":"F","hasNote":false},{"id":"FIN-1169","slug":"front-running","term":"Front Running","also_known_as":[],"difficulty":"Advanced","definition":"Front running is the illegal or unethical practice of a broker or trader using advance knowledge of a client\'s large pending order to trade for their own benefit before the client\'s order is executed.","letter":"F","hasNote":false},{"id":"FIN-876","slug":"fully-diluted-shares","term":"Fully Diluted Shares","also_known_as":[],"difficulty":"Intermediate","definition":"Fully diluted shares are the total number of a company\'s shares that would exist if all securities that could be converted into shares, such as stock options, warrants and convertible bonds, were exercised or converted.","letter":"F","hasNote":false},{"id":"FIN-1054","slug":"functional-currency","term":"Functional Currency","also_known_as":[],"difficulty":"Advanced","definition":"Functional currency is the currency of the main economic environment in which a business operates, usually the currency in which it earns revenue and pays costs.","letter":"F","hasNote":false},{"id":"FIN-734","slug":"fund-expense-ratio","term":"Fund Expense Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"A fund expense ratio is the annual cost of running an investment fund, expressed as a percentage of the fund\'s assets, which is deducted from the fund\'s returns.","letter":"F","hasNote":false},{"id":"FIN-711","slug":"fundamental-analysis","term":"Fundamental Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Fundamental analysis is a method of evaluating an investment by studying the underlying factors that affect its value, such as a company\'s financial statements, business model, management, industry and the wider economy.","letter":"F","hasNote":false},{"id":"FUT-1473","slug":"future-value","term":"Future Value","also_known_as":["FV"],"difficulty":"Beginner","definition":"Future value is how much an amount of money today will be worth at a later date after it earns interest or returns.","letter":"F","hasNote":false},{"id":"FIN-424","slug":"futures-contract","term":"Futures Contract","also_known_as":[],"difficulty":"Intermediate","definition":"A futures contract is a standardised agreement, traded on an exchange, to buy or sell a specific quantity of an asset at a set price on a future date.","letter":"F","hasNote":false},{"id":"FIN-1260","slug":"game-theory","term":"Game Theory","also_known_as":[],"difficulty":"Advanced","definition":"Game theory is the study of strategic decision-making, analysing situations where the outcome for each participant depends on the choices of others.","letter":"G","hasNote":false},{"id":"FIN-1377","slug":"gamma","term":"Gamma","also_known_as":[],"difficulty":"Advanced","definition":"Gamma is a measure of how much an option\'s delta changes when the price of the underlying asset changes by one unit.","letter":"G","hasNote":false},{"id":"FIN-1208","slug":"gdp-deflator","term":"GDP Deflator","also_known_as":[],"difficulty":"Advanced","definition":"The GDP deflator is a measure of the overall level of prices of all goods and services produced in an economy, calculated by dividing nominal GDP by real GDP and multiplying by 100.","letter":"G","hasNote":false},{"id":"FIN-753","slug":"gdp-per-capita","term":"GDP per Capita","also_known_as":[],"difficulty":"Intermediate","definition":"GDP per capita is a country\'s gross domestic product divided by its population, giving the average economic output per person.","letter":"G","hasNote":false},{"id":"FIN-148","slug":"general-and-administrative-expense","term":"General and Administrative Expense","also_known_as":[],"difficulty":"Beginner","definition":"General and administrative expenses are the overhead costs of running a business that are not directly tied to producing goods or selling them, such as office rent, management salaries, accounting, legal fees and insurance.","letter":"G","hasNote":false},{"id":"FIN-099","slug":"general-ledger","term":"General Ledger","also_known_as":[],"difficulty":"Beginner","definition":"The general ledger is the main record of all a business\'s accounts, showing every transaction and the running balance for each account.","letter":"G","hasNote":false},{"id":"FIN-958","slug":"general-partner","term":"General Partner (GP)","also_known_as":["GP"],"difficulty":"Intermediate","definition":"A general partner (GP) is the party that manages a partnership, such as a private equity or venture capital fund, making investment decisions and bearing responsibility for the fund\'s operations.","letter":"G","hasNote":false},{"id":"FIN-093","slug":"generally-accepted-accounting-principles","term":"Generally Accepted Accounting Principles (GAAP)","also_known_as":["GAAP"],"difficulty":"Beginner","definition":"Generally Accepted Accounting Principles (GAAP) are the standard rules and conventions that companies follow when preparing financial statements, so that reports are consistent and comparable.","letter":"G","hasNote":false},{"id":"FIN-480","slug":"geometric-mean","term":"Geometric Mean","also_known_as":[],"difficulty":"Intermediate","definition":"The geometric mean is a type of average calculated by multiplying a set of values together and taking the root equal to the number of values. In finance, it gives the true average growth rate per period over time.","letter":"G","hasNote":false},{"id":"FIN-1011","slug":"gift-tax","term":"Gift Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Gift tax is a tax on transfers of money or property made during a person\'s lifetime to someone else without receiving full value in return.","letter":"G","hasNote":false},{"id":"FIN-1235","slug":"gini-coefficient","term":"Gini Coefficient","also_known_as":[],"difficulty":"Advanced","definition":"The Gini coefficient is a measure of inequality in the distribution of income or wealth within a population, ranging from 0, meaning perfect equality, to 1, meaning one person has everything.","letter":"G","hasNote":false},{"id":"FIN-1431","slug":"go-to-market-strategy","term":"Go-to-Market Strategy","also_known_as":[],"difficulty":"Advanced","definition":"A go-to-market strategy is a plan for how a company will launch and sell a product or service to customers, covering who the target customers are, how they will be reached and how the product will be priced and sold.","letter":"G","hasNote":false},{"id":"FIN-1352","slug":"goal-seek","term":"Goal Seek","also_known_as":[],"difficulty":"Advanced","definition":"Goal seek is a spreadsheet tool that finds the input value needed to produce a specific result in a formula, by automatically adjusting one input until the target output is reached.","letter":"G","hasNote":false},{"id":"FIN-120","slug":"going-concern","term":"Going Concern","also_known_as":[],"difficulty":"Beginner","definition":"Going concern is the assumption that a business will continue operating for the foreseeable future, usually at least twelve months, rather than closing down or being forced to sell its assets.","letter":"G","hasNote":false},{"id":"FIN-391","slug":"going-concern-value","term":"Going-Concern Value","also_known_as":[],"difficulty":"Intermediate","definition":"Going-concern value is the value of a business as an operating enterprise that is expected to continue running, including the value of its assets working together and its ability to generate future profits.","letter":"G","hasNote":false},{"id":"FIN-1061","slug":"going-concern-warning","term":"Going-Concern Warning","also_known_as":[],"difficulty":"Advanced","definition":"A going-concern warning is a statement, made by management or by the auditor, that there is significant doubt about a company\'s ability to continue operating for the foreseeable future, usually at least the next twelve months.","letter":"G","hasNote":false},{"id":"FIN-1465","slug":"going-private","term":"Going Private","also_known_as":[],"difficulty":"Advanced","definition":"Going private is a transaction in which a publicly listed company is acquired and its shares are removed from the stock exchange, so it becomes privately owned.","letter":"G","hasNote":false},{"id":"FIN-1233","slug":"goods-and-services-tax","term":"Goods and Services Tax (GST)","also_known_as":["GST"],"difficulty":"Advanced","definition":"Goods and services tax (GST) is a consumption tax charged on most goods and services at each stage of supply, with businesses claiming back tax paid on their purchases. It is the name used for value-added tax in countries such as Australia, New Zealand, Canada, India and Singapore.","letter":"G","hasNote":false},{"id":"FIN-155","slug":"goodwill","term":"Goodwill","also_known_as":[],"difficulty":"Beginner","definition":"Goodwill is the amount a company pays to buy another business above the fair value of that business\'s identifiable net assets. It reflects things such as reputation, customer relationships, skilled staff and expected benefits from combining the businesses.","letter":"G","hasNote":false},{"id":"FIN-397","slug":"gordon-growth-model","term":"Gordon Growth Model","also_known_as":[],"difficulty":"Intermediate","definition":"The Gordon Growth Model is a version of the dividend discount model that values a share by assuming its dividends will grow at a constant rate forever.","letter":"G","hasNote":false},{"id":"FIN-245","slug":"government-bond","term":"Government Bond","also_known_as":["Sovereign Bond"],"difficulty":"Beginner","definition":"A government bond is a bond issued by a national government to borrow money, paying regular interest and repaying the face value at maturity.","letter":"G","hasNote":true},{"id":"FIN-788","slug":"government-debt","term":"Government Debt","also_known_as":[],"difficulty":"Intermediate","definition":"Government debt is the total amount of money a government owes to its creditors, accumulated from past budget deficits.","letter":"G","hasNote":false},{"id":"FIN-1055","slug":"government-grant","term":"Government Grant","also_known_as":[],"difficulty":"Advanced","definition":"A government grant is assistance from a government, in the form of money or other resources, given to a business in return for meeting certain conditions, such as investing in a region, creating jobs or carrying out research.","letter":"G","hasNote":false},{"id":"FIN-1229","slug":"government-spending","term":"Government Spending","also_known_as":[],"difficulty":"Advanced","definition":"Government spending is the money spent by national, regional and local governments on goods, services, investment and transfers, such as healthcare, education, defence, infrastructure, pensions and welfare.","letter":"G","hasNote":false},{"id":"FIN-069","slug":"grace-period","term":"Grace Period","also_known_as":[],"difficulty":"Beginner","definition":"A grace period is a set length of time after a payment is due, or after a purchase is made, during which no interest or penalty is charged.","letter":"G","hasNote":false},{"id":"FIN-1056","slug":"grant-income","term":"Grant Income","also_known_as":[],"difficulty":"Advanced","definition":"Grant income is the amount of a government or other grant that a business or organisation recognises as income in a particular period.","letter":"G","hasNote":false},{"id":"FIN-916","slug":"greeks","term":"Greeks","also_known_as":[],"difficulty":"Intermediate","definition":"The Greeks are a set of measures, named after Greek letters, that show how sensitive an option\'s price is to changes in factors such as the underlying asset\'s price, time, volatility and interest rates.","letter":"G","hasNote":false},{"id":"FIN-1183","slug":"greenwashing","term":"Greenwashing","also_known_as":[],"difficulty":"Advanced","definition":"Greenwashing is making misleading or exaggerated claims about how environmentally friendly a company, product or investment is.","letter":"G","hasNote":false},{"id":"FUT-0540","slug":"gross-domestic-product","term":"Gross Domestic Product (GDP)","also_known_as":["GDP"],"difficulty":"Beginner","definition":"Gross domestic product (GDP) is the total value of all final goods and services produced within a country over a period, usually a quarter or a year. It is the most widely used measure of the size of an economy.","letter":"G","hasNote":false},{"id":"FIN-009","slug":"gross-income","term":"Gross Income","also_known_as":[],"difficulty":"Beginner","definition":"Gross income is total income before any taxes or deductions are taken out. For an employee, it is the full salary and other pay agreed with the employer.","letter":"G","hasNote":false},{"id":"FIN-145","slug":"gross-margin","term":"Gross Margin","also_known_as":[],"difficulty":"Beginner","definition":"Gross margin is gross profit expressed as a percentage of revenue. It shows how much of each unit of sales is left after paying the direct costs of the goods or services sold.","letter":"G","hasNote":false},{"id":"FIN-475","slug":"gross-merchandise-value","term":"Gross Merchandise Value","also_known_as":[],"difficulty":"Intermediate","definition":"Gross merchandise value is the total value of goods or services sold through a marketplace or platform over a period, before deducting fees, discounts, returns or other costs.","letter":"G","hasNote":false},{"id":"FIN-1209","slug":"gross-national-product","term":"Gross National Product (GNP)","also_known_as":["GNP"],"difficulty":"Advanced","definition":"Gross national product (GNP) is the total value of goods and services produced by a country\'s residents and businesses, whether located at home or abroad, over a period.","letter":"G","hasNote":false},{"id":"FIN-144","slug":"gross-profit","term":"Gross Profit","also_known_as":[],"difficulty":"Beginner","definition":"Gross profit is the money left from revenue after subtracting the direct cost of the goods or services sold.","letter":"G","hasNote":false},{"id":"FIN-1132","slug":"gross-revenue-retention","term":"Gross Revenue Retention (GRR)","also_known_as":["GRR"],"difficulty":"Advanced","definition":"Gross revenue retention (GRR) is the percentage of recurring revenue a company keeps from its existing customers over a period after downgrades and cancellations, ignoring any expansion revenue.","letter":"G","hasNote":false},{"id":"FIN-888","slug":"growing-annuity","term":"Growing Annuity","also_known_as":[],"difficulty":"Intermediate","definition":"A growing annuity is a series of cash flows paid at regular intervals for a fixed number of periods, with each payment increasing at a constant rate.","letter":"G","hasNote":false},{"id":"FIN-887","slug":"growing-perpetuity","term":"Growing Perpetuity","also_known_as":[],"difficulty":"Intermediate","definition":"A growing perpetuity is a series of cash flows that continues forever and increases at a constant rate each period.","letter":"G","hasNote":false},{"id":"FIN-671","slug":"growth-capex","term":"Growth Capex","also_known_as":[],"difficulty":"Intermediate","definition":"Growth capex is capital spending aimed at expanding a company\'s capacity, entering new markets or adding new products and capabilities, rather than just maintaining existing operations.","letter":"G","hasNote":false},{"id":"FIN-955","slug":"growth-equity","term":"Growth Equity","also_known_as":[],"difficulty":"Intermediate","definition":"Growth equity is a type of private equity investment in established, growing companies that need capital to expand, typically in exchange for a minority ownership stake.","letter":"G","hasNote":false},{"id":"FIN-714","slug":"growth-investing","term":"Growth Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Growth investing is an investment strategy focused on buying shares of companies expected to grow their revenues and earnings faster than average, even if their shares look expensive by traditional measures.","letter":"G","hasNote":false},{"id":"FIN-702","slug":"growth-stock","term":"Growth Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A growth stock is a share in a company expected to grow its sales and earnings faster than the overall market, often valued at a high price relative to its current profits.","letter":"G","hasNote":false},{"id":"FIN-083","slug":"guarantor","term":"Guarantor","also_known_as":[],"difficulty":"Beginner","definition":"A guarantor is a person or organisation that promises to repay a debt if the main borrower fails to do so.","letter":"G","hasNote":false},{"id":"FIN-1214","slug":"hard-landing","term":"Hard Landing","also_known_as":[],"difficulty":"Advanced","definition":"A hard landing is when efforts to slow an overheating economy, usually by raising interest rates, lead to a sharp slowdown or recession, with falling output and rising unemployment.","letter":"H","hasNote":false},{"id":"FIN-481","slug":"harmonic-mean","term":"Harmonic Mean","also_known_as":[],"difficulty":"Intermediate","definition":"The harmonic mean is a type of average calculated by dividing the number of values by the sum of their reciprocals. It is useful for averaging rates and ratios.","letter":"H","hasNote":false},{"id":"FIN-200","slug":"headcount-forecast","term":"Headcount Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A headcount forecast is a plan of how many employees a business expects to have over a future period, by team or role, and what they will cost.","letter":"H","hasNote":false},{"id":"FIN-933","slug":"health-insurance","term":"Health Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Health insurance is insurance that pays for some or all of the cost of medical care, such as doctors\' visits, hospital stays, surgery and medicines, in exchange for regular premiums.","letter":"H","hasNote":false},{"id":"FUT-1082","slug":"hedging","term":"Hedging","also_known_as":[],"difficulty":"Intermediate","definition":"Hedging is taking a position in one investment or contract to reduce the risk of losses in another, much like buying insurance against an unfavourable price movement.","letter":"H","hasNote":false},{"id":"FIN-1154","slug":"herding","term":"Herding","also_known_as":[],"difficulty":"Intermediate","definition":"Herding is the tendency of investors to follow what other investors are doing, rather than relying on their own analysis, which can push prices further and faster than fundamentals justify.","letter":"H","hasNote":false},{"id":"FIN-555","slug":"historical-cost","term":"Historical Cost","also_known_as":[],"difficulty":"Intermediate","definition":"Historical cost is the accounting practice of recording an asset at the price originally paid for it, rather than at its current market value.","letter":"H","hasNote":false},{"id":"FIN-915","slug":"historical-volatility","term":"Historical Volatility","also_known_as":[],"difficulty":"Intermediate","definition":"Historical volatility is a measure of how much an asset\'s price has actually fluctuated over a past period, usually calculated as the annualized standard deviation of its returns.","letter":"H","hasNote":false},{"id":"FIN-1172","slug":"holding-period","term":"Holding Period","also_known_as":[],"difficulty":"Advanced","definition":"A holding period is the length of time an investor owns an investment, from the date of purchase to the date of sale.","letter":"H","hasNote":false},{"id":"FIN-518","slug":"home-equity","term":"Home Equity","also_known_as":[],"difficulty":"Beginner","definition":"Home equity is the part of a home\'s value that the owner owns outright. It equals the current market value of the home minus the amount still owed on any mortgage or other loans secured against it.","letter":"H","hasNote":false},{"id":"FIN-819","slug":"home-equity-line-of-credit","term":"Home Equity Line of Credit (HELOC)","also_known_as":["HELOC"],"difficulty":"Intermediate","definition":"A home equity line of credit (HELOC) is a revolving credit line, common in the United States, secured on a borrower\'s home, which allows them to borrow, repay and borrow again up to a set limit based on the equity in the property.","letter":"H","hasNote":false},{"id":"FIN-818","slug":"home-equity-loan","term":"Home Equity Loan","also_known_as":[],"difficulty":"Intermediate","definition":"A home equity loan is a loan, common in the United States, that allows a homeowner to borrow a lump sum against the equity in their home, which is the difference between the property\'s value and the amount still owed on the mortgage.","letter":"H","hasNote":false},{"id":"FIN-615","slug":"horizontal-analysis","term":"Horizontal Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Horizontal analysis compares financial statement figures across two or more periods to show how each item has changed over time, in amounts and in percentages.","letter":"H","hasNote":false},{"id":"FIN-1253","slug":"human-capital","term":"Human Capital","also_known_as":[],"difficulty":"Advanced","definition":"Human capital is the knowledge, skills, health, experience and abilities that people possess, which make them productive and allow them to earn income.","letter":"H","hasNote":false},{"id":"FIN-182","slug":"hurdle-rate","term":"Hurdle Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A hurdle rate is the minimum rate of return a company requires before it will approve an investment or project.","letter":"H","hasNote":false},{"id":"FIN-763","slug":"hyperinflation","term":"Hyperinflation","also_known_as":[],"difficulty":"Intermediate","definition":"Hyperinflation is extremely rapid and out-of-control inflation, in which prices rise so quickly that money loses its value very fast, often defined as prices rising by more than 50% in a single month.","letter":"H","hasNote":false},{"id":"FIN-492","slug":"hypothesis-test","term":"Hypothesis Test","also_known_as":[],"difficulty":"Intermediate","definition":"A hypothesis test is a statistical method for using sample data to decide whether there is enough evidence to reject an assumption about a population, called the null hypothesis.","letter":"H","hasNote":false},{"id":"FIN-1293","slug":"iban","term":"IBAN","also_known_as":[],"difficulty":"Advanced","definition":"An IBAN, or International Bank Account Number, is a standard international format for identifying a bank account, used to make cross-border payments more accurate and efficient.","letter":"I","hasNote":false},{"id":"FIN-553","slug":"identity-theft","term":"Identity Theft","also_known_as":[],"difficulty":"Beginner","definition":"Identity theft is the use of someone else\'s personal information, such as their name, identity number or bank details, without permission, usually to commit fraud or obtain money, credit or services.","letter":"I","hasNote":false},{"id":"FIN-1338","slug":"if-converted-method","term":"If-Converted Method","also_known_as":[],"difficulty":"Advanced","definition":"The if-converted method is a way of calculating diluted earnings per share that assumes convertible securities, such as convertible bonds or preferred shares, were converted into ordinary shares at the start of the period.","letter":"I","hasNote":false},{"id":"FIN-1413","slug":"immediate-annuity","term":"Immediate Annuity","also_known_as":[],"difficulty":"Advanced","definition":"An immediate annuity is an insurance contract in which a person pays a lump sum to an insurer in exchange for regular income payments that begin straight away, often for the rest of their life.","letter":"I","hasNote":false},{"id":"FIN-1184","slug":"impact-investing","term":"Impact Investing","also_known_as":[],"difficulty":"Advanced","definition":"Impact investing is investing with the intention of generating measurable positive social or environmental outcomes alongside a financial return.","letter":"I","hasNote":false},{"id":"FIN-153","slug":"impairment","term":"Impairment","also_known_as":[],"difficulty":"Intermediate","definition":"Impairment is a reduction in the recorded value of an asset when its recoverable amount falls below the value shown on the balance sheet.","letter":"I","hasNote":false},{"id":"FIN-914","slug":"implied-volatility","term":"Implied Volatility","also_known_as":[],"difficulty":"Intermediate","definition":"Implied volatility is the level of future volatility in an asset\'s price that is implied by the current market price of its options.","letter":"I","hasNote":false},{"id":"FIN-1263","slug":"impossible-trinity","term":"Impossible Trinity","also_known_as":[],"difficulty":"Advanced","definition":"The impossible trinity is the principle that a country cannot have all three of the following at the same time: a fixed exchange rate, free movement of capital across its borders, and an independent monetary policy.","letter":"I","hasNote":false},{"id":"FIN-441","slug":"in-the-money","term":"In-the-Money","also_known_as":[],"difficulty":"Intermediate","definition":"An option is in the money when exercising it immediately would be profitable: for a call, when the underlying price is above the strike price; for a put, when it is below.","letter":"I","hasNote":false},{"id":"FIN-004","slug":"income","term":"Income","also_known_as":[],"difficulty":"Beginner","definition":"Income is money a person or business receives over a period of time, such as a salary, business profits, interest, rent or dividends.","letter":"I","hasNote":false},{"id":"FIN-303","slug":"income-elasticity-of-demand","term":"Income Elasticity of Demand","also_known_as":[],"difficulty":"Intermediate","definition":"Income elasticity of demand measures how strongly the quantity demanded of a good responds to a change in consumers\' incomes.","letter":"I","hasNote":false},{"id":"FIN-1234","slug":"income-inequality","term":"Income Inequality","also_known_as":[],"difficulty":"Advanced","definition":"Income inequality is the extent to which income is distributed unevenly among individuals or households in a population.","letter":"I","hasNote":false},{"id":"FIN-111","slug":"income-statement","term":"Income Statement","also_known_as":["Profit and Loss Statement (P&L)","Profit and Loss Statement","P&L"],"difficulty":"Beginner","definition":"An income statement is a financial statement that shows a business\'s revenue, expenses and resulting profit or loss over a period, such as a quarter or a year.","letter":"I","hasNote":true},{"id":"FIN-571","slug":"income-tax-expense","term":"Income Tax Expense","also_known_as":[],"difficulty":"Intermediate","definition":"Income tax expense is the total tax charge a company records in its income statement for a period, including both tax payable now and changes in deferred tax.","letter":"I","hasNote":false},{"id":"FIN-667","slug":"incremental-cash-flow","term":"Incremental Cash Flow","also_known_as":[],"difficulty":"Intermediate","definition":"Incremental cash flow is the additional cash a company expects to receive or pay out as a direct result of undertaking a specific project or decision, compared with not doing it.","letter":"I","hasNote":false},{"id":"FIN-640","slug":"incremental-cost","term":"Incremental Cost","also_known_as":[],"difficulty":"Intermediate","definition":"An incremental cost is the additional cost incurred as a result of a decision, such as producing more units, accepting an order or launching a project.","letter":"I","hasNote":false},{"id":"FIN-1422","slug":"incurred-but-not-reported","term":"Incurred But Not Reported (IBNR)","also_known_as":["IBNR"],"difficulty":"Advanced","definition":"Incurred but not reported (IBNR) refers to insurance claims for events that have already happened but have not yet been reported to the insurer, for which the insurer must set aside an estimated reserve.","letter":"I","hasNote":false},{"id":"FIN-1406","slug":"indemnity-principle","term":"Indemnity Principle","also_known_as":[],"difficulty":"Advanced","definition":"The indemnity principle is the insurance principle that a policyholder should be restored to the same financial position after a loss as they were in immediately before it, but should not profit from the loss.","letter":"I","hasNote":false},{"id":"FIN-731","slug":"index-fund","term":"Index Fund","also_known_as":[],"difficulty":"Beginner","definition":"An index fund is an investment fund that aims to match the performance of a specific market index by holding all, or a representative sample, of the securities in that index.","letter":"I","hasNote":false},{"id":"FIN-997","slug":"index-number","term":"Index Number","also_known_as":[],"difficulty":"Intermediate","definition":"An index number is a figure that shows how a value has changed relative to a base period, which is usually set equal to 100.","letter":"I","hasNote":false},{"id":"FIN-643","slug":"indirect-cost","term":"Indirect Cost","also_known_as":[],"difficulty":"Intermediate","definition":"An indirect cost is a cost that supports several products, services or activities and cannot be traced directly to any single one of them, such as factory rent, utilities or administrative salaries.","letter":"I","hasNote":false},{"id":"FIN-1192","slug":"individual-retirement-account","term":"Individual Retirement Account (IRA)","also_known_as":["IRA"],"difficulty":"Advanced","definition":"An individual retirement account (IRA) is a tax-advantaged personal retirement account in the United States that individuals can open themselves, separate from any employer plan.","letter":"I","hasNote":false},{"id":"FIN-1218","slug":"industrial-production","term":"Industrial Production","also_known_as":[],"difficulty":"Advanced","definition":"Industrial production is a measure of the output of a country\'s factories, mines and utilities, usually published monthly as an index.","letter":"I","hasNote":false},{"id":"FIN-308","slug":"inferior-good","term":"Inferior Good","also_known_as":[],"difficulty":"Intermediate","definition":"An inferior good is a product for which demand falls when consumers\' incomes rise and increases when incomes fall.","letter":"I","hasNote":false},{"id":"FUT-0563","slug":"inflation","term":"Inflation","also_known_as":[],"difficulty":"Beginner","definition":"Inflation is the general rise in the prices of goods and services over time. As prices rise, each unit of money buys less.","letter":"I","hasNote":false},{"id":"FIN-766","slug":"inflation-expectations","term":"Inflation Expectations","also_known_as":[],"difficulty":"Intermediate","definition":"Inflation expectations are the rates of inflation that households, businesses and investors expect to see in the future.","letter":"I","hasNote":false},{"id":"FIN-697","slug":"inflation-risk","term":"Inflation Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Inflation risk is the risk that rising prices will reduce the real value of an investment\'s returns or of money saved, so that it buys less in the future.","letter":"I","hasNote":false},{"id":"FIN-784","slug":"inflation-targeting","term":"Inflation Targeting","also_known_as":[],"difficulty":"Intermediate","definition":"Inflation targeting is a monetary policy framework in which a central bank publicly commits to keeping inflation at or near a specific numerical target, and sets interest rates with that goal in mind.","letter":"I","hasNote":false},{"id":"FIN-1113","slug":"information-asymmetry","term":"Information Asymmetry","also_known_as":[],"difficulty":"Advanced","definition":"Information asymmetry is a situation in which one party in a transaction or relationship has more or better information than the other.","letter":"I","hasNote":false},{"id":"FIN-B3-NEW5","slug":"information-ratio","term":"Information Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The information ratio measures a portfolio\'s return above its benchmark for each unit of tracking error, showing how consistently a manager has outperformed.","letter":"I","hasNote":false},{"id":"FIN-1010","slug":"inheritance-tax","term":"Inheritance Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Inheritance tax is a tax on money or property received from someone who has died. Depending on the country, it is charged either on the heir who receives the assets or on the deceased person\'s estate as a whole.","letter":"I","hasNote":false},{"id":"FIN-904","slug":"initial-margin","term":"Initial Margin","also_known_as":[],"difficulty":"Intermediate","definition":"Initial margin is the amount of money or collateral an investor must deposit with a broker or clearing house when opening a leveraged position, such as a futures contract or a margin purchase of shares.","letter":"I","hasNote":false},{"id":"FIN-284","slug":"initial-public-offering","term":"Initial Public Offering (IPO)","also_known_as":["IPO"],"difficulty":"Intermediate","definition":"An initial public offering (IPO) is the first time a private company sells its shares to the public, after which its shares can be traded on a stock exchange.","letter":"I","hasNote":false},{"id":"FIN-221","slug":"inorganic-growth","term":"Inorganic Growth","also_known_as":[],"difficulty":"Beginner","definition":"Inorganic growth is growth a business achieves by buying or merging with other companies, rather than by expanding its existing operations.","letter":"I","hasNote":false},{"id":"FIN-1168","slug":"insider-trading","term":"Insider Trading","also_known_as":[],"difficulty":"Intermediate","definition":"Insider trading is buying or selling a company\'s securities while in possession of material information about the company that is not yet public, which is illegal in most countries.","letter":"I","hasNote":false},{"id":"FIN-973","slug":"insolvency","term":"Insolvency","also_known_as":[],"difficulty":"Intermediate","definition":"Insolvency is the financial state in which a person or company cannot pay its debts as they fall due, or its liabilities exceed its assets.","letter":"I","hasNote":false},{"id":"FIN-090","slug":"installment-loan","term":"Installment Loan","also_known_as":[],"difficulty":"Beginner","definition":"An instalment loan is a loan for a fixed amount that is repaid in regular, scheduled payments over a set period until the balance reaches zero.","letter":"I","hasNote":false},{"id":"FIN-739","slug":"institutional-investor","term":"Institutional Investor","also_known_as":[],"difficulty":"Intermediate","definition":"An institutional investor is an organisation that invests large sums of money on behalf of others, such as a pension fund, insurance company, mutual fund, endowment or sovereign wealth fund.","letter":"I","hasNote":false},{"id":"FIN-923","slug":"insurable-interest","term":"Insurable Interest","also_known_as":[],"difficulty":"Intermediate","definition":"Insurable interest is the requirement that a person buying insurance must stand to suffer a genuine financial loss if the insured event happens.","letter":"I","hasNote":false},{"id":"FIN-1424","slug":"insurance-agent","term":"Insurance Agent","also_known_as":[],"difficulty":"Intermediate","definition":"An insurance agent is a person or business licensed to sell insurance policies on behalf of one or more insurance companies, acting as the insurer\'s representative.","letter":"I","hasNote":false},{"id":"FIN-938","slug":"insurance-broker","term":"Insurance Broker","also_known_as":[],"difficulty":"Beginner","definition":"An insurance broker is an intermediary who helps clients find and buy insurance, acting on behalf of the client rather than the insurance company.","letter":"I","hasNote":false},{"id":"FUT-1178","slug":"insurance-policy","term":"Insurance Policy","also_known_as":["Insurance Premium"],"difficulty":"Beginner","definition":"An insurance policy is a contract in which an insurer agrees to pay for specified losses or events in exchange for regular payments, called premiums, from the policyholder.","letter":"I","hasNote":false},{"id":"FIN-921","slug":"insurer","term":"Insurer","also_known_as":[],"difficulty":"Beginner","definition":"An insurer is a company that provides insurance, agreeing to compensate policyholders for specified losses in exchange for regular payments called premiums.","letter":"I","hasNote":false},{"id":"FIN-154","slug":"intangible-asset","term":"Intangible Asset","also_known_as":[],"difficulty":"Beginner","definition":"An intangible asset is a valuable resource that has no physical form, such as a patent, trademark, copyright, software, customer list or brand.","letter":"I","hasNote":false},{"id":"FIN-465","slug":"intellectual-property","term":"Intellectual Property","also_known_as":[],"difficulty":"Beginner","definition":"Intellectual property is creations of the mind, such as inventions, designs, brand names, artistic works and confidential know-how, that the law allows owners to protect and control.","letter":"I","hasNote":false},{"id":"FIN-851","slug":"interbank-market","term":"Interbank Market","also_known_as":[],"difficulty":"Intermediate","definition":"The interbank market is the market in which banks lend money to and borrow money from each other, usually for very short periods, often overnight.","letter":"I","hasNote":false},{"id":"FIN-836","slug":"interchange-fee","term":"Interchange Fee","also_known_as":[],"difficulty":"Intermediate","definition":"An interchange fee is a fee paid by a merchant\'s bank to a cardholder\'s bank each time a card payment is made, set by the card network and usually calculated as a percentage of the transaction plus a small fixed amount.","letter":"I","hasNote":false},{"id":"FIN-1030","slug":"intercompany-transaction","term":"Intercompany Transaction","also_known_as":[],"difficulty":"Advanced","definition":"An intercompany transaction is a transaction between two companies in the same group, such as a sale of goods, a loan, a service charge or a dividend between a parent and its subsidiary.","letter":"I","hasNote":false},{"id":"FIN-049","slug":"interest","term":"Interest","also_known_as":[],"difficulty":"Beginner","definition":"Interest is the cost of borrowing money, or the reward for lending or saving it. It is usually expressed as a percentage of the amount borrowed or saved.","letter":"I","hasNote":false},{"id":"FIN-633","slug":"interest-coverage-ratio","term":"Interest Coverage Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The interest coverage ratio is a company\'s operating profit, usually EBIT, divided by its interest expense. It shows how many times over the company can pay its interest from its earnings.","letter":"I","hasNote":false},{"id":"FIN-566","slug":"interest-expense","term":"Interest Expense","also_known_as":[],"difficulty":"Intermediate","definition":"Interest expense is the cost a company incurs for borrowed money during a period, such as interest on loans, bonds and lease liabilities.","letter":"I","hasNote":false},{"id":"FIN-567","slug":"interest-income","term":"Interest Income","also_known_as":[],"difficulty":"Intermediate","definition":"Interest income is the money a company or individual earns from lending money or holding interest-bearing assets, such as bank deposits, bonds and loans.","letter":"I","hasNote":false},{"id":"FIN-825","slug":"interest-only-loan","term":"Interest-Only Loan","also_known_as":[],"difficulty":"Intermediate","definition":"An interest-only loan is a loan where the borrower pays only the interest for a set period or for the whole term, without reducing the amount originally borrowed.","letter":"I","hasNote":false},{"id":"FIN-050","slug":"interest-rate","term":"Interest Rate","also_known_as":[],"difficulty":"Beginner","definition":"An interest rate is the percentage charged on borrowed money, or paid on saved money, over a period of time, usually a year.","letter":"I","hasNote":false},{"id":"FIN-1386","slug":"interest-rate-cap","term":"Interest Rate Cap","also_known_as":[],"difficulty":"Advanced","definition":"An interest rate cap is a derivative contract that pays the holder when a floating interest rate rises above a set level, called the cap rate, protecting borrowers against rising interest costs.","letter":"I","hasNote":false},{"id":"FIN-1387","slug":"interest-rate-floor","term":"Interest Rate Floor","also_known_as":[],"difficulty":"Advanced","definition":"An interest rate floor is a derivative contract that pays the holder when a floating interest rate falls below a set level, called the floor rate, protecting lenders and investors against falling interest income.","letter":"I","hasNote":false},{"id":"FIN-1272","slug":"interest-rate-parity","term":"Interest Rate Parity","also_known_as":[],"difficulty":"Advanced","definition":"Interest rate parity is the principle that the difference in interest rates between two countries should be offset by the difference between the forward exchange rate and the spot exchange rate, so that investors cannot earn risk-free profits by moving money between currencies.","letter":"I","hasNote":false},{"id":"FIN-696","slug":"interest-rate-risk","term":"Interest Rate Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Interest rate risk is the risk that changes in interest rates will reduce the value of an investment or increase the cost of borrowing.","letter":"I","hasNote":false},{"id":"FIN-375","slug":"interest-rate-spread","term":"Interest Rate Spread","also_known_as":[],"difficulty":"Intermediate","definition":"The interest rate spread is the difference between the average interest rate a bank charges on loans and the average rate it pays on deposits and other borrowing.","letter":"I","hasNote":false},{"id":"FIN-907","slug":"interest-rate-swap","term":"Interest Rate Swap","also_known_as":[],"difficulty":"Intermediate","definition":"An interest rate swap is a contract in which two parties agree to exchange interest payments on a notional principal amount, typically with one paying a fixed rate and the other paying a floating rate.","letter":"I","hasNote":false},{"id":"FIN-598","slug":"internal-audit","term":"Internal Audit","also_known_as":[],"difficulty":"Intermediate","definition":"An internal audit is an independent review carried out within an organisation to evaluate and improve its risk management, internal controls and governance processes.","letter":"I","hasNote":false},{"id":"FIN-600","slug":"internal-control","term":"Internal Control","also_known_as":[],"difficulty":"Intermediate","definition":"Internal control is the set of policies, procedures and checks an organisation uses to ensure its financial reporting is reliable, its operations are effective and it complies with laws, while protecting its assets from loss or fraud.","letter":"I","hasNote":false},{"id":"FIN-177","slug":"internal-rate-of-return","term":"Internal Rate of Return (IRR)","also_known_as":["IRR"],"difficulty":"Intermediate","definition":"The internal rate of return (IRR) is the annual rate of return a project or investment is expected to earn, calculated as the discount rate at which its net present value equals zero.","letter":"I","hasNote":false},{"id":"FIN-710","slug":"international-diversification","term":"International Diversification","also_known_as":[],"difficulty":"Intermediate","definition":"International diversification is spreading investments across different countries and regions, rather than concentrating them in one\'s home market, to reduce risk and access wider opportunities.","letter":"I","hasNote":false},{"id":"FIN-094","slug":"international-financial-reporting-standards","term":"International Financial Reporting Standards (IFRS)","also_known_as":["IFRS"],"difficulty":"Beginner","definition":"International Financial Reporting Standards (IFRS) are a set of accounting rules used in many countries around the world so that companies\' financial statements are prepared in a consistent and comparable way.","letter":"I","hasNote":false},{"id":"FIN-811","slug":"international-monetary-fund","term":"International Monetary Fund (IMF)","also_known_as":["IMF"],"difficulty":"Intermediate","definition":"The International Monetary Fund (IMF) is an international organisation that works to promote global financial stability, international monetary cooperation and economic growth, including by lending to member countries facing balance of payments problems.","letter":"I","hasNote":false},{"id":"FIN-1491","slug":"interpolation","term":"Interpolation","also_known_as":[],"difficulty":"Advanced","definition":"Interpolation is a method of estimating an unknown value that lies between two or more known values.","letter":"I","hasNote":false},{"id":"FIN-388","slug":"intrinsic-value","term":"Intrinsic Value","also_known_as":[],"difficulty":"Intermediate","definition":"Intrinsic value is the estimated true worth of an asset based on its fundamental characteristics, such as the cash it is expected to generate, rather than its current market price.","letter":"I","hasNote":false},{"id":"FIN-438","slug":"intrinsic-value-option","term":"Intrinsic Value (Option)","also_known_as":[],"difficulty":"Intermediate","definition":"The intrinsic value of an option is the amount it would be worth if it were exercised immediately. It is never less than zero.","letter":"I","hasNote":false},{"id":"FIN-138","slug":"inventory","term":"Inventory","also_known_as":[],"difficulty":"Beginner","definition":"Inventory is the goods a business holds for sale, along with the materials and partly finished products used to make them.","letter":"I","hasNote":false},{"id":"FIN-1045","slug":"inventory-turnover","term":"Inventory Turnover","also_known_as":[],"difficulty":"Advanced","definition":"Inventory turnover is the number of times a business sells and replaces its inventory during a period, usually calculated as cost of goods sold divided by average inventory.","letter":"I","hasNote":false},{"id":"FIN-226","slug":"investing","term":"Investing","also_known_as":[],"difficulty":"Beginner","definition":"Investing is putting money into assets, such as shares, bonds, funds or property, with the aim of growing wealth or earning income over time.","letter":"I","hasNote":false},{"id":"FIN-042","slug":"investment","term":"Investment","also_known_as":[],"difficulty":"Beginner","definition":"An investment is something you buy or put money into with the expectation that it will produce income or grow in value over time.","letter":"I","hasNote":false},{"id":"FIN-339","slug":"investment-bank","term":"Investment Bank","also_known_as":[],"difficulty":"Intermediate","definition":"An investment bank is a financial institution that helps companies and governments raise money in financial markets, advises on mergers and acquisitions, and trades securities.","letter":"I","hasNote":false},{"id":"FIN-730","slug":"investment-horizon","term":"Investment Horizon","also_known_as":[],"difficulty":"Intermediate","definition":"An investment horizon is the length of time an investor expects to hold an investment or a portfolio before needing to use the money.","letter":"I","hasNote":false},{"id":"FIN-227","slug":"investment-objective","term":"Investment Objective","also_known_as":[],"difficulty":"Beginner","definition":"An investment objective is the specific goal an investor wants their money to achieve, such as long-term growth, regular income or keeping capital safe.","letter":"I","hasNote":false},{"id":"FIN-389","slug":"investment-value","term":"Investment Value","also_known_as":[],"difficulty":"Intermediate","definition":"Investment value is the value of an asset to a particular investor, based on that investor\'s own goals, circumstances and expected benefits.","letter":"I","hasNote":false},{"id":"FIN-043","slug":"investor","term":"Investor","also_known_as":[],"difficulty":"Beginner","definition":"An investor is a person or organisation that puts money into assets, such as shares, bonds, property or businesses, expecting to earn a return.","letter":"I","hasNote":false},{"id":"FIN-1375","slug":"iron-condor","term":"Iron Condor","also_known_as":[],"difficulty":"Advanced","definition":"An iron condor is an options strategy that combines four options to profit when an asset\'s price stays within a set range, by selling a put and a call close to the current price and buying a further-away put and call for protection.","letter":"I","hasNote":false},{"id":"FIN-1139","slug":"issued-shares","term":"Issued Shares","also_known_as":[],"difficulty":"Advanced","definition":"Issued shares are the shares a company has actually sold or given to shareholders, including any it has later bought back and holds in treasury.","letter":"I","hasNote":false},{"id":"FIN-1289","slug":"issuer","term":"Issuer","also_known_as":[],"difficulty":"Advanced","definition":"In card payments, an issuer is the bank or financial institution that provides a payment card to a customer, approves transactions and is responsible for collecting payment from the cardholder.","letter":"I","hasNote":false},{"id":"FIN-1005","slug":"itemized-deduction","term":"Itemized Deduction","also_known_as":[],"difficulty":"Intermediate","definition":"An itemized deduction is a specific allowable expense, such as certain mortgage interest, state and local taxes, medical costs or charitable gifts, that a taxpayer lists individually to reduce taxable income. The term is used mainly in the United States.","letter":"I","hasNote":false},{"id":"FIN-1068","slug":"job-costing","term":"Job Costing","also_known_as":[],"difficulty":"Advanced","definition":"Job costing is a method of tracking the costs of individual jobs, projects or orders separately, used when each piece of work is different, such as custom manufacturing, construction or professional services.","letter":"J","hasNote":false},{"id":"FIN-592","slug":"joint-venture","term":"Joint Venture","also_known_as":[],"difficulty":"Intermediate","definition":"A joint venture is an arrangement in which two or more parties share control of a business or project, with major decisions requiring the agreement of all the controlling parties.","letter":"J","hasNote":false},{"id":"FIN-100","slug":"journal-entry","term":"Journal Entry","also_known_as":[],"difficulty":"Beginner","definition":"A journal entry is the record of a single business transaction, showing the date, the accounts affected, the amounts debited and credited and a short description.","letter":"J","hasNote":false},{"id":"FIN-215","slug":"key-performance-indicator","term":"Key Performance Indicator (KPI)","also_known_as":["KPI"],"difficulty":"Beginner","definition":"A key performance indicator (KPI) is a measurable value that shows how well a business, team or individual is achieving an important objective.","letter":"K","hasNote":false},{"id":"FIN-1237","slug":"keynesian-economics","term":"Keynesian Economics","also_known_as":[],"difficulty":"Advanced","definition":"Keynesian economics is a school of economic thought, based on the work of John Maynard Keynes, which holds that total demand is the main driver of output and employment in the short run, and that governments should act to stabilise the economy during downturns.","letter":"K","hasNote":false},{"id":"FIN-853","slug":"know-your-customer","term":"Know Your Customer (KYC)","also_known_as":["KYC"],"difficulty":"Intermediate","definition":"Know Your Customer (KYC) is the process banks and other financial institutions use to verify the identity of their customers and understand their financial activities, to prevent fraud, money laundering and other financial crime.","letter":"K","hasNote":false},{"id":"FIN-1483","slug":"kurtosis","term":"Kurtosis","also_known_as":[],"difficulty":"Advanced","definition":"Kurtosis is a statistical measure of how much of a probability distribution\'s variation comes from extreme values in its tails, compared with a normal distribution.","letter":"K","hasNote":false},{"id":"FIN-770","slug":"labor-force-participation-rate","term":"Labor Force Participation Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The labor force participation rate is the percentage of the working-age population that is either employed or actively looking for work.","letter":"L","hasNote":false},{"id":"FIN-775","slug":"lagging-indicator","term":"Lagging Indicator","also_known_as":[],"difficulty":"Intermediate","definition":"A lagging indicator is an economic statistic that tends to change only after the overall economy has already changed direction, confirming trends rather than predicting them.","letter":"L","hasNote":false},{"id":"FIN-707","slug":"large-cap-stock","term":"Large-Cap Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A large-cap stock is a share in a company with a very large market capitalization, typically among the biggest companies listed in a market.","letter":"L","hasNote":false},{"id":"FIN-070","slug":"late-fee","term":"Late Fee","also_known_as":[],"difficulty":"Beginner","definition":"A late fee is a charge added when a payment on a loan, credit card or bill is not made by the due date or before any grace period ends.","letter":"L","hasNote":false},{"id":"FIN-990","slug":"law-of-large-numbers","term":"Law of Large Numbers","also_known_as":[],"difficulty":"Intermediate","definition":"The law of large numbers is a principle of probability stating that as the number of trials or observations increases, the average of the results gets closer to the expected value.","letter":"L","hasNote":false},{"id":"FIN-774","slug":"leading-indicator","term":"Leading Indicator","also_known_as":[],"difficulty":"Intermediate","definition":"A leading indicator is an economic statistic that tends to change before the overall economy changes direction, so it can help predict future economic activity.","letter":"L","hasNote":false},{"id":"FIN-520","slug":"lease","term":"Lease","also_known_as":[],"difficulty":"Beginner","definition":"A lease is a contract that gives one party, the lessee, the right to use an asset owned by another party, the lessor, for a set period in exchange for regular payments.","letter":"L","hasNote":false},{"id":"FIN-586","slug":"lease-liability","term":"Lease Liability","also_known_as":[],"difficulty":"Intermediate","definition":"A lease liability is the obligation a lessee records on its balance sheet to make future lease payments, measured at the present value of those payments.","letter":"L","hasNote":false},{"id":"FIN-045","slug":"lender","term":"Lender","also_known_as":["Creditor"],"difficulty":"Beginner","definition":"A lender is a person or organisation that provides money to a borrower on the understanding that it will be paid back, usually with interest.","letter":"L","hasNote":true},{"id":"FIN-786","slug":"lender-of-last-resort","term":"Lender of Last Resort","also_known_as":[],"difficulty":"Intermediate","definition":"A lender of last resort is an institution, usually a central bank, that lends money to banks and other financial institutions facing short-term cash shortages when they cannot borrow elsewhere, to prevent panic and financial collapse.","letter":"L","hasNote":false},{"id":"FIN-1281","slug":"letter-of-credit","term":"Letter of Credit","also_known_as":[],"difficulty":"Advanced","definition":"A letter of credit is a written commitment by a bank, made on behalf of a buyer, to pay a seller a specified amount once the seller presents documents showing it has met the agreed conditions, such as shipping the goods.","letter":"L","hasNote":false},{"id":"FIN-1364","slug":"letter-of-intent","term":"Letter of Intent (LOI)","also_known_as":["LOI"],"difficulty":"Advanced","definition":"A letter of intent (LOI) is a document setting out the main terms of a proposed transaction, such as an acquisition, agreed in principle between the parties before detailed legal agreements are negotiated.","letter":"L","hasNote":false},{"id":"FIN-275","slug":"leverage","term":"Leverage","also_known_as":[],"difficulty":"Intermediate","definition":"Leverage is the use of borrowed money to increase the size of an investment or business activity, which magnifies both potential gains and potential losses.","letter":"L","hasNote":false},{"id":"FIN-369","slug":"leverage-ratio-banking","term":"Leverage Ratio (Banking)","also_known_as":[],"difficulty":"Intermediate","definition":"The leverage ratio, in banking, compares a bank\'s high-quality capital with its total exposures, without adjusting for risk. It acts as a simple backstop to risk-based capital rules.","letter":"L","hasNote":false},{"id":"FIN-967","slug":"leveraged-buyout","term":"Leveraged Buyout","also_known_as":[],"difficulty":"Intermediate","definition":"A leveraged buyout is the acquisition of a company using a large amount of borrowed money to pay for the purchase, with the target company\'s assets and cash flows typically used to support and repay the debt.","letter":"L","hasNote":false},{"id":"FIN-1349","slug":"leveraged-buyout-lbo-model","term":"Leveraged Buyout (LBO) Model","also_known_as":["LBO Model"],"difficulty":"Advanced","definition":"A leveraged buyout (LBO) model is a financial model used to analyse the acquisition of a company funded largely with debt, estimating the returns that the equity investors, usually a private equity firm, can expect.","letter":"L","hasNote":false},{"id":"FIN-1277","slug":"leveraged-loan","term":"Leveraged Loan","also_known_as":[],"difficulty":"Advanced","definition":"A leveraged loan is a loan made to a company that already has a high level of debt or a low credit rating, usually below investment grade, typically carrying a floating interest rate higher than loans to stronger borrowers.","letter":"L","hasNote":false},{"id":"FIN-1334","slug":"levered-beta","term":"Levered Beta","also_known_as":[],"difficulty":"Advanced","definition":"Levered beta is a measure of a company\'s market risk that includes the effect of its debt, reflecting the volatility of its shares relative to the overall market.","letter":"L","hasNote":false},{"id":"FIN-014","slug":"liability","term":"Liability","also_known_as":[],"difficulty":"Beginner","definition":"A liability is something you owe to another person or organisation, such as a loan, a mortgage, a credit card balance or an unpaid bill.","letter":"L","hasNote":false},{"id":"FIN-936","slug":"liability-insurance","term":"Liability Insurance","also_known_as":[],"difficulty":"Intermediate","definition":"Liability insurance is insurance that protects the policyholder against the cost of legal claims made against them for injuring other people or damaging their property.","letter":"L","hasNote":false},{"id":"FIN-1303","slug":"libor","term":"LIBOR","also_known_as":[],"difficulty":"Advanced","definition":"LIBOR, the London Interbank Offered Rate, was a benchmark interest rate based on estimates submitted by major banks of the rates at which they could borrow from each other, which has now been discontinued.","letter":"L","hasNote":false},{"id":"FIN-458","slug":"licensing-model","term":"Licensing Model","also_known_as":[],"difficulty":"Intermediate","definition":"A licensing model is a business model in which a company allows others to use its intellectual property, such as a patent, brand, technology, software or content, in exchange for fees or royalties.","letter":"L","hasNote":false},{"id":"FIN-930","slug":"life-expectancy","term":"Life Expectancy","also_known_as":[],"difficulty":"Intermediate","definition":"Life expectancy is the average number of years a person is expected to live, based on their current age, sex and other factors, calculated from statistics on death rates in a population.","letter":"L","hasNote":false},{"id":"FIN-222","slug":"like-for-like-growth","term":"Like-for-Like Growth","also_known_as":[],"difficulty":"Beginner","definition":"Like-for-like growth is the change in sales from a comparable set of operations, such as stores open for the whole of both periods, excluding the effect of new openings, closures or acquisitions.","letter":"L","hasNote":false},{"id":"FIN-269","slug":"limit-order","term":"Limit Order","also_known_as":[],"difficulty":"Intermediate","definition":"A limit order is an instruction to buy or sell a security only at a specified price or better.","letter":"L","hasNote":false},{"id":"FIN-957","slug":"limited-partner","term":"Limited Partner (LP)","also_known_as":["LP"],"difficulty":"Intermediate","definition":"A limited partner (LP) is an investor in a partnership, such as a private equity or venture capital fund, who provides capital but does not take part in managing the fund, and whose liability is limited to the amount invested.","letter":"L","hasNote":false},{"id":"FIN-487","slug":"linear-regression","term":"Linear Regression","also_known_as":[],"difficulty":"Intermediate","definition":"Linear regression is a statistical method that models the relationship between two or more variables by fitting a straight line through the data that best predicts one variable from the other.","letter":"L","hasNote":false},{"id":"FIN-974","slug":"liquidation","term":"Liquidation","also_known_as":[],"difficulty":"Intermediate","definition":"Liquidation is the process of closing a company by selling its assets and using the proceeds to pay its creditors, after which the company ceases to exist.","letter":"L","hasNote":false},{"id":"FIN-979","slug":"liquidation-preference","term":"Liquidation Preference","also_known_as":[],"difficulty":"Intermediate","definition":"A liquidation preference is a right, usually held by investors with preferred shares, to be paid a set amount before ordinary shareholders when a company is sold, wound up or has another liquidity event.","letter":"L","hasNote":false},{"id":"FIN-390","slug":"liquidation-value","term":"Liquidation Value","also_known_as":[],"difficulty":"Intermediate","definition":"Liquidation value is the estimated amount that could be raised if a company\'s assets were sold off individually, usually quickly, and its operations shut down.","letter":"L","hasNote":false},{"id":"FIN-504","slug":"liquidity","term":"Liquidity","also_known_as":[],"difficulty":"Beginner","definition":"Liquidity is how quickly and easily an asset can be turned into cash without losing much of its value. For a person or business, it also means having enough cash available to meet bills as they fall due.","letter":"L","hasNote":false},{"id":"FIN-1319","slug":"liquidity-coverage-ratio","term":"Liquidity Coverage Ratio (LCR)","also_known_as":["LCR"],"difficulty":"Advanced","definition":"The liquidity coverage ratio (LCR) is a banking regulation requiring banks to hold enough high-quality liquid assets to cover their expected net cash outflows over a 30-day period of severe stress.","letter":"L","hasNote":false},{"id":"FIN-1144","slug":"liquidity-risk","term":"Liquidity Risk","also_known_as":[],"difficulty":"Advanced","definition":"Liquidity risk is the risk that an investor or institution cannot buy or sell an asset quickly enough, or at a fair price, or cannot obtain enough cash to meet its obligations when they fall due.","letter":"L","hasNote":false},{"id":"FIN-062","slug":"loan","term":"Loan","also_known_as":[],"difficulty":"Beginner","definition":"A loan is money borrowed from a lender that must be repaid over time, usually with interest, according to agreed terms.","letter":"L","hasNote":false},{"id":"FIN-827","slug":"loan-covenant","term":"Loan Covenant","also_known_as":[],"difficulty":"Intermediate","definition":"A loan covenant is a condition in a loan agreement that requires the borrower to do certain things, or prevents it from doing certain things, in order to protect the lender.","letter":"L","hasNote":false},{"id":"FIN-371","slug":"loan-loss-provision","term":"Loan Loss Provision","also_known_as":[],"difficulty":"Intermediate","definition":"A loan loss provision is an expense a bank records in a period to cover expected losses on loans that may not be repaid.","letter":"L","hasNote":false},{"id":"FIN-372","slug":"loan-loss-reserve","term":"Loan Loss Reserve","also_known_as":[],"difficulty":"Intermediate","definition":"A loan loss reserve is the total amount a bank has set aside on its balance sheet to cover expected losses on its loans. It reduces the reported value of loans to the amount the bank expects to collect.","letter":"L","hasNote":false},{"id":"FIN-1313","slug":"loan-modification","term":"Loan Modification","also_known_as":[],"difficulty":"Advanced","definition":"A loan modification is a permanent change to the terms of an existing loan, such as lowering the interest rate, extending the repayment period or reducing the balance, agreed between the lender and a borrower who is struggling to make payments.","letter":"L","hasNote":false},{"id":"FIN-378","slug":"loan-origination","term":"Loan Origination","also_known_as":[],"difficulty":"Intermediate","definition":"Loan origination is the process by which a lender creates a new loan, from receiving the application through checking the borrower, approving the loan, preparing documents and paying out the money.","letter":"L","hasNote":false},{"id":"FIN-088","slug":"loan-term","term":"Loan Term","also_known_as":[],"difficulty":"Beginner","definition":"The loan term is the length of time over which a loan must be repaid, such as three years for a car loan or 25 years for a mortgage.","letter":"L","hasNote":false},{"id":"FIN-377","slug":"loan-to-deposit-ratio","term":"Loan-to-Deposit Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The loan-to-deposit ratio compares a bank\'s total loans with its total deposits. It shows how much of the money deposited with the bank has been lent out.","letter":"L","hasNote":false},{"id":"FIN-823","slug":"loan-to-value-ratio","term":"Loan-to-Value Ratio (LTV)","also_known_as":["LTV"],"difficulty":"Intermediate","definition":"The loan-to-value ratio (LTV) compares the size of a loan with the value of the asset securing it, usually a property, and is expressed as a percentage.","letter":"L","hasNote":false},{"id":"FIN-1366","slug":"locked-box-mechanism","term":"Locked-Box Mechanism","also_known_as":[],"difficulty":"Advanced","definition":"A locked-box mechanism is a way of fixing the price in an acquisition based on a balance sheet at an agreed date before signing, with no adjustments after completion, while the seller promises not to take value out of the business in the meantime.","letter":"L","hasNote":false},{"id":"FIN-1203","slug":"log-return","term":"Log Return","also_known_as":[],"difficulty":"Advanced","definition":"A log return is the natural logarithm of the ratio of an investment\'s ending value to its starting value, also called the continuously compounded return.","letter":"L","hasNote":false},{"id":"FIN-1484","slug":"lognormal-distribution","term":"Lognormal Distribution","also_known_as":[],"difficulty":"Advanced","definition":"The lognormal distribution is a probability distribution of a variable whose natural logarithm follows a normal distribution, meaning the variable itself can only take positive values and is skewed to the right.","letter":"L","hasNote":false},{"id":"FIN-1417","slug":"long-term-care-insurance","term":"Long-Term Care Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Long-term care insurance is insurance that helps pay for care over an extended period for people who cannot fully look after themselves because of ageing, chronic illness, disability or cognitive impairment.","letter":"L","hasNote":false},{"id":"FIN-1051","slug":"long-term-investments","term":"Long-Term Investments","also_known_as":[],"difficulty":"Advanced","definition":"Long-term investments are financial investments a company intends to hold for more than a year, such as shares in other companies, bonds held to maturity or stakes in associates, shown as non-current assets on the balance sheet.","letter":"L","hasNote":false},{"id":"FIN-1499","slug":"look-ahead-bias","term":"Look-Ahead Bias","also_known_as":[],"difficulty":"Advanced","definition":"Look-ahead bias is an error in analysis or backtesting that occurs when information that would not have been available at the time is used to make decisions or predictions.","letter":"L","hasNote":false},{"id":"FIN-721","slug":"loss-aversion","term":"Loss Aversion","also_known_as":[],"difficulty":"Intermediate","definition":"Loss aversion is the tendency for people to feel the pain of losses more strongly than the pleasure of equivalent gains.","letter":"L","hasNote":false},{"id":"FIN-1029","slug":"loss-carryforward","term":"Loss Carryforward","also_known_as":[],"difficulty":"Advanced","definition":"A loss carryforward is a tax rule that allows a business or individual to use a tax loss from one year to reduce taxable profits in future years.","letter":"L","hasNote":false},{"id":"FIN-927","slug":"loss-ratio","term":"Loss Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The loss ratio is the ratio of claims paid or incurred by an insurer to the premiums it earned over the same period, expressed as a percentage.","letter":"L","hasNote":false},{"id":"FIN-1122","slug":"ltv-to-cac-ratio","term":"LTV to CAC Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The LTV to CAC ratio compares the lifetime value of a customer, the total profit a business expects to earn from them, with the customer acquisition cost, the cost of winning them.","letter":"L","hasNote":false},{"id":"FIN-B2-NEW1","slug":"lump-sum-investing","term":"Lump-Sum Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Lump-sum investing is putting a large amount of money into an investment all at once, rather than spreading the purchases over time.","letter":"L","hasNote":false},{"id":"FIN-1206","slug":"macaulay-duration","term":"Macaulay Duration","also_known_as":[],"difficulty":"Advanced","definition":"Macaulay duration is the weighted average time until a bond\'s cash flows are received, with each payment\'s time weighted by its share of the bond\'s present value, measured in years.","letter":"M","hasNote":false},{"id":"FIN-1497","slug":"machine-learning-in-finance","term":"Machine Learning in Finance","also_known_as":[],"difficulty":"Advanced","definition":"Machine learning in finance is the use of computer algorithms that learn patterns from data to make predictions or decisions, applied to tasks such as credit scoring, fraud detection, trading and risk management.","letter":"M","hasNote":false},{"id":"FIN-293","slug":"macroeconomics","term":"Macroeconomics","also_known_as":[],"difficulty":"Beginner","definition":"Macroeconomics is the branch of economics that studies the economy as a whole, including total output, growth, inflation, unemployment, interest rates and international trade.","letter":"M","hasNote":false},{"id":"FIN-670","slug":"maintenance-capex","term":"Maintenance Capex","also_known_as":[],"difficulty":"Intermediate","definition":"Maintenance capex is the capital spending a company needs to keep its existing assets and operations running at their current level, such as replacing worn-out equipment.","letter":"M","hasNote":false},{"id":"FIN-905","slug":"maintenance-margin","term":"Maintenance Margin","also_known_as":[],"difficulty":"Intermediate","definition":"Maintenance margin is the minimum amount of equity an investor must keep in a margin account to hold a leveraged position open, below which the broker will issue a margin call.","letter":"M","hasNote":false},{"id":"FIN-1264","slug":"managed-float","term":"Managed Float","also_known_as":[],"difficulty":"Advanced","definition":"A managed float is an exchange rate system in which a currency\'s value is mainly set by market supply and demand, but the central bank intervenes from time to time to influence its value or reduce volatility.","letter":"M","hasNote":false},{"id":"FIN-1041","slug":"management-accounts","term":"Management Accounts","also_known_as":[],"difficulty":"Advanced","definition":"Management accounts are internal financial reports prepared for a business\'s managers, usually monthly, to help them monitor performance and make decisions.","letter":"M","hasNote":false},{"id":"FIN-1478","slug":"management-buyout","term":"Management Buyout (MBO)","also_known_as":["MBO"],"difficulty":"Advanced","definition":"A management buyout (MBO) is a transaction in which a company\'s existing managers buy the business, or a large part of it, from its current owners, often with funding from private equity investors and lenders.","letter":"M","hasNote":false},{"id":"FIN-959","slug":"management-fee","term":"Management Fee","also_known_as":[],"difficulty":"Intermediate","definition":"A management fee is a fee charged by an investment manager to cover the cost of managing a fund or portfolio, usually calculated as a percentage of the assets managed or committed.","letter":"M","hasNote":false},{"id":"FIN-214","slug":"management-reporting","term":"Management Reporting","also_known_as":[],"difficulty":"Beginner","definition":"Management reporting is the regular preparation of financial and operational reports for a company\'s managers, designed to help them monitor performance and make decisions.","letter":"M","hasNote":false},{"id":"FIN-274","slug":"margin-call","term":"Margin Call","also_known_as":[],"difficulty":"Intermediate","definition":"A margin call is a demand from a broker for an investor to add money or securities to a margin account after losses have pushed the account\'s equity below the required minimum.","letter":"M","hasNote":false},{"id":"FIN-273","slug":"margin-trading","term":"Margin Trading","also_known_as":[],"difficulty":"Intermediate","definition":"Margin trading is buying securities partly with money borrowed from a broker, using the securities themselves as collateral for the loan.","letter":"M","hasNote":false},{"id":"FIN-316","slug":"marginal-benefit","term":"Marginal Benefit","also_known_as":[],"difficulty":"Intermediate","definition":"Marginal benefit is the additional benefit a person or business gains from consuming or producing one more unit of something.","letter":"M","hasNote":false},{"id":"FIN-641","slug":"marginal-cost","term":"Marginal Cost","also_known_as":[],"difficulty":"Intermediate","definition":"Marginal cost is the additional cost of producing one more unit of a good or service.","letter":"M","hasNote":false},{"id":"FIN-539","slug":"marginal-tax-rate","term":"Marginal Tax Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The marginal tax rate is the rate of tax paid on the next unit of income earned. It is the rate of the tax bracket that a person\'s top slice of income falls into.","letter":"M","hasNote":false},{"id":"FIN-317","slug":"marginal-utility","term":"Marginal Utility","also_known_as":[],"difficulty":"Intermediate","definition":"Marginal utility is the additional satisfaction a person gets from consuming one more unit of a good or service.","letter":"M","hasNote":false},{"id":"FIN-903","slug":"mark-to-market","term":"Mark-to-Market","also_known_as":[],"difficulty":"Intermediate","definition":"Mark-to-market is the practice of valuing assets and liabilities at their current market price rather than at their original cost.","letter":"M","hasNote":false},{"id":"FIN-288","slug":"market-capitalization","term":"Market Capitalization","also_known_as":[],"difficulty":"Beginner","definition":"Market capitalization is the total market value of a company\'s shares, calculated by multiplying the current share price by the number of shares outstanding.","letter":"M","hasNote":false},{"id":"FIN-724","slug":"market-correction","term":"Market Correction","also_known_as":[],"difficulty":"Intermediate","definition":"A market correction is a decline of 10% or more, but less than 20%, in the price of a stock market index or other asset from its most recent high.","letter":"M","hasNote":false},{"id":"FIN-1161","slug":"market-crash","term":"Market Crash","also_known_as":[],"difficulty":"Intermediate","definition":"A market crash is a sudden, steep fall in prices across a large part of a financial market, typically within a single day or a few days.","letter":"M","hasNote":false},{"id":"FIN-300","slug":"market-equilibrium","term":"Market Equilibrium","also_known_as":[],"difficulty":"Intermediate","definition":"Market equilibrium is the state of a market in which the quantity demanded equals the quantity supplied, so there is no pressure for the price to change.","letter":"M","hasNote":false},{"id":"FIN-315","slug":"market-failure","term":"Market Failure","also_known_as":[],"difficulty":"Intermediate","definition":"Market failure is a situation in which a free market, left to itself, does not produce the best outcome for society, resulting in too much or too little of a good being produced.","letter":"M","hasNote":false},{"id":"FIN-236","slug":"market-index","term":"Market Index","also_known_as":["Index"],"difficulty":"Beginner","definition":"A market index is a measure that tracks the performance of a group of investments, such as the largest companies on a stock exchange, to represent how a market or part of a market is doing.","letter":"M","hasNote":true},{"id":"FIN-1162","slug":"market-liquidity","term":"Market Liquidity","also_known_as":[],"difficulty":"Advanced","definition":"Market liquidity is the ease with which assets can be bought or sold in a market quickly, in large amounts and without significantly moving their price.","letter":"M","hasNote":false},{"id":"FIN-279","slug":"market-maker","term":"Market Maker","also_known_as":[],"difficulty":"Intermediate","definition":"A market maker is a firm that continuously quotes prices at which it will buy and sell a particular security, ensuring that investors can trade at any time.","letter":"M","hasNote":false},{"id":"FIN-1171","slug":"market-manipulation","term":"Market Manipulation","also_known_as":[],"difficulty":"Advanced","definition":"Market manipulation is deliberately interfering with the free and fair operation of a market to create artificial prices or a false impression of supply, demand or trading activity.","letter":"M","hasNote":false},{"id":"FIN-268","slug":"market-order","term":"Market Order","also_known_as":[],"difficulty":"Intermediate","definition":"A market order is an instruction to buy or sell a security immediately at the best price currently available.","letter":"M","hasNote":false},{"id":"FIN-1147","slug":"market-risk-premium","term":"Market Risk Premium","also_known_as":[],"difficulty":"Advanced","definition":"The market risk premium is the extra return investors expect from holding a broad market portfolio of shares, rather than risk-free assets, calculated as the expected market return minus the risk-free rate.","letter":"M","hasNote":false},{"id":"FIN-1160","slug":"market-sentiment","term":"Market Sentiment","also_known_as":[],"difficulty":"Advanced","definition":"Market sentiment is the overall mood or attitude of investors towards a market or an asset, ranging from optimistic, often called bullish, to pessimistic, often called bearish.","letter":"M","hasNote":false},{"id":"FIN-939","slug":"market-share","term":"Market Share","also_known_as":[],"difficulty":"Beginner","definition":"Market share is the percentage of total sales in a market that is earned by a particular company or product over a period.","letter":"M","hasNote":false},{"id":"FIN-386","slug":"market-value","term":"Market Value","also_known_as":[],"difficulty":"Intermediate","definition":"Market value is the current price at which an asset can be bought or sold in the market.","letter":"M","hasNote":false},{"id":"FIN-1118","slug":"market-value-added","term":"Market Value Added (MVA)","also_known_as":["MVA"],"difficulty":"Advanced","definition":"Market value added (MVA) is the difference between a company\'s market value and the total capital invested in it by shareholders and lenders, showing how much value management has created or destroyed.","letter":"M","hasNote":false},{"id":"FIN-456","slug":"marketplace-model","term":"Marketplace Model","also_known_as":[],"difficulty":"Intermediate","definition":"A marketplace model is a business model in which a company provides a platform that connects buyers and sellers and earns money from the transactions between them, usually through fees or commissions.","letter":"M","hasNote":false},{"id":"FIN-123","slug":"matching-principle","term":"Matching Principle","also_known_as":[],"difficulty":"Beginner","definition":"The matching principle is the accounting rule that expenses should be recorded in the same period as the revenue they helped to generate.","letter":"M","hasNote":false},{"id":"FIN-1448","slug":"material-adverse-change","term":"Material Adverse Change","also_known_as":[],"difficulty":"Advanced","definition":"A material adverse change clause is a provision in an acquisition or financing agreement that allows a party, usually the buyer or lender, to withdraw or renegotiate if a significant negative change occurs in the target\'s business or financial condition before completion.","letter":"M","hasNote":false},{"id":"FIN-121","slug":"materiality","term":"Materiality","also_known_as":[],"difficulty":"Beginner","definition":"Materiality is the accounting principle that information should be reported accurately and separately if leaving it out or getting it wrong could influence the decisions of people using the financial statements.","letter":"M","hasNote":false},{"id":"FIN-431","slug":"maturity-date","term":"Maturity Date","also_known_as":[],"difficulty":"Beginner","definition":"The maturity date is the date on which a bond, loan or other financial contract ends and the final payment is due, such as the repayment of a bond\'s face value.","letter":"M","hasNote":false},{"id":"FIN-693","slug":"maximum-drawdown","term":"Maximum Drawdown","also_known_as":[],"difficulty":"Intermediate","definition":"Maximum drawdown is the largest fall in the value of an investment or portfolio from a peak to a subsequent low, before a new peak is reached, usually expressed as a percentage.","letter":"M","hasNote":false},{"id":"FIN-1490","slug":"mean-absolute-percentage-error","term":"Mean Absolute Percentage Error (MAPE)","also_known_as":["MAPE"],"difficulty":"Advanced","definition":"Mean absolute percentage error (MAPE) is a measure of forecast accuracy, calculated as the average of the absolute forecast errors expressed as percentages of the actual values.","letter":"M","hasNote":false},{"id":"FIN-477","slug":"median","term":"Median","also_known_as":[],"difficulty":"Beginner","definition":"The median is the middle value in a set of numbers arranged in order. Half the values are above it and half are below.","letter":"M","hasNote":false},{"id":"FIN-502","slug":"medium-of-exchange","term":"Medium of Exchange","also_known_as":[],"difficulty":"Beginner","definition":"A medium of exchange is anything widely accepted in payment for goods and services. It is the function of money that makes buying and selling easy.","letter":"M","hasNote":false},{"id":"FIN-963","slug":"merger","term":"Merger","also_known_as":[],"difficulty":"Beginner","definition":"A merger is the combination of two companies into a single company, usually with the shareholders of both companies becoming shareholders in the combined business.","letter":"M","hasNote":false},{"id":"FIN-962","slug":"merger-and-acquisition","term":"Merger and Acquisition (M&A)","also_known_as":["M&A"],"difficulty":"Intermediate","definition":"Merger and acquisition (M&A), usually written in the plural as mergers and acquisitions, is the general term for transactions in which companies combine, buy or sell other companies or parts of companies.","letter":"M","hasNote":false},{"id":"FIN-1348","slug":"merger-model","term":"Merger Model","also_known_as":[],"difficulty":"Advanced","definition":"A merger model is a financial model that combines the financial statements of an acquiring company and a target company to analyse the effects of an acquisition, especially on the acquirer\'s earnings per share and financial position.","letter":"M","hasNote":false},{"id":"FIN-977","slug":"mezzanine-financing","term":"Mezzanine Financing","also_known_as":[],"difficulty":"Intermediate","definition":"Mezzanine financing is a hybrid form of financing that sits between senior debt and equity in a company\'s capital structure, typically combining subordinated debt with features that give the lender a share of the company\'s growth.","letter":"M","hasNote":false},{"id":"FIN-292","slug":"microeconomics","term":"Microeconomics","also_known_as":[],"difficulty":"Beginner","definition":"Microeconomics is the branch of economics that studies the decisions of individual households, workers and businesses, and how they interact in particular markets.","letter":"M","hasNote":false},{"id":"FIN-1301","slug":"microfinance","term":"Microfinance","also_known_as":[],"difficulty":"Advanced","definition":"Microfinance is the provision of small loans, savings accounts, insurance and other financial services to low-income people and small businesses who lack access to traditional banking.","letter":"M","hasNote":false},{"id":"FIN-B3-NEW3","slug":"mid-cap-stock","term":"Mid-Cap Stock","also_known_as":[],"difficulty":"Advanced","definition":"A mid-cap stock is a share in a company whose market capitalization falls between that of small-cap and large-cap companies.","letter":"M","hasNote":false},{"id":"FIN-416","slug":"mid-year-convention","term":"Mid-Year Convention","also_known_as":[],"difficulty":"Intermediate","definition":"The mid-year convention is an assumption in discounted cash flow analysis that cash flows arrive, on average, in the middle of each year rather than at the end.","letter":"M","hasNote":false},{"id":"FIN-068","slug":"minimum-payment","term":"Minimum Payment","also_known_as":[],"difficulty":"Beginner","definition":"A minimum payment is the smallest amount a borrower must pay on a debt, usually a credit card, by the due date to keep the account in good standing and avoid a late fee.","letter":"M","hasNote":false},{"id":"FIN-325","slug":"minimum-wage","term":"Minimum Wage","also_known_as":[],"difficulty":"Beginner","definition":"A minimum wage is the lowest hourly, daily or monthly pay that employers are legally required to pay workers.","letter":"M","hasNote":false},{"id":"FIN-839","slug":"mobile-payment","term":"Mobile Payment","also_known_as":[],"difficulty":"Beginner","definition":"A mobile payment is any payment made using a mobile device, such as a smartphone or tablet, whether in a shop, online or by sending money directly to another person.","letter":"M","hasNote":false},{"id":"FIN-478","slug":"mode","term":"Mode","also_known_as":[],"difficulty":"Beginner","definition":"The mode is the value that appears most often in a set of data.","letter":"M","hasNote":false},{"id":"FIN-1354","slug":"model-risk","term":"Model Risk","also_known_as":[],"difficulty":"Advanced","definition":"Model risk is the risk of losses or poor decisions resulting from errors in a financial model, or from using a model incorrectly or for a purpose it was not designed for.","letter":"M","hasNote":false},{"id":"FIN-1207","slug":"modified-duration","term":"Modified Duration","also_known_as":[],"difficulty":"Advanced","definition":"Modified duration measures how much a bond\'s price is expected to change, in percentage terms, for a one percentage point change in its yield.","letter":"M","hasNote":false},{"id":"FIN-1137","slug":"modified-internal-rate-of-return","term":"Modified Internal Rate of Return (MIRR)","also_known_as":["MIRR"],"difficulty":"Advanced","definition":"The modified internal rate of return (MIRR) is a version of the internal rate of return that assumes cash flows from a project are reinvested at a chosen rate, usually the cost of capital, rather than at the project\'s own internal rate of return.","letter":"M","hasNote":false},{"id":"FIN-1111","slug":"modigliani-miller-theorem","term":"Modigliani-Miller Theorem","also_known_as":[],"difficulty":"Advanced","definition":"The Modigliani-Miller theorem is a foundational principle of corporate finance stating that, under certain ideal conditions, a company\'s value is not affected by how it is financed, whether by debt or equity.","letter":"M","hasNote":false},{"id":"FIN-1150","slug":"momentum-investing","term":"Momentum Investing","also_known_as":[],"difficulty":"Advanced","definition":"Momentum investing is an investment strategy of buying assets that have risen in price recently and selling or avoiding those that have fallen, on the expectation that these trends will continue for a while.","letter":"M","hasNote":false},{"id":"FIN-1239","slug":"monetarism","term":"Monetarism","also_known_as":[],"difficulty":"Advanced","definition":"Monetarism is a school of economic thought, associated with economist Milton Friedman, which holds that the money supply is the main determinant of nominal economic activity and inflation, and that central banks should aim for steady, predictable money growth.","letter":"M","hasNote":false},{"id":"FIN-1222","slug":"monetary-base","term":"Monetary Base","also_known_as":[],"difficulty":"Advanced","definition":"The monetary base is the total amount of money created directly by a central bank, made up of physical currency in circulation and the reserves banks hold at the central bank.","letter":"M","hasNote":false},{"id":"FUT-0600","slug":"monetary-policy","term":"Monetary Policy","also_known_as":[],"difficulty":"Beginner","definition":"Monetary policy is the set of actions a central bank takes to influence interest rates, the supply of money and credit conditions, in order to achieve goals such as stable prices and steady economic growth.","letter":"M","hasNote":false},{"id":"FIN-001","slug":"money","term":"Money","also_known_as":[],"difficulty":"Beginner","definition":"Money is anything people widely accept as payment for goods, services and debts. It lets people trade easily, compare the value of different things and save purchasing power for later.","letter":"M","hasNote":false},{"id":"FIN-850","slug":"money-market","term":"Money Market","also_known_as":[],"difficulty":"Intermediate","definition":"The money market is the part of the financial system where short-term borrowing and lending takes place, usually for periods of less than a year, using instruments such as treasury bills, commercial paper and repurchase agreements.","letter":"M","hasNote":false},{"id":"FIN-732","slug":"money-market-fund","term":"Money Market Fund","also_known_as":[],"difficulty":"Beginner","definition":"A money market fund is an investment fund that invests in very short-term, high-quality debt securities, such as treasury bills, commercial paper and bank deposits, aiming to preserve capital and provide liquidity with a modest return.","letter":"M","hasNote":false},{"id":"FIN-782","slug":"money-supply","term":"Money Supply","also_known_as":[],"difficulty":"Intermediate","definition":"The money supply is the total amount of money circulating in an economy at a given time, including cash and various types of bank deposits.","letter":"M","hasNote":false},{"id":"FIN-1202","slug":"money-weighted-return","term":"Money-Weighted Return","also_known_as":[],"difficulty":"Advanced","definition":"Money-weighted return is a measure of investment performance that takes into account the timing and size of money added to or withdrawn from a portfolio, reflecting the return actually experienced by the investor.","letter":"M","hasNote":false},{"id":"FIN-440","slug":"moneyness","term":"Moneyness","also_known_as":[],"difficulty":"Intermediate","definition":"Moneyness describes the relationship between an option\'s strike price and the current price of the underlying asset, indicating whether the option would be profitable to exercise now.","letter":"M","hasNote":false},{"id":"FIN-1341","slug":"monte-carlo-simulation","term":"Monte Carlo Simulation","also_known_as":[],"difficulty":"Advanced","definition":"Monte Carlo simulation is a technique that uses a computer to run thousands of scenarios, each with randomly chosen values for uncertain inputs, to show the range and probability of possible outcomes.","letter":"M","hasNote":false},{"id":"FIN-1038","slug":"month-end-close","term":"Month-End Close","also_known_as":[],"difficulty":"Advanced","definition":"Month-end close is the set of accounting tasks a business carries out at the end of each month to record, check and finalise its financial transactions, so that accurate monthly results can be produced.","letter":"M","hasNote":false},{"id":"FIN-1130","slug":"monthly-recurring-revenue","term":"Monthly Recurring Revenue (MRR)","also_known_as":["MRR"],"difficulty":"Intermediate","definition":"Monthly recurring revenue (MRR) is the predictable revenue a subscription business expects to receive each month from its active customers.","letter":"M","hasNote":false},{"id":"FIN-808","slug":"moral-hazard","term":"Moral Hazard","also_known_as":[],"difficulty":"Intermediate","definition":"Moral hazard is the tendency for people or organisations to take greater risks when they are protected from the consequences of those risks, for example by insurance, guarantees or the expectation of a rescue.","letter":"M","hasNote":false},{"id":"FIN-516","slug":"mortgage","term":"Mortgage","also_known_as":[],"difficulty":"Beginner","definition":"A mortgage is a loan used to buy property, in which the property itself serves as security for the lender. If the borrower does not repay, the lender can take the property and sell it.","letter":"M","hasNote":false},{"id":"FIN-911","slug":"mortgage-backed-security","term":"Mortgage-Backed Security (MBS)","also_known_as":["MBS"],"difficulty":"Intermediate","definition":"A mortgage-backed security (MBS) is an investment backed by a pool of home or commercial mortgages, which pays investors from the interest and principal repayments made by the borrowers.","letter":"M","hasNote":false},{"id":"FIN-858","slug":"mortgage-insurance","term":"Mortgage Insurance","also_known_as":[],"difficulty":"Intermediate","definition":"Mortgage insurance is insurance that protects a lender, not the borrower, against losses if a borrower stops making mortgage payments, typically required when the borrower\'s deposit is small. The term is used mainly in the United States.","letter":"M","hasNote":false},{"id":"FIN-995","slug":"moving-average","term":"Moving Average","also_known_as":[],"difficulty":"Intermediate","definition":"A moving average is the average of a set of data points over a fixed number of recent periods, recalculated each period as new data is added and the oldest data is dropped.","letter":"M","hasNote":false},{"id":"FIN-488","slug":"multiple-regression","term":"Multiple Regression","also_known_as":[],"difficulty":"Intermediate","definition":"Multiple regression is a statistical method that models how a dependent variable is related to two or more independent variables at the same time.","letter":"M","hasNote":false},{"id":"FIN-398","slug":"multiples-valuation","term":"Multiples Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Multiples valuation is a method of valuing a company by applying a ratio, such as price-to-earnings or EV/EBITDA, taken from similar companies or transactions to the company\'s own financial figures.","letter":"M","hasNote":false},{"id":"FIN-247","slug":"municipal-bond","term":"Municipal Bond","also_known_as":[],"difficulty":"Beginner","definition":"A municipal bond is a bond issued by a local or regional government, such as a city, county or state, to fund public projects like schools, roads and water systems.","letter":"M","hasNote":false},{"id":"FUT-0467","slug":"mutual-fund","term":"Mutual Fund","also_known_as":[],"difficulty":"Beginner","definition":"A mutual fund is an investment fund that pools money from many investors and invests it in a diversified portfolio of shares, bonds or other assets, managed by professionals.","letter":"M","hasNote":false},{"id":"FIN-1096","slug":"mutually-exclusive-projects","term":"Mutually Exclusive Projects","also_known_as":[],"difficulty":"Advanced","definition":"Mutually exclusive projects are investment options where choosing one rules out the others, because they compete for the same resources, site or purpose.","letter":"M","hasNote":false},{"id":"FIN-B3-NEW2","slug":"nash-equilibrium","term":"Nash Equilibrium","also_known_as":[],"difficulty":"Advanced","definition":"A Nash equilibrium is a situation in a strategic interaction where no participant can improve their outcome by changing their own strategy, as long as the others keep theirs unchanged.","letter":"N","hasNote":false},{"id":"FIN-1258","slug":"natural-monopoly","term":"Natural Monopoly","also_known_as":[],"difficulty":"Advanced","definition":"A natural monopoly is a market in which a single supplier can serve the whole market at a lower cost than two or more competing suppliers could, usually because of very high fixed costs and large economies of scale.","letter":"N","hasNote":false},{"id":"FIN-1217","slug":"natural-rate-of-unemployment","term":"Natural Rate of Unemployment","also_known_as":[],"difficulty":"Advanced","definition":"The natural rate of unemployment is the level of unemployment that exists when the economy is operating at its sustainable potential, made up of frictional and structural unemployment but not cyclical unemployment.","letter":"N","hasNote":false},{"id":"FIN-314","slug":"negative-externality","term":"Negative Externality","also_known_as":[],"difficulty":"Intermediate","definition":"A negative externality is a cost that an activity imposes on people who are not directly involved in it and who are not compensated for it.","letter":"N","hasNote":false},{"id":"FIN-342","slug":"neobank","term":"Neobank","also_known_as":[],"difficulty":"Beginner","definition":"A neobank is a bank or banking service that operates entirely online, through a mobile app and website, without physical branches.","letter":"N","hasNote":false},{"id":"FIN-735","slug":"net-asset-value","term":"Net Asset Value (NAV)","also_known_as":["NAV"],"difficulty":"Intermediate","definition":"Net asset value (NAV) is the value of an investment fund\'s assets minus its liabilities, usually expressed per unit or share of the fund.","letter":"N","hasNote":false},{"id":"FIN-631","slug":"net-debt","term":"Net Debt","also_known_as":[],"difficulty":"Intermediate","definition":"Net debt is a company\'s total borrowings minus its cash and cash equivalents. It shows how much debt would remain if the company used all its cash to repay what it owes.","letter":"N","hasNote":false},{"id":"FIN-632","slug":"net-debt-to-ebitda","term":"Net Debt to EBITDA","also_known_as":[],"difficulty":"Intermediate","definition":"Net debt to EBITDA is a company\'s net debt divided by its annual EBITDA. It shows roughly how many years of earnings before interest, taxes, depreciation and amortization it would take to repay its debt.","letter":"N","hasNote":false},{"id":"FIN-1236","slug":"net-exports","term":"Net Exports","also_known_as":[],"difficulty":"Advanced","definition":"Net exports are the value of a country\'s exports of goods and services minus the value of its imports over a period.","letter":"N","hasNote":false},{"id":"NEW-01","slug":"net-income-accounting","term":"Net Income (Accounting)","also_known_as":["Net Profit","Bottom Line"],"difficulty":"Beginner","definition":"Net income, in accounting, is a company\'s total profit for a period after all expenses, interest and taxes have been deducted from revenue. It is often called the bottom line.","letter":"N","hasNote":false},{"id":"FIN-010","slug":"net-income-personal","term":"Net Income (Personal)","also_known_as":["Take-Home Pay"],"difficulty":"Beginner","definition":"Net income, for a person, is the money left from your earnings after income tax and other deductions have been taken out. It is often called take-home pay.","letter":"N","hasNote":false},{"id":"FIN-374","slug":"net-interest-income","term":"Net Interest Income","also_known_as":[],"difficulty":"Intermediate","definition":"Net interest income is the difference between the interest a bank earns on its loans and investments and the interest it pays on its deposits and borrowing.","letter":"N","hasNote":false},{"id":"FIN-373","slug":"net-interest-margin","term":"Net Interest Margin (NIM)","also_known_as":["NIM"],"difficulty":"Intermediate","definition":"Net interest margin (NIM) is a measure of a bank\'s profitability from lending, calculated as net interest income divided by the average assets that earn interest, such as loans and investments.","letter":"N","hasNote":false},{"id":"FIN-569","slug":"net-loss","term":"Net Loss","also_known_as":[],"difficulty":"Intermediate","definition":"A net loss occurs when a company\'s total expenses, including taxes, exceed its total revenue for a period, so its bottom line is negative.","letter":"N","hasNote":false},{"id":"FIN-1028","slug":"net-operating-loss","term":"Net Operating Loss (NOL)","also_known_as":["NOL"],"difficulty":"Advanced","definition":"A net operating loss (NOL) is a loss for tax purposes, when a business\'s allowable deductions exceed its taxable income for a year, which can often be used to reduce taxable income in other years. The term is used mainly in the United States.","letter":"N","hasNote":false},{"id":"FIN-176","slug":"net-present-value","term":"Net Present Value (NPV)","also_known_as":["NPV"],"difficulty":"Intermediate","definition":"Net present value (NPV) is the value today of all the cash a project or investment is expected to produce, minus what it costs. A positive NPV means the project is expected to earn more than the required return.","letter":"N","hasNote":false},{"id":"FIN-618","slug":"net-profit-margin","term":"Net Profit Margin","also_known_as":[],"difficulty":"Intermediate","definition":"Net profit margin is net income divided by revenue, showing the percentage of each sale that remains as profit after all expenses, interest and taxes.","letter":"N","hasNote":false},{"id":"FIN-474","slug":"net-promoter-score","term":"Net Promoter Score (NPS)","also_known_as":["NPS"],"difficulty":"Intermediate","definition":"Net Promoter Score (NPS) is a measure of customer loyalty based on how likely customers are to recommend a company, product or service to others, on a scale from 0 to 10.","letter":"N","hasNote":false},{"id":"FIN-583","slug":"net-realizable-value","term":"Net Realizable Value","also_known_as":[],"difficulty":"Intermediate","definition":"Net realizable value is the estimated selling price of an item of inventory in the ordinary course of business, minus the estimated costs of completing it and making the sale.","letter":"N","hasNote":false},{"id":"FIN-1131","slug":"net-revenue-retention","term":"Net Revenue Retention (NRR)","also_known_as":["NRR"],"difficulty":"Advanced","definition":"Net revenue retention (NRR) is the percentage of recurring revenue a company keeps from an existing group of customers over a period, including upgrades and expansion, minus downgrades and cancellations.","letter":"N","hasNote":false},{"id":"FIN-1320","slug":"net-stable-funding-ratio","term":"Net Stable Funding Ratio (NSFR)","also_known_as":["NSFR"],"difficulty":"Advanced","definition":"The net stable funding ratio (NSFR) is a banking regulation requiring banks to fund their activities with enough stable sources of funding, such as long-term debt, capital and stable deposits, relative to the liquidity and maturity of their assets, over a one-year horizon.","letter":"N","hasNote":false},{"id":"FIN-1102","slug":"net-working-capital","term":"Net Working Capital","also_known_as":[],"difficulty":"Advanced","definition":"Net working capital is the difference between a business\'s current operating assets, such as receivables and inventory, and its current operating liabilities, such as payables, usually excluding cash and debt when used in valuation and modelling.","letter":"N","hasNote":false},{"id":"FIN-1359","slug":"net-working-capital-peg","term":"Net Working Capital Peg","also_known_as":[],"difficulty":"Advanced","definition":"A net working capital peg is a target level of working capital agreed between a buyer and seller in an acquisition, against which the actual working capital at completion is compared to adjust the purchase price.","letter":"N","hasNote":false},{"id":"FIN-012","slug":"net-worth","term":"Net Worth","also_known_as":[],"difficulty":"Beginner","definition":"Net worth is the value of everything you own minus everything you owe. It is the most common measure of a person\'s or household\'s financial position at a point in time.","letter":"N","hasNote":false},{"id":"FIN-460","slug":"network-effect","term":"Network Effect","also_known_as":[],"difficulty":"Intermediate","definition":"A network effect occurs when a product or service becomes more valuable to each user as more people use it.","letter":"N","hasNote":false},{"id":"FIN-1226","slug":"neutral-interest-rate","term":"Neutral Interest Rate","also_known_as":[],"difficulty":"Advanced","definition":"The neutral interest rate is the theoretical interest rate at which monetary policy is neither stimulating nor restraining the economy, consistent with full employment and stable inflation.","letter":"N","hasNote":false},{"id":"FIN-752","slug":"nominal-gdp","term":"Nominal GDP","also_known_as":[],"difficulty":"Beginner","definition":"Nominal GDP is the value of all goods and services produced in an economy, measured at the prices of the period in which they were produced, without adjusting for inflation.","letter":"N","hasNote":false},{"id":"FIN-057","slug":"nominal-interest-rate","term":"Nominal Interest Rate","also_known_as":[],"difficulty":"Beginner","definition":"The nominal interest rate is the stated interest rate on a loan or investment, before adjusting for inflation or for the effect of compounding.","letter":"N","hasNote":false},{"id":"FIN-685","slug":"nominal-return","term":"Nominal Return","also_known_as":[],"difficulty":"Intermediate","definition":"Nominal return is the return on an investment measured in money terms, before adjusting for inflation.","letter":"N","hasNote":false},{"id":"FIN-036","slug":"nominal-value","term":"Nominal Value","also_known_as":[],"difficulty":"Beginner","definition":"Nominal value is an amount expressed in money terms as it appears at the time, without adjusting for inflation. It is the face amount you see on a price tag, payslip or statement.","letter":"N","hasNote":false},{"id":"FIN-160","slug":"non-current-asset","term":"Non-Current Asset","also_known_as":[],"difficulty":"Beginner","definition":"A non-current asset is an asset a business expects to hold and use for more than one year, such as land, buildings, equipment, long-term investments and intangible assets.","letter":"N","hasNote":false},{"id":"FIN-162","slug":"non-current-liability","term":"Non-Current Liability","also_known_as":[],"difficulty":"Beginner","definition":"A non-current liability is an obligation that a business does not need to settle within the next year, such as a long-term loan, bonds or a pension obligation.","letter":"N","hasNote":false},{"id":"FIN-1449","slug":"non-disclosure-agreement","term":"Non-Disclosure Agreement (NDA)","also_known_as":["NDA"],"difficulty":"Intermediate","definition":"A non-disclosure agreement (NDA) is a legal contract in which one or more parties agree to keep certain information confidential and not to use it except for an agreed purpose.","letter":"N","hasNote":false},{"id":"FIN-1329","slug":"non-fungible-token","term":"Non-Fungible Token (NFT)","also_known_as":["NFT"],"difficulty":"Advanced","definition":"A non-fungible token (NFT) is a unique digital token recorded on a blockchain that represents ownership of, or a claim to, a specific item, such as digital art, a collectible, music or a virtual item.","letter":"N","hasNote":false},{"id":"FIN-875","slug":"non-operating-asset","term":"Non-Operating Asset","also_known_as":[],"difficulty":"Intermediate","definition":"A non-operating asset is an asset a company owns that is not needed to run its core business, such as excess cash, investments in other companies or unused land.","letter":"N","hasNote":false},{"id":"FIN-593","slug":"noncontrolling-interest","term":"Noncontrolling Interest","also_known_as":["Minority Interest"],"difficulty":"Intermediate","definition":"Noncontrolling interest is the portion of a subsidiary\'s equity, and its profits, that belongs to shareholders other than the parent company.","letter":"N","hasNote":true},{"id":"FIN-370","slug":"nonperforming-loan","term":"Nonperforming Loan (NPL)","also_known_as":["NPL"],"difficulty":"Intermediate","definition":"A nonperforming loan (NPL) is a loan on which the borrower has stopped making scheduled payments for a set period, usually 90 days or more, or is unlikely to repay in full.","letter":"N","hasNote":false},{"id":"FIN-1007","slug":"nonrefundable-tax-credit","term":"Nonrefundable Tax Credit","also_known_as":[],"difficulty":"Intermediate","definition":"A nonrefundable tax credit is a tax credit that can reduce a person\'s tax bill only down to zero. Any part of the credit that exceeds the tax owed is lost, unless the rules allow it to be carried forward.","letter":"N","hasNote":false},{"id":"FIN-500","slug":"normal-distribution","term":"Normal Distribution","also_known_as":[],"difficulty":"Intermediate","definition":"A normal distribution is a symmetrical, bell-shaped pattern in which most values cluster around the mean and values become less common the further they are from it.","letter":"N","hasNote":false},{"id":"FIN-307","slug":"normal-good","term":"Normal Good","also_known_as":[],"difficulty":"Intermediate","definition":"A normal good is a product for which demand increases when consumers\' incomes rise and decreases when incomes fall.","letter":"N","hasNote":false},{"id":"FIN-1091","slug":"normalized-earnings","term":"Normalized Earnings","also_known_as":[],"difficulty":"Advanced","definition":"Normalized earnings are a company\'s profits adjusted to remove unusual, one-time or non-recurring items, and sometimes to smooth out the effects of the business cycle, to show what the business earns in a typical year.","letter":"N","hasNote":false},{"id":"FIN-116","slug":"notes-to-financial-statements","term":"Notes to Financial Statements","also_known_as":[],"difficulty":"Beginner","definition":"Notes to financial statements are the detailed explanations and additional information that accompany the main financial statements and help readers understand the figures.","letter":"N","hasNote":false},{"id":"FIN-1059","slug":"off-balance-sheet-financing","term":"Off-Balance-Sheet Financing","also_known_as":[],"difficulty":"Advanced","definition":"Off-balance-sheet financing is a way of funding a company\'s activities that does not show the related assets or liabilities on its balance sheet, which can make the company appear less indebted than it really is.","letter":"O","hasNote":false},{"id":"FIN-1093","slug":"one-time-charge","term":"One-Time Charge","also_known_as":[],"difficulty":"Advanced","definition":"A one-time charge is an expense a company reports that it considers unusual and unlikely to recur, such as restructuring costs, a legal settlement or an asset write-down.","letter":"O","hasNote":false},{"id":"FIN-864","slug":"open-banking","term":"Open Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Open banking is a system, which originated in the United Kingdom and the European Union, that allows customers to securely share their bank account data with authorised third-party providers, and to let those providers initiate payments, with the customer\'s consent.","letter":"O","hasNote":false},{"id":"FIN-1173","slug":"open-end-fund","term":"Open-End Fund","also_known_as":[],"difficulty":"Advanced","definition":"An open-end fund is an investment fund that continuously issues new units when investors buy and redeems units when investors sell, at a price based on the fund\'s net asset value.","letter":"O","hasNote":false},{"id":"FIN-1332","slug":"open-finance","term":"Open Finance","also_known_as":[],"difficulty":"Advanced","definition":"Open finance is the extension of open banking to a wider range of financial products, allowing customers to securely share data from savings, investments, pensions, mortgages and insurance with authorised third parties, with their consent.","letter":"O","hasNote":false},{"id":"FIN-779","slug":"open-market-operations","term":"Open Market Operations","also_known_as":[],"difficulty":"Intermediate","definition":"Open market operations are the buying and selling of government securities or other assets by a central bank in financial markets, to manage the money supply and keep short-term interest rates close to its policy rate.","letter":"O","hasNote":false},{"id":"FIN-190","slug":"operating-cash-flow","term":"Operating Cash Flow","also_known_as":[],"difficulty":"Intermediate","definition":"Operating cash flow is the cash a business generates from its normal day-to-day activities, such as selling goods and paying suppliers, staff and taxes.","letter":"O","hasNote":false},{"id":"FIN-651","slug":"operating-cycle","term":"Operating Cycle","also_known_as":[],"difficulty":"Intermediate","definition":"The operating cycle is the average time it takes a business to buy inventory, sell it and collect the cash from customers.","letter":"O","hasNote":false},{"id":"FIN-146","slug":"operating-expense","term":"Operating Expense","also_known_as":["Operating Expenditure (OpEx)","Operating Expenditure","OpEx"],"difficulty":"Beginner","definition":"An operating expense is a cost a business incurs in running its day-to-day operations that is not directly tied to producing its goods, such as rent, salaries, marketing, utilities and administration.","letter":"O","hasNote":true},{"id":"FUT-0052","slug":"operating-income","term":"Operating Income","also_known_as":["Operating Profit"],"difficulty":"Beginner","definition":"Operating income is the profit a business makes from its core operations, calculated as revenue minus cost of goods sold and operating expenses, before interest and taxes.","letter":"O","hasNote":false},{"id":"FIN-217","slug":"operating-kpi","term":"Operating KPI","also_known_as":[],"difficulty":"Beginner","definition":"An operating KPI is a key performance indicator that measures how well a business\'s day-to-day activities are working, such as production output, delivery times, customer numbers or staff productivity.","letter":"O","hasNote":false},{"id":"FIN-584","slug":"operating-lease","term":"Operating Lease","also_known_as":[],"difficulty":"Intermediate","definition":"An operating lease is a lease in which the lessee uses an asset for part of its life without taking on most of the risks and rewards of owning it, such as a short-term rental of equipment or office space.","letter":"O","hasNote":false},{"id":"FIN-647","slug":"operating-leverage","term":"Operating Leverage","also_known_as":[],"difficulty":"Intermediate","definition":"Operating leverage is the degree to which a company\'s costs are fixed rather than variable, which determines how strongly its operating profit changes when sales change.","letter":"O","hasNote":false},{"id":"FIN-617","slug":"operating-margin","term":"Operating Margin","also_known_as":[],"difficulty":"Intermediate","definition":"Operating margin is operating income divided by revenue, showing the percentage of each sale that remains as profit after paying for the costs of running the business, before interest and tax.","letter":"O","hasNote":false},{"id":"FIN-1350","slug":"operating-model","term":"Operating Model","also_known_as":[],"difficulty":"Advanced","definition":"An operating model is a financial model that projects a company\'s detailed operations, such as revenue drivers, costs, staffing and capital spending, and links them to its income statement, balance sheet and cash flow statement.","letter":"O","hasNote":false},{"id":"FIN-900","slug":"operational-risk","term":"Operational Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Operational risk is the risk of losses resulting from inadequate or failed internal processes, people and systems, or from external events.","letter":"O","hasNote":false},{"id":"FIN-033","slug":"opportunity-cost","term":"Opportunity Cost","also_known_as":[],"difficulty":"Beginner","definition":"Opportunity cost is the value of the best alternative you give up when you make a choice. Every decision to use time or money one way means not using it another way.","letter":"O","hasNote":false},{"id":"FIN-1108","slug":"optimal-capital-structure","term":"Optimal Capital Structure","also_known_as":[],"difficulty":"Advanced","definition":"Optimal capital structure is the mix of debt and equity that minimises a company\'s overall cost of capital and maximises its value.","letter":"O","hasNote":false},{"id":"FIN-425","slug":"option","term":"Option","also_known_as":[],"difficulty":"Intermediate","definition":"An option is a contract that gives its buyer the right, but not the obligation, to buy or sell an asset at a set price on or before a specific date.","letter":"O","hasNote":false},{"id":"FIN-1457","slug":"option-pool","term":"Option Pool","also_known_as":[],"difficulty":"Advanced","definition":"An option pool is a portion of a company\'s shares set aside to grant stock options or other equity awards to current and future employees, advisers and directors.","letter":"O","hasNote":false},{"id":"FIN-437","slug":"option-premium","term":"Option Premium","also_known_as":[],"difficulty":"Intermediate","definition":"The option premium is the price the buyer of an option pays to the seller for the rights the option provides.","letter":"O","hasNote":false},{"id":"FIN-510","slug":"ordinary-annuity","term":"Ordinary Annuity","also_known_as":[],"difficulty":"Intermediate","definition":"An ordinary annuity is a series of equal payments made at the end of each period, such as the end of each month or year, for a set number of periods.","letter":"O","hasNote":false},{"id":"FIN-220","slug":"organic-growth","term":"Organic Growth","also_known_as":[],"difficulty":"Beginner","definition":"Organic growth is growth a business achieves from its existing operations, through selling more, raising prices or launching new products, rather than by buying other businesses.","letter":"O","hasNote":false},{"id":"FIN-575","slug":"other-comprehensive-income","term":"Other Comprehensive Income","also_known_as":[],"difficulty":"Intermediate","definition":"Other comprehensive income is a category of gains and losses that are recognised directly in equity rather than in net income, because they are considered unrealized or outside normal operating performance.","letter":"O","hasNote":false},{"id":"FIN-1471","slug":"out-of-court-restructuring","term":"Out-of-Court Restructuring","also_known_as":[],"difficulty":"Advanced","definition":"An out-of-court restructuring is a reorganisation of a company\'s debts and finances negotiated directly between the company and its creditors, without a formal court-supervised insolvency or bankruptcy process.","letter":"O","hasNote":false},{"id":"FIN-523","slug":"out-of-pocket-maximum","term":"Out-of-Pocket Maximum","also_known_as":[],"difficulty":"Intermediate","definition":"An out-of-pocket maximum is the most a person with health insurance will have to pay for covered medical care in a year, after which the insurer pays 100% of covered costs.","letter":"O","hasNote":false},{"id":"FIN-443","slug":"out-of-the-money","term":"Out-of-the-Money","also_known_as":[],"difficulty":"Intermediate","definition":"An option is out of the money when exercising it immediately would not be profitable: for a call, when the underlying price is below the strike price; for a put, when it is above.","letter":"O","hasNote":false},{"id":"FIN-499","slug":"outlier","term":"Outlier","also_known_as":[],"difficulty":"Beginner","definition":"An outlier is a data point that is very different from most of the other values in a data set.","letter":"O","hasNote":false},{"id":"FIN-1211","slug":"output-gap","term":"Output Gap","also_known_as":[],"difficulty":"Advanced","definition":"The output gap is the difference between an economy\'s actual output and its estimated potential output, usually expressed as a percentage of potential GDP.","letter":"O","hasNote":false},{"id":"FIN-948","slug":"outsourcing","term":"Outsourcing","also_known_as":[],"difficulty":"Intermediate","definition":"Outsourcing is the practice of hiring an outside company to perform tasks, services or manufacturing that a business could otherwise do itself.","letter":"O","hasNote":false},{"id":"FIN-281","slug":"over-the-counter-market","term":"Over-the-Counter Market","also_known_as":[],"difficulty":"Intermediate","definition":"An over-the-counter (OTC) market is a decentralised market where securities and other instruments are traded directly between two parties, rather than on an organised exchange.","letter":"O","hasNote":false},{"id":"FIN-1157","slug":"overconfidence-bias","term":"Overconfidence Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Overconfidence bias is the tendency for people to overestimate their own knowledge, abilities or the accuracy of their predictions.","letter":"O","hasNote":false},{"id":"FIN-071","slug":"overdraft","term":"Overdraft","also_known_as":[],"difficulty":"Beginner","definition":"An overdraft happens when you spend or withdraw more money than you have in your bank account, so the balance goes below zero.","letter":"O","hasNote":false},{"id":"FIN-072","slug":"overdraft-protection","term":"Overdraft Protection","also_known_as":[],"difficulty":"Beginner","definition":"Overdraft protection is a bank service that covers a payment when your account does not have enough money, instead of rejecting it, usually in return for a fee or interest.","letter":"O","hasNote":false},{"id":"FIN-1498","slug":"overfitting","term":"Overfitting","also_known_as":[],"difficulty":"Advanced","definition":"Overfitting is when a statistical or machine learning model fits its training data too closely, capturing random noise rather than the underlying pattern, so that it performs well on past data but poorly on new data.","letter":"O","hasNote":false},{"id":"FIN-644","slug":"overhead","term":"Overhead","also_known_as":[],"difficulty":"Intermediate","definition":"Overhead is the ongoing cost of running a business that is not directly tied to producing a specific product or service, such as rent, utilities, administration, insurance and management salaries.","letter":"O","hasNote":false},{"id":"FIN-490","slug":"p-value","term":"P-Value","also_known_as":[],"difficulty":"Intermediate","definition":"A p-value is the probability of seeing results at least as extreme as those observed, assuming that there is actually no real effect or difference, the null hypothesis.","letter":"P","hasNote":false},{"id":"FIN-576","slug":"paid-in-capital","term":"Paid-In Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Paid-in capital is the total amount of money shareholders have invested in a company by buying shares directly from it, including amounts paid above the shares\' nominal value.","letter":"P","hasNote":false},{"id":"FIN-006","slug":"passive-income","term":"Passive Income","also_known_as":[],"difficulty":"Beginner","definition":"Passive income is money that keeps coming in with little ongoing effort once the initial work or investment has been made, such as rent, dividends, interest or royalties.","letter":"P","hasNote":false},{"id":"FIN-715","slug":"passive-investing","term":"Passive Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Passive investing is an investment strategy that aims to match the performance of a market index, rather than trying to beat it, usually by buying and holding a fund that tracks the index.","letter":"P","hasNote":false},{"id":"FIN-466","slug":"patent","term":"Patent","also_known_as":[],"difficulty":"Beginner","definition":"A patent is a legal right granted by a government that gives an inventor the exclusive right to make, use and sell an invention for a limited period, usually up to 20 years from filing.","letter":"P","hasNote":false},{"id":"FIN-179","slug":"payback-period","term":"Payback Period","also_known_as":[],"difficulty":"Beginner","definition":"The payback period is the length of time it takes for an investment to earn back its initial cost from the cash it generates.","letter":"P","hasNote":false},{"id":"FIN-822","slug":"payday-loan","term":"Payday Loan","also_known_as":[],"difficulty":"Beginner","definition":"A payday loan is a small, short-term, high-cost loan, typically due on the borrower\'s next payday, often used to cover urgent expenses.","letter":"P","hasNote":false},{"id":"FIN-B3-NEW8","slug":"payment-gateway","term":"Payment Gateway","also_known_as":[],"difficulty":"Advanced","definition":"A payment gateway is a technology service that securely captures and transmits a customer\'s payment details from a website, app or terminal to the payment processor, so that an online or card payment can be authorised.","letter":"P","hasNote":false},{"id":"FIN-1287","slug":"payment-processor","term":"Payment Processor","also_known_as":[],"difficulty":"Advanced","definition":"A payment processor is a company that handles the technical steps of card and electronic payments, passing transaction information between merchants, banks and card networks so that payments can be authorised and settled.","letter":"P","hasNote":false},{"id":"FIN-542","slug":"payroll-tax","term":"Payroll Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Payroll tax is a tax based on wages and salaries, paid by employers, employees or both, usually to fund social security, pensions, healthcare or unemployment benefits.","letter":"P","hasNote":false},{"id":"FIN-1109","slug":"pecking-order-theory","term":"Pecking Order Theory","also_known_as":[],"difficulty":"Advanced","definition":"Pecking order theory is a theory of corporate finance stating that companies prefer to fund investments first with internal cash, then with debt, and only as a last resort by issuing new shares.","letter":"P","hasNote":false},{"id":"FIN-840","slug":"peer-to-peer-payment","term":"Peer-to-Peer Payment","also_known_as":[],"difficulty":"Beginner","definition":"A peer-to-peer payment is a transfer of money directly from one person to another, usually through a mobile app or online service, without needing cash or a cheque.","letter":"P","hasNote":false},{"id":"FIN-410","slug":"peg-ratio","term":"PEG Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The PEG ratio is a company\'s price-to-earnings ratio divided by its expected annual earnings growth rate. It adjusts the P/E ratio for growth.","letter":"P","hasNote":false},{"id":"FIN-1149","slug":"penny-stock","term":"Penny Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A penny stock is a share that trades at a very low price, typically in a small company with limited trading, and often outside major stock exchanges.","letter":"P","hasNote":false},{"id":"FIN-525","slug":"pension","term":"Pension","also_known_as":[],"difficulty":"Beginner","definition":"A pension is a fund or arrangement that provides regular income to a person after they retire, built up through contributions during their working life.","letter":"P","hasNote":false},{"id":"FIN-1048","slug":"pension-liability","term":"Pension Liability","also_known_as":[],"difficulty":"Advanced","definition":"A pension liability is the obligation a company records for retirement benefits it has promised to employees under a defined benefit pension plan, measured as the gap between the value of the promised benefits and the assets set aside to pay them.","letter":"P","hasNote":false},{"id":"FIN-507","slug":"percentage-point","term":"Percentage Point","also_known_as":[],"difficulty":"Beginner","definition":"A percentage point is the simple arithmetic difference between two percentages. It is different from a percentage change, which measures how much a figure has grown relative to its starting level.","letter":"P","hasNote":false},{"id":"FIN-986","slug":"percentile","term":"Percentile","also_known_as":[],"difficulty":"Beginner","definition":"A percentile is a value below which a given percentage of observations in a data set fall.","letter":"P","hasNote":false},{"id":"FIN-508","slug":"periodic-rate","term":"Periodic Rate","also_known_as":[],"difficulty":"Intermediate","definition":"A periodic rate is the interest rate that applies to a single period, such as a month or a quarter, rather than to a full year.","letter":"P","hasNote":false},{"id":"FIN-1026","slug":"permanent-difference","term":"Permanent Difference","also_known_as":[],"difficulty":"Advanced","definition":"A permanent difference is an item of income or expense that is treated differently in the accounts and for tax and will never reverse, such as a fine that is expensed in the accounts but is never deductible for tax.","letter":"P","hasNote":false},{"id":"FIN-414","slug":"perpetual-growth-method","term":"Perpetual Growth Method","also_known_as":[],"difficulty":"Intermediate","definition":"The perpetual growth method calculates a company\'s terminal value in a discounted cash flow model by assuming its cash flows will grow at a constant rate forever after the forecast period.","letter":"P","hasNote":false},{"id":"FUT-1476","slug":"perpetuity","term":"Perpetuity","also_known_as":[],"difficulty":"Intermediate","definition":"A perpetuity is a stream of equal payments that continues forever. Its value today can be found by dividing the regular payment by the discount rate.","letter":"P","hasNote":false},{"id":"FIN-365","slug":"personal-loan","term":"Personal Loan","also_known_as":[],"difficulty":"Beginner","definition":"A personal loan is a fixed amount of money borrowed from a bank or lender for personal use, repaid in regular instalments over a set period with interest.","letter":"P","hasNote":false},{"id":"FIN-1215","slug":"phillips-curve","term":"Phillips Curve","also_known_as":[],"difficulty":"Advanced","definition":"The Phillips curve is an economic idea describing a relationship between unemployment and inflation, in which lower unemployment tends to be associated with higher inflation, at least in the short run.","letter":"P","hasNote":false},{"id":"FIN-1467","slug":"pik-interest","term":"PIK Interest","also_known_as":[],"difficulty":"Advanced","definition":"PIK interest, short for payment-in-kind interest, is interest that is not paid in cash but is instead added to the loan balance, increasing the amount owed.","letter":"P","hasNote":false},{"id":"FIN-1355","slug":"pitchbook","term":"Pitchbook","also_known_as":[],"difficulty":"Advanced","definition":"A pitchbook is a presentation prepared by an investment bank or advisory firm to win business from a client or to present a proposed transaction, containing market analysis, valuation work and recommendations.","letter":"P","hasNote":false},{"id":"FIN-459","slug":"platform-business","term":"Platform Business","also_known_as":[],"difficulty":"Intermediate","definition":"A platform business is a company that creates value by enabling interactions between different groups of users, such as buyers and sellers, drivers and riders or app developers and phone users, rather than mainly by making products itself.","letter":"P","hasNote":false},{"id":"FIN-1290","slug":"point-of-sale","term":"Point of Sale (POS)","also_known_as":["POS"],"difficulty":"Advanced","definition":"A point of sale (POS) is the place and moment where a customer pays for goods or services, and the hardware and software used to process the sale, such as a till, card terminal or tablet system.","letter":"P","hasNote":false},{"id":"FIN-1464","slug":"poison-pill","term":"Poison Pill","also_known_as":[],"difficulty":"Advanced","definition":"A poison pill is a defensive tactic used by a company\'s board to make a hostile takeover more difficult or expensive, typically by allowing existing shareholders, other than the bidder, to buy additional shares at a discount if any party acquires more than a set percentage of the company.","letter":"P","hasNote":false},{"id":"FIN-1482","slug":"poisson-distribution","term":"Poisson Distribution","also_known_as":[],"difficulty":"Advanced","definition":"The Poisson distribution is a probability distribution that describes the number of times an event occurs in a fixed period of time or space, when events happen independently at a constant average rate.","letter":"P","hasNote":false},{"id":"FIN-928","slug":"policy-limit","term":"Policy Limit","also_known_as":[],"difficulty":"Intermediate","definition":"A policy limit is the maximum amount an insurer will pay under an insurance policy for a covered loss, either per claim, per event or over the policy\'s term.","letter":"P","hasNote":false},{"id":"FIN-778","slug":"policy-rate","term":"Policy Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The policy rate is the main interest rate set by a central bank to carry out monetary policy, influencing borrowing costs, spending and inflation across the economy.","letter":"P","hasNote":false},{"id":"FIN-922","slug":"policyholder","term":"Policyholder","also_known_as":[],"difficulty":"Beginner","definition":"A policyholder is the person or organisation that owns an insurance policy, pays its premiums and holds the rights under the contract.","letter":"P","hasNote":false},{"id":"FIN-1299","slug":"politically-exposed-person","term":"Politically Exposed Person (PEP)","also_known_as":["PEP"],"difficulty":"Advanced","definition":"A politically exposed person (PEP) is someone who holds, or has recently held, a prominent public position, such as a senior politician, judge, senior military officer or head of a state-owned company, together with their close family members and associates.","letter":"P","hasNote":false},{"id":"FIN-495","slug":"population","term":"Population","also_known_as":[],"difficulty":"Beginner","definition":"A population, in statistics, is the entire group of people, items or events that a study is interested in understanding.","letter":"P","hasNote":false},{"id":"FIN-232","slug":"portfolio","term":"Portfolio","also_known_as":[],"difficulty":"Beginner","definition":"A portfolio is the complete collection of investments held by a person or organisation, such as shares, bonds, funds, property and cash.","letter":"P","hasNote":false},{"id":"FIN-233","slug":"portfolio-manager","term":"Portfolio Manager","also_known_as":[],"difficulty":"Beginner","definition":"A portfolio manager is a professional who makes investment decisions for a fund, institution or client, choosing which assets to buy, hold and sell to meet stated objectives.","letter":"P","hasNote":false},{"id":"FIN-313","slug":"positive-externality","term":"Positive Externality","also_known_as":[],"difficulty":"Intermediate","definition":"A positive externality is a benefit that an activity provides to people who are not directly involved in it and who do not pay for it.","letter":"P","hasNote":false},{"id":"FIN-1447","slug":"post-merger-integration","term":"Post-Merger Integration","also_known_as":[],"difficulty":"Advanced","definition":"Post-merger integration is the process of combining two companies after a merger or acquisition, bringing together their operations, systems, people and cultures to achieve the expected benefits of the deal.","letter":"P","hasNote":false},{"id":"FIN-879","slug":"post-money-valuation","term":"Post-Money Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Post-money valuation is the value of a company immediately after it receives new investment in a funding round, equal to the pre-money valuation plus the amount of new money invested.","letter":"P","hasNote":false},{"id":"FIN-1210","slug":"potential-gdp","term":"Potential GDP","also_known_as":[],"difficulty":"Advanced","definition":"Potential GDP is the level of output an economy could produce if it used its labour, capital and technology at normal, sustainable levels, without causing inflation to rise.","letter":"P","hasNote":false},{"id":"FIN-878","slug":"pre-money-valuation","term":"Pre-Money Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Pre-money valuation is the value of a company immediately before it receives new investment in a funding round.","letter":"P","hasNote":false},{"id":"FIN-394","slug":"precedent-transaction-analysis","term":"Precedent Transaction Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Precedent transaction analysis is a valuation method that estimates a company\'s value by looking at the prices paid in past acquisitions of similar companies.","letter":"P","hasNote":false},{"id":"FIN-1436","slug":"preferred-return","term":"Preferred Return","also_known_as":[],"difficulty":"Advanced","definition":"A preferred return is the minimum annual rate of return that investors in a private fund or investment must receive before the manager can share in the profits through carried interest.","letter":"P","hasNote":false},{"id":"FIN-240","slug":"preferred-stock","term":"Preferred Stock","also_known_as":[],"difficulty":"Beginner","definition":"Preferred stock is a type of share that usually pays a fixed dividend and has priority over common stock for dividends and for repayment if the company is wound up, but typically carries no voting rights.","letter":"P","hasNote":false},{"id":"FIN-128","slug":"prepaid-expense","term":"Prepaid Expense","also_known_as":[],"difficulty":"Beginner","definition":"A prepaid expense is a payment made in advance for goods or services that will be received or used in future periods. It is recorded as an asset until it is used up.","letter":"P","hasNote":false},{"id":"FIN-1395","slug":"prepayment-risk","term":"Prepayment Risk","also_known_as":[],"difficulty":"Advanced","definition":"Prepayment risk is the risk that borrowers repay their loans earlier than expected, especially when interest rates fall, returning money to lenders or investors sooner and forcing them to reinvest at lower rates.","letter":"P","hasNote":false},{"id":"FUT-1472","slug":"present-value","term":"Present Value","also_known_as":["PV"],"difficulty":"Beginner","definition":"Present value is what a future amount of money is worth today, after allowing for the return that money could earn in the meantime.","letter":"P","hasNote":false},{"id":"FIN-568","slug":"pretax-income","term":"Pretax Income","also_known_as":[],"difficulty":"Intermediate","definition":"Pretax income is a company\'s profit before income tax expense is deducted. It is also called profit before tax or earnings before tax.","letter":"P","hasNote":false},{"id":"FIN-323","slug":"price-ceiling","term":"Price Ceiling","also_known_as":[],"difficulty":"Intermediate","definition":"A price ceiling is a legal maximum price set by a government that sellers are not allowed to exceed.","letter":"P","hasNote":false},{"id":"FIN-1163","slug":"price-discovery","term":"Price Discovery","also_known_as":[],"difficulty":"Advanced","definition":"Price discovery is the process by which buyers and sellers interacting in a market determine an asset\'s price, as new information and changing views are reflected in trades.","letter":"P","hasNote":false},{"id":"FIN-1259","slug":"price-discrimination","term":"Price Discrimination","also_known_as":[],"difficulty":"Advanced","definition":"Price discrimination is the practice of charging different customers different prices for the same or a very similar product, based on their willingness to pay rather than differences in cost.","letter":"P","hasNote":false},{"id":"FIN-301","slug":"price-elasticity-of-demand","term":"Price Elasticity of Demand","also_known_as":[],"difficulty":"Intermediate","definition":"Price elasticity of demand measures how strongly the quantity of a good that people buy responds to a change in its price.","letter":"P","hasNote":false},{"id":"FIN-302","slug":"price-elasticity-of-supply","term":"Price Elasticity of Supply","also_known_as":[],"difficulty":"Intermediate","definition":"Price elasticity of supply measures how strongly the quantity producers supply responds to a change in the price of a good.","letter":"P","hasNote":false},{"id":"FIN-324","slug":"price-floor","term":"Price Floor","also_known_as":[],"difficulty":"Intermediate","definition":"A price floor is a legal minimum price set by a government, below which a good or service cannot be sold.","letter":"P","hasNote":false},{"id":"FIN-404","slug":"price-to-book-ratio","term":"Price-to-Book Ratio (P/B)","also_known_as":["P/B"],"difficulty":"Intermediate","definition":"The price-to-book ratio (P/B) compares a company\'s share price with its book value per share, which is the value of its net assets as shown in its accounts.","letter":"P","hasNote":false},{"id":"FIN-406","slug":"price-to-cash-flow-ratio","term":"Price-to-Cash-Flow Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The price-to-cash-flow ratio compares a company\'s share price with its operating cash flow per share, showing how much investors are paying for each unit of cash the business generates.","letter":"P","hasNote":false},{"id":"FIN-401","slug":"price-to-earnings-ratio","term":"Price-to-Earnings Ratio (P/E)","also_known_as":["P/E"],"difficulty":"Intermediate","definition":"The price-to-earnings ratio (P/E) is a company\'s share price divided by its earnings per share. It shows how much investors are paying for each unit of the company\'s profit.","letter":"P","hasNote":false},{"id":"FIN-411","slug":"price-to-free-cash-flow-ratio","term":"Price-to-Free-Cash-Flow Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The price-to-free-cash-flow ratio compares a company\'s market capitalization with its free cash flow, showing how much investors are paying for each unit of cash available after the business has funded its operations and capital investment.","letter":"P","hasNote":false},{"id":"FIN-405","slug":"price-to-sales-ratio","term":"Price-to-Sales Ratio (P/S)","also_known_as":["P/S"],"difficulty":"Intermediate","definition":"The price-to-sales ratio (P/S) compares a company\'s market capitalization with its total revenue, showing how much investors are paying for each unit of sales.","letter":"P","hasNote":false},{"id":"FIN-1345","slug":"price-volume-mix-analysis","term":"Price-Volume-Mix Analysis","also_known_as":[],"difficulty":"Advanced","definition":"Price-volume-mix analysis is a method of explaining changes in revenue or profit between two periods by separating the effects of changes in selling prices, sales volumes and the mix of products sold.","letter":"P","hasNote":false},{"id":"FIN-282","slug":"primary-market","term":"Primary Market","also_known_as":[],"difficulty":"Intermediate","definition":"The primary market is where new securities are created and sold for the first time, with the money going to the issuing company or government.","letter":"P","hasNote":false},{"id":"FIN-847","slug":"prime-rate","term":"Prime Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The prime rate is the interest rate that commercial banks in the United States and some other countries charge their most creditworthy customers, used as a benchmark for many other loans.","letter":"P","hasNote":false},{"id":"FIN-048","slug":"principal","term":"Principal","also_known_as":[],"difficulty":"Beginner","definition":"Principal is the original amount of money borrowed or invested, before any interest is added.","letter":"P","hasNote":false},{"id":"FIN-810","slug":"principal-agent-problem","term":"Principal-Agent Problem","also_known_as":[],"difficulty":"Intermediate","definition":"The principal-agent problem is a conflict of interest that arises when one party, the agent, is expected to act on behalf of another, the principal, but has different interests and more information than the principal.","letter":"P","hasNote":false},{"id":"FIN-815","slug":"principal-repayment","term":"Principal Repayment","also_known_as":[],"difficulty":"Beginner","definition":"Principal repayment is the part of a loan payment that reduces the original amount borrowed, as opposed to the part that pays interest.","letter":"P","hasNote":false},{"id":"FIN-1037","slug":"prior-period-error","term":"Prior-Period Error","also_known_as":[],"difficulty":"Advanced","definition":"A prior-period error is a mistake in a company\'s financial statements for one or more earlier periods, caused by misusing or failing to use reliable information that was available at the time.","letter":"P","hasNote":false},{"id":"FIN-1261","slug":"prisoner-s-dilemma","term":"Prisoner\'s Dilemma","also_known_as":[],"difficulty":"Advanced","definition":"The prisoner\'s dilemma is a classic example in game theory showing why two individuals acting in their own interest may both end up worse off than if they had cooperated.","letter":"P","hasNote":false},{"id":"FIN-345","slug":"private-banking","term":"Private Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Private banking is a set of personalised banking, investment and financial planning services offered to wealthy individuals and families.","letter":"P","hasNote":false},{"id":"FIN-287","slug":"private-company","term":"Private Company","also_known_as":[],"difficulty":"Intermediate","definition":"A private company is a company whose shares are not traded publicly and are usually owned by a small group, such as founders, families, employees or private investors.","letter":"P","hasNote":false},{"id":"FIN-956","slug":"private-equity","term":"Private Equity","also_known_as":[],"difficulty":"Intermediate","definition":"Private equity is investment in companies that are not listed on a public stock exchange, typically by specialist firms that buy significant stakes and work to improve the companies before selling them for a profit.","letter":"P","hasNote":false},{"id":"FIN-310","slug":"private-good","term":"Private Good","also_known_as":[],"difficulty":"Intermediate","definition":"A private good is a product or service that is excludable, meaning people who do not pay can be prevented from using it, and rivalrous, meaning one person\'s use reduces its availability to others.","letter":"P","hasNote":false},{"id":"FIN-1325","slug":"private-key","term":"Private Key","also_known_as":[],"difficulty":"Advanced","definition":"A private key is a secret code, usually a long string of numbers and letters, that proves ownership of cryptocurrency or other blockchain assets and allows the owner to authorise transactions.","letter":"P","hasNote":false},{"id":"FIN-610","slug":"pro-forma-financial-statements","term":"Pro Forma Financial Statements","also_known_as":[],"difficulty":"Intermediate","definition":"Pro forma financial statements are financial statements prepared to show how a company\'s results or position would have looked if a particular event, such as an acquisition or financing, had happened at an earlier date.","letter":"P","hasNote":false},{"id":"FIN-981","slug":"probability","term":"Probability","also_known_as":[],"difficulty":"Beginner","definition":"Probability is a measure of how likely an event is to happen, expressed as a number between 0, meaning it will certainly not happen, and 1, meaning it will certainly happen.","letter":"P","hasNote":false},{"id":"FIN-985","slug":"probability-distribution","term":"Probability Distribution","also_known_as":[],"difficulty":"Intermediate","definition":"A probability distribution is a description of all the possible values a random variable can take and how likely each value is.","letter":"P","hasNote":false},{"id":"FIN-1069","slug":"process-costing","term":"Process Costing","also_known_as":[],"difficulty":"Advanced","definition":"Process costing is a method of calculating product costs used when identical units are produced in a continuous process, by adding up the costs of each production stage and dividing them by the number of units produced.","letter":"P","hasNote":false},{"id":"FIN-949","slug":"procurement","term":"Procurement","also_known_as":[],"difficulty":"Intermediate","definition":"Procurement is the process by which an organisation finds, selects and buys the goods and services it needs from outside suppliers.","letter":"P","hasNote":false},{"id":"FIN-764","slug":"producer-price-index","term":"Producer Price Index (PPI)","also_known_as":["PPI"],"difficulty":"Intermediate","definition":"The Producer Price Index (PPI) measures the average change over time in the prices that domestic producers receive for their goods and services, reflecting price changes at the wholesale or factory level.","letter":"P","hasNote":false},{"id":"FIN-321","slug":"producer-surplus","term":"Producer Surplus","also_known_as":[],"difficulty":"Intermediate","definition":"Producer surplus is the difference between the price a seller receives for a good and the minimum price at which they would have been willing to sell it. It measures the extra benefit producers gain from selling.","letter":"P","hasNote":false},{"id":"FIN-941","slug":"product-market-fit","term":"Product-Market Fit","also_known_as":[],"difficulty":"Intermediate","definition":"Product-market fit is the point at which a product clearly satisfies a strong market need, so that customers actively want it, keep using it and recommend it to others.","letter":"P","hasNote":false},{"id":"FIN-754","slug":"productivity","term":"Productivity","also_known_as":[],"difficulty":"Intermediate","definition":"Productivity is a measure of how efficiently inputs, such as labour and capital, are turned into output, commonly measured as output per worker or output per hour worked.","letter":"P","hasNote":false},{"id":"FIN-1418","slug":"professional-indemnity-insurance","term":"Professional Indemnity Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Professional indemnity insurance is insurance that protects professionals and businesses providing advice or services against claims from clients who suffer financial loss because of errors, negligence or failure to perform their work properly.","letter":"P","hasNote":false},{"id":"FIN-1072","slug":"profit-center","term":"Profit Center","also_known_as":[],"difficulty":"Advanced","definition":"A profit center is a department, division or unit of a business whose manager is responsible for both its revenues and its costs, and is therefore accountable for its profit.","letter":"P","hasNote":false},{"id":"FIN-181","slug":"profitability-index","term":"Profitability Index","also_known_as":[],"difficulty":"Intermediate","definition":"The profitability index compares the present value of a project\'s future cash flows with its initial cost. A value above 1 means the project is expected to create value.","letter":"P","hasNote":false},{"id":"FIN-792","slug":"progressive-tax","term":"Progressive Tax","also_known_as":[],"difficulty":"Intermediate","definition":"A progressive tax is a tax system in which the tax rate increases as income or the amount being taxed increases, so higher earners pay a larger share of their income in tax.","letter":"P","hasNote":false},{"id":"FIN-1327","slug":"proof-of-stake","term":"Proof of Stake","also_known_as":[],"difficulty":"Advanced","definition":"Proof of stake is a method used by some blockchains to agree on which transactions are valid, in which participants called validators lock up, or stake, their own cryptocurrency for the right to propose and confirm new blocks.","letter":"P","hasNote":false},{"id":"FIN-1326","slug":"proof-of-work","term":"Proof of Work","also_known_as":[],"difficulty":"Advanced","definition":"Proof of work is a method used by some blockchains to agree on which transactions are valid, in which participants called miners compete to solve difficult computational puzzles, and the winner adds the next block and earns a reward.","letter":"P","hasNote":false},{"id":"FIN-935","slug":"property-insurance","term":"Property Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Property insurance is insurance that protects against financial loss from damage to or loss of physical property, such as buildings, contents, vehicles and equipment.","letter":"P","hasNote":false},{"id":"FIN-156","slug":"property-plant-and-equipment","term":"Property, Plant and Equipment (PP&E)","also_known_as":["PP&E"],"difficulty":"Beginner","definition":"Property, plant and equipment (PP&E) are the physical, long-term assets a business uses to produce goods or services, such as land, buildings, machinery, vehicles and computers.","letter":"P","hasNote":false},{"id":"FIN-549","slug":"property-tax","term":"Property Tax","also_known_as":[],"difficulty":"Beginner","definition":"Property tax is a tax charged on the ownership of land and buildings, usually based on the assessed value of the property and collected by local governments.","letter":"P","hasNote":false},{"id":"FIN-1159","slug":"prospect-theory","term":"Prospect Theory","also_known_as":[],"difficulty":"Advanced","definition":"Prospect theory is a theory of how people make decisions involving risk, showing that they judge outcomes as gains or losses relative to a reference point and feel losses more strongly than equivalent gains.","letter":"P","hasNote":false},{"id":"FIN-729","slug":"prospectus","term":"Prospectus","also_known_as":[],"difficulty":"Intermediate","definition":"A prospectus is a formal legal document that a company or fund must publish when offering securities to the public, describing the investment, its risks and key information investors need to make a decision.","letter":"P","hasNote":false},{"id":"FIN-445","slug":"protective-put","term":"Protective Put","also_known_as":["Married Put"],"difficulty":"Intermediate","definition":"A protective put is an options strategy in which an investor who owns shares buys a put option on those shares to limit potential losses if the price falls.","letter":"P","hasNote":true},{"id":"FIN-579","slug":"provisions","term":"Provisions","also_known_as":[],"difficulty":"Intermediate","definition":"Provisions are liabilities of uncertain timing or amount that a company records when it has a present obligation from a past event, is likely to have to pay and can estimate the amount reliably.","letter":"P","hasNote":false},{"id":"FIN-1181","slug":"proxy-voting","term":"Proxy Voting","also_known_as":[],"difficulty":"Advanced","definition":"Proxy voting is voting on company matters by a shareholder who does not attend the meeting in person, by authorising someone else, or submitting instructions, to vote on their behalf.","letter":"P","hasNote":false},{"id":"FIN-286","slug":"public-company","term":"Public Company","also_known_as":[],"difficulty":"Intermediate","definition":"A public company is a company whose shares can be bought and sold by members of the public, usually on a stock exchange.","letter":"P","hasNote":false},{"id":"FIN-309","slug":"public-good","term":"Public Good","also_known_as":[],"difficulty":"Intermediate","definition":"A public good is a product or service that is non-excludable, meaning people cannot easily be prevented from using it, and non-rivalrous, meaning one person\'s use does not reduce its availability to others.","letter":"P","hasNote":false},{"id":"FIN-1170","slug":"pump-and-dump","term":"Pump and Dump","also_known_as":[],"difficulty":"Intermediate","definition":"A pump and dump is a fraudulent scheme in which promoters artificially inflate the price of an asset, usually a little-known share or cryptocurrency, through false or misleading hype, then sell their holdings at the inflated price.","letter":"P","hasNote":false},{"id":"FIN-1361","slug":"purchase-price-adjustment","term":"Purchase Price Adjustment","also_known_as":[],"difficulty":"Advanced","definition":"A purchase price adjustment is a change to the price paid in an acquisition after completion, based on the actual financial position of the business at completion, usually its cash, debt and working capital.","letter":"P","hasNote":false},{"id":"FIN-1368","slug":"purchase-price-allocation","term":"Purchase Price Allocation (PPA)","also_known_as":["PPA"],"difficulty":"Advanced","definition":"Purchase price allocation (PPA) is the process of assigning the price paid in an acquisition to the identifiable assets acquired and liabilities assumed, measured at fair value, with any remaining amount recorded as goodwill.","letter":"P","hasNote":false},{"id":"FIN-1219","slug":"purchasing-managers-index","term":"Purchasing Managers\' Index (PMI)","also_known_as":["PMI"],"difficulty":"Advanced","definition":"The Purchasing Managers\' Index (PMI) is a monthly economic indicator based on surveys of purchasing managers at companies, showing whether business conditions in manufacturing or services are improving or worsening.","letter":"P","hasNote":false},{"id":"FIN-003","slug":"purchasing-power","term":"Purchasing Power","also_known_as":[],"difficulty":"Beginner","definition":"Purchasing power is the amount of goods and services that a sum of money can buy. When prices rise, the same amount of money buys less, so its purchasing power falls.","letter":"P","hasNote":false},{"id":"FIN-804","slug":"purchasing-power-parity","term":"Purchasing Power Parity (PPP)","also_known_as":["PPP"],"difficulty":"Intermediate","definition":"Purchasing power parity (PPP) is an economic theory and measurement method that compares currencies by the amount of goods and services they can buy, so that the same basket of goods should cost the same in different countries once prices are converted into a common currency.","letter":"P","hasNote":false},{"id":"FIN-427","slug":"put-option","term":"Put Option","also_known_as":[],"difficulty":"Intermediate","definition":"A put option is a contract that gives its buyer the right, but not the obligation, to sell an asset at a set price, the strike price, on or before a specific date.","letter":"P","hasNote":false},{"id":"FIN-1190","slug":"qualified-dividend","term":"Qualified Dividend","also_known_as":[],"difficulty":"Advanced","definition":"A qualified dividend is a dividend that meets United States tax requirements to be taxed at the lower rates that apply to long-term capital gains, rather than at ordinary income tax rates.","letter":"Q","hasNote":false},{"id":"FIN-1033","slug":"qualified-opinion","term":"Qualified Opinion","also_known_as":[],"difficulty":"Advanced","definition":"A qualified opinion is an audit opinion stating that a company\'s financial statements are fairly presented except for a specific matter, where the auditor has found a material problem or could not obtain enough evidence, but the issue is not widespread.","letter":"Q","hasNote":false},{"id":"FIN-1090","slug":"quality-of-earnings","term":"Quality of Earnings","also_known_as":[],"difficulty":"Advanced","definition":"Quality of earnings is the extent to which a company\'s reported profits reflect its true, sustainable, cash-generating performance, rather than one-off items, aggressive accounting or estimates.","letter":"Q","hasNote":false},{"id":"FIN-780","slug":"quantitative-easing","term":"Quantitative Easing (QE)","also_known_as":["QE"],"difficulty":"Intermediate","definition":"Quantitative easing (QE) is a monetary policy in which a central bank creates new money to buy large amounts of financial assets, usually government bonds, to lower long-term interest rates and support the economy.","letter":"Q","hasNote":false},{"id":"FIN-781","slug":"quantitative-tightening","term":"Quantitative Tightening (QT)","also_known_as":["QT"],"difficulty":"Intermediate","definition":"Quantitative tightening (QT) is a monetary policy in which a central bank reduces the amount of financial assets it holds, shrinking its balance sheet and withdrawing money from the financial system.","letter":"Q","hasNote":false},{"id":"FIN-224","slug":"quarter-over-quarter-growth","term":"Quarter-over-Quarter Growth","also_known_as":[],"difficulty":"Beginner","definition":"Quarter-over-quarter growth compares a figure for one three-month period with the immediately preceding three-month period, expressed as a percentage change.","letter":"Q","hasNote":false},{"id":"FIN-609","slug":"quarterly-report","term":"Quarterly Report","also_known_as":[],"difficulty":"Intermediate","definition":"A quarterly report is a financial report a company publishes every three months, showing its results and financial position for that quarter, usually in less detail than the annual report.","letter":"Q","hasNote":false},{"id":"FIN-627","slug":"quick-ratio","term":"Quick Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The quick ratio is a company\'s most liquid current assets, typically cash, short-term investments and receivables, divided by its current liabilities. It tests whether short-term obligations could be met without selling inventory.","letter":"Q","hasNote":false},{"id":"FIN-331","slug":"quota","term":"Quota","also_known_as":[],"difficulty":"Intermediate","definition":"A quota, in trade, is a government limit on the quantity or value of a particular good that can be imported or exported during a set period.","letter":"Q","hasNote":false},{"id":"FIN-984","slug":"random-variable","term":"Random Variable","also_known_as":[],"difficulty":"Intermediate","definition":"A random variable is a quantity whose value depends on the outcome of an uncertain event, with each possible value having a certain probability.","letter":"R","hasNote":false},{"id":"FIN-482","slug":"range","term":"Range","also_known_as":[],"difficulty":"Beginner","definition":"The range is the difference between the highest and lowest values in a set of data. It is the simplest measure of how spread out the data are.","letter":"R","hasNote":false},{"id":"FIN-041","slug":"rate-of-return","term":"Rate of Return","also_known_as":[],"difficulty":"Beginner","definition":"The rate of return is the gain or loss on an investment expressed as a percentage of the amount originally invested, usually over a year.","letter":"R","hasNote":false},{"id":"FIN-613","slug":"ratio-analysis","term":"Ratio Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Ratio analysis is the use of relationships between figures in a company\'s financial statements, expressed as ratios, to assess its profitability, liquidity, efficiency, debt and value.","letter":"R","hasNote":false},{"id":"FIN-1262","slug":"rational-expectations","term":"Rational Expectations","also_known_as":[],"difficulty":"Advanced","definition":"Rational expectations is an economic theory that people form their expectations about the future, such as future inflation, using all available information and an understanding of how the economy works, so that their predictions are not systematically wrong.","letter":"R","hasNote":false},{"id":"FIN-139","slug":"raw-materials","term":"Raw Materials","also_known_as":[],"difficulty":"Beginner","definition":"Raw materials are the basic inputs a manufacturer buys to turn into finished products, such as wood for furniture, steel for cars or flour for bread.","letter":"R","hasNote":false},{"id":"FIN-1271","slug":"real-exchange-rate","term":"Real Exchange Rate","also_known_as":[],"difficulty":"Advanced","definition":"The real exchange rate is the exchange rate between two currencies adjusted for differences in price levels between the two countries, showing the relative cost of goods and services in each.","letter":"R","hasNote":false},{"id":"FIN-751","slug":"real-gdp","term":"Real GDP","also_known_as":[],"difficulty":"Beginner","definition":"Real GDP is the value of all goods and services produced in an economy, adjusted for changes in prices, so that it measures changes in the actual quantity of output rather than changes caused by inflation.","letter":"R","hasNote":false},{"id":"FIN-058","slug":"real-interest-rate","term":"Real Interest Rate","also_known_as":[],"difficulty":"Beginner","definition":"The real interest rate is the interest rate after adjusting for inflation. It shows how much your purchasing power actually grows when you save, or how much borrowing really costs.","letter":"R","hasNote":false},{"id":"FIN-1098","slug":"real-option","term":"Real Option","also_known_as":[],"difficulty":"Advanced","definition":"A real option is a right, but not an obligation, that a company has to make a future business decision, such as expanding, delaying, changing or abandoning an investment, as circumstances change.","letter":"R","hasNote":false},{"id":"FIN-684","slug":"real-return","term":"Real Return","also_known_as":[],"difficulty":"Intermediate","definition":"Real return is the return on an investment after adjusting for inflation. It shows how much an investor\'s purchasing power has actually increased.","letter":"R","hasNote":false},{"id":"FIN-846","slug":"real-time-payment","term":"Real-Time Payment","also_known_as":[],"difficulty":"Intermediate","definition":"A real-time payment is an electronic payment between bank accounts that is processed and settled almost instantly, usually within seconds, and is available at any time of day, every day of the year.","letter":"R","hasNote":false},{"id":"FIN-037","slug":"real-value","term":"Real Value","also_known_as":["Inflation-Adjusted Value"],"difficulty":"Beginner","definition":"Real value is the value of money or an amount after adjusting for inflation. It shows what the money can actually buy, so amounts from different years can be compared fairly.","letter":"R","hasNote":true},{"id":"FIN-681","slug":"realized-gain","term":"Realized Gain","also_known_as":[],"difficulty":"Beginner","definition":"A realized gain is the profit an investor locks in by actually selling an asset for more than they paid for it.","letter":"R","hasNote":false},{"id":"FIN-231","slug":"rebalancing","term":"Rebalancing","also_known_as":[],"difficulty":"Beginner","definition":"Rebalancing is the process of buying and selling investments to bring a portfolio back to its target asset allocation after market movements have changed it.","letter":"R","hasNote":false},{"id":"FIN-1442","slug":"recapitalization","term":"Recapitalization","also_known_as":[],"difficulty":"Advanced","definition":"A recapitalization is a significant change in a company\'s capital structure, its mix of debt and equity, such as borrowing to pay a large dividend or buy back shares, or issuing equity to repay debt.","letter":"R","hasNote":false},{"id":"FUT-0558","slug":"recession","term":"Recession","also_known_as":[],"difficulty":"Beginner","definition":"A recession is a significant, widespread and lasting decline in economic activity, typically seen in falling output, income, employment and spending.","letter":"R","hasNote":false},{"id":"FIN-602","slug":"reconciliation","term":"Reconciliation","also_known_as":[],"difficulty":"Intermediate","definition":"Reconciliation is the process of comparing two sets of records to check that they agree, and investigating and correcting any differences.","letter":"R","hasNote":false},{"id":"FIN-679","slug":"record-date","term":"Record Date","also_known_as":[],"difficulty":"Intermediate","definition":"The record date is the date on which a company checks its register to identify which shareholders are entitled to receive a dividend or other distribution.","letter":"R","hasNote":false},{"id":"FIN-1043","slug":"recoverable-amount","term":"Recoverable Amount","also_known_as":[],"difficulty":"Advanced","definition":"Recoverable amount is the higher of an asset\'s fair value less costs to sell and its value in use, and it is the figure an asset\'s carrying amount is compared with in an impairment test under IFRS.","letter":"R","hasNote":false},{"id":"FIN-1470","slug":"recovery-rate","term":"Recovery Rate","also_known_as":[],"difficulty":"Advanced","definition":"The recovery rate is the percentage of a debt\'s value that creditors recover after a borrower defaults, through bankruptcy, restructuring or sale of assets.","letter":"R","hasNote":false},{"id":"FIN-944","slug":"recurring-revenue","term":"Recurring Revenue","also_known_as":[],"difficulty":"Intermediate","definition":"Recurring revenue is income that a business expects to receive regularly and predictably, usually through subscriptions, contracts or repeated purchases.","letter":"R","hasNote":false},{"id":"FIN-087","slug":"refinancing","term":"Refinancing","also_known_as":[],"difficulty":"Beginner","definition":"Refinancing is replacing an existing loan with a new one, usually to get a lower interest rate, change the repayment period or release cash.","letter":"R","hasNote":false},{"id":"FIN-1006","slug":"refundable-tax-credit","term":"Refundable Tax Credit","also_known_as":[],"difficulty":"Intermediate","definition":"A refundable tax credit is a tax credit that can reduce a person\'s tax bill below zero, so any amount left over after the tax is cleared is paid to them as a refund.","letter":"R","hasNote":false},{"id":"FIN-1178","slug":"registered-investment-adviser","term":"Registered Investment Adviser","also_known_as":[],"difficulty":"Advanced","definition":"A registered investment adviser is a firm or individual in the United States that provides investment advice for a fee and is registered with the Securities and Exchange Commission or a state securities regulator.","letter":"R","hasNote":false},{"id":"FIN-486","slug":"regression-analysis","term":"Regression Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Regression analysis is a set of statistical methods for estimating how one variable, the dependent variable, is related to one or more other variables, the independent variables.","letter":"R","hasNote":false},{"id":"FIN-793","slug":"regressive-tax","term":"Regressive Tax","also_known_as":[],"difficulty":"Intermediate","definition":"A regressive tax is a tax that takes a larger share of income from people with lower incomes than from people with higher incomes.","letter":"R","hasNote":false},{"id":"FIN-1331","slug":"regtech","term":"RegTech","also_known_as":[],"difficulty":"Advanced","definition":"RegTech, short for regulatory technology, is the use of technology, such as data analytics, automation and artificial intelligence, to help businesses comply with regulations more efficiently and effectively.","letter":"R","hasNote":false},{"id":"FIN-1405","slug":"regulatory-capital","term":"Regulatory Capital","also_known_as":[],"difficulty":"Advanced","definition":"Regulatory capital is the minimum amount and quality of capital that banks, insurers and other financial institutions are required by regulators to hold, to absorb losses and protect depositors, policyholders and the financial system.","letter":"R","hasNote":false},{"id":"FIN-937","slug":"reinsurance","term":"Reinsurance","also_known_as":[],"difficulty":"Intermediate","definition":"Reinsurance is insurance bought by insurance companies to protect themselves against large losses, transferring part of the risks they have taken on to another insurer, called a reinsurer.","letter":"R","hasNote":false},{"id":"FIN-699","slug":"reinvestment-risk","term":"Reinvestment Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Reinvestment risk is the risk that future cash flows from an investment, such as interest payments or maturing principal, will have to be reinvested at lower rates of return than the original investment.","letter":"R","hasNote":false},{"id":"FIN-1032","slug":"related-party-disclosure","term":"Related-Party Disclosure","also_known_as":[],"difficulty":"Advanced","definition":"A related-party disclosure is information in a company\'s financial statements about its relationships and transactions with related parties, such as directors, major shareholders, their families and companies they control.","letter":"R","hasNote":false},{"id":"FIN-594","slug":"related-party-transaction","term":"Related-Party Transaction","also_known_as":[],"difficulty":"Intermediate","definition":"A related-party transaction is a deal or arrangement between a company and parties that have a close relationship with it, such as its directors, major shareholders, their family members or other companies they control.","letter":"R","hasNote":false},{"id":"FIN-639","slug":"relevant-cost","term":"Relevant Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A relevant cost is a cost that will differ between the options being considered in a decision. Only relevant costs, and relevant revenues, should affect the choice.","letter":"R","hasNote":false},{"id":"FIN-844","slug":"remittance","term":"Remittance","also_known_as":[],"difficulty":"Beginner","definition":"A remittance is money sent by a person working in one country to family or others in another country, usually their home country.","letter":"R","hasNote":false},{"id":"FIN-519","slug":"rent","term":"Rent","also_known_as":[],"difficulty":"Beginner","definition":"Rent is the regular payment a tenant makes to a landlord for the right to use a property, such as a home, office or piece of land, for an agreed period.","letter":"R","hasNote":false},{"id":"FIN-326","slug":"rent-control","term":"Rent Control","also_known_as":[],"difficulty":"Intermediate","definition":"Rent control is a government rule that limits how much landlords can charge for renting a home, or how much they can increase rent each year.","letter":"R","hasNote":false},{"id":"FIN-1255","slug":"rent-seeking","term":"Rent-Seeking","also_known_as":[],"difficulty":"Advanced","definition":"Rent-seeking is the pursuit of income or wealth by manipulating the political, legal or economic environment, such as by lobbying for favourable regulations, subsidies or protection, rather than by creating new value.","letter":"R","hasNote":false},{"id":"FIN-882","slug":"replacement-cost","term":"Replacement Cost","also_known_as":[],"difficulty":"Intermediate","definition":"Replacement cost is the amount it would cost today to replace an asset with a new one of similar quality and usefulness.","letter":"R","hasNote":false},{"id":"FIN-1304","slug":"repo-rate","term":"Repo Rate","also_known_as":[],"difficulty":"Advanced","definition":"The repo rate is the interest rate charged on a repurchase agreement, the short-term borrowing in which one party sells securities and agrees to buy them back at a slightly higher price. In some countries, it is also the name of the central bank\'s main policy rate.","letter":"R","hasNote":false},{"id":"FIN-117","slug":"reporting-period","term":"Reporting Period","also_known_as":[],"difficulty":"Beginner","definition":"A reporting period is the span of time covered by a set of financial statements, such as a month, a quarter or a year.","letter":"R","hasNote":false},{"id":"FIN-861","slug":"repossession","term":"Repossession","also_known_as":[],"difficulty":"Intermediate","definition":"Repossession is the process by which a lender takes back an asset that was used as security for a loan, such as a car or home, when the borrower fails to keep up with payments.","letter":"R","hasNote":false},{"id":"FIN-1363","slug":"representations-and-warranties","term":"Representations and Warranties","also_known_as":[],"difficulty":"Advanced","definition":"Representations and warranties are statements of fact made by the seller, and sometimes the buyer, in an acquisition agreement about matters such as the business\'s financial statements, legal compliance, contracts, assets and liabilities.","letter":"R","hasNote":false},{"id":"FIN-852","slug":"repurchase-agreement","term":"Repurchase Agreement","also_known_as":[],"difficulty":"Intermediate","definition":"A repurchase agreement is a short-term borrowing arrangement in which one party sells securities, usually government bonds, to another and agrees to buy them back at a slightly higher price on a set future date.","letter":"R","hasNote":false},{"id":"FIN-901","slug":"reputational-risk","term":"Reputational Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Reputational risk is the risk that damage to an organisation\'s reputation will lead to loss of customers, revenue, investors, partners or employees, or to higher costs and regulatory scrutiny.","letter":"R","hasNote":false},{"id":"FIN-1195","slug":"required-minimum-distribution","term":"Required Minimum Distribution (RMD)","also_known_as":["RMD"],"difficulty":"Advanced","definition":"A required minimum distribution (RMD) is the minimum amount the owner of certain United States retirement accounts must withdraw each year once they reach a set age.","letter":"R","hasNote":false},{"id":"FIN-412","slug":"required-rate-of-return","term":"Required Rate of Return","also_known_as":[],"difficulty":"Intermediate","definition":"The required rate of return is the minimum annual return an investor expects to earn from an investment, given its level of risk, before they are willing to invest.","letter":"R","hasNote":false},{"id":"FIN-149","slug":"research-and-development-expense","term":"Research and Development Expense","also_known_as":[],"difficulty":"Beginner","definition":"Research and development expense is the cost of creating new products, improving existing ones or developing new processes and technologies.","letter":"R","hasNote":false},{"id":"FIN-1268","slug":"reserve-currency","term":"Reserve Currency","also_known_as":[],"difficulty":"Advanced","definition":"A reserve currency is a foreign currency held in significant amounts by central banks and governments as part of their foreign exchange reserves, and widely used in international trade and finance.","letter":"R","hasNote":false},{"id":"FIN-359","slug":"reserve-ratio","term":"Reserve Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The reserve ratio is the proportion of a bank\'s deposits that it holds as reserves, either as cash in its vaults or as deposits at the central bank, rather than lending out.","letter":"R","hasNote":false},{"id":"FIN-1221","slug":"reserve-requirement","term":"Reserve Requirement","also_known_as":[],"difficulty":"Advanced","definition":"A reserve requirement is a rule set by a central bank requiring banks to hold a minimum percentage of their customers\' deposits as reserves, either as cash in their vaults or on deposit with the central bank.","letter":"R","hasNote":false},{"id":"FIN-1119","slug":"residual-income","term":"Residual Income","also_known_as":[],"difficulty":"Advanced","definition":"Residual income is the profit a company or division earns above the minimum return required on the capital invested in it.","letter":"R","hasNote":false},{"id":"FIN-560","slug":"residual-value","term":"Residual Value","also_known_as":[],"difficulty":"Intermediate","definition":"Residual value is the estimated amount an asset will be worth, or could be sold for, at the end of its useful life, after deducting the expected costs of disposal.","letter":"R","hasNote":false},{"id":"FIN-1073","slug":"responsibility-accounting","term":"Responsibility Accounting","also_known_as":[],"difficulty":"Advanced","definition":"Responsibility accounting is a management accounting system that assigns costs, revenues and assets to the managers who control them, and measures each manager\'s performance on the items they can influence.","letter":"R","hasNote":false},{"id":"FIN-606","slug":"restatement","term":"Restatement","also_known_as":[],"difficulty":"Intermediate","definition":"A restatement is the revision of previously published financial statements to correct a material error or to reflect a change in accounting policy.","letter":"R","hasNote":false},{"id":"FIN-565","slug":"restricted-cash","term":"Restricted Cash","also_known_as":[],"difficulty":"Intermediate","definition":"Restricted cash is cash that a company holds but cannot freely use, because it is set aside for a specific purpose by a contract, law or regulation.","letter":"R","hasNote":false},{"id":"FIN-1458","slug":"restricted-stock","term":"Restricted Stock","also_known_as":[],"difficulty":"Advanced","definition":"Restricted stock is shares given to an employee or founder that are subject to conditions, usually continued employment over a vesting period, and may be forfeited or bought back by the company if the conditions are not met.","letter":"R","hasNote":false},{"id":"FIN-1050","slug":"restricted-stock-unit","term":"Restricted Stock Unit","also_known_as":[],"difficulty":"Advanced","definition":"A restricted stock unit (RSU) is a promise by an employer to give an employee shares in the company, or their cash value, once certain conditions are met, usually continuing to work for the company for a set period.","letter":"R","hasNote":false},{"id":"FIN-972","slug":"restructuring","term":"Restructuring","also_known_as":[],"difficulty":"Intermediate","definition":"Restructuring is a significant change to a company\'s finances, operations or organisation, often made to improve performance, reduce costs or deal with financial difficulty.","letter":"R","hasNote":false},{"id":"FIN-338","slug":"retail-bank","term":"Retail Bank","also_known_as":["Retail Banking"],"difficulty":"Beginner","definition":"A retail bank is a bank that provides financial services directly to individual consumers, such as current and savings accounts, debit and credit cards, mortgages and personal loans.","letter":"R","hasNote":true},{"id":"FIN-740","slug":"retail-investor","term":"Retail Investor","also_known_as":[],"difficulty":"Intermediate","definition":"A retail investor is an individual who invests their own money, usually in smaller amounts, through brokerage accounts, funds, pensions or savings products, rather than investing professionally on behalf of others.","letter":"R","hasNote":false},{"id":"FIN-164","slug":"retained-earnings","term":"Retained Earnings","also_known_as":[],"difficulty":"Beginner","definition":"Retained earnings are the total profits a company has kept in the business over its life, rather than paying out to shareholders as dividends.","letter":"R","hasNote":false},{"id":"FIN-657","slug":"retention-ratio","term":"Retention Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The retention ratio is the proportion of a company\'s net income that it keeps in the business rather than paying out as dividends. It equals one minus the dividend payout ratio.","letter":"R","hasNote":false},{"id":"FIN-524","slug":"retirement","term":"Retirement","also_known_as":[],"difficulty":"Beginner","definition":"Retirement is the stage of life when a person stops working full-time and relies mainly on savings, pensions, investments and government benefits for income.","letter":"R","hasNote":false},{"id":"FIN-746","slug":"retirement-account","term":"Retirement Account","also_known_as":[],"difficulty":"Intermediate","definition":"A retirement account is a savings or investment account designed specifically to help people build money for retirement, usually offering tax advantages in exchange for restrictions on when the money can be accessed.","letter":"R","hasNote":false},{"id":"FIN-040","slug":"return","term":"Return","also_known_as":[],"difficulty":"Beginner","definition":"Return is the gain or loss made on an investment over a period of time. It includes both any income received and any change in the investment\'s value.","letter":"R","hasNote":false},{"id":"FIN-620","slug":"return-on-assets","term":"Return on Assets (ROA)","also_known_as":["ROA"],"difficulty":"Intermediate","definition":"Return on assets (ROA) is net income divided by total assets, showing how much profit a company generates from everything it owns.","letter":"R","hasNote":false},{"id":"FIN-623","slug":"return-on-capital-employed","term":"Return on Capital Employed (ROCE)","also_known_as":["ROCE"],"difficulty":"Intermediate","definition":"Return on capital employed (ROCE) is operating profit, usually EBIT, divided by capital employed, which is total assets minus current liabilities. It shows how efficiently a company generates profit from its long-term funding.","letter":"R","hasNote":false},{"id":"FIN-621","slug":"return-on-equity","term":"Return on Equity (ROE)","also_known_as":["ROE"],"difficulty":"Intermediate","definition":"Return on equity (ROE) is a company\'s net income divided by its shareholders\' equity. It shows how much profit the business earns for each unit of money its owners have invested.","letter":"R","hasNote":false},{"id":"FIN-622","slug":"return-on-invested-capital","term":"Return on Invested Capital (ROIC)","also_known_as":["ROIC"],"difficulty":"Intermediate","definition":"Return on invested capital (ROIC) is a company\'s after-tax operating profit divided by the total capital invested in its operations by both shareholders and lenders.","letter":"R","hasNote":false},{"id":"FIN-171","slug":"return-on-investment","term":"Return on Investment (ROI)","also_known_as":["ROI"],"difficulty":"Beginner","definition":"Return on investment (ROI) is a measure of how much profit an investment produces compared with its cost, expressed as a percentage.","letter":"R","hasNote":false},{"id":"FIN-1080","slug":"return-on-sales","term":"Return on Sales (ROS)","also_known_as":["ROS"],"difficulty":"Advanced","definition":"Return on sales (ROS) is a company\'s operating profit divided by its revenue, showing how much operating profit it makes from each unit of sales.","letter":"R","hasNote":false},{"id":"FIN-1269","slug":"revaluation","term":"Revaluation","also_known_as":[],"difficulty":"Advanced","definition":"Revaluation is a deliberate increase by a government or central bank in the official value of its currency against other currencies, under a fixed or pegged exchange rate system.","letter":"R","hasNote":false},{"id":"FIN-1435","slug":"revenue-based-financing","term":"Revenue-Based Financing","also_known_as":[],"difficulty":"Advanced","definition":"Revenue-based financing is a way for businesses to raise money by agreeing to repay investors a fixed percentage of future monthly revenue until a set total amount has been repaid.","letter":"R","hasNote":false},{"id":"FIN-1344","slug":"revenue-build","term":"Revenue Build","also_known_as":[],"difficulty":"Advanced","definition":"A revenue build is the part of a financial model that forecasts revenue from its underlying drivers, such as the number of customers, units sold, prices, stores or contracts, rather than simply applying a growth rate to past revenue.","letter":"R","hasNote":false},{"id":"FIN-1134","slug":"revenue-concentration","term":"Revenue Concentration","also_known_as":[],"difficulty":"Advanced","definition":"Revenue concentration is the degree to which a company\'s revenue depends on a small number of sources, such as a few customers, products, markets or contracts.","letter":"R","hasNote":false},{"id":"FIN-198","slug":"revenue-forecast","term":"Revenue Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A revenue forecast is an estimate of how much income a business expects to earn from sales over a future period.","letter":"R","hasNote":false},{"id":"FIN-218","slug":"revenue-growth","term":"Revenue Growth","also_known_as":[],"difficulty":"Beginner","definition":"Revenue growth is the percentage increase or decrease in a business\'s revenue from one period to another.","letter":"R","hasNote":false},{"id":"FIN-453","slug":"revenue-model","term":"Revenue Model","also_known_as":[],"difficulty":"Beginner","definition":"A revenue model is the specific way a business earns money from its customers, such as by selling products, charging subscriptions, taking commissions or selling advertising.","letter":"R","hasNote":false},{"id":"FIN-124","slug":"revenue-recognition","term":"Revenue Recognition","also_known_as":[],"difficulty":"Beginner","definition":"Revenue recognition is the accounting principle that decides when and how much revenue a business records, generally when it has delivered the promised goods or services to the customer.","letter":"R","hasNote":false},{"id":"FIN-1095","slug":"revenue-synergy","term":"Revenue Synergy","also_known_as":[],"difficulty":"Advanced","definition":"A revenue synergy is an increase in combined revenue expected from merging or acquiring a business, beyond what the two companies could achieve separately.","letter":"R","hasNote":false},{"id":"FIN-1305","slug":"reverse-repo","term":"Reverse Repo","also_known_as":[],"difficulty":"Advanced","definition":"A reverse repo is the opposite side of a repurchase agreement: one party buys securities and agrees to sell them back at a slightly higher price on a set date, which is effectively a short-term loan secured by the securities.","letter":"R","hasNote":false},{"id":"FIN-1105","slug":"reverse-stock-split","term":"Reverse Stock Split","also_known_as":[],"difficulty":"Advanced","definition":"A reverse stock split is a corporate action that reduces the number of a company\'s shares outstanding by combining several existing shares into one, increasing the price per share without changing the company\'s total value.","letter":"R","hasNote":false},{"id":"FIN-104","slug":"reversing-entry","term":"Reversing Entry","also_known_as":[],"difficulty":"Beginner","definition":"A reversing entry is an optional journal entry made at the start of a new period that cancels out certain adjusting entries from the end of the previous period, to make recording simpler.","letter":"R","hasNote":false},{"id":"FIN-515","slug":"revolving-credit","term":"Revolving Credit","also_known_as":[],"difficulty":"Beginner","definition":"Revolving credit is a type of borrowing that lets you borrow up to a set limit, repay and borrow again as often as you like, without applying for a new loan each time.","letter":"R","hasNote":false},{"id":"FIN-826","slug":"revolving-credit-facility","term":"Revolving Credit Facility","also_known_as":[],"difficulty":"Intermediate","definition":"A revolving credit facility is a flexible borrowing arrangement, usually provided by banks to companies, that allows the borrower to draw money up to an agreed limit, repay it and borrow again as needed during the term of the facility.","letter":"R","hasNote":false},{"id":"FIN-1453","slug":"right-of-first-refusal","term":"Right of First Refusal","also_known_as":[],"difficulty":"Advanced","definition":"A right of first refusal is a contractual right that requires an owner wishing to sell an asset, such as shares in a private company, to offer it first to a specified party, who can buy it on the same terms as an offer received from an outsider.","letter":"R","hasNote":false},{"id":"FIN-587","slug":"right-of-use-asset","term":"Right-of-Use Asset","also_known_as":[],"difficulty":"Intermediate","definition":"A right-of-use asset is an asset a lessee records on its balance sheet that represents its right to use a leased item, such as a building or vehicle, over the lease term.","letter":"R","hasNote":false},{"id":"FIN-663","slug":"rights-issue","term":"Rights Issue","also_known_as":[],"difficulty":"Intermediate","definition":"A rights issue is a way for a company to raise new money by offering its existing shareholders the right to buy additional shares, usually at a discount to the current market price, in proportion to their current holdings.","letter":"R","hasNote":false},{"id":"FIN-689","slug":"risk-adjusted-return","term":"Risk-Adjusted Return","also_known_as":[],"difficulty":"Intermediate","definition":"Risk-adjusted return is a measure of an investment\'s return that takes into account how much risk was taken to achieve it, allowing fairer comparisons between investments.","letter":"R","hasNote":false},{"id":"FIN-896","slug":"risk-appetite","term":"Risk Appetite","also_known_as":[],"difficulty":"Intermediate","definition":"Risk appetite is the amount and type of risk an organisation or individual is willing to accept in pursuit of its objectives.","letter":"R","hasNote":false},{"id":"FIN-1399","slug":"risk-capacity","term":"Risk Capacity","also_known_as":[],"difficulty":"Advanced","definition":"Risk capacity is the maximum amount of risk a person or organisation can take on without endangering its ability to meet its obligations or achieve its essential goals.","letter":"R","hasNote":false},{"id":"FIN-874","slug":"risk-free-rate","term":"Risk-Free Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The risk-free rate is the theoretical return on an investment with no risk of loss, used as a baseline for measuring the extra return that riskier investments must offer. In practice, it is usually represented by the yield on government bonds of a stable country.","letter":"R","hasNote":false},{"id":"FIN-895","slug":"risk-management","term":"Risk Management","also_known_as":[],"difficulty":"Intermediate","definition":"Risk management is the process of identifying, assessing and responding to risks that could affect an individual\'s or organisation\'s finances, operations or objectives.","letter":"R","hasNote":false},{"id":"FIN-924","slug":"risk-pooling","term":"Risk Pooling","also_known_as":[],"difficulty":"Intermediate","definition":"Risk pooling is the practice of combining the risks of many individuals or organisations, so that the losses of the few who suffer harm can be paid for by the contributions of all.","letter":"R","hasNote":false},{"id":"FIN-700","slug":"risk-premium","term":"Risk Premium","also_known_as":[],"difficulty":"Intermediate","definition":"A risk premium is the extra return investors expect, or demand, for holding a risky investment instead of a risk-free one.","letter":"R","hasNote":false},{"id":"FIN-1426","slug":"risk-retention","term":"Risk Retention","also_known_as":[],"difficulty":"Advanced","definition":"Risk retention is the decision to accept and bear a risk, or part of it, rather than avoiding it or transferring it to someone else, such as an insurer.","letter":"R","hasNote":false},{"id":"FIN-513","slug":"risk-tolerance","term":"Risk Tolerance","also_known_as":[],"difficulty":"Intermediate","definition":"Risk tolerance is how much variation in investment returns, including the possibility of losses, a person is willing and able to accept in pursuit of their goals.","letter":"R","hasNote":false},{"id":"FIN-925","slug":"risk-transfer","term":"Risk Transfer","also_known_as":[],"difficulty":"Intermediate","definition":"Risk transfer is shifting the financial consequences of a risk from one party to another, usually in exchange for a payment.","letter":"R","hasNote":false},{"id":"FIN-366","slug":"risk-weighted-assets","term":"Risk-Weighted Assets","also_known_as":[],"difficulty":"Intermediate","definition":"Risk-weighted assets are a bank\'s assets adjusted for their level of risk, so that riskier assets count for more and safer assets count for less. They are used to set how much capital a bank must hold.","letter":"R","hasNote":false},{"id":"FIN-737","slug":"robo-advisor","term":"Robo-Advisor","also_known_as":[],"difficulty":"Intermediate","definition":"A robo-advisor is an online service that uses automated algorithms to create and manage investment portfolios for clients, usually at a lower cost than a traditional human financial adviser.","letter":"R","hasNote":false},{"id":"FIN-672","slug":"rolling-forecast","term":"Rolling Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A rolling forecast is a forecast that is updated regularly, typically every month or quarter, by adding a new period at the end as each period passes, so it always looks a fixed time ahead.","letter":"R","hasNote":false},{"id":"FIN-1489","slug":"root-mean-squared-error","term":"Root Mean Squared Error (RMSE)","also_known_as":["RMSE"],"difficulty":"Advanced","definition":"Root mean squared error (RMSE) is a measure of forecast or model accuracy, calculated by squaring each error, averaging the squared errors and then taking the square root.","letter":"R","hasNote":false},{"id":"FIN-1020","slug":"roth-conversion","term":"Roth Conversion","also_known_as":[],"difficulty":"Intermediate","definition":"A Roth conversion is moving money from a traditional, tax-deferred retirement account in the United States, such as a traditional IRA or 401(k), into a Roth account, paying income tax on the amount converted in exchange for tax-free growth afterwards.","letter":"R","hasNote":false},{"id":"FIN-1193","slug":"roth-ira","term":"Roth IRA","also_known_as":[],"difficulty":"Advanced","definition":"A Roth IRA is a United States individual retirement account funded with income that has already been taxed, in which investments grow tax-free and qualified withdrawals in retirement are not taxed.","letter":"R","hasNote":false},{"id":"FIN-947","slug":"royalty","term":"Royalty","also_known_as":[],"difficulty":"Intermediate","definition":"A royalty is a payment made to the owner of an asset, such as a patent, copyright, trademark, franchise or natural resource, for the right to use it.","letter":"R","hasNote":false},{"id":"FIN-1133","slug":"rule-of-40","term":"Rule of 40","also_known_as":[],"difficulty":"Advanced","definition":"The Rule of 40 is a guideline used mainly for software and subscription companies, stating that a company\'s revenue growth rate plus its profit margin should add up to at least 40%.","letter":"R","hasNote":false},{"id":"FIN-1094","slug":"run-rate-revenue","term":"Run-Rate Revenue","also_known_as":[],"difficulty":"Advanced","definition":"Run-rate revenue is an estimate of annual revenue based on recent results, calculated by projecting a short period\'s revenue, such as the latest month or quarter, over a full year.","letter":"R","hasNote":false},{"id":"FIN-674","slug":"runway","term":"Runway","also_known_as":[],"difficulty":"Intermediate","definition":"Runway is the length of time a company can continue operating before it runs out of cash, assuming its current spending and income continue.","letter":"R","hasNote":false},{"id":"FIN-1148","slug":"safe-haven-asset","term":"Safe-Haven Asset","also_known_as":[],"difficulty":"Advanced","definition":"A safe-haven asset is an investment that is expected to hold or increase its value during periods of market turmoil or economic crisis, when riskier assets are falling.","letter":"S","hasNote":false},{"id":"FIN-1459","slug":"safe","term":"SAFE (Simple Agreement for Future Equity)","also_known_as":["Simple Agreement for Future Equity"],"difficulty":"Advanced","definition":"A SAFE (Simple Agreement for Future Equity) is an agreement in which an investor gives money to a start-up in exchange for the right to receive shares in a future priced funding round, without setting a valuation at the time of investment.","letter":"S","hasNote":false},{"id":"FIN-1196","slug":"safe-withdrawal-rate","term":"Safe Withdrawal Rate","also_known_as":["Four Percent Rule"],"difficulty":"Advanced","definition":"A safe withdrawal rate is the highest percentage of a retirement portfolio that can be withdrawn in the first year, and then adjusted for inflation each year, with a high likelihood that the money will last for a set period, such as 30 years.","letter":"S","hasNote":true},{"id":"FIN-795","slug":"sales-tax","term":"Sales Tax","also_known_as":[],"difficulty":"Beginner","definition":"A sales tax is a tax charged on the sale of goods and services, usually calculated as a percentage of the purchase price and collected by the seller at the point of sale.","letter":"S","hasNote":false},{"id":"FIN-494","slug":"sample","term":"Sample","also_known_as":[],"difficulty":"Beginner","definition":"A sample is a smaller group selected from a larger population, used to draw conclusions about the whole population without examining every member.","letter":"S","hasNote":false},{"id":"FIN-496","slug":"sampling-bias","term":"Sampling Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Sampling bias occurs when the method used to choose a sample makes some members of the population more likely to be included than others, so the sample does not accurately represent the population.","letter":"S","hasNote":false},{"id":"FIN-1298","slug":"sanctions-screening","term":"Sanctions Screening","also_known_as":[],"difficulty":"Advanced","definition":"Sanctions screening is the process of checking customers, transactions and counterparties against official lists of sanctioned individuals, organisations, countries and vessels, to ensure that no prohibited dealings take place.","letter":"S","hasNote":false},{"id":"FIN-020","slug":"saving-rate","term":"Saving Rate","also_known_as":[],"difficulty":"Beginner","definition":"The saving rate is the percentage of income that is saved rather than spent over a period, such as a month or a year.","letter":"S","hasNote":false},{"id":"FIN-019","slug":"savings","term":"Savings","also_known_as":[],"difficulty":"Beginner","definition":"Savings is the part of income that is not spent on current consumption and is instead kept for future use, either as cash or in accounts and investments.","letter":"S","hasNote":false},{"id":"FIN-353","slug":"savings-account","term":"Savings Account","also_known_as":[],"difficulty":"Beginner","definition":"A savings account is a bank account designed for keeping money you do not need for everyday spending, which pays interest on the balance.","letter":"S","hasNote":false},{"id":"FIN-341","slug":"savings-bank","term":"Savings Bank","also_known_as":[],"difficulty":"Beginner","definition":"A savings bank is a financial institution whose main purpose is to accept savings deposits and pay interest on them, often lending mainly for home purchases.","letter":"S","hasNote":false},{"id":"FIN-942","slug":"scalability","term":"Scalability","also_known_as":[],"difficulty":"Intermediate","definition":"Scalability is the ability of a business to grow its revenue significantly without a proportional increase in costs.","letter":"S","hasNote":false},{"id":"FIN-294","slug":"scarcity","term":"Scarcity","also_known_as":[],"difficulty":"Beginner","definition":"Scarcity is the basic economic problem that resources are limited while human wants are virtually unlimited, so people and societies must make choices.","letter":"S","hasNote":false},{"id":"FIN-202","slug":"scenario-analysis","term":"Scenario Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Scenario analysis is a planning method that estimates how financial results would change under several different possible futures, such as a base case, an optimistic case and a pessimistic case.","letter":"S","hasNote":false},{"id":"FIN-994","slug":"seasonality","term":"Seasonality","also_known_as":[],"difficulty":"Beginner","definition":"Seasonality is a regular, predictable pattern in data that repeats over a fixed period, such as each year, quarter, month or week.","letter":"S","hasNote":false},{"id":"FIN-996","slug":"seasonally-adjusted-data","term":"Seasonally Adjusted Data","also_known_as":[],"difficulty":"Intermediate","definition":"Seasonally adjusted data is data that has been statistically modified to remove the effects of regular seasonal patterns, making it easier to see underlying trends and compare one period with another.","letter":"S","hasNote":false},{"id":"FIN-1106","slug":"seasoned-equity-offering","term":"Seasoned Equity Offering","also_known_as":[],"difficulty":"Advanced","definition":"A seasoned equity offering is the sale of new shares by a company whose shares are already publicly traded, to raise additional capital.","letter":"S","hasNote":false},{"id":"FIN-1441","slug":"secondary-buyout","term":"Secondary Buyout","also_known_as":[],"difficulty":"Advanced","definition":"A secondary buyout is the sale of a company from one private equity firm to another private equity firm.","letter":"S","hasNote":false},{"id":"FIN-283","slug":"secondary-market","term":"Secondary Market","also_known_as":[],"difficulty":"Intermediate","definition":"The secondary market is where investors buy and sell securities that have already been issued, trading with each other rather than with the original issuer.","letter":"S","hasNote":false},{"id":"FIN-285","slug":"secondary-offering","term":"Secondary Offering","also_known_as":[],"difficulty":"Intermediate","definition":"A secondary offering is a sale of shares by a company that is already publicly listed, or by its existing major shareholders, after its initial public offering.","letter":"S","hasNote":false},{"id":"FIN-1286","slug":"secured-credit-card","term":"Secured Credit Card","also_known_as":[],"difficulty":"Intermediate","definition":"A secured credit card is a credit card that requires the cardholder to pay a cash deposit, which usually sets the credit limit and serves as security for the card issuer.","letter":"S","hasNote":false},{"id":"FIN-079","slug":"secured-debt","term":"Secured Debt","also_known_as":[],"difficulty":"Beginner","definition":"Secured debt is borrowing backed by an asset, called collateral, that the lender can take and sell if the borrower fails to repay.","letter":"S","hasNote":false},{"id":"FIN-1165","slug":"securities-lending","term":"Securities Lending","also_known_as":[],"difficulty":"Advanced","definition":"Securities lending is the temporary transfer of shares or bonds from one party to another, in return for a fee and collateral, with an agreement to return equivalent securities later.","letter":"S","hasNote":false},{"id":"FIN-910","slug":"securitization","term":"Securitization","also_known_as":[],"difficulty":"Intermediate","definition":"Securitization is the process of pooling financial assets that produce regular cash flows, such as mortgages or car loans, and transforming them into securities that can be sold to investors.","letter":"S","hasNote":false},{"id":"FIN-1469","slug":"security-interest","term":"Security Interest","also_known_as":[],"difficulty":"Advanced","definition":"A security interest is a legal right granted by a borrower to a lender over specific assets, allowing the lender to take and sell those assets if the borrower fails to repay.","letter":"S","hasNote":false},{"id":"FIN-1328","slug":"security-token","term":"Security Token","also_known_as":[],"difficulty":"Advanced","definition":"A security token is a digital token recorded on a blockchain that represents ownership of, or a claim on, a financial asset such as a share, bond or fund unit, and is therefore subject to securities laws.","letter":"S","hasNote":false},{"id":"FIN-952","slug":"seed-capital","term":"Seed Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Seed capital is the initial money used to start a business, typically to develop a product, conduct market research and build a team before the company can attract larger investment.","letter":"S","hasNote":false},{"id":"FIN-1062","slug":"segment-margin","term":"Segment Margin","also_known_as":[],"difficulty":"Advanced","definition":"Segment margin is the profit a business segment, such as a product line, region or division, contributes after deducting its variable costs and the fixed costs directly traceable to it, but before shared company-wide costs.","letter":"S","hasNote":false},{"id":"FIN-595","slug":"segment-reporting","term":"Segment Reporting","also_known_as":[],"difficulty":"Intermediate","definition":"Segment reporting is the disclosure of financial information about the different parts of a company\'s business, such as product lines or geographic regions, as they are reviewed by its management.","letter":"S","hasNote":false},{"id":"FIN-601","slug":"segregation-of-duties","term":"Segregation of Duties","also_known_as":[],"difficulty":"Intermediate","definition":"Segregation of duties is an internal control principle that divides key tasks in a process among different people, so that no single person can both commit and conceal an error or fraud.","letter":"S","hasNote":false},{"id":"FIN-498","slug":"selection-bias","term":"Selection Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Selection bias occurs when the individuals, groups or data included in an analysis are chosen in a way that is not random, so the results do not fairly represent the population or the effect being studied.","letter":"S","hasNote":false},{"id":"FIN-1427","slug":"self-insurance","term":"Self-Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Self-insurance is a risk management approach in which a person or organisation sets aside its own funds to pay for potential losses, instead of buying insurance to cover them.","letter":"S","hasNote":false},{"id":"FIN-1474","slug":"seller-financing","term":"Seller Financing","also_known_as":[],"difficulty":"Advanced","definition":"Seller financing is an arrangement in which the seller of a business or property lends part of the purchase price to the buyer, who repays it over time, instead of the buyer paying the full price upfront.","letter":"S","hasNote":false},{"id":"FIN-147","slug":"selling-expense","term":"Selling Expense","also_known_as":[],"difficulty":"Beginner","definition":"A selling expense is a cost incurred to market and sell a business\'s products or services, such as advertising, sales staff pay, commissions and delivery to customers.","letter":"S","hasNote":false},{"id":"FIN-637","slug":"semi-variable-cost","term":"Semi-Variable Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A semi-variable cost is a cost that has both a fixed part, paid regardless of activity, and a variable part that changes with the level of activity.","letter":"S","hasNote":false},{"id":"FIN-975","slug":"senior-debt","term":"Senior Debt","also_known_as":[],"difficulty":"Intermediate","definition":"Senior debt is borrowing that has the highest priority for repayment if a company goes bankrupt or is liquidated, ranking ahead of other types of debt and equity.","letter":"S","hasNote":false},{"id":"FIN-203","slug":"sensitivity-analysis","term":"Sensitivity Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Sensitivity analysis tests how much a financial result, such as profit or project value, changes when one assumption is changed while all others are held constant.","letter":"S","hasNote":false},{"id":"FIN-891","slug":"sensitivity-table","term":"Sensitivity Table","also_known_as":[],"difficulty":"Intermediate","definition":"A sensitivity table is a grid in a financial model that shows how an output, such as a company\'s valuation, changes when two key assumptions are varied at the same time.","letter":"S","hasNote":false},{"id":"FIN-1146","slug":"sequence-of-returns-risk","term":"Sequence-of-Returns Risk","also_known_as":[],"difficulty":"Advanced","definition":"Sequence-of-returns risk is the risk that poor investment returns early in retirement, while withdrawals are being made, permanently reduce how long savings will last, even if average returns over the whole period are acceptable.","letter":"S","hasNote":false},{"id":"FIN-953","slug":"series-a","term":"Series A","also_known_as":[],"difficulty":"Intermediate","definition":"Series A is typically the first major round of venture capital financing for a start-up, following seed funding, used to grow a business that has shown early promise.","letter":"S","hasNote":false},{"id":"FIN-954","slug":"series-b","term":"Series B","also_known_as":[],"difficulty":"Intermediate","definition":"Series B is a later round of venture capital financing, following Series A, used to help a start-up that has proven its business model scale up and expand.","letter":"S","hasNote":false},{"id":"FIN-1429","slug":"serviceable-available-market","term":"Serviceable Available Market (SAM)","also_known_as":["SAM"],"difficulty":"Advanced","definition":"Serviceable available market (SAM) is the portion of the total addressable market that a company can realistically target with its current products, business model and geographic reach.","letter":"S","hasNote":false},{"id":"FIN-1430","slug":"serviceable-obtainable-market","term":"Serviceable Obtainable Market (SOM)","also_known_as":["SOM"],"difficulty":"Advanced","definition":"Serviceable obtainable market (SOM) is the portion of the serviceable available market that a company can realistically capture in the near term, given its competition, resources and sales capacity.","letter":"S","hasNote":false},{"id":"FIN-727","slug":"settlement-date","term":"Settlement Date","also_known_as":[],"difficulty":"Intermediate","definition":"The settlement date is the date on which a trade is completed, when the buyer pays for the securities and the seller delivers them, transferring ownership.","letter":"S","hasNote":false},{"id":"FIN-1295","slug":"settlement-risk","term":"Settlement Risk","also_known_as":[],"difficulty":"Advanced","definition":"Settlement risk is the risk that one party in a transaction delivers payment or assets as agreed, but the other party fails to deliver its side, leading to a loss.","letter":"S","hasNote":false},{"id":"FIN-238","slug":"share","term":"Share","also_known_as":[],"difficulty":"Beginner","definition":"A share is a single unit of ownership in a company. Owning shares makes you a part-owner, entitled to a portion of the company\'s profits and, usually, a vote on certain decisions.","letter":"S","hasNote":false},{"id":"FIN-588","slug":"share-based-compensation","term":"Share-Based Compensation","also_known_as":[],"difficulty":"Intermediate","definition":"Share-based compensation is payment to employees, directors or others in the form of shares, share options or other equity instruments, recorded as an expense in the company\'s accounts.","letter":"S","hasNote":false},{"id":"FIN-165","slug":"share-capital","term":"Share Capital","also_known_as":[],"difficulty":"Beginner","definition":"Share capital is the money a company has raised by issuing shares to its owners. It forms part of shareholders\' equity on the balance sheet.","letter":"S","hasNote":false},{"id":"FIN-660","slug":"share-repurchase","term":"Share Repurchase","also_known_as":["Buyback"],"difficulty":"Intermediate","definition":"A share repurchase is when a company buys back its own shares from the market or directly from shareholders, reducing the number of shares outstanding.","letter":"S","hasNote":true},{"id":"FIN-1446","slug":"share-sale","term":"Share Sale","also_known_as":[],"difficulty":"Advanced","definition":"A share sale is a transaction in which a buyer acquires the shares of a company, taking ownership of the whole company, including all its assets, liabilities and obligations.","letter":"S","hasNote":false},{"id":"FIN-1182","slug":"shareholder-activism","term":"Shareholder Activism","also_known_as":[],"difficulty":"Advanced","definition":"Shareholder activism is when shareholders use their ownership rights to push a company to make changes, such as in strategy, management, governance, capital allocation or environmental and social practices.","letter":"S","hasNote":false},{"id":"FIN-1455","slug":"shareholder-agreement","term":"Shareholder Agreement","also_known_as":[],"difficulty":"Advanced","definition":"A shareholder agreement is a contract between some or all of a company\'s shareholders, setting out their rights and obligations, how the company is run and what happens in situations such as the sale of shares or disputes.","letter":"S","hasNote":false},{"id":"FIN-290","slug":"shares-outstanding","term":"Shares Outstanding","also_known_as":[],"difficulty":"Intermediate","definition":"Shares outstanding is the total number of a company\'s shares currently held by all its shareholders, including insiders and institutions, but excluding shares the company has bought back and holds itself.","letter":"S","hasNote":false},{"id":"FIN-691","slug":"sharpe-ratio","term":"Sharpe Ratio","also_known_as":[],"difficulty":"Intermediate","definition":"The Sharpe ratio measures an investment\'s return above the risk-free rate for each unit of total risk, measured by the standard deviation of its returns.","letter":"S","hasNote":false},{"id":"FIN-1166","slug":"short-interest","term":"Short Interest","also_known_as":[],"difficulty":"Advanced","definition":"Short interest is the total number of a company\'s shares that have been sold short and not yet bought back, often expressed as a percentage of the shares available for trading.","letter":"S","hasNote":false},{"id":"FIN-272","slug":"short-selling","term":"Short Selling","also_known_as":[],"difficulty":"Intermediate","definition":"Short selling is selling a security you do not own, by borrowing it, in the hope of buying it back later at a lower price and keeping the difference as profit.","letter":"S","hasNote":false},{"id":"FIN-564","slug":"short-term-investments","term":"Short-Term Investments","also_known_as":[],"difficulty":"Intermediate","definition":"Short-term investments are financial assets that a company expects to sell or that will mature within one year, but that do not qualify as cash equivalents.","letter":"S","hasNote":false},{"id":"FIN-1114","slug":"signaling-theory","term":"Signaling Theory","also_known_as":[],"difficulty":"Advanced","definition":"Signaling theory is the idea that companies and their managers use actions, such as paying dividends, buying back shares or taking on debt, to convey information about the company\'s prospects to investors who know less than they do.","letter":"S","hasNote":false},{"id":"FIN-051","slug":"simple-interest","term":"Simple Interest","also_known_as":[],"difficulty":"Beginner","definition":"Simple interest is interest calculated only on the original amount borrowed or saved, not on any interest already earned or charged.","letter":"S","hasNote":false},{"id":"FIN-514","slug":"sinking-fund","term":"Sinking Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A sinking fund is money set aside regularly for a specific future expense or debt repayment, so the full amount is available when it is needed.","letter":"S","hasNote":false},{"id":"FIN-1336","slug":"size-premium","term":"Size Premium","also_known_as":[],"difficulty":"Advanced","definition":"A size premium is the extra return that some analysts add to the cost of equity for smaller companies, based on the view that small companies are riskier and have historically earned higher returns than large ones.","letter":"S","hasNote":false},{"id":"FIN-988","slug":"skewness","term":"Skewness","also_known_as":[],"difficulty":"Intermediate","definition":"Skewness is a measure of how asymmetrical a probability distribution is, showing whether extreme values are more likely on one side of the average than the other.","letter":"S","hasNote":false},{"id":"FIN-706","slug":"small-cap-stock","term":"Small-Cap Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A small-cap stock is a share in a company with a relatively small market capitalization compared with other listed companies.","letter":"S","hasNote":false},{"id":"FIN-1153","slug":"smart-beta","term":"Smart Beta","also_known_as":[],"difficulty":"Advanced","definition":"Smart beta is an investment approach that tracks an index built using rules other than market capitalization, such as factors like value or low volatility, or equal weighting, typically through low-cost exchange-traded funds.","letter":"S","hasNote":false},{"id":"FIN-1324","slug":"smart-contract","term":"Smart Contract","also_known_as":[],"difficulty":"Advanced","definition":"A smart contract is a computer program stored on a blockchain that automatically carries out the terms of an agreement when specified conditions are met.","letter":"S","hasNote":false},{"id":"FIN-1185","slug":"socially-responsible-investing","term":"Socially Responsible Investing","also_known_as":[],"difficulty":"Advanced","definition":"Socially responsible investing is an investment approach that considers ethical, social or environmental values when choosing investments, often by excluding companies or industries that conflict with those values.","letter":"S","hasNote":false},{"id":"FIN-1302","slug":"sofr","term":"SOFR","also_known_as":[],"difficulty":"Advanced","definition":"SOFR, the Secured Overnight Financing Rate, is a benchmark interest rate in the United States based on the cost of overnight borrowing secured by US Treasury securities in the repurchase agreement market.","letter":"S","hasNote":false},{"id":"FIN-1213","slug":"soft-landing","term":"Soft Landing","also_known_as":[],"difficulty":"Advanced","definition":"A soft landing is when a central bank slows down an overheating economy enough to bring inflation under control, without causing a recession.","letter":"S","hasNote":false},{"id":"FIN-505","slug":"solvency","term":"Solvency","also_known_as":[],"difficulty":"Beginner","definition":"Solvency is the ability of a person or business to meet all its long-term financial obligations, meaning its assets are worth more than its debts.","letter":"S","hasNote":false},{"id":"FIN-1428","slug":"solvency-ratio","term":"Solvency Ratio","also_known_as":[],"difficulty":"Advanced","definition":"A solvency ratio is a measure of an insurer\'s or company\'s ability to meet its long-term obligations, comparing its available capital or resources with its liabilities or capital requirements.","letter":"S","hasNote":false},{"id":"FIN-1141","slug":"sortino-ratio","term":"Sortino Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The Sortino ratio measures an investment\'s return above a target or risk-free rate for each unit of downside risk, counting only volatility from returns that fall below the target.","letter":"S","hasNote":false},{"id":"FIN-1347","slug":"sources-and-uses","term":"Sources and Uses","also_known_as":[],"difficulty":"Advanced","definition":"Sources and uses is a summary table in a transaction, such as an acquisition or leveraged buyout, showing where the money to fund the deal comes from and how it will be spent.","letter":"S","hasNote":false},{"id":"FIN-1247","slug":"sovereign-default","term":"Sovereign Default","also_known_as":[],"difficulty":"Advanced","definition":"A sovereign default is when a national government fails to make interest or principal payments on its debt on time, or forces creditors to accept less favourable terms.","letter":"S","hasNote":false},{"id":"FIN-661","slug":"special-dividend","term":"Special Dividend","also_known_as":[],"difficulty":"Intermediate","definition":"A special dividend is a one-off payment a company makes to shareholders, separate from its regular dividends, usually when it has unusually large profits or surplus cash.","letter":"S","hasNote":false},{"id":"FIN-1443","slug":"special-purpose-acquisition-company","term":"Special Purpose Acquisition Company (SPAC)","also_known_as":["SPAC"],"difficulty":"Advanced","definition":"A special purpose acquisition company (SPAC) is a publicly listed company created with no operations of its own, which raises money from investors in a stock market listing in order to acquire a private company, taking it public.","letter":"S","hasNote":false},{"id":"FIN-1392","slug":"special-purpose-vehicle","term":"Special Purpose Vehicle (SPV)","also_known_as":["SPV"],"difficulty":"Advanced","definition":"A special purpose vehicle (SPV) is a separate legal entity created by a company or financial institution for a specific, limited purpose, such as holding assets, financing a project or issuing securities, often to isolate financial risk.","letter":"S","hasNote":false},{"id":"FIN-1243","slug":"specialization","term":"Specialization","also_known_as":[],"difficulty":"Advanced","definition":"Specialization is the concentration of a person, business, region or country on producing a limited range of goods or services, in order to become more efficient, and then trading for other needs.","letter":"S","hasNote":false},{"id":"FIN-893","slug":"speculation","term":"Speculation","also_known_as":[],"difficulty":"Intermediate","definition":"Speculation is buying, selling or holding financial assets in the hope of profiting from changes in their price, usually accepting significant risk in exchange for the chance of large gains.","letter":"S","hasNote":false},{"id":"FIN-966","slug":"spin-off","term":"Spin-Off","also_known_as":[],"difficulty":"Intermediate","definition":"A spin-off is the creation of a new, independent company by separating a division or subsidiary from its parent company, usually by distributing shares in the new company to the parent\'s existing shareholders.","letter":"S","hasNote":false},{"id":"FIN-1475","slug":"sponsor","term":"Sponsor","also_known_as":[],"difficulty":"Advanced","definition":"In private equity, a sponsor is the private equity firm that leads and controls an investment, such as a leveraged buyout, providing most of the equity and managing the company after acquisition.","letter":"S","hasNote":false},{"id":"FIN-1198","slug":"spot-rate","term":"Spot Rate","also_known_as":[],"difficulty":"Advanced","definition":"In fixed income, a spot rate is the interest rate, or yield, for a single payment made at a specific date in the future, starting today, as implied by a zero-coupon bond of that maturity.","letter":"S","hasNote":false},{"id":"FIN-871","slug":"stablecoin","term":"Stablecoin","also_known_as":[],"difficulty":"Intermediate","definition":"A stablecoin is a type of cryptocurrency designed to maintain a stable value by linking it to a reference asset, usually a traditional currency such as the US dollar.","letter":"S","hasNote":false},{"id":"FIN-760","slug":"stagflation","term":"Stagflation","also_known_as":[],"difficulty":"Intermediate","definition":"Stagflation is an economic situation that combines high inflation with slow or stagnant economic growth and high unemployment.","letter":"S","hasNote":false},{"id":"FIN-1012","slug":"stamp-duty","term":"Stamp Duty","also_known_as":[],"difficulty":"Intermediate","definition":"Stamp duty is a tax charged on certain legal documents and transactions, most often on buying property or shares. The name comes from the official stamp that was once applied to documents to show the tax had been paid.","letter":"S","hasNote":false},{"id":"FIN-1066","slug":"standard-costing","term":"Standard Costing","also_known_as":[],"difficulty":"Advanced","definition":"Standard costing is a system in which expected costs for materials, labour and overheads per unit are set in advance and then compared with actual costs, so differences can be investigated.","letter":"S","hasNote":false},{"id":"FIN-535","slug":"standard-deduction","term":"Standard Deduction","also_known_as":[],"difficulty":"Intermediate","definition":"A standard deduction is a fixed amount that taxpayers can subtract from their income before tax is calculated, without having to list or prove specific expenses.","letter":"S","hasNote":false},{"id":"FUT-0351","slug":"standard-deviation","term":"Standard Deviation","also_known_as":[],"difficulty":"Intermediate","definition":"Standard deviation is a measure of how much a set of values typically differs from the mean. It is the square root of the variance.","letter":"S","hasNote":false},{"id":"FIN-032","slug":"standard-of-living","term":"Standard of Living","also_known_as":[],"difficulty":"Beginner","definition":"Standard of living is the level of wealth, comfort, goods and services available to a person, household or country. It reflects how well people are able to live, not just how much they earn.","letter":"S","hasNote":false},{"id":"FIN-843","slug":"standing-order","term":"Standing Order","also_known_as":[],"difficulty":"Beginner","definition":"A standing order is an instruction, common in the United Kingdom and Europe, that a customer gives to their bank to pay a fixed amount to another account at regular intervals, such as weekly or monthly.","letter":"S","hasNote":false},{"id":"FIN-115","slug":"statement-of-changes-in-equity","term":"Statement of Changes in Equity","also_known_as":[],"difficulty":"Beginner","definition":"The statement of changes in equity shows how the owners\' equity in a business changed during a period, including profits, dividends, new shares issued and other movements.","letter":"S","hasNote":false},{"id":"FIN-113","slug":"statement-of-comprehensive-income","term":"Statement of Comprehensive Income","also_known_as":[],"difficulty":"Beginner","definition":"The statement of comprehensive income shows a company\'s net income for a period together with other gains and losses that are not included in net income, giving a fuller picture of how equity changed.","letter":"S","hasNote":false},{"id":"FIN-1077","slug":"static-budget","term":"Static Budget","also_known_as":[],"difficulty":"Advanced","definition":"A static budget is a budget prepared for a single planned level of activity, such as a set number of units sold, that does not change if actual activity turns out to be different.","letter":"S","hasNote":false},{"id":"FIN-1487","slug":"stationarity","term":"Stationarity","also_known_as":[],"difficulty":"Advanced","definition":"Stationarity is a property of a time series whose statistical characteristics, such as its average, variance and autocorrelation, stay constant over time.","letter":"S","hasNote":false},{"id":"FIN-493","slug":"statistical-significance","term":"Statistical Significance","also_known_as":[],"difficulty":"Intermediate","definition":"Statistical significance describes a result that is unlikely to have occurred by chance alone if there were no real effect, usually judged by whether its p-value falls below a chosen threshold, such as 0.05.","letter":"S","hasNote":false},{"id":"FIN-1042","slug":"statutory-accounts","term":"Statutory Accounts","also_known_as":[],"difficulty":"Advanced","definition":"Statutory accounts are the official annual financial statements a company is legally required to prepare and, in many countries, file with a government registry, following the applicable accounting standards and company law.","letter":"S","hasNote":false},{"id":"FIN-790","slug":"stimulus","term":"Stimulus","also_known_as":[],"difficulty":"Intermediate","definition":"Stimulus refers to government or central bank actions designed to boost economic activity, usually during a recession or slowdown, by increasing spending or making borrowing cheaper.","letter":"S","hasNote":false},{"id":"FIN-237","slug":"stock","term":"Stock","also_known_as":[],"difficulty":"Beginner","definition":"A stock is a type of investment that represents ownership in a company. Owning stock gives you a claim on part of the company\'s assets and profits.","letter":"S","hasNote":false},{"id":"FIN-1373","slug":"stock-consideration","term":"Stock Consideration","also_known_as":[],"difficulty":"Advanced","definition":"Stock consideration is payment for an acquisition made with the acquirer\'s own shares, rather than cash, so target shareholders become shareholders in the combined company.","letter":"S","hasNote":false},{"id":"FIN-1049","slug":"stock-option-expense","term":"Stock Option Expense","also_known_as":[],"difficulty":"Advanced","definition":"Stock option expense is the cost a company records in its income statement for granting stock options to employees, based on the fair value of the options when they were granted and spread over the period in which they are earned.","letter":"S","hasNote":false},{"id":"FIN-662","slug":"stock-split","term":"Stock Split","also_known_as":[],"difficulty":"Beginner","definition":"A stock split is when a company increases the number of its shares by dividing each existing share into several new ones, reducing the price per share proportionally without changing the company\'s total value.","letter":"S","hasNote":false},{"id":"FIN-271","slug":"stop-limit-order","term":"Stop-Limit Order","also_known_as":[],"difficulty":"Intermediate","definition":"A stop-limit order combines a stop order and a limit order. When the stop price is reached, it becomes a limit order that will be filled only at the limit price or better.","letter":"S","hasNote":false},{"id":"FIN-270","slug":"stop-order","term":"Stop Order","also_known_as":[],"difficulty":"Intermediate","definition":"A stop order is an instruction to buy or sell a security once its price reaches a specified level, called the stop price. When the stop price is reached, the order becomes a market order.","letter":"S","hasNote":false},{"id":"FIN-503","slug":"store-of-value","term":"Store of Value","also_known_as":[],"difficulty":"Beginner","definition":"A store of value is an asset that keeps its purchasing power over time, so it can be saved now and used later without losing much of its worth.","letter":"S","hasNote":false},{"id":"FIN-447","slug":"straddle","term":"Straddle","also_known_as":[],"difficulty":"Intermediate","definition":"A straddle is an options strategy that involves buying both a call and a put on the same asset, with the same strike price and expiry date, to profit from a large price move in either direction.","letter":"S","hasNote":false},{"id":"FIN-448","slug":"strangle","term":"Strangle","also_known_as":[],"difficulty":"Intermediate","definition":"A strangle is an options strategy that involves buying an out-of-the-money call and an out-of-the-money put on the same asset with the same expiry date, to profit from a large price move in either direction.","letter":"S","hasNote":false},{"id":"FIN-229","slug":"strategic-asset-allocation","term":"Strategic Asset Allocation","also_known_as":[],"difficulty":"Beginner","definition":"Strategic asset allocation is a long-term plan that sets target percentages for each type of asset in a portfolio, based on an investor\'s goals, time horizon and risk tolerance.","letter":"S","hasNote":false},{"id":"FIN-970","slug":"strategic-buyer","term":"Strategic Buyer","also_known_as":[],"difficulty":"Intermediate","definition":"A strategic buyer is a company that acquires another business because it fits with its own operations, typically a competitor, supplier, customer or company in a related industry.","letter":"S","hasNote":false},{"id":"FIN-205","slug":"stress-testing","term":"Stress Testing","also_known_as":[],"difficulty":"Intermediate","definition":"Stress testing examines how a business, bank or investment portfolio would cope under extreme but plausible adverse conditions, such as a severe recession, a market crash or a sudden rise in interest rates.","letter":"S","hasNote":false},{"id":"FIN-428","slug":"strike-price","term":"Strike Price","also_known_as":["Exercise Price"],"difficulty":"Intermediate","definition":"The strike price is the fixed price at which the holder of an option can buy the underlying asset, for a call, or sell it, for a put.","letter":"S","hasNote":true},{"id":"FIN-771","slug":"structural-unemployment","term":"Structural Unemployment","also_known_as":[],"difficulty":"Intermediate","definition":"Structural unemployment is long-term unemployment that occurs when there is a mismatch between the skills or locations of workers and the jobs available in the economy.","letter":"S","hasNote":false},{"id":"FIN-1389","slug":"structured-product","term":"Structured Product","also_known_as":[],"difficulty":"Advanced","definition":"A structured product is a pre-packaged investment that combines a basic investment, such as a bond or deposit, with one or more derivatives, to create a specific pattern of returns linked to an underlying asset, such as a stock index.","letter":"S","hasNote":false},{"id":"FIN-417","slug":"stub-period","term":"Stub Period","also_known_as":[],"difficulty":"Intermediate","definition":"A stub period is a period shorter than a full year, typically at the start of a valuation or forecast, that bridges the gap between the valuation date and the start of the next full financial year.","letter":"S","hasNote":false},{"id":"FIN-820","slug":"student-loan","term":"Student Loan","also_known_as":[],"difficulty":"Beginner","definition":"A student loan is money borrowed to pay for education costs, such as tuition fees, books and living expenses, usually repaid after the student finishes or leaves their studies.","letter":"S","hasNote":false},{"id":"FIN-976","slug":"subordinated-debt","term":"Subordinated Debt","also_known_as":[],"difficulty":"Intermediate","definition":"Subordinated debt is borrowing that ranks below other debts for repayment if a company goes bankrupt or is liquidated, so it is repaid only after senior debt has been paid in full.","letter":"S","hasNote":false},{"id":"FIN-1423","slug":"subrogation","term":"Subrogation","also_known_as":[],"difficulty":"Advanced","definition":"Subrogation is the right of an insurer, after paying a claim, to take over the policyholder\'s legal rights to recover the amount from a third party who caused the loss.","letter":"S","hasNote":false},{"id":"FIN-454","slug":"subscription-model","term":"Subscription Model","also_known_as":[],"difficulty":"Beginner","definition":"A subscription model is a business model in which customers pay a recurring fee, such as monthly or yearly, for continued access to a product or service.","letter":"S","hasNote":false},{"id":"FIN-611","slug":"subsequent-event","term":"Subsequent Event","also_known_as":[],"difficulty":"Intermediate","definition":"A subsequent event is a significant event that occurs after the end of a reporting period but before the financial statements are issued, which may need to be reflected in, or disclosed alongside, those statements.","letter":"S","hasNote":false},{"id":"FIN-590","slug":"subsidiary","term":"Subsidiary","also_known_as":[],"difficulty":"Intermediate","definition":"A subsidiary is a company controlled by another company, called the parent, usually because the parent owns more than half of its voting shares.","letter":"S","hasNote":false},{"id":"FIN-328","slug":"subsidy","term":"Subsidy","also_known_as":[],"difficulty":"Beginner","definition":"A subsidy is a payment or financial support provided by a government to individuals or businesses to lower the cost of producing or buying certain goods or services.","letter":"S","hasNote":false},{"id":"FIN-305","slug":"substitute-good","term":"Substitute Good","also_known_as":[],"difficulty":"Beginner","definition":"A substitute good is a product that can be used in place of another to satisfy the same need, such as tea instead of coffee or a bus instead of a train.","letter":"S","hasNote":false},{"id":"FIN-1179","slug":"suitability","term":"Suitability","also_known_as":[],"difficulty":"Advanced","definition":"Suitability is the obligation of a financial adviser or broker to recommend only investments that are appropriate for a particular client, given their financial situation, objectives, experience and tolerance for risk.","letter":"S","hasNote":false},{"id":"FIN-880","slug":"sum-of-the-parts-valuation","term":"Sum-of-the-Parts Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Sum-of-the-parts valuation is a method of valuing a company with several distinct businesses by valuing each business separately and adding the values together.","letter":"S","hasNote":false},{"id":"FIN-638","slug":"sunk-cost","term":"Sunk Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A sunk cost is money that has already been spent and cannot be recovered, whatever decision is made next. Sound decisions should ignore it.","letter":"S","hasNote":false},{"id":"FIN-1136","slug":"supplier-concentration","term":"Supplier Concentration","also_known_as":[],"difficulty":"Advanced","definition":"Supplier concentration is the extent to which a company depends on a small number of suppliers for important materials, components or services.","letter":"S","hasNote":false},{"id":"FIN-295","slug":"supply","term":"Supply","also_known_as":[],"difficulty":"Beginner","definition":"Supply is the quantity of a good or service that producers are willing and able to sell at different prices over a period of time.","letter":"S","hasNote":false},{"id":"FIN-1434","slug":"supply-chain-finance","term":"Supply Chain Finance","also_known_as":[],"difficulty":"Advanced","definition":"Supply chain finance is a financing arrangement in which a buyer\'s bank or a finance provider pays the buyer\'s suppliers early, at a small discount, while the buyer pays the full invoice later on the normal or extended due date.","letter":"S","hasNote":false},{"id":"FIN-297","slug":"supply-curve","term":"Supply Curve","also_known_as":[],"difficulty":"Intermediate","definition":"A supply curve is a graph showing the relationship between the price of a good and the quantity producers are willing to supply at each price, with all other factors held constant.","letter":"S","hasNote":false},{"id":"FIN-1240","slug":"supply-side-economics","term":"Supply-Side Economics","also_known_as":[],"difficulty":"Advanced","definition":"Supply-side economics is a school of economic thought which holds that economic growth is best promoted by policies that increase the economy\'s capacity to produce, such as lower taxes, reduced regulation and incentives to work, save and invest.","letter":"S","hasNote":false},{"id":"FIN-497","slug":"survivorship-bias","term":"Survivorship Bias","also_known_as":[],"difficulty":"Intermediate","definition":"Survivorship bias is the error of focusing only on people, companies or investments that have survived or succeeded, while overlooking those that failed or disappeared, which leads to overly optimistic conclusions.","letter":"S","hasNote":false},{"id":"FIN-658","slug":"sustainable-growth-rate","term":"Sustainable Growth Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The sustainable growth rate is the maximum rate at which a company can grow its sales and earnings using only its own retained profits, without issuing new shares or changing its level of debt relative to equity.","letter":"S","hasNote":false},{"id":"FIN-906","slug":"swap","term":"Swap","also_known_as":[],"difficulty":"Intermediate","definition":"A swap is a derivative contract in which two parties agree to exchange streams of cash flows over a set period, based on an agreed principal amount and terms.","letter":"S","hasNote":false},{"id":"FIN-1384","slug":"swap-rate","term":"Swap Rate","also_known_as":[],"difficulty":"Advanced","definition":"The swap rate is the fixed interest rate in an interest rate swap that makes the swap worth zero at the start, balancing the expected value of the fixed payments against the expected floating payments.","letter":"S","hasNote":false},{"id":"FIN-1388","slug":"swaption","term":"Swaption","also_known_as":[],"difficulty":"Advanced","definition":"A swaption is an option that gives the holder the right, but not the obligation, to enter into an interest rate swap on agreed terms at a future date.","letter":"S","hasNote":false},{"id":"FIN-1292","slug":"swift","term":"SWIFT","also_known_as":[],"difficulty":"Advanced","definition":"SWIFT, the Society for Worldwide Interbank Financial Telecommunication, is a global network that allows banks and other financial institutions to send secure, standardised messages to each other about payments and other transactions.","letter":"S","hasNote":false},{"id":"FIN-461","slug":"switching-cost","term":"Switching Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A switching cost is the cost, effort or inconvenience a customer faces when changing from one product, service or supplier to another.","letter":"S","hasNote":false},{"id":"FIN-1276","slug":"syndicated-loan","term":"Syndicated Loan","also_known_as":[],"difficulty":"Advanced","definition":"A syndicated loan is a large loan provided to a single borrower by a group of lenders, called a syndicate, organised and managed by one or more lead banks.","letter":"S","hasNote":false},{"id":"FIN-665","slug":"synergy","term":"Synergy","also_known_as":[],"difficulty":"Intermediate","definition":"Synergy is the extra value created when two companies or business units combine, because together they are worth more than the sum of their separate values.","letter":"S","hasNote":false},{"id":"FUT-0361","slug":"systematic-risk","term":"Systematic Risk","also_known_as":["Market Risk"],"difficulty":"Intermediate","definition":"Systematic risk is the risk that affects the whole market or economy, such as a recession, rising interest rates or a financial crisis. It cannot be removed by diversifying.","letter":"S","hasNote":false},{"id":"FIN-1310","slug":"systemically-important-bank","term":"Systemically Important Bank","also_known_as":[],"difficulty":"Advanced","definition":"A systemically important bank is a bank whose size, complexity, interconnectedness or importance to the financial system is such that its failure could cause serious damage to the wider economy.","letter":"S","hasNote":false},{"id":"FIN-106","slug":"t-account","term":"T-Account","also_known_as":[],"difficulty":"Beginner","definition":"A T-account is a simple visual way of showing a single account, drawn in the shape of a letter T, with debits recorded on the left and credits on the right.","letter":"T","hasNote":false},{"id":"FIN-230","slug":"tactical-asset-allocation","term":"Tactical Asset Allocation","also_known_as":[],"difficulty":"Intermediate","definition":"Tactical asset allocation is a short- to medium-term strategy of temporarily shifting a portfolio away from its long-term targets to take advantage of expected market opportunities.","letter":"T","hasNote":false},{"id":"FIN-1452","slug":"tag-along-right","term":"Tag-Along Right","also_known_as":[],"difficulty":"Advanced","definition":"A tag-along right is a provision in a shareholder agreement that allows minority shareholders to join a sale when a majority shareholder sells its stake, selling their shares on the same terms.","letter":"T","hasNote":false},{"id":"FIN-898","slug":"tail-risk","term":"Tail Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Tail risk is the risk of rare, extreme events that cause very large losses, lying in the far ends, or tails, of a probability distribution of possible outcomes.","letter":"T","hasNote":false},{"id":"FIN-1128","slug":"take-rate","term":"Take Rate","also_known_as":[],"difficulty":"Advanced","definition":"Take rate is the percentage of the total value of transactions on a marketplace or platform that the platform keeps as its own revenue, through commissions and fees.","letter":"T","hasNote":false},{"id":"FIN-733","slug":"target-date-fund","term":"Target-Date Fund","also_known_as":[],"difficulty":"Intermediate","definition":"A target-date fund is an investment fund that automatically adjusts its mix of assets, becoming more conservative over time as it approaches a specific target year, usually the investor\'s expected retirement date.","letter":"T","hasNote":false},{"id":"FIN-1175","slug":"target-risk-fund","term":"Target-Risk Fund","also_known_as":[],"difficulty":"Advanced","definition":"A target-risk fund is a diversified investment fund that keeps a fixed level of risk, such as conservative, moderate or aggressive, by maintaining a set mix of assets over time.","letter":"T","hasNote":false},{"id":"FIN-330","slug":"tariff","term":"Tariff","also_known_as":[],"difficulty":"Beginner","definition":"A tariff is a tax on goods imported from other countries, usually charged as a percentage of the goods\' value or as a fixed amount per unit.","letter":"T","hasNote":false},{"id":"FIN-532","slug":"tax","term":"Tax","also_known_as":[],"difficulty":"Beginner","definition":"A tax is a compulsory payment that individuals and businesses must make to the government, used to fund public services and government activities.","letter":"T","hasNote":false},{"id":"FIN-745","slug":"tax-advantaged-account","term":"Tax-Advantaged Account","also_known_as":[],"difficulty":"Intermediate","definition":"A tax-advantaged account is a savings or investment account that receives special tax treatment, such as tax relief on contributions, tax-free growth or tax-free withdrawals, to encourage saving for specific goals.","letter":"T","hasNote":false},{"id":"FIN-1008","slug":"tax-allowance","term":"Tax Allowance","also_known_as":[],"difficulty":"Intermediate","definition":"A tax allowance is an amount that can be earned or deducted before tax is charged, most commonly the personal allowance: the portion of income on which no income tax is paid.","letter":"T","hasNote":false},{"id":"FIN-1018","slug":"tax-audit","term":"Tax Audit","also_known_as":[],"difficulty":"Intermediate","definition":"A tax audit is an examination by a tax authority of a person\'s or business\'s tax returns and records, to check that income, deductions and tax have been reported correctly.","letter":"T","hasNote":false},{"id":"FIN-550","slug":"tax-avoidance","term":"Tax Avoidance","also_known_as":[],"difficulty":"Beginner","definition":"Tax avoidance is the legal use of tax rules to reduce the amount of tax owed, for example by claiming allowances, deductions and reliefs or by structuring transactions in a tax-efficient way.","letter":"T","hasNote":false},{"id":"FIN-1232","slug":"tax-base","term":"Tax Base","also_known_as":[],"difficulty":"Advanced","definition":"The tax base is the total amount of income, property, spending or other activity that a tax is applied to.","letter":"T","hasNote":false},{"id":"FIN-538","slug":"tax-bracket","term":"Tax Bracket","also_known_as":[],"difficulty":"Beginner","definition":"A tax bracket is a range of income that is taxed at a particular rate. In a progressive system, income in higher brackets is taxed at higher rates.","letter":"T","hasNote":false},{"id":"FIN-1002","slug":"tax-compliance","term":"Tax Compliance","also_known_as":[],"difficulty":"Intermediate","definition":"Tax compliance is meeting all the tax obligations set by law: registering where required, keeping records, filing accurate returns and paying the right amount of tax on time.","letter":"T","hasNote":false},{"id":"FIN-537","slug":"tax-credit","term":"Tax Credit","also_known_as":[],"difficulty":"Beginner","definition":"A tax credit is an amount subtracted directly from the tax a person or business owes, reducing the tax bill unit for unit.","letter":"T","hasNote":false},{"id":"FIN-534","slug":"tax-deduction","term":"Tax Deduction","also_known_as":[],"difficulty":"Beginner","definition":"A tax deduction is an amount that can be subtracted from income before tax is calculated, which reduces taxable income and therefore the tax owed.","letter":"T","hasNote":false},{"id":"FIN-749","slug":"tax-deferred-growth","term":"Tax-Deferred Growth","also_known_as":[],"difficulty":"Intermediate","definition":"Tax-deferred growth means investment earnings, such as interest, dividends and capital gains, are not taxed as they occur, but only later, usually when money is withdrawn.","letter":"T","hasNote":false},{"id":"FIN-1187","slug":"tax-efficient-investing","term":"Tax-Efficient Investing","also_known_as":[],"difficulty":"Advanced","definition":"Tax-efficient investing is arranging investments to legally reduce the taxes paid on investment returns, so that more of the return is kept.","letter":"T","hasNote":false},{"id":"FIN-551","slug":"tax-evasion","term":"Tax Evasion","also_known_as":[],"difficulty":"Beginner","definition":"Tax evasion is the illegal practice of not paying tax that is owed, for example by hiding income, inflating deductions or providing false information to tax authorities.","letter":"T","hasNote":false},{"id":"FIN-536","slug":"tax-exemption","term":"Tax Exemption","also_known_as":[],"difficulty":"Intermediate","definition":"A tax exemption is a legal right to exclude certain income, people, organisations or transactions from tax, either fully or partly.","letter":"T","hasNote":false},{"id":"FIN-1019","slug":"tax-free-growth","term":"Tax-Free Growth","also_known_as":[],"difficulty":"Intermediate","definition":"Tax-free growth means investment returns, such as interest, dividends and capital gains, that are never taxed, as long as the account\'s rules are followed.","letter":"T","hasNote":false},{"id":"FIN-1016","slug":"tax-haven","term":"Tax Haven","also_known_as":[],"difficulty":"Intermediate","definition":"A tax haven is a country or territory with very low or zero taxes, often combined with secrecy and few requirements for real business activity, that attracts companies and individuals seeking to reduce tax elsewhere.","letter":"T","hasNote":false},{"id":"FIN-327","slug":"tax-incidence","term":"Tax Incidence","also_known_as":[],"difficulty":"Intermediate","definition":"Tax incidence describes who actually bears the burden of a tax, buyers or sellers, regardless of who legally pays it to the government.","letter":"T","hasNote":false},{"id":"FIN-1186","slug":"tax-loss-harvesting","term":"Tax-Loss Harvesting","also_known_as":[],"difficulty":"Advanced","definition":"Tax-loss harvesting is selling investments that have fallen in value to realize a loss, which can be used to offset taxable gains, while usually reinvesting the money to stay invested.","letter":"T","hasNote":false},{"id":"FIN-1204","slug":"tax-lot","term":"Tax Lot","also_known_as":[],"difficulty":"Advanced","definition":"A tax lot is a record of a specific purchase of a security, including the date, quantity and price paid, used to calculate the gain or loss when part of a holding is sold.","letter":"T","hasNote":false},{"id":"FIN-1027","slug":"tax-provision","term":"Tax Provision","also_known_as":[],"difficulty":"Advanced","definition":"A tax provision is the total income tax expense a company records for a period in its income statement, made up of current tax owed for the period and deferred tax arising from timing differences.","letter":"T","hasNote":false},{"id":"FIN-546","slug":"tax-refund","term":"Tax Refund","also_known_as":[],"difficulty":"Beginner","definition":"A tax refund is money returned by the tax authority to a taxpayer who paid more tax during the year than they actually owed.","letter":"T","hasNote":false},{"id":"FIN-545","slug":"tax-residency","term":"Tax Residency","also_known_as":[],"difficulty":"Intermediate","definition":"Tax residency is a person\'s or company\'s status as a resident of a country for tax purposes, which determines whether, and on what income, that country can tax them.","letter":"T","hasNote":false},{"id":"FIN-544","slug":"tax-return","term":"Tax Return","also_known_as":[],"difficulty":"Beginner","definition":"A tax return is a form, usually filed once a year with the tax authority, that reports a person\'s or business\'s income, deductions and other information used to calculate the tax they owe.","letter":"T","hasNote":false},{"id":"FIN-796","slug":"tax-revenue","term":"Tax Revenue","also_known_as":[],"difficulty":"Intermediate","definition":"Tax revenue is the total income a government collects from taxes, such as income tax, corporate tax, sales or value-added tax and social security contributions.","letter":"T","hasNote":false},{"id":"FIN-1015","slug":"tax-shelter","term":"Tax Shelter","also_known_as":[],"difficulty":"Intermediate","definition":"A tax shelter is an investment, account or arrangement that legally reduces or defers the tax a person or business must pay.","letter":"T","hasNote":false},{"id":"FIN-1014","slug":"tax-treaty","term":"Tax Treaty","also_known_as":[],"difficulty":"Intermediate","definition":"A tax treaty is an agreement between two countries that decides which country can tax different types of income, with the aim of preventing double taxation and tax evasion.","letter":"T","hasNote":false},{"id":"FIN-543","slug":"tax-year","term":"Tax Year","also_known_as":[],"difficulty":"Intermediate","definition":"A tax year is the twelve-month period used for calculating and reporting income and tax. It may match the calendar year or follow different dates set by the government.","letter":"T","hasNote":false},{"id":"FIN-744","slug":"taxable-account","term":"Taxable Account","also_known_as":[],"difficulty":"Intermediate","definition":"A taxable account is an investment account with no special tax advantages, in which income and realized gains are subject to tax in the year they occur.","letter":"T","hasNote":false},{"id":"FIN-1003","slug":"taxable-event","term":"Taxable Event","also_known_as":[],"difficulty":"Intermediate","definition":"A taxable event is any transaction or occurrence that creates a tax liability under the law, such as receiving income, selling an asset at a gain or receiving a dividend.","letter":"T","hasNote":false},{"id":"FIN-533","slug":"taxable-income","term":"Taxable Income","also_known_as":[],"difficulty":"Beginner","definition":"Taxable income is the portion of income on which tax is actually charged, after subtracting allowable deductions, exemptions and allowances from total income.","letter":"T","hasNote":false},{"id":"FIN-1356","slug":"teaser","term":"Teaser","also_known_as":[],"difficulty":"Advanced","definition":"A teaser is a short, anonymous document sent to potential buyers or investors at the start of a sale process, giving a brief overview of a business to gauge interest without revealing its identity.","letter":"T","hasNote":false},{"id":"FIN-712","slug":"technical-analysis","term":"Technical Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Technical analysis is a method of evaluating and forecasting investment prices by studying past market data, mainly price movements and trading volumes, rather than a company\'s underlying financial performance.","letter":"T","hasNote":false},{"id":"FIN-1025","slug":"temporary-difference","term":"Temporary Difference","also_known_as":[],"difficulty":"Advanced","definition":"A temporary difference is a difference between the value of an asset or liability in the accounts and its value for tax purposes that will reverse in future, creating either taxable or deductible amounts.","letter":"T","hasNote":false},{"id":"FIN-931","slug":"term-life-insurance","term":"Term Life Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Term life insurance is life insurance that provides cover for a set period, such as 10, 20 or 30 years, paying a lump sum to beneficiaries if the insured person dies during that period.","letter":"T","hasNote":false},{"id":"FIN-814","slug":"term-loan","term":"Term Loan","also_known_as":[],"difficulty":"Intermediate","definition":"A term loan is a loan for a fixed amount that is repaid over a set period, usually with regular scheduled payments and either a fixed or variable interest rate.","letter":"T","hasNote":false},{"id":"FIN-969","slug":"term-sheet","term":"Term Sheet","also_known_as":[],"difficulty":"Intermediate","definition":"A term sheet is a short document that sets out the main terms and conditions of a proposed investment or transaction, used as the basis for negotiating final legal agreements.","letter":"T","hasNote":false},{"id":"FIN-413","slug":"terminal-growth-rate","term":"Terminal Growth Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The terminal growth rate is the constant annual rate at which a company\'s cash flows are assumed to grow forever after the end of the detailed forecast period in a discounted cash flow valuation.","letter":"T","hasNote":false},{"id":"FIN-184","slug":"terminal-value","term":"Terminal Value","also_known_as":[],"difficulty":"Intermediate","definition":"Terminal value is the estimated value of a business or project beyond the period for which detailed cash flow forecasts are made. It captures the value of all cash flows from that point onwards.","letter":"T","hasNote":false},{"id":"FIN-1244","slug":"terms-of-trade","term":"Terms of Trade","also_known_as":[],"difficulty":"Advanced","definition":"The terms of trade are the ratio of a country\'s export prices to its import prices, usually expressed as an index, showing how many imports it can buy with a given quantity of exports.","letter":"T","hasNote":false},{"id":"FIN-918","slug":"theta","term":"Theta","also_known_as":[],"difficulty":"Intermediate","definition":"Theta is a measure of how much an option\'s value is expected to decrease as each day passes, assuming all other factors stay the same. It is often called time decay.","letter":"T","hasNote":false},{"id":"FIN-196","slug":"three-statement-model","term":"Three-Statement Model","also_known_as":["Integrated Financial Model"],"difficulty":"Intermediate","definition":"A three-statement model is a financial model that forecasts a company\'s income statement, balance sheet and cash flow statement together, with all three linked so that a change in one flows through to the others.","letter":"T","hasNote":true},{"id":"FIN-362","slug":"tier-1-capital","term":"Tier 1 Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Tier 1 capital is a bank\'s highest-quality capital, consisting mainly of shareholders\' equity and retained earnings, which can absorb losses while the bank continues operating.","letter":"T","hasNote":false},{"id":"FIN-364","slug":"tier-2-capital","term":"Tier 2 Capital","also_known_as":[],"difficulty":"Intermediate","definition":"Tier 2 capital is a bank\'s supplementary capital, made up of instruments such as certain long-term subordinated debt and some loan loss reserves, which absorb losses mainly if the bank fails.","letter":"T","hasNote":false},{"id":"FIN-351","slug":"time-deposit","term":"Time Deposit","also_known_as":["Term Deposit"],"difficulty":"Beginner","definition":"A time deposit is money placed in a bank for a fixed period, such as six months or five years, in exchange for a set interest rate. Withdrawing it early usually involves a penalty or is not allowed.","letter":"T","hasNote":true},{"id":"FIN-992","slug":"time-series","term":"Time Series","also_known_as":[],"difficulty":"Intermediate","definition":"A time series is a sequence of data points recorded at successive, usually equally spaced, points in time.","letter":"T","hasNote":false},{"id":"FIN-038","slug":"time-value-of-money","term":"Time Value of Money","also_known_as":[],"difficulty":"Beginner","definition":"The time value of money is the idea that money available today is worth more than the same amount received in the future, because money today can be invested to earn a return.","letter":"T","hasNote":false},{"id":"FIN-439","slug":"time-value-option","term":"Time Value (Option)","also_known_as":[],"difficulty":"Intermediate","definition":"The time value of an option is the part of its price above its intrinsic value. It reflects the possibility that the option will become more valuable before it expires.","letter":"T","hasNote":false},{"id":"FIN-1201","slug":"time-weighted-return","term":"Time-Weighted Return","also_known_as":[],"difficulty":"Advanced","definition":"Time-weighted return is a measure of investment performance that removes the effect of money being added to or withdrawn from a portfolio, showing how the investments themselves performed.","letter":"T","hasNote":false},{"id":"FIN-1322","slug":"tokenization","term":"Tokenization","also_known_as":[],"difficulty":"Advanced","definition":"Tokenization is the process of representing ownership of an asset, such as a share, bond, property or fund unit, as a digital token recorded on a blockchain or similar digital ledger.","letter":"T","hasNote":false},{"id":"FIN-856","slug":"too-big-to-fail","term":"Too Big to Fail","also_known_as":[],"difficulty":"Intermediate","definition":"Too big to fail describes a financial institution or company so large and interconnected that its collapse would cause severe damage to the wider economy, so governments feel compelled to rescue it if it gets into trouble.","letter":"T","hasNote":false},{"id":"FIN-940","slug":"total-addressable-market","term":"Total Addressable Market (TAM)","also_known_as":["TAM"],"difficulty":"Intermediate","definition":"Total addressable market (TAM) is the total revenue opportunity available for a product or service if it captured 100% of its potential market.","letter":"T","hasNote":false},{"id":"FIN-1212","slug":"total-factor-productivity","term":"Total Factor Productivity","also_known_as":[],"difficulty":"Advanced","definition":"Total factor productivity is the part of economic output growth that cannot be explained by increases in labour and capital, reflecting how efficiently these inputs are used, through factors such as technology, innovation and better management.","letter":"T","hasNote":false},{"id":"FIN-683","slug":"total-return","term":"Total Return","also_known_as":["Holding Period Return"],"difficulty":"Beginner","definition":"Total return is the full gain or loss on an investment over a period, combining the income it paid with the change in its price.","letter":"T","hasNote":true},{"id":"FIN-B3-NEW7","slug":"total-return-swap","term":"Total Return Swap","also_known_as":[],"difficulty":"Advanced","definition":"A total return swap is a derivative in which one party pays the total return of an asset, including income and changes in value, to the other party in exchange for a set of payments, usually a floating interest rate plus a spread.","letter":"T","hasNote":false},{"id":"FIN-692","slug":"tracking-error","term":"Tracking Error","also_known_as":[],"difficulty":"Intermediate","definition":"Tracking error is the standard deviation of the difference between a fund\'s returns and the returns of its benchmark, showing how closely the fund follows the benchmark.","letter":"T","hasNote":false},{"id":"FIN-332","slug":"trade-balance","term":"Trade Balance","also_known_as":["Balance of Trade"],"difficulty":"Beginner","definition":"The trade balance is the difference between the value of a country\'s exports and the value of its imports of goods and services over a period.","letter":"T","hasNote":true},{"id":"FIN-1280","slug":"trade-finance","term":"Trade Finance","also_known_as":[],"difficulty":"Advanced","definition":"Trade finance is the range of financial products and services that help businesses carry out international trade, by reducing the risks of non-payment and non-delivery and providing funding for goods in transit.","letter":"T","hasNote":false},{"id":"FIN-034","slug":"trade-off","term":"Trade-Off","also_known_as":[],"difficulty":"Beginner","definition":"A trade-off is a situation where gaining more of one thing means accepting less of another. It is the balancing act involved in almost every financial decision.","letter":"T","hasNote":false},{"id":"FIN-1110","slug":"trade-off-theory-of-capital-structure","term":"Trade-Off Theory of Capital Structure","also_known_as":[],"difficulty":"Advanced","definition":"The trade-off theory of capital structure states that companies choose their mix of debt and equity by balancing the tax benefits of debt against the costs of financial distress that rise as debt increases.","letter":"T","hasNote":false},{"id":"FIN-801","slug":"trade-protectionism","term":"Trade Protectionism","also_known_as":[],"difficulty":"Intermediate","definition":"Trade protectionism is a government policy of restricting imports from other countries, through measures such as tariffs, quotas and subsidies, to protect domestic industries and jobs from foreign competition.","letter":"T","hasNote":false},{"id":"FIN-1440","slug":"trade-sale","term":"Trade Sale","also_known_as":[],"difficulty":"Advanced","definition":"A trade sale is the sale of a company, or part of one, to another company, usually a business in the same or a related industry, rather than to financial investors or through a stock market listing.","letter":"T","hasNote":false},{"id":"FIN-469","slug":"trade-secret","term":"Trade Secret","also_known_as":[],"difficulty":"Beginner","definition":"A trade secret is confidential business information that gives a company a competitive advantage because it is not publicly known, such as a recipe, manufacturing process, customer list or algorithm.","letter":"T","hasNote":false},{"id":"FIN-467","slug":"trademark","term":"Trademark","also_known_as":[],"difficulty":"Beginner","definition":"A trademark is a legally protected sign, such as a name, logo, slogan, sound or design, that identifies the goods or services of a particular business and distinguishes them from those of others.","letter":"T","hasNote":false},{"id":"FIN-725","slug":"trading-volume","term":"Trading Volume","also_known_as":[],"difficulty":"Intermediate","definition":"Trading volume is the number of shares or contracts of a security traded during a given period, such as a day.","letter":"T","hasNote":false},{"id":"FIN-403","slug":"trailing-p-e","term":"Trailing P/E","also_known_as":[],"difficulty":"Intermediate","definition":"Trailing P/E is a company\'s current share price divided by its earnings per share over the past twelve months.","letter":"T","hasNote":false},{"id":"FIN-913","slug":"tranche","term":"Tranche","also_known_as":[],"difficulty":"Intermediate","definition":"A tranche is one of several slices of a pooled investment, such as a securitization, each with a different level of risk, return and priority for receiving payments.","letter":"T","hasNote":false},{"id":"FIN-1473","slug":"transaction-costs","term":"Transaction Costs","also_known_as":[],"difficulty":"Advanced","definition":"Transaction costs are the expenses incurred in buying, selling or completing a transaction, such as fees for advisers, lawyers, accountants and brokers, taxes, and financing charges.","letter":"T","hasNote":false},{"id":"FIN-883","slug":"transaction-multiple","term":"Transaction Multiple","also_known_as":[],"difficulty":"Intermediate","definition":"A transaction multiple is a valuation ratio derived from the price paid for a company in an actual acquisition, such as the deal\'s enterprise value divided by the target company\'s earnings before interest, taxes, depreciation and amortization.","letter":"T","hasNote":false},{"id":"FIN-1433","slug":"transfer-pricing","term":"Transfer Pricing","also_known_as":[],"difficulty":"Advanced","definition":"Transfer pricing is the setting of prices for goods, services, loans and intellectual property traded between companies in the same group, especially across countries, which determines where the group\'s profits are taxed.","letter":"T","hasNote":false},{"id":"FIN-1225","slug":"transmission-mechanism","term":"Transmission Mechanism","also_known_as":[],"difficulty":"Advanced","definition":"The transmission mechanism is the process by which changes in a central bank\'s policy interest rate, or other monetary policy actions, affect the wider economy, including spending, output, employment and inflation.","letter":"T","hasNote":false},{"id":"FIN-249","slug":"treasury-bill","term":"Treasury Bill","also_known_as":[],"difficulty":"Beginner","definition":"A Treasury bill is a short-term debt security issued by the US government, maturing in one year or less. It is sold at a discount and repaid at its full face value.","letter":"T","hasNote":false},{"id":"FIN-251","slug":"treasury-bond","term":"Treasury Bond","also_known_as":[],"difficulty":"Beginner","definition":"A Treasury bond is a long-term debt security issued by the US government, with a maturity of more than ten years, typically twenty or thirty years, that pays interest every six months.","letter":"T","hasNote":false},{"id":"FIN-1103","slug":"treasury-management","term":"Treasury Management","also_known_as":[],"difficulty":"Advanced","definition":"Treasury management is the management of a company\'s cash, liquidity, funding and financial risks, such as interest rate and currency risk, usually carried out by a dedicated treasury team.","letter":"T","hasNote":false},{"id":"FIN-250","slug":"treasury-note","term":"Treasury Note","also_known_as":[],"difficulty":"Beginner","definition":"A Treasury note is a medium-term debt security issued by the US government, with a maturity of between two and ten years, that pays interest every six months.","letter":"T","hasNote":false},{"id":"FIN-577","slug":"treasury-stock","term":"Treasury Stock","also_known_as":[],"difficulty":"Intermediate","definition":"Treasury stock is shares that a company has bought back from shareholders and holds itself, rather than cancelling them. These shares are not counted as outstanding.","letter":"T","hasNote":false},{"id":"FIN-1337","slug":"treasury-stock-method","term":"Treasury Stock Method","also_known_as":[],"difficulty":"Advanced","definition":"The treasury stock method is a way of calculating the dilution from stock options and warrants, assuming they are exercised and the company uses the cash received to buy back shares at the current market price.","letter":"T","hasNote":false},{"id":"FIN-1409","slug":"treaty-reinsurance","term":"Treaty Reinsurance","also_known_as":[],"difficulty":"Advanced","definition":"Treaty reinsurance is an agreement in which a reinsurer agrees to accept a share of an entire portfolio or class of an insurer\'s policies, such as all its property insurance, rather than individual policies.","letter":"T","hasNote":false},{"id":"FIN-993","slug":"trend","term":"Trend","also_known_as":[],"difficulty":"Beginner","definition":"In data analysis, a trend is the general, long-term direction in which a set of data is moving over time, such as upwards, downwards or flat.","letter":"T","hasNote":false},{"id":"FIN-1078","slug":"trend-analysis","term":"Trend Analysis","also_known_as":[],"difficulty":"Advanced","definition":"Trend analysis is the examination of financial or operating data over several periods to identify patterns, such as steady growth, decline or changes in direction.","letter":"T","hasNote":false},{"id":"FIN-1142","slug":"treynor-ratio","term":"Treynor Ratio","also_known_as":[],"difficulty":"Advanced","definition":"The Treynor ratio measures an investment\'s return above the risk-free rate for each unit of market risk, measured by beta.","letter":"T","hasNote":false},{"id":"FIN-101","slug":"trial-balance","term":"Trial Balance","also_known_as":[],"difficulty":"Beginner","definition":"A trial balance is a list of all accounts in the general ledger with their debit or credit balances at a point in time, used to check that total debits equal total credits.","letter":"T","hasNote":false},{"id":"FIN-528","slug":"trust","term":"Trust","also_known_as":[],"difficulty":"Beginner","definition":"A trust is a legal arrangement in which one person or organisation, the trustee, holds and manages assets for the benefit of others, the beneficiaries, according to rules set by the person who created it.","letter":"T","hasNote":false},{"id":"FIN-1462","slug":"turnaround","term":"Turnaround","also_known_as":[],"difficulty":"Intermediate","definition":"A turnaround is the process of restoring a struggling or declining business to financial health and sustainable profitability.","letter":"T","hasNote":false},{"id":"FIN-1060","slug":"unaudited-financial-statements","term":"Unaudited Financial Statements","also_known_as":[],"difficulty":"Advanced","definition":"Unaudited financial statements are financial statements that have not been examined by an independent auditor, so no auditor has given an opinion on whether they are fairly presented.","letter":"U","hasNote":false},{"id":"FIN-867","slug":"unbanked","term":"Unbanked","also_known_as":[],"difficulty":"Intermediate","definition":"Unbanked describes people who do not have an account with a bank or other formal financial institution.","letter":"U","hasNote":false},{"id":"FIN-1216","slug":"underemployment","term":"Underemployment","also_known_as":[],"difficulty":"Advanced","definition":"Underemployment is a situation in which people are working, but not as much as they would like, or in jobs that do not make full use of their skills, education or experience.","letter":"U","hasNote":false},{"id":"FIN-422","slug":"underlying-asset","term":"Underlying Asset","also_known_as":[],"difficulty":"Intermediate","definition":"The underlying asset is the financial asset or reference on which a derivative contract is based, and whose price determines the derivative\'s value.","letter":"U","hasNote":false},{"id":"FIN-379","slug":"underwriting","term":"Underwriting","also_known_as":[],"difficulty":"Intermediate","definition":"Underwriting is the process by which a lender, insurer or investment bank assesses risk and decides whether to take it on, and on what terms.","letter":"U","hasNote":false},{"id":"FIN-129","slug":"unearned-revenue","term":"Unearned Revenue","also_known_as":["Deferred Revenue"],"difficulty":"Beginner","definition":"Unearned revenue is money a business has received from customers for goods or services it has not yet delivered. It is recorded as a liability until the work is done.","letter":"U","hasNote":true},{"id":"FIN-769","slug":"unemployment-rate","term":"Unemployment Rate","also_known_as":[],"difficulty":"Beginner","definition":"The unemployment rate is the percentage of people in the labour force who are without a job but are available for work and actively looking for one.","letter":"U","hasNote":false},{"id":"FIN-1075","slug":"unfavorable-variance","term":"Unfavorable Variance","also_known_as":[],"difficulty":"Advanced","definition":"An unfavorable variance is a difference between actual and budgeted or standard results that reduces profit, such as costs coming in higher than budget or revenue lower than budget.","letter":"U","hasNote":false},{"id":"FIN-1121","slug":"unit-economics","term":"Unit Economics","also_known_as":[],"difficulty":"Advanced","definition":"Unit economics is the analysis of the revenue and costs associated with a single unit of a business, such as one customer, one order or one product, to judge whether the business model can be profitable as it grows.","letter":"U","hasNote":false},{"id":"FIN-501","slug":"unit-of-account","term":"Unit of Account","also_known_as":[],"difficulty":"Beginner","definition":"A unit of account is the common measure in which prices, debts, incomes and values are expressed. It is one of the three main jobs that money performs.","letter":"U","hasNote":false},{"id":"FIN-1466","slug":"unitranche-debt","term":"Unitranche Debt","also_known_as":[],"difficulty":"Advanced","definition":"Unitranche debt is a single loan that combines what would traditionally be separate senior and subordinated debt into one facility, with one blended interest rate and one set of documents.","letter":"U","hasNote":false},{"id":"FIN-344","slug":"universal-bank","term":"Universal Bank","also_known_as":[],"difficulty":"Intermediate","definition":"A universal bank is a bank that offers a wide range of financial services under one roof, including retail banking, commercial banking, investment banking and often insurance and asset management.","letter":"U","hasNote":false},{"id":"FIN-1412","slug":"universal-life-insurance","term":"Universal Life Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Universal life insurance is a type of permanent life insurance, common in the United States, that combines a death benefit with a cash value account, and allows the policyholder to adjust premium payments and the death benefit within certain limits.","letter":"U","hasNote":false},{"id":"FIN-1333","slug":"unlevered-beta","term":"Unlevered Beta","also_known_as":[],"difficulty":"Advanced","definition":"Unlevered beta is a measure of a company\'s market risk with the effect of its debt removed, reflecting only the risk of its business operations.","letter":"U","hasNote":false},{"id":"FIN-682","slug":"unrealized-gain","term":"Unrealized Gain","also_known_as":[],"difficulty":"Beginner","definition":"An unrealized gain is an increase in the value of an investment that the investor still holds and has not yet sold. It is sometimes called a paper gain.","letter":"U","hasNote":false},{"id":"FIN-080","slug":"unsecured-debt","term":"Unsecured Debt","also_known_as":[],"difficulty":"Beginner","definition":"Unsecured debt is borrowing that is not backed by any asset. The lender relies only on the borrower\'s promise and creditworthiness to be repaid.","letter":"U","hasNote":false},{"id":"FIN-694","slug":"unsystematic-risk","term":"Unsystematic Risk","also_known_as":[],"difficulty":"Intermediate","definition":"Unsystematic risk is the risk specific to a single company or industry, such as a product failure, a lawsuit or poor management, which can be reduced by diversifying across many investments.","letter":"U","hasNote":false},{"id":"FIN-946","slug":"upselling","term":"Upselling","also_known_as":[],"difficulty":"Intermediate","definition":"Upselling is the practice of encouraging customers to buy a more expensive, upgraded or larger version of the product or service they are already considering.","letter":"U","hasNote":false},{"id":"FIN-559","slug":"useful-life","term":"Useful Life","also_known_as":[],"difficulty":"Intermediate","definition":"Useful life is the period over which an asset is expected to be used by a business, or the number of units it is expected to produce. It determines how its cost is spread through depreciation or amortization.","letter":"U","hasNote":false},{"id":"FIN-1312","slug":"usury","term":"Usury","also_known_as":[],"difficulty":"Advanced","definition":"Usury is the practice of lending money at interest rates considered excessively high, and usury laws set legal limits on the interest rates lenders can charge.","letter":"U","hasNote":false},{"id":"FIN-318","slug":"utility","term":"Utility","also_known_as":[],"difficulty":"Intermediate","definition":"Utility is the satisfaction, happiness or benefit a person gets from consuming a good or service.","letter":"U","hasNote":false},{"id":"FIN-381","slug":"valuation","term":"Valuation","also_known_as":[],"difficulty":"Intermediate","definition":"Valuation is the process of estimating what an asset, business or investment is worth.","letter":"V","hasNote":false},{"id":"FIN-1460","slug":"valuation-cap","term":"Valuation Cap","also_known_as":[],"difficulty":"Advanced","definition":"A valuation cap is the maximum company valuation at which a convertible note or SAFE converts into shares, ensuring early investors receive a lower price per share than later investors if the company\'s value rises sharply.","letter":"V","hasNote":false},{"id":"FIN-794","slug":"value-added-tax","term":"Value-Added Tax (VAT)","also_known_as":["VAT"],"difficulty":"Beginner","definition":"Value-added tax (VAT) is a consumption tax charged on goods and services at each stage of production and distribution, where each business pays tax only on the value it adds, and the full tax is ultimately paid by the final consumer.","letter":"V","hasNote":false},{"id":"FIN-897","slug":"value-at-risk","term":"Value at Risk (VaR)","also_known_as":["VaR"],"difficulty":"Intermediate","definition":"Value at Risk (VaR) is a statistical estimate of the maximum loss a portfolio is expected to suffer over a set period, at a given level of confidence, under normal market conditions.","letter":"V","hasNote":false},{"id":"FIN-713","slug":"value-investing","term":"Value Investing","also_known_as":[],"difficulty":"Intermediate","definition":"Value investing is an investment strategy that involves buying shares that appear to be trading for less than their intrinsic value, based on careful analysis of the company\'s fundamentals.","letter":"V","hasNote":false},{"id":"FIN-703","slug":"value-stock","term":"Value Stock","also_known_as":[],"difficulty":"Intermediate","definition":"A value stock is a share that trades at a low price relative to measures of its fundamental worth, such as earnings, book value or dividends, often because investors have lower expectations for the company.","letter":"V","hasNote":false},{"id":"FIN-1416","slug":"variable-annuity","term":"Variable Annuity","also_known_as":[],"difficulty":"Advanced","definition":"A variable annuity is an annuity in which the money is invested in a choice of investment funds, so the account value and future income vary with the performance of those investments.","letter":"V","hasNote":false},{"id":"FIN-636","slug":"variable-cost","term":"Variable Cost","also_known_as":[],"difficulty":"Intermediate","definition":"A variable cost is a cost that changes in total in direct proportion to the amount a business produces or sells.","letter":"V","hasNote":false},{"id":"FIN-1065","slug":"variable-costing","term":"Variable Costing","also_known_as":[],"difficulty":"Advanced","definition":"Variable costing is a method of calculating product costs that includes only variable manufacturing costs in the cost of each unit, treating fixed production overheads as an expense of the period in which they occur.","letter":"V","hasNote":false},{"id":"FIN-060","slug":"variable-rate","term":"Variable Rate","also_known_as":["Floating Rate"],"difficulty":"Beginner","definition":"A variable rate is an interest rate that can change over time, usually because it is linked to a benchmark rate set by the market or the central bank.","letter":"V","hasNote":true},{"id":"NEW-02","slug":"variance-statistics","term":"Variance (Statistics)","also_known_as":[],"difficulty":"Intermediate","definition":"Variance, in statistics, is a measure of how spread out a set of values is, calculated as the average of the squared differences between each value and the mean.","letter":"V","hasNote":false},{"id":"FIN-B3-NEW6","slug":"variation-margin","term":"Variation Margin","also_known_as":[],"difficulty":"Advanced","definition":"Variation margin is the payment made daily, or more frequently, between parties to a futures contract or other cleared derivative to settle gains and losses as market prices change.","letter":"V","hasNote":false},{"id":"FIN-1378","slug":"vega","term":"Vega","also_known_as":[],"difficulty":"Advanced","definition":"Vega is a measure of how much an option\'s price is expected to change when the implied volatility of the underlying asset changes by one percentage point.","letter":"V","hasNote":false},{"id":"FIN-1223","slug":"velocity-of-money","term":"Velocity of Money","also_known_as":[],"difficulty":"Advanced","definition":"The velocity of money is the average number of times each unit of money is spent on goods and services during a period, calculated as nominal GDP divided by the money supply.","letter":"V","hasNote":false},{"id":"FIN-950","slug":"venture-capital","term":"Venture Capital","also_known_as":[],"difficulty":"Beginner","definition":"Venture capital is a form of private equity financing provided by investors to young, high-growth companies in exchange for an ownership stake.","letter":"V","hasNote":false},{"id":"FIN-1339","slug":"venture-capital-method","term":"Venture Capital Method","also_known_as":[],"difficulty":"Advanced","definition":"The venture capital method is a way of valuing early-stage companies by estimating their value at a future exit, then discounting it back to today using the high rate of return that venture investors require.","letter":"V","hasNote":false},{"id":"FIN-616","slug":"vertical-analysis","term":"Vertical Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"Vertical analysis expresses each item in a financial statement as a percentage of a base figure within the same statement and period, such as revenue or total assets, to show its relative size.","letter":"V","hasNote":false},{"id":"FIN-748","slug":"vesting","term":"Vesting","also_known_as":[],"difficulty":"Intermediate","definition":"Vesting is the process by which an employee gains full ownership of benefits provided by an employer, such as retirement plan contributions or share awards, usually after working for a set period.","letter":"V","hasNote":false},{"id":"FIN-1439","slug":"vintage-year","term":"Vintage Year","also_known_as":[],"difficulty":"Advanced","definition":"Vintage year is the year in which a private equity, venture capital or other private fund begins investing, or makes its first capital call, used to group funds for performance comparison.","letter":"V","hasNote":false},{"id":"FUT-0350","slug":"volatility","term":"Volatility","also_known_as":[],"difficulty":"Beginner","definition":"Volatility is how much and how quickly the price of an investment moves up and down over time. Higher volatility means larger and more frequent price swings.","letter":"V","hasNote":false},{"id":"FIN-1376","slug":"volatility-skew","term":"Volatility Skew","also_known_as":[],"difficulty":"Advanced","definition":"Volatility skew is the pattern in which options on the same asset and expiry date have different implied volatilities depending on their exercise prices.","letter":"V","hasNote":false},{"id":"FIN-1456","slug":"voting-rights","term":"Voting Rights","also_known_as":[],"difficulty":"Intermediate","definition":"Voting rights are the rights of shareholders to vote on company matters, such as electing directors, approving major transactions and changing the company\'s constitution, usually in proportion to the number of shares they own.","letter":"V","hasNote":false},{"id":"FIN-742","slug":"warrant","term":"Warrant","also_known_as":[],"difficulty":"Intermediate","definition":"A warrant is a security issued by a company that gives its holder the right, but not the obligation, to buy the company\'s shares at a set price before a specific date.","letter":"W","hasNote":false},{"id":"FIN-1189","slug":"wash-sale-rule","term":"Wash-Sale Rule","also_known_as":[],"difficulty":"Advanced","definition":"The wash-sale rule is a United States tax rule that disallows a capital loss on selling a security if the same or a substantially identical security is bought within 30 days before or after the sale.","letter":"W","hasNote":false},{"id":"FIN-1393","slug":"waterfall-structure","term":"Waterfall Structure","also_known_as":[],"difficulty":"Advanced","definition":"A waterfall structure is the set of rules that determines the order in which cash flows from a pool of assets, or a fund, are paid to different classes of investors and other parties.","letter":"W","hasNote":false},{"id":"FIN-011","slug":"wealth","term":"Wealth","also_known_as":[],"difficulty":"Beginner","definition":"Wealth is the total value of everything a person, household or country owns, such as money, investments, property and businesses, usually after subtracting what is owed.","letter":"W","hasNote":false},{"id":"FIN-479","slug":"weighted-average","term":"Weighted Average","also_known_as":[],"difficulty":"Beginner","definition":"A weighted average is an average in which some values count more than others, according to assigned weights that reflect their importance or size.","letter":"W","hasNote":false},{"id":"FIN-582","slug":"weighted-average-cost-method","term":"Weighted Average Cost Method","also_known_as":[],"difficulty":"Intermediate","definition":"The weighted average cost method is an inventory costing method that assigns each unit sold, and each unit remaining, the average cost of all similar units available during the period.","letter":"W","hasNote":false},{"id":"FUT-1666","slug":"weighted-average-cost-of-capital","term":"Weighted Average Cost of Capital (WACC)","also_known_as":["WACC"],"difficulty":"Intermediate","definition":"The weighted average cost of capital (WACC) is the average rate of return a company must pay to all its funders, lenders and shareholders, weighted by how much of each type of funding it uses.","letter":"W","hasNote":false},{"id":"FIN-204","slug":"what-if-analysis","term":"What-If Analysis","also_known_as":[],"difficulty":"Intermediate","definition":"What-if analysis is the practice of changing assumptions in a financial model to see how results would change, answering questions such as \\"what if sales fall by 15%?\\"","letter":"W","hasNote":false},{"id":"FIN-932","slug":"whole-life-insurance","term":"Whole Life Insurance","also_known_as":[],"difficulty":"Beginner","definition":"Whole life insurance is permanent life insurance that provides cover for the insured person\'s entire life, as long as premiums are paid, and usually builds up a cash value over time.","letter":"W","hasNote":false},{"id":"FIN-348","slug":"wholesale-banking","term":"Wholesale Banking","also_known_as":[],"difficulty":"Intermediate","definition":"Wholesale banking is the provision of banking services to large institutions, such as major corporations, governments, other banks and financial firms, rather than to individuals or small businesses.","letter":"W","hasNote":false},{"id":"FIN-527","slug":"will","term":"Will","also_known_as":[],"difficulty":"Beginner","definition":"A will is a legal document that sets out how a person wants their property and money distributed after they die, and who should manage that process.","letter":"W","hasNote":false},{"id":"FIN-841","slug":"wire-transfer","term":"Wire Transfer","also_known_as":[],"difficulty":"Beginner","definition":"A wire transfer is an electronic transfer of money from one bank account to another, often used for large, urgent or international payments.","letter":"W","hasNote":false},{"id":"FIN-750","slug":"withdrawal-rate","term":"Withdrawal Rate","also_known_as":[],"difficulty":"Intermediate","definition":"The withdrawal rate is the percentage of a retirement portfolio that an investor takes out each year to provide income.","letter":"W","hasNote":false},{"id":"FIN-541","slug":"withholding-tax","term":"Withholding Tax","also_known_as":[],"difficulty":"Intermediate","definition":"Withholding tax is tax deducted at the source of income, such as from wages, interest or dividends, and paid directly to the government by the payer rather than by the person receiving the income.","letter":"W","hasNote":false},{"id":"FIN-140","slug":"work-in-progress","term":"Work in Progress","also_known_as":[],"difficulty":"Beginner","definition":"Work in progress is the value of goods that are partly made but not yet finished at a particular date. It includes the raw materials used so far, plus labour and production costs added to them.","letter":"W","hasNote":false},{"id":"FIN-163","slug":"working-capital","term":"Working Capital","also_known_as":[],"difficulty":"Beginner","definition":"Working capital is the difference between a business\'s current assets and its current liabilities. It measures the short-term resources available to run the business after covering short-term obligations.","letter":"W","hasNote":false},{"id":"FIN-201","slug":"working-capital-forecast","term":"Working Capital Forecast","also_known_as":[],"difficulty":"Intermediate","definition":"A working capital forecast is an estimate of how much cash a business will have tied up in inventory and customer receivables, offset by amounts owed to suppliers, over a future period.","letter":"W","hasNote":false},{"id":"FIN-812","slug":"world-bank","term":"World Bank","also_known_as":[],"difficulty":"Intermediate","definition":"The World Bank is an international financial institution that provides loans, grants and expertise to developing countries to support economic development and reduce poverty.","letter":"W","hasNote":false},{"id":"FIN-210","slug":"worst-case-scenario","term":"Worst-Case Scenario","also_known_as":["Downside Case"],"difficulty":"Beginner","definition":"The worst-case scenario is a forecast based on pessimistic but still plausible assumptions, showing how bad results could be if things go wrong.","letter":"W","hasNote":true},{"id":"FIN-137","slug":"write-off","term":"Write-Off","also_known_as":[],"difficulty":"Beginner","definition":"A write-off is the removal of an asset\'s value from the accounts, wholly or partly, because it no longer has the value previously recorded, such as a debt that will never be paid or stock that cannot be sold.","letter":"W","hasNote":false},{"id":"FIN-1351","slug":"xirr","term":"XIRR","also_known_as":[],"difficulty":"Advanced","definition":"XIRR is a spreadsheet function that calculates the internal rate of return for a series of cash flows that occur on irregular dates, rather than at evenly spaced intervals.","letter":"X","hasNote":false},{"id":"FIN-1039","slug":"year-end-close","term":"Year-End Close","also_known_as":[],"difficulty":"Advanced","definition":"Year-end close is the process of finalising a company\'s accounts at the end of its financial year, including all month-end tasks plus additional adjustments, checks and preparation for the annual financial statements and audit.","letter":"Y","hasNote":false},{"id":"FIN-223","slug":"year-over-year-growth","term":"Year-over-Year Growth","also_known_as":[],"difficulty":"Beginner","definition":"Year-over-year growth compares a figure for one period with the same period a year earlier, expressed as a percentage change.","letter":"Y","hasNote":false},{"id":"FIN-258","slug":"yield-curve","term":"Yield Curve","also_known_as":[],"difficulty":"Intermediate","definition":"The yield curve is a line on a graph that shows the yields of bonds with the same credit quality but different maturities, from short-term to long-term, usually for government bonds.","letter":"Y","hasNote":false},{"id":"FIN-1220","slug":"yield-curve-inversion","term":"Yield Curve Inversion","also_known_as":[],"difficulty":"Advanced","definition":"A yield curve inversion is when interest rates on short-term government bonds rise above those on long-term government bonds, reversing the usual pattern in which longer loans pay higher rates.","letter":"Y","hasNote":false},{"id":"FIN-257","slug":"yield-to-call","term":"Yield to Call","also_known_as":[],"difficulty":"Intermediate","definition":"Yield to call is the annual return an investor would earn on a callable bond if the issuer repays it early, on the first date it is allowed to, rather than at maturity.","letter":"Y","hasNote":false},{"id":"FIN-255","slug":"yield-to-maturity","term":"Yield to Maturity (YTM)","also_known_as":["YTM"],"difficulty":"Intermediate","definition":"Yield to maturity (YTM) is the total annual return an investor can expect from a bond if it is bought at today\'s price, held until it matures and all payments are made as promised.","letter":"Y","hasNote":false},{"id":"FIN-987","slug":"z-score","term":"Z-Score","also_known_as":[],"difficulty":"Intermediate","definition":"A z-score is a measure of how many standard deviations a value is above or below the mean of a data set.","letter":"Z","hasNote":false},{"id":"FIN-252","slug":"zero-coupon-bond","term":"Zero-Coupon Bond","also_known_as":[],"difficulty":"Intermediate","definition":"A zero-coupon bond is a bond that pays no regular interest. Instead, it is sold at a discount to its face value and repaid at full face value at maturity.","letter":"Z","hasNote":false}]')}}]);